#admin-onboarding-flows p{margin:0}
#admin-onboarding-flows .lede{color:var(--muted);max-width:74ch}
#admin-onboarding-flows .facts{display:flex;flex-wrap:wrap;gap:6px 18px;margin-top:12px;font-family:var(--font-mono);font-size:12px;color:var(--muted)}
#admin-onboarding-flows .facts b{color:var(--fg);font-weight:500}
#admin-onboarding-flows .card{background:var(--surface);border:1px solid var(--rule);border-radius:12px;padding:18px 20px;display:grid;gap:14px;min-width:0}
#admin-onboarding-flows .sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
#admin-onboarding-flows .bar{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px 20px}
#admin-onboarding-flows .tabs{display:inline-flex;flex-wrap:wrap;gap:4px;padding:4px;border:1px solid var(--rule);border-radius:22px;background:var(--bg)}
#admin-onboarding-flows .tab{font-family:var(--font-body);font-weight:500;font-size:14px;line-height:1;height:34px;padding:0 15px;border:0;border-radius:999px;background:transparent;color:var(--muted);cursor:pointer;display:inline-flex;align-items:center;gap:8px}
#admin-onboarding-flows .tab:hover{color:var(--fg)}
#admin-onboarding-flows .tab[aria-selected="true"]{background:var(--surface);color:var(--fg);box-shadow:0 0 0 1px var(--rule)}
#admin-onboarding-flows .tab:focus-visible,#admin-onboarding-flows .nodeg:focus-visible,#admin-onboarding-flows .linkbtn:focus-visible{outline:2px solid var(--fg);outline-offset:2px}
#admin-onboarding-flows .tab .dot{width:9px;height:9px;border-radius:50%}
#admin-onboarding-flows .tab .cnt{font-family:var(--font-mono);font-size:11.5px;color:var(--faint);font-variant-numeric:tabular-nums}
#admin-onboarding-flows .dot.share{background:var(--share)}
#admin-onboarding-flows .dot.pub{background:var(--pub)}
#admin-onboarding-flows .dot.none{background:var(--drop)}
#admin-onboarding-flows .dot.both{background:linear-gradient(90deg,var(--share) 50%,var(--pub) 50%)}
#admin-onboarding-flows .dot.loop{background:transparent;box-shadow:inset 0 0 0 2px var(--muted)}
#admin-onboarding-flows .dot.all{background:linear-gradient(90deg,var(--pub) 0 34%,var(--share) 34% 67%,var(--drop) 67%)}
#admin-onboarding-flows .legend{display:flex;flex-wrap:wrap;gap:6px 16px;margin:0;padding:0;list-style:none;font-size:12.5px;color:var(--muted)}
#admin-onboarding-flows .legend li{display:flex;align-items:center;gap:7px}
#admin-onboarding-flows .legend .sw{width:18px;height:6px;border-radius:2px}
#admin-onboarding-flows .legend .box{width:10px;height:14px;border-radius:2px;background:var(--node)}
#admin-onboarding-flows .legend .box.hatch{background:repeating-linear-gradient(135deg,var(--node) 0 2px,transparent 2px 4.5px);outline:1px solid var(--node);outline-offset:-1px}
#admin-onboarding-flows .viewline{color:var(--muted);max-width:92ch}
