/* The spec's toolbar has a third switch, so its labels give way sooner. */
@container (max-width: 560px) {
  .shots-viewer-spec .shots-seg-label { display: none; }
  .shots-viewer-spec .shots-seg-btn { padding: 0 9px; }
}
/* The prose around the screens: diagrams and tables written into an HTML
   spec. A diagram is inline SVG drawn with these few classes, so it follows
   light and dark mode; a literal fill still works, in one theme. */
.spec-html figure { margin: 12px 0; }
.spec-html figure > svg { display: block; width: 100%; max-width: 100%; height: auto; }
.spec-html figcaption { margin-top: 4px; font-size: 12px; color: var(--text-muted, #68686c); }
.spec-html .spec-diagram-wrap { overflow-x: auto; border: 1px solid var(--border-light, #e3e3e6); border-radius: 10px; padding: 10px; background: var(--bg-secondary, #f5f5f7); }
.spec-html svg text { font-family: inherit; fill: var(--text-primary, #0a0a0a); }
.spec-html svg .spec-muted { fill: var(--text-muted, #68686c); }
.spec-html svg .spec-box { fill: var(--bg-primary, #fff); stroke: var(--border, #d1d1d6); stroke-width: 1; }
.spec-html svg .spec-box-changed { fill: var(--bg-primary, #fff); stroke: var(--accent, #0a6ee0); stroke-width: 1.5; }
.spec-html svg .spec-box-new { fill: var(--accent-tint, rgba(10, 110, 224, 0.08)); stroke: var(--accent, #0a6ee0); stroke-width: 1.5; stroke-dasharray: 4 3; }
.spec-html svg .spec-line { fill: none; stroke: var(--text-faint, #8e8e93); stroke-width: 1.2; }
.spec-html svg .spec-arrow { fill: var(--text-faint, #8e8e93); }
.spec-html svg .spec-accent { fill: var(--accent, #0a6ee0); }
.spec-html svg .spec-good { fill: #16a34a; }
.spec-html svg .spec-bad { fill: #dc2626; }
/* A plan's own pictures: screenshots uploaded to Homeroom, shown in the
   text (frontend/src/lib/spec-html.ts keeps only those). A `spec-strip` is
   a row of captioned pictures that scrolls sideways, the way a design doc
   lays out a flow of phone screens. */
.spec-html img { display: block; max-width: 100%; height: auto; border-radius: 12px; }
.spec-html .spec-strip { display: flex; gap: 16px; overflow-x: auto; scroll-snap-type: x proximity; overscroll-behavior-x: contain; margin: 12px 0; padding: 2px 2px 10px; }
.spec-html .spec-strip > figure { flex: 0 0 auto; width: min(240px, 72%); margin: 0; scroll-snap-align: start; }
.spec-html .spec-strip > figure > img { width: 100%; }
.spec-html .spec-strip figcaption { margin-top: 8px; font-size: 13px; line-height: 1.4; }
.spec-html .spec-screens { margin: 12px 0; }
.spec-html .spec-screens-caption { margin-top: 6px; font-size: 12px; color: var(--text-muted, #68686c); }
.dev-topic-details { margin-top: 8px; }
.dev-topic-details-summary {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  cursor: pointer;
  list-style: none;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--accent);
  user-select: none;
}
.dev-topic-details-summary::-webkit-details-marker { display: none; }
.dev-topic-details-summary::before { content: "▸"; font-size: 11px; }
.dev-topic-details[open] > .dev-topic-details-summary::before { content: "▾"; }
.dev-topic-details-body {
  margin-top: 8px;
  padding: 10px 12px;
  border-radius: 14px;
  background: var(--bg-primary);
  font-size: 13px;
  line-height: 1.5;
  color: var(--text-primary);
}
.dev-topic-note { font-size: 13px; line-height: 1.5; color: var(--text-muted); }
.dev-topic-about-body + .dev-topic-note { margin-top: 8px; }
/* #2603: a governance proposal's vote roster, under the About sheet's
   words. The ledger's review line rendered outside the ledger, so it takes
   the note's size and its own top margin rather than the row grid's. */
.dev-topic-roster { margin-top: 10px; font-size: 13px; line-height: 1.5; }

/* ── Discussion ──
   The app's own thread — `#gc-thread-messages`, the group chat's transcript
   host — is dressed as the sheet after the head. A request's page is its own
   layout (#4453, `.dev-request` below): its GitHub comments are rows of that
   thread. */
#gc-thread-head { display: block; }

/* ── The change page as the Workshop's Needs-you item ──────────────────
   topic/topic-head.tsx ChangeHero, StepsSheet and DetailsSheet. The hero
   borrows the item's pieces by class — the eyebrow, the title, the by-line
   and its avatar, the chips — and adds only what a page needs that a swipe
   card does not: no fixed height and no snap, the title unclamped, the
   chips under the by-line rather than beside it, and the card's action
   band under them. */
.dev-topic-hero {
  position: relative;
  padding: 16px 20px 18px;
  overflow: hidden;
}
.dev-topic-hero[data-ws-tint="a"] { background-image: linear-gradient(165deg, rgba(139, 92, 246, .10), rgba(255, 255, 255, 0) 55%, rgba(244, 114, 182, .08)); }
.dev-topic-hero[data-ws-tint="b"] { background-image: linear-gradient(165deg, rgba(59, 130, 246, .10), rgba(255, 255, 255, 0) 55%, rgba(251, 191, 36, .08)); }
.dark .dev-topic-hero[data-ws-tint="a"] { background-image: linear-gradient(165deg, rgba(139, 92, 246, .16), rgba(0, 0, 0, 0) 55%, rgba(244, 114, 182, .10)); }
.dark .dev-topic-hero[data-ws-tint="b"] { background-image: linear-gradient(165deg, rgba(59, 130, 246, .16), rgba(0, 0, 0, 0) 55%, rgba(251, 191, 36, .08)); }
.dev-topic-hero-top { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 20px; }
.dev-topic-hero-eyebrow { display: inline-flex; align-items: center; gap: 4px; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.dev-topic-hero-eyebrow > a { color: var(--accent); text-decoration: none; letter-spacing: 0; text-transform: none; font-weight: 700; }
.dev-topic-hero-eyebrow > a:hover { text-decoration: underline; }
/* The item's title, unclamped and at page size: a page has room for the
   whole line, where the swipe card's three-line clamp hid the end of a
   long one behind an ellipsis nobody could open. */
.dev-topic-hero > .dev-topic-hero-title {
  margin: 10px 0 0; max-width: none; display: block; -webkit-line-clamp: unset; overflow: visible;
  font-size: 24px; line-height: 1.2; overflow-wrap: anywhere;
}
.dev-topic-hero > .dev-topic-hero-by { margin-top: 10px; max-width: none; }
/* The card's tags in the Needs-you chip's shape. Each keeps the tint and
   ink utilities it arrived with — the card's own colours — and those
   outrank the chip's neutral fill because tailwind.css loads last. (The
   selectors here are two classes deep on purpose: the item's own rules,
   and its wide-layout ones further down, are one class, and the hero's
   must win whichever comes later in the file.) */
.dev-topic-hero > .dev-topic-hero-chips { margin-top: 10px; flex: none; justify-content: flex-start; }
.dev-topic-hero-chips > .dev-badge { height: 24px; padding: 0 9px; gap: 6px; border-radius: 9999px; font-size: 12px; font-weight: 600; }
.dev-topic-hero-chips > .dev-badge.font-mono { font-size: 11.5px; }
.dev-topic-hero-chips > .dev-badge .attr-avatar { width: 16px; height: 16px; font-size: 0.65rem; }
/* The band wears the card's class for the band rules above — the one-line
   fold into ⋯, the accent pills, Preview and the hamburger at the right;
   the card's own box (its radius, padding and edge) comes off here. */
.dev-topic-hero > div.dev-topic-hero-actions.dev-card-topic {
  margin-top: 12px; padding: 0; border-radius: 0; box-shadow: none; background: none; --dev-edge-w: 0px;
}
/* QA 2026-09-24 Q26: THE HERO'S BAND IS AS TALL AS ITS VOTE BUTTON. The band
   reserves and clips one 28px row (the card rule above), which is right for
   the 28px pills, but the hero also carries the Vote button, and that is
   30px (`.dev-vote-btn`). So the row was 30px inside a 28px window: the Vote
   pill lost its bottom 2px and the round menu button its last pixel, and on
   a phone both read as cut flat along the bottom. 30px here fits the tallest
   thing the hero's band holds; a wrapped second row still starts at 36px
   (30 plus the 6px row gap) and stays clipped, and useFoldedActions' "off the
   row" test reads the band's own height, so the fold is unchanged. Only the
   hero: on a card the Vote button sits in the status row, not in this band. */
.dev-topic-hero .gc-card-actions { margin-top: 0; min-height: 30px; max-height: 30px; }
.dev-topic-hero .gc-card-actions > .dev-vote-btn { margin-inline-end: 4px; }
/* The summary at the item's reading size, the whole of it. */
.dev-topic-hero-summary { margin: 14px 0 0; font-size: 17px; line-height: 1.45; color: var(--text-secondary); }
.dev-topic-hero-summary > :first-child { margin-top: 0; }
.dev-topic-hero-summary > :last-child { margin-bottom: 0; }
/* "Addresses", then the issue as a chip: the number bold, the title after
   it, ellipsised rather than wrapped; the owner's pencil at the line's end. */
.dev-topic-hero-issues { margin-top: 12px; min-width: 0; }
.dev-topic-hero-issues-line { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 8px; font-size: 13px; color: var(--text-muted); }
.dev-topic-hero-issues-k { font-weight: 600; }
.dev-topic-issue { max-width: 100%; height: auto; min-height: 24px; padding-block: 2px 2px; padding-inline: 8px 10px; gap: 6px; text-decoration: none; }
.dev-topic-issue:hover { text-decoration: none; filter: brightness(.96); }
.dev-topic-issue > b { font-weight: 700; flex: none; }
.dev-topic-issue > span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 500; }
.dev-topic-hero-issues-edit { margin-inline-start: auto; }
.dev-topic-hero-issues form { margin-top: 4px; }
/* The picture, or the line that says it is coming. */
.dev-topic-hero .dev-topic-visuals { margin-top: 14px; }
.dev-topic-hero .dev-topic-shots { margin-top: 12px; }
.dev-topic-hero-shots { display: inline-flex; align-items: center; gap: 8px; margin: 14px 0 0; font-size: 13px; color: var(--text-muted); }
.dev-topic-hero-shots > .dc-status-spinner-arc { flex: none; margin: 0; }
.dev-topic-hero > .dev-topic-note { margin-top: 12px; }

/* ── The steps: the card's grey strip, expanded ──
   The same panel as card/dev-card.tsx RequirementsRow — its tints ride in
   as the same utilities — with room to say, under each gate, what the
   ledger row for it said. */
.dev-topic-steps { padding: 8px; }
.dev-steps { overflow: hidden; }
.dev-steps-head { display: flex; align-items: baseline; gap: 6px; padding: 10px 14px; font-size: 13px; line-height: 1.35; color: var(--text-secondary); }
.dev-steps-headline { font-weight: 700; color: var(--text-primary); white-space: nowrap; }
.dev-steps-detail { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--text-muted); }
.dev-steps-count { margin-inline-start: auto; font-variant-numeric: tabular-nums; font-size: 12px; color: var(--text-muted); white-space: nowrap; }
.dev-steps-list { list-style: none; margin: 0; padding: 4px 0; }
.dev-step { display: grid; grid-template-columns: 22px 1fr auto; column-gap: 10px; align-items: baseline; padding: 9px 14px; font-size: 13.5px; line-height: 1.4; }
.dev-step + .dev-step { border-top: 1px solid var(--app-sheet-line); }
/* The mark: a ring, filled ok for a cleared step and blocked for a red one;
   the step waiting on a person wears the attention tone, and the one in
   flight spins the shell's arc. */
.dev-step-mark {
  display: inline-flex; align-items: center; justify-content: center; align-self: start; margin-top: 1px;
  width: 20px; height: 20px; border-radius: 9999px; font-size: 11px; font-weight: 800;
  box-shadow: inset 0 0 0 1.5px currentColor; color: var(--text-muted); background: transparent;
}
.dev-step-mark-done { background: var(--state-ok); color: #fff; box-shadow: none; }
.dev-step-mark-blocked { background: var(--state-blocked); color: #fff; box-shadow: none; }
.dev-step-mark-waiting { color: var(--state-attention); }
.dev-step-mark-active { box-shadow: none; color: var(--accent); }
.dev-step-mark-active > .dc-status-icon { margin: 0; }
.dev-step-label { font-weight: 600; color: var(--text-primary); }
.dev-step-done .dev-step-label { color: var(--text-secondary); }
.dev-step-pending .dev-step-label { color: var(--text-muted); }
/* A step an admin's force merge skips is done, but greyed: it was not cleared. */
.dev-step[data-req-skipped] .dev-step-label { color: var(--text-muted); }
.dev-step-actor { font-size: 12px; color: var(--text-muted); white-space: nowrap; }
.dev-step-body { grid-column: 2 / 4; display: flex; flex-direction: column; gap: 3px; margin-top: 2px; min-width: 0; font-size: 12.5px; color: var(--text-muted); }
.dev-step-body .dev-ledger-text { color: var(--text-secondary); }
.dev-step-blocked .dev-step-body .dev-ledger-text { color: var(--text-primary); }
.dev-step-note { color: var(--text-muted); }
.dev-step-when { color: var(--text-muted); }
.dev-step-body .dev-ledger-fails { font-size: 12px; }
.dev-step-body .dev-ledger-ops { margin-top: 4px; }
.dev-step-body .dev-ledger-help { margin: 0; }
/* The vote's line: the bar to the threshold, the card's pill, the counts. */
.dev-step-vote { display: flex; align-items: center; flex-wrap: wrap; gap: 8px 10px; }
.dev-step-vote-bar { flex: 0 0 160px; height: 8px; border-radius: 999px; background: var(--state-neutral-bg); overflow: hidden; }
.dev-step-vote-bar > i { display: block; height: 100%; border-radius: 999px; background: var(--state-ok); }
.dev-step-vote-tally { color: var(--text-primary); font-weight: 600; font-size: 12.5px; }
/* #3234: the threshold moved during the vote; muted, beside the counts. */
.dev-step-vote-was { color: var(--text-muted); font-size: 12.5px; }

/* ── A merge gate's step: one short line ──
   The mark, the label and the line on one row (app-view.js _stepLine), a
   button only for whoever can clear it. The line takes the step's tone when
   it is waiting on somebody or blocked — the one word a scan is after. */
.dev-step-main {
  display: flex; flex-wrap: wrap; align-items: baseline; gap: 2px 10px; min-width: 0;
  grid-column: 2 / 4;
}
.dev-step-line { font-size: 12.5px; color: var(--text-muted); min-width: 0; }
.dev-step-active .dev-step-line { color: var(--text-secondary); }
.dev-step-waiting .dev-step-line { color: var(--state-attention); font-weight: 600; }
.dev-step-blocked .dev-step-line { color: var(--state-blocked); font-weight: 600; }
.dev-step-main .dev-ledger-review-line { gap: 4px 8px; }
/* Who voted is a list of names, not the step's state: it keeps the muted ink
   whatever the mark says. */
.dev-step-main .dev-ledger-roster.dev-step-line { color: var(--text-muted); font-weight: 400; }
.dev-step-main .dev-ledger-help { margin: 0; }
.dev-step-main .dev-step-vote-was { flex-basis: 100%; font-weight: 400; }
/* The Checks step is a disclosure: the whole row is its control. */
.dev-step-toggle {
  border: 0; background: none; padding: 0; margin: 0; font: inherit; color: inherit; text-align: start;
  cursor: pointer; width: 100%;
}
.dev-step-toggle:hover .dev-step-label { color: var(--accent); }
.dev-step-chev {
  width: 14px; height: 14px; margin-inline-start: auto; align-self: center; flex: none;
  color: var(--text-muted); transition: transform 150ms;
}
.dev-step-toggle[aria-expanded="true"] .dev-step-chev { transform: rotate(90deg); }
@media (prefers-reduced-motion: reduce) { .dev-step-chev { transition: none; } }
/* Reduce motion setting (#6510): the same, when Settings asks for it. */
:where(html[data-motion="reduce"]) .dev-step-chev { transition: none; }
/* The run, open: a row per stage — its name, its bar, its count. */
.dev-step-run {
  display: grid; grid-template-columns: 5.5rem minmax(0, 1fr) auto; gap: 7px 10px; align-items: center;
  margin-top: 6px; padding: 10px 12px; border-radius: 10px; background: var(--bg-secondary);
  font-size: 12px; color: var(--text-muted);
}
.dev-step-run-row { display: contents; }
.dev-step-run-k { color: var(--text-secondary); font-weight: 600; white-space: nowrap; }
.dev-step-run-v { font-variant-numeric: tabular-nums; text-align: end; white-space: nowrap; }
.dev-step-run-v.is-bad { color: var(--state-blocked); font-weight: 600; }
.dev-step-run .dev-ledger-build-bar { flex-basis: auto; height: 8px; margin: 0; gap: 3px; }
.dev-step-run .dev-ledger-build-seg { background: var(--state-neutral-bg); }
.dev-step-run .dev-ledger-build-seg.is-done { background: var(--state-ok); }
.dev-step-run .dev-ledger-build-seg.is-now { background: var(--accent); }
.dev-step-run-track {
  position: relative; display: block; height: 8px; border-radius: 999px; overflow: hidden;
  background: var(--state-neutral-bg);
}
.dev-step-run-track > i { position: absolute; top: 0; bottom: 0; inset-inline-start: 0; display: block; }
.dev-step-run-track > .is-pass { background: var(--state-ok); }
.dev-step-run-track > .is-fail { background: var(--state-blocked); }
.dev-step-run-track.is-busy { animation: dev-ledger-progress-pulse 1.4s ease-in-out infinite; }
@media (prefers-reduced-motion: reduce) { .dev-step-run-track.is-busy { animation: none; } }
/* Reduce motion setting (#6510): the same, when Settings asks for it. */
:where(html[data-motion="reduce"]) .dev-step-run-track.is-busy { animation: none; }
.dev-step-run > .dev-ledger-fails { grid-column: 1 / -1; margin: 2px 0 0; }
.dev-step-run-note { grid-column: 1 / -1; margin: 0; font-size: 12px; color: var(--text-muted); }
@media (max-width: 520px) {
  .dev-step-run { grid-template-columns: 4.25rem minmax(3rem, 1fr) minmax(0, max-content); gap: 7px 8px; }
  .dev-step-run-v { white-space: normal; }
}

/* The hero's status row: the card's pill and Vote button, above the band. */
.dev-topic-hero .dev-card-badges.dev-topic-hero-status { margin-top: 0; }
.dev-topic-hero .dev-topic-hero-status + .gc-card-actions { margin-top: 8px; }

/* ── Technical details, as a sheet over the page ──
   Opened from the ⋯ menu (DetailsSheet); body-mounted, so no frosted sheet
   contains it. A bottom sheet on a phone, a centred card above 720px. */
.dev-details-scrim {
  position: fixed; inset: 0; z-index: 70;
  display: flex; align-items: flex-end; justify-content: center;
  background: rgba(20, 20, 26, .28); backdrop-filter: blur(2px); -webkit-backdrop-filter: blur(2px);
}
.dev-details-card {
  width: min(680px, 100%); max-height: 78vh; overflow: auto; box-sizing: border-box;
  padding: 14px 18px 20px; border-start-start-radius: 22px; border-start-end-radius: 22px; border-end-end-radius: 0; border-end-start-radius: 0;
  background: var(--bg-primary); color: var(--text-primary);
  box-shadow: 0 -12px 40px rgba(0, 0, 0, .22);
}
@media (min-width: 720px) {
  .dev-details-scrim { align-items: center; }
  .dev-details-card { border-radius: 22px; }
}
.dev-details-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 8px; }
.dev-details-head > .dev-topic-h { margin: 0; }
.dev-details-close {
  display: inline-flex; align-items: center; justify-content: center; width: 30px; height: 30px;
  border: 0; border-radius: 9999px; background: var(--bg-tertiary); color: var(--text-primary); cursor: pointer;
}
.dev-details-card > .dev-topic-details-body { margin: 0; padding: 0; background: none; font-size: 13.5px; line-height: 1.5; }
/* B10b: Details stays mounted while shut (the steps it carries stay on the
   page); the scrim's flex would otherwise outrank the hidden attribute. */
.dev-details-scrim[hidden] { display: none; }
.dev-details-pr { display: flex; align-items: baseline; gap: 10px; margin: 0 0 10px; font-size: 13px; color: var(--text-secondary); }
.dev-details-pr > a { font-weight: 600; color: var(--accent); }
/* The steps sheet sits in the card as its own panel: the card is the
   surface, so the sheet's frost and hairline step aside. */
.dev-details-card .dev-topic-steps { padding: 0; background: none; backdrop-filter: none; -webkit-backdrop-filter: none; box-shadow: none; border-radius: 0; }
.dev-details-part { margin-top: 14px; }
.dev-details-sub { margin: 0 0 6px; font-size: 12px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--text-muted); }
.dev-details-part > .dev-topic-details-body { margin: 0; padding: 0; background: none; font-size: 13.5px; line-height: 1.5; }
/* B10b: the hero's Tested line, in the steps' own marks. A tap opens
   Details at the Checks part. */
.dev-topic-tested {
  display: inline-flex; align-items: center; gap: 8px; margin: 12px 0 0; padding: 0;
  border: 0; background: none; cursor: pointer; font: inherit; font-size: 13.5px; font-weight: 600; color: var(--text-secondary);
}
.dev-topic-tested[data-tested="failed"] { color: var(--state-blocked); }
.dev-topic-tested-mark {
  display: inline-flex; align-items: center; justify-content: center; flex: none;
  width: 20px; height: 20px; border-radius: 9999px; font-size: 11px; font-weight: 800;
  box-shadow: inset 0 0 0 1.5px currentColor; color: var(--text-muted);
}
.dev-topic-tested-mark-passed { background: var(--state-ok); color: #fff; box-shadow: none; }
.dev-topic-tested-mark-failed { background: var(--state-blocked); color: #fff; box-shadow: none; }
.dev-topic-tested-mark-broken { color: var(--state-attention); }
.dev-topic-tested-mark-running { box-shadow: none; color: var(--accent); }
.dev-topic-tested-mark-running > .dc-status-icon { margin: 0; }
.dev-description-dialog { margin: auto; border: 0; border-radius: 20px; width: min(680px, calc(100% - 24px)); max-height: 85dvh; }
.dev-description-dialog::backdrop { background: rgba(20, 20, 26, .5); }
@media (max-width: 480px) {
  .dev-topic-hero { padding: 14px 14px 16px; }
  .dev-topic-hero-title { font-size: 22px; }
  .dev-topic-hero-summary { font-size: 16px; }
  .dev-step-vote-bar { flex-basis: 120px; }
}
/* The Workshop row's two-line preview names the spec after the sentence. */
.dev-feed-comment-spec { display: block; margin-top: 2px; font-weight: 600; color: var(--text-primary); }
#dev-topic-thread #gc-thread-messages {
  margin: 4px 0 0;
  max-width: 900px;
  margin-inline-start: auto;
  margin-inline-end: auto;
  background-color: var(--dc-sheet-fill);
  backdrop-filter: var(--dc-frost);
  -webkit-backdrop-filter: var(--dc-frost);
  border-radius: 26px;
  padding: 12px 14px 14px;
  box-shadow: 0 0 0 1px var(--app-sheet-line) inset;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
#dev-topic-thread #gc-thread-messages::before {
  content: "Discussion";
  display: block;
  font-size: 12px;
  font-weight: 600;
  line-height: 1;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--text-muted);
}
/* "Load earlier" as a quiet pill; the empty line as a muted centred note. */
#dev-topic-thread #gc-thread-earlier {
  height: 26px;
  padding: 0 12px;
  font-size: 12px;
  font-weight: 500;
  color: var(--text-muted);
}
#dev-topic-thread #gc-thread-messages > .text-xs { text-align: center; color: var(--text-muted); }
/* A message as a bubble: the swatch avatar outside, the white bubble with
   the author and the age on its first line, the viewer's own in the accent
   tint — the Activity feed's row, at reading size. */
#dev-topic-thread .gc-msg {
  padding: 0;
  gap: 8px;
  align-items: flex-start;
}
#dev-topic-thread .gc-msg:hover { background: transparent; }
#dev-topic-thread .gc-msg > .min-w-0 {
  flex: 0 1 auto;
  max-width: 85%;
  padding: 8px 12px 9px;
  border-radius: 16px;
  background: var(--bg-primary);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.05);
}
#dev-topic-thread .gc-msg-self > .min-w-0 { background: var(--accent-tint); }
/* A change's Discussion speaks the general chat's language (group-chat.js
   `language: 'chat'`): the transcript draws the bubbles itself, the
   viewer's own in the accent bubble, so the topic page's own bubble dressing
   above stands down there — the row is the Messages screen's row. */
#dev-topic-thread #gc-thread-messages[data-language="chat"] .gc-msg { padding: 8px 16px; gap: 12px; }
#dev-topic-thread #gc-thread-messages[data-language="chat"] .gc-msg > .min-w-0 {
  flex: 1 1 0%;
  max-width: 100%;
  padding: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}
#dev-topic-thread #gc-thread-messages[data-language="chat"] .gc-msg-self > .min-w-0 { background: transparent; }
#dev-topic-thread #gc-thread-messages[data-language="chat"] .gc-msg > .min-w-0 > .flex { gap: 8px; margin-bottom: 0; }
#dev-topic-thread #gc-thread-messages[data-language="chat"] .gc-msg > .min-w-0 > .flex > .truncate { font-size: 17px; }
#dev-topic-thread #gc-thread-messages[data-language="chat"] .gc-msg > .min-w-0 > .flex > .shrink-0 { font-size: 15px; }
#dev-topic-thread #gc-thread-messages[data-language="chat"] .gc-msg > .min-w-0 > .leading-snug { font-size: 17px; }
#dev-topic-thread #gc-thread-messages[data-language="chat"] .gc-msg > [aria-hidden="true"] { width: 44px; height: 44px; font-size: 17px; border-radius: 12px; margin-top: 0; }
/* The editor needs the row's available width, not the bubble's intrinsic
   text width. Save and Cancel clear data-editing and restore bubble sizing. */
#dev-topic-thread .gc-msg[data-editing="1"] > .min-w-0 {
  flex: 1 1 0%;
  max-width: 100%;
}
#dev-topic-thread .gc-msg > .min-w-0 > .flex { gap: 6px; margin-bottom: 2px; }
#dev-topic-thread .gc-msg > .min-w-0 > .flex > .truncate { font-size: 14px; }
#dev-topic-thread .gc-msg > .min-w-0 > .flex > .shrink-0 { font-size: 12.5px; }
#dev-topic-thread .gc-msg > .min-w-0 > .leading-snug { font-size: 15px; }
#dev-topic-thread .gc-msg > [aria-hidden="true"] { width: 26px; height: 26px; font-size: 11px; border-radius: 999px; margin-top: 6px; }
/* (#5165) Grouped gutter follows the 26px bubble avatar, so a continuation bubble lines up under the first one. */
#dev-topic-thread .gc-msg[data-grouped] > .gc-msg-gutter { width: 26px; }
#dev-topic-thread #gc-thread-messages[data-language="chat"] .gc-msg[data-grouped] > .gc-msg-gutter { width: 44px; }
#dev-topic-thread .gc-msg-system { padding: 2px 12px; font-size: 12px; }
#dev-topic-thread .gc-msg-system-repeat { color: var(--text-faint); }
@media (max-width: 639px) {
  #dev-topic-thread .gc-msg > .min-w-0 { max-width: 100%; }
}
/* ═══════════════════════════════════════════════════════════════════════
   #4453: A REQUEST'S PAGE, drawn as a Messages reply thread
   (group-chat/thread-shell.tsx `RequestShell`). The "‹ Workshop" chip, then
   ONE sheet, the one Messages opens a reply thread in: its header ("Request
   #N", the category, ⋯), a scroller with the request as the root post
   (dev-board/topic/request-head.tsx) and its replies under "N replies"
   (group-chat/transcript.tsx `RequestRows`), and the thread's composer at
   its foot.

   Messages' tokens are only defined on `.messages-layout` and
   `.dev-ws-discussion`, so they are defined here too, with the same values.
   ═══════════════════════════════════════════════════════════════════════ */
.dev-request {
  --messages-surface: #ffffff;
  --messages-surface-2: var(--bg-secondary);
  --messages-hair: var(--border-light);
  --messages-disc-shadow: 0 1px 2px rgba(0, 0, 0, 0.06);
  display: flex;
  flex-direction: column;
  width: 100%;
  max-width: 780px;
  height: 100%;
  min-height: 0;
  margin: 0 auto;
  padding: 0 12px;
  box-sizing: border-box;
}
.dark .dev-request {
  --messages-surface: var(--dc-raised);
  --messages-surface-2: #3a3a3c;
  --messages-hair: rgba(255, 255, 255, 0.08);
  --messages-disc-shadow: 0 1px 2px rgba(0, 0, 0, 0.4);
}
.dev-request-back { flex: 0 0 auto; display: flex; padding-inline-start: 4px; }
.dev-request-back:empty { display: none; }
.dev-request-back .dev-topic-back { margin: 0 0 12px; }
.dev-request-sheet { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; }
.dev-request-bar { flex: 0 0 auto; }
.dev-request-scroll { flex: 1 1 auto; min-height: 0; overflow-y: auto; }
/* THE BAR GETS AN EDGE ONCE THE PAGE SCROLLS UNDER IT (overnight audit R01,
   2 Nov 2026). The bar is the sheet's first row and the scroller its next
   sibling, with nothing between them, so a scrolled page was cut flush
   under the title: the root post's own title (the bar repeats it) read as a
   second copy sliced in half, a line of the words as a stray bar. A hairline
   inside the bar's foot says where the page goes under it. Where scroll
   timelines exist it fades in over the first 12px of scroll, so a page at
   rest keeps its seamless head; elsewhere it is always drawn. Inset, so the
   scroller's text never paints over it. */
.dev-request-bar { box-shadow: inset 0 -1px 0 var(--messages-hair); }
@supports (animation-timeline: scroll()) and (timeline-scope: --a) {
  .dev-request-sheet { timeline-scope: --dev-request-scroll; }
  .dev-request-scroll { scroll-timeline: --dev-request-scroll y; }
  .dev-request-bar {
    animation: dev-request-bar-edge linear both;
    animation-timeline: --dev-request-scroll;
    animation-range: 0 12px;
  }
}
@keyframes dev-request-bar-edge {
  from { box-shadow: inset 0 -1px 0 transparent; }
  to { box-shadow: inset 0 -1px 0 var(--messages-hair); }
}
.dev-request-bar .messages-thread-action { position: relative; }

/* The root post: the request itself. */
.dev-request-root { padding-top: 4px; padding-bottom: 14px; }
.dev-request-title {
  margin: 4px 0 6px;
  font-size: 20px;
  line-height: 1.25;
  font-weight: 700;
  color: var(--text-primary);
  text-wrap: balance;
  overflow-wrap: anywhere;
}
/* The asker's own words: a quote, set apart from what the page says. */
.dev-request-ask {
  margin: 2px 0 0;
  padding-block: 2px 2px; padding-inline: 12px 0;
  border-inline-start: 3px solid color-mix(in srgb, var(--text-muted) 40%, transparent);
}
.dev-request-ask-text { font-size: 15px; line-height: 1.5; color: var(--text-secondary); overflow-wrap: anywhere; }
.dev-request-ask-text .dev-issue-body { font-size: inherit; color: inherit; }
.dev-request-ask-text p,
.dev-request-ask-text .dc-p { margin: 0 0 4px; }
.dev-request-ask-text ul { margin: 0 0 4px; padding-inline-start: 20px; list-style: disc; }
.dev-request-ask-text ol { margin: 0 0 4px; padding-inline-start: 20px; list-style: decimal; }
.dev-request-ask-text strong { color: var(--text-primary); }
/* #5999: the request a close proposal closes, first in its About sheet.
   The row size (15px, 650) rather than the request page's large heading:
   the card above already holds this page's one heading. */
.dev-topic-closes { margin-bottom: 10px; }
.dev-topic-closes-title {
  display: block;
  margin: 2px 0 4px;
  font-size: 15px;
  font-weight: 650;
  color: var(--text-primary);
  text-decoration: none;
  overflow-wrap: anywhere;
}
.dev-topic-closes-title:hover { text-decoration: underline; }

/* The hub's own reveal, in the quote's text column; the caret turns over. */
.dev-request-more.dev-ws-reveal-start { margin-top: 4px; padding-inline-start: 0; width: auto; }
.dev-request-more .dev-ws-reveal-chev { transition: transform 240ms cubic-bezier(.32, .72, 0, 1); }
@media (prefers-reduced-motion: reduce) {
  .dev-request-more .dev-ws-reveal-chev { transition: none; }
}
/* Reduce motion setting (#6510): the same, when Settings asks for it. */
:where(html[data-motion="reduce"]) .dev-request-more .dev-ws-reveal-chev { transition: none; }

/* #4481 and #4482: a request's screenshots (dev-board/topic/request-shots.ts).
   With the experimental C switch on, the blocks that hold one leave the fold
   for `.dev-request-shots`, set like the words. A picture whose link carries
   a C comment's pin (comment-pin/pin-data.ts) shows the comment over it as a
   layer: the pin's square corner on the point, the words in a card beside
   it, and a button on the picture's corner that hides both. The picture
   itself stays clean. `.pin-shot` takes the picture link's box and margin,
   so the layer's percentages land on the image. */
.dev-request-shots { margin-top: 6px; font-size: 15px; line-height: 1.5; color: var(--text-secondary); overflow-wrap: anywhere; }
.dev-request-shots .dev-issue-body { font-size: inherit; color: inherit; }
.dev-request-shots p,
.dev-request-shots .dc-p { margin: 0 0 4px; }
.dev-request-shots strong { color: var(--text-primary); }
/* #6387: hold a picture's or a video's place while it loads, so nothing
   under it jumps. The box is the size the page usually shows one in (512px
   wide, its 320px cap at 16:10) in the status card's plane colour, until
   `data-shot-ready` says the media knows its own shape
   (topic/request-head.tsx RequestWords); then it takes that shape. */
.dev-request-shots .dc-inline-img:not([data-shot-ready]),
.dev-request-shots .dc-inline-video:not([data-shot-ready]) {
  width: 512px;
  max-width: 100%;
  aspect-ratio: 16 / 10;
  background: var(--messages-surface);
}
.pin-shot { position: relative; display: block; width: fit-content; max-width: 100%; margin: 6px 0; }
.pin-shot > .dc-inline-img-link,
.pin-shot > .dc-inline-img { margin: 0; }
.pin-shot-layer {
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  transition: opacity 160ms ease, visibility 160ms;
}
/* One mark per pin; a request of several comments numbers them. */
.pin-shot-mark { position: absolute; inset: 0; }
/* The button's `data-shown` is the one record of whether it is shown; its words say which press it is (not `aria-pressed`, whose name must not change). */
.pin-shot-toggle[data-shown="false"] + .pin-shot-layer { opacity: 0; visibility: hidden; }
/* direction: physical — the pins mark a POINT ON A PICTURE. `--pin-x` and
   `--pin-y` are percentages of the screenshot itself, and the note's side is
   chosen from that same number, so none of it moves when the prose does:
   pinning a point at 70% across the picture pins it there in Arabic too. */
.pin-shot-pin {
  position: absolute;
  left: var(--pin-x);
  top: var(--pin-y);
  width: 24px;
  height: 24px;
  box-sizing: border-box;
  border: 2px solid #ffffff;
  border-radius: 50% 50% 50% 0;
  background: var(--accent);
  color: var(--accent-ink);
  display: grid;
  place-items: center;
  font-size: 11px;
  font-weight: 800;
  line-height: 1;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.35);
  transform: translateY(-100%);
}
.pin-shot-note {
  position: absolute;
  box-sizing: border-box;
  width: max-content;
  max-width: max(120px, min(240px, calc(100% - var(--pin-x) - 34px)));
  padding: 6px 10px;
  border-radius: 12px;
  background: var(--dc-sheet);
  color: var(--text-primary);
  font-size: 13px;
  font-weight: 500;
  line-height: 1.35;
  text-align: start;
  overflow-wrap: anywhere;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.18), 0 0 0 1px var(--app-sheet-line);
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 6;
  line-clamp: 6;
  overflow: hidden;
}
/* Right of the pin, or left of the point in the picture's right part; its
   foot level with the point, or its head there near the picture's top. */
.pin-shot-mark[data-side="right"] .pin-shot-note { left: calc(var(--pin-x) + 30px); }
.pin-shot-mark[data-side="left"] .pin-shot-note {
  right: calc(100% - var(--pin-x) + 6px);
  max-width: max(120px, min(240px, calc(var(--pin-x) - 10px)));
}
.pin-shot-mark[data-rise="up"] .pin-shot-note { bottom: calc(100% - var(--pin-y)); }
.pin-shot-mark[data-rise="down"] .pin-shot-note { top: var(--pin-y); }
/* direction: logical — the pins point at a picture's own coordinates; the
   button's corner below follows the reading direction again. */
.pin-shot-toggle {
  position: absolute;
  top: 6px;
  inset-inline-end: 6px;
  z-index: 2;
  appearance: none;
  border: 0;
  cursor: pointer;
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  line-height: 1;
  padding: 5px 9px;
  border-radius: 999px;
  color: var(--text-primary);
  background: var(--dc-sheet);
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.2), 0 0 0 1px var(--app-sheet-line);
}
.pin-shot-toggle:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.dark .pin-shot-note,
.dark .pin-shot-toggle { background: var(--dc-raised); }
@media (prefers-reduced-motion: reduce) {
  .pin-shot-layer { transition: none; }
}
/* Reduce motion setting (#6510): the same, when Settings asks for it. */
:where(html[data-motion="reduce"]) .pin-shot-layer { transition: none; }

/* A request's track card drawn from the board's older row keeps its place
   unseen until the fresh row says where the work is (request-head.tsx
   `trackPending`, polish board #12). */
.dev-request-track[data-request-track="pending"] { visibility: hidden; }
/* Where it stands: a card on the sheet, the stepper, a sentence, the next step. */
.dev-request-status {
  margin-top: 10px;
  max-width: 560px;
  border-radius: 16px;
  padding: 14px 14px 12px;
  background: var(--messages-surface);
}
.dev-request-steps {
  list-style: none;
  margin: 0 0 12px;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
}
.dev-request-step { position: relative; display: flex; flex-direction: column; align-items: flex-start; gap: 5px; min-width: 0; }
.dev-request-step::before {
  content: '';
  position: absolute;
  top: 10px;
  inset-inline-start: 24px;
  inset-inline-end: 4px;
  height: 2px;
  border-radius: 2px;
  background: var(--messages-hair);
}
.dev-request-step:last-child::before { display: none; }
.dev-request-step[data-state="done"]::before { background: color-mix(in srgb, var(--text-muted) 45%, transparent); }
.dev-request-step-mark {
  position: relative;
  z-index: 1;
  width: 22px;
  height: 22px;
  box-sizing: border-box;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 2px solid var(--messages-hair);
  background: var(--messages-surface);
  color: var(--text-muted);
}
.dev-request-step-mark svg { width: 13px; height: 13px; stroke-width: 2.5; }
/* Done: a muted check ring, no fill. Now: the lit ring and dot. Next: a hairline. */
.dev-request-step[data-state="done"] .dev-request-step-mark { border-color: color-mix(in srgb, var(--text-muted) 55%, transparent); }
.dev-request-step[data-state="now"] .dev-request-step-mark { border-color: var(--lit-ink); background: var(--lit-tint); }
.dev-request-step[data-state="now"] .dev-request-step-mark::after {
  content: '';
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: var(--lit-ink);
}
.dev-request-step-label { font-size: 13px; font-weight: 600; color: var(--text-muted); }
.dev-request-step[data-state="now"] .dev-request-step-label { color: var(--text-primary); font-weight: 700; }
.dev-request-say { margin: 0; font-size: 15px; font-weight: 600; color: var(--text-primary); }
.dev-request-fine { margin: 2px 0 0; font-size: 13px; color: var(--text-muted); }
.dev-request-actions { margin-top: 12px; display: flex; gap: 8px; }
.dev-request-primary {
  appearance: none;
  display: inline-flex;
  align-items: center;
  border: 0;
  cursor: pointer;
  font: inherit;
  font-size: 14px;
  font-weight: 600;
  color: var(--accent-ink);
  background: var(--accent);
  padding: 8px 16px;
  border-radius: 999px;
  text-decoration: none;
}
.dev-request-primary:hover { background: var(--accent-light); }
.dev-request-primary:disabled { opacity: .55; cursor: default; }

/* #5987: "Build it with your own Claude Code", folded under the card's own
   action, which stays the one primary thing on the page. Its link is the
   shared Button primitive's pill (own-agent-link.tsx). */
.dev-request-own-agent { margin-top: 14px; padding-top: 12px; border-top: 1px solid var(--messages-hair); }
.dev-request-own-agent-summary { cursor: pointer; font-size: 13px; font-weight: 600; color: var(--text-muted); }
.dev-request-own-agent-lead { margin: 8px 0 0; font-size: 13px; color: var(--text-muted); }
.dev-request-own-agent-needs-heading { margin: 10px 0 2px; font-size: 13px; font-weight: 600; color: var(--text-primary); }
.dev-request-own-agent-needs { margin: 0; padding-inline-start: 18px; list-style: disc; font-size: 13px; line-height: 1.6; color: var(--text-muted); }
.dev-request-own-agent-check { display: inline-block; width: 14px; height: 14px; margin-inline-start: 6px; vertical-align: -2px; color: var(--text-muted); }
.dev-request-own-agent-add { margin-inline-start: 6px; font-weight: 600; color: var(--accent); }

/* Each spec at its newest version, hanging off the request as a shared item. */
.dev-request-specs.messages-object-list { margin-top: 8px; max-width: 560px; }
.dev-request-read {
  appearance: none;
  flex: 0 0 auto;
  border: 0;
  cursor: pointer;
  font: inherit;
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
  background: var(--messages-surface-2);
  padding: 7px 14px;
  border-radius: 999px;
}
.dev-request-read:disabled { opacity: .6; cursor: default; }

/* The stream: no sheet of its own (the sheet is the thread's), Messages'
   row metrics, and the viewer's own replies not set apart. No padding under
   it either: the transcript's end is its scroller's 12px, as in every chat
   (`.chat-transcript`, "A chat's foot", 1 November 2026). Its 8px, stacked
   on the scroller's 6px, put 14px under the last reply; on the scroller's
   12px it would have put 20. */
#dev-topic-thread #gc-thread-messages:is([data-language="request"], [data-language="change"]) {
  margin: 0;
  max-width: none;
  padding: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  display: block;
}
#dev-topic-thread #gc-thread-messages:is([data-language="request"], [data-language="change"])::before { content: none; }
#dev-topic-thread #gc-thread-messages:is([data-language="request"], [data-language="change"]) .gc-msg { padding: 8px 16px; gap: 12px; }
#dev-topic-thread #gc-thread-messages:is([data-language="request"], [data-language="change"]) .gc-msg[data-grouped] { padding-top: 1px; padding-bottom: 1px; }
#dev-topic-thread #gc-thread-messages:is([data-language="request"], [data-language="change"]) .gc-msg > .min-w-0 {
  flex: 1 1 0%;
  max-width: 100%;
  padding: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}
#dev-topic-thread #gc-thread-messages:is([data-language="request"], [data-language="change"]) .gc-msg-self > .min-w-0 { background: transparent; }
#dev-topic-thread #gc-thread-messages:is([data-language="request"], [data-language="change"]) .gc-msg-username-self { color: inherit; }
#dev-topic-thread #gc-thread-messages:is([data-language="request"], [data-language="change"]) .gc-msg > .min-w-0 > .flex { gap: 8px; margin-bottom: 0; }
#dev-topic-thread #gc-thread-messages:is([data-language="request"], [data-language="change"]) .gc-msg > .min-w-0 > .flex > .truncate { font-size: 17px; }
#dev-topic-thread #gc-thread-messages:is([data-language="request"], [data-language="change"]) .gc-msg > .min-w-0 > .flex > .shrink-0 { font-size: 15px; }
#dev-topic-thread #gc-thread-messages:is([data-language="request"], [data-language="change"]) .gc-msg > .min-w-0 > .leading-snug { font-size: 17px; line-height: 1.3; }
#dev-topic-thread #gc-thread-messages:is([data-language="request"], [data-language="change"]) .gc-msg > [aria-hidden="true"] {
  width: 36px;
  height: 36px;
  font-size: 13px;
  border-radius: 12px;
  margin-top: 0;
}
/* (#5165) The grouped row's gutter span keeps Tailwind's w-11 (44px) while
   this surface draws a 36px avatar, so every line after the first is indented
   8px. Match the gutter to the avatar so the text lines up under it. */
#dev-topic-thread #gc-thread-messages:is([data-language="request"], [data-language="change"]) .gc-msg[data-grouped] > .gc-msg-gutter { width: 36px; }
#dev-topic-thread #gc-thread-messages:is([data-language="request"], [data-language="change"]) .gc-msg-time { font-size: inherit; }
#dev-topic-thread #gc-thread-messages:is([data-language="request"], [data-language="change"]) .gc-msg-content {
  font-size: 17px;
  line-height: 1.3;
  color: var(--text-primary);
}
/* Messages' own desktop scale: 15 over 13, the words at 15. */
@media (min-width: 768px) {
  #dev-topic-thread #gc-thread-messages:is([data-language="request"], [data-language="change"]) .gc-msg > .min-w-0 > .flex > .truncate { font-size: 15px; }
  #dev-topic-thread #gc-thread-messages:is([data-language="request"], [data-language="change"]) .gc-msg > .min-w-0 > .flex > .shrink-0 { font-size: 13px; }
  #dev-topic-thread #gc-thread-messages:is([data-language="request"], [data-language="change"]) .gc-msg > .min-w-0 > .leading-snug,
  #dev-topic-thread #gc-thread-messages:is([data-language="request"], [data-language="change"]) .gc-msg-content { font-size: 15px; line-height: 1.4; }
}
.gc-msg-via { color: var(--text-muted); white-space: nowrap; }
/* Something that happened: one muted line, its glyph in the avatar column. */
#dev-topic-thread #gc-thread-messages:is([data-language="request"], [data-language="change"]) .dev-request-event,
.dev-request-event {
  display: flex;
  align-items: baseline;
  gap: 12px;
  padding: 6px 16px;
  text-align: start;
  font-size: 15px;
  color: var(--text-muted);
}
.dev-request-event-glyph { flex: 0 0 36px; text-align: center; font-size: 15px; }
.dev-request-event-text { min-width: 0; overflow-wrap: anywhere; }
.dev-request-event-text b { color: var(--text-primary); font-weight: 600; }
.dev-request-event-time { white-space: nowrap; }
.dev-request-event-link {
  appearance: none;
  border: 0;
  background: none;
  padding: 0;
  cursor: pointer;
  font: inherit;
  color: var(--accent);
  font-weight: 600;
  text-decoration: none;
}
.dev-request-event-link:hover { text-decoration: underline; }
@media (max-width: 640px) {
  .dev-request { padding: 0 8px; }
  .dev-request-title { font-size: 18px; }
  .dev-request-step-label { font-size: 12px; }
}

/* ═══════════════════════════════════════════════════════════════════════
   #4455: A CHANGE'S PAGE, the same thread (`.dev-request.dev-change`), with
   the change as its root post (dev-board/topic/change-head.tsx): the title,
   the summary as the request page's quote, one row with the requests it
   addresses and the thanks, then two cards one above the other (Votes, then
   Testing: each its name and figure over its bar, its button beside them and
   one line under), then the Before and after card. Its stream is the
   request page's (`[data-language="change"]` above).

   A bar still moving is drawn in the lit ink; a finished one is full and
   green, with a green check and figure (AGENTS.md, "a finished progress bar
   may be green"): done is good news here, not a state to quieten.
   ═══════════════════════════════════════════════════════════════════════ */
.dev-change-via { margin-inline-start: -4px; color: var(--text-muted); }
.dev-change-stale { margin: 6px 0 0; font-size: 13px; color: var(--text-muted); }
.dev-change-root .dev-topic-hero-more { margin-top: 6px; }
.dev-change-root .dev-change-issues { margin-top: 10px; }

/* The requests it addresses, and the thanks: one row. */
.dev-change-addresses { margin-top: 10px; }
.dev-change-chips {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  column-gap: 6px;
  row-gap: 6px;
}
.dev-change-chips-lead { grid-area: 1 / 1; font-size: 13px; color: var(--text-muted); }
.dev-change-chips-first { grid-area: 1 / 2; min-width: 0; display: flex; align-items: center; gap: 6px; }
.dev-change-chips .dev-topic-issue { flex: 0 1 auto; min-width: 0; max-width: 100%; }
.dev-change-reqs-more { flex: none; }
/* The thanks host is `display: contents`, so the button's wrap is the cell. */
.dev-change-chips .dev-change-thanks { grid-area: 1 / 3; justify-self: end; margin-inline-start: 4px; }
.dev-change-chips:not(:has(.dev-change-chips-first)) .dev-change-thanks { grid-area: 1 / 1 / 2 / -1; justify-self: start; margin-inline-start: 0; }
.dev-change-chips-rest {
  grid-area: 2 / 2 / 3 / -1;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 6px;
  min-width: 0;
}

/* Votes, then Testing: two cards in the Messages surface. */
.dev-change-pair { margin-top: 12px; display: grid; gap: 8px; }
/* 6 Nov 2026 (#6419): on the change's own page the Votes and Testing pair
   keeps the change's own state in sight while the reader scrolls. #6615
   (11 Nov 2026): it does so without changing the page's flow. The cards stay
   at full size where they are (`.dev-change-pair[data-stick]`, in flow and
   never sticky); the one-line rows float in `.dev-change-pair-float`, a
   zero-height sticky holder between the mark and the pair that travels within
   the article's content column and lets go, with no extra code, where the
   change's own content ends above the replies. The strip is absolutely
   positioned, so appearing or going changes no height above or below the
   reader: the first version shrank the pair in place and gave the lost height
   back as a margin, and while the cards updated that made the page jump back
   and forth. Because nothing in the flow resizes, the switch cannot feed
   scroll anchoring, and the pair opts out of being an anchor as well. The
   mark is the 1px sentinel above the pair that says when it has left the top
   of the scroller: it has an area to observe and its -1px margin moves
   nothing, and `-4px` is `.messages-thread-scroll`'s own top padding, as the
   old pin had. `--dc-sheet-solid` is the plane colour for a surface content
   passes behind, so nothing shows through the card's padding or the strip's
   gap. */
.dev-change-pair-mark { display: block; height: 1px; margin-bottom: -1px; }
.dev-change-pair[data-stick] { overflow-anchor: none; }
.dev-change-pair-float { position: sticky; top: -4px; z-index: 10; height: 0; overflow-anchor: none; }
.dev-change-pair-float > .dev-change-pair { position: absolute; inset-inline: 0; top: 0; margin-top: 0; }
.dev-change-pair[data-stuck] { gap: 4px; padding-block: 8px; background-color: var(--dc-sheet-solid); }
.dev-change-pair[data-stuck] .dev-change-gate { padding: 8px 12px; }
.dev-change-pair[data-stuck] :is(.dev-change-bar, .dev-change-gate-facts, .dev-change-gate-note,
  .dev-change-gate-why, .dev-change-gate-fix) { display: none; }
.dev-change-pair[data-stuck] [data-change-gate-line="testing"] .dev-change-gate-act { display: none; }
.dev-change-gate {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  column-gap: 16px;
  padding-block: 12px 12px; padding-inline: 14px 12px;
  border-radius: 16px;
  background: var(--messages-surface);
}
.dev-change-gate-main { min-width: 0; }
.dev-change-gate-act { display: flex; align-items: center; gap: 8px; }
.dev-change-gate-head { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; line-height: 1.3; }
.dev-change-gate-name { display: inline-flex; align-items: center; gap: 6px; font-size: 15px; font-weight: 600; color: var(--text-primary); }
.dev-change-gate-check { width: 14px; height: 14px; color: var(--state-ok); stroke-width: 2.5; }
.dev-change-gate-figure { font-size: 13px; color: var(--text-muted); font-variant-numeric: tabular-nums; text-align: end; }
.dev-change-gate[data-tone="ask"] .dev-change-gate-figure { color: var(--accent); font-weight: 600; }
.dev-change-gate[data-tone="done"] .dev-change-gate-figure { color: var(--state-ok); font-weight: 600; }
.dev-change-gate[data-tone="bad"] .dev-change-gate-figure { color: var(--state-blocked); font-weight: 600; }
.dev-change-gate[data-tone="warn"] .dev-change-gate-figure { color: var(--state-attention); font-weight: 600; }
.dev-change-bar { margin-top: 8px; height: 8px; display: flex; gap: 3px; }
.dev-change-bar-seg {
  position: relative;
  height: 100%;
  min-width: 6px;
  border-radius: 999px;
  overflow: hidden;
  background: color-mix(in srgb, var(--text-muted) 16%, transparent);
}
.dev-change-bar-fill { position: absolute; inset-block: 0 0; inset-inline: 0 auto; border-radius: inherit; transition: width 400ms cubic-bezier(.32, .72, 0, 1); }
.dev-change-bar-fill[data-state="moving"],
.dev-change-gate[data-done="false"] .dev-change-bar-fill[data-state="done"] { background: var(--lit-ink); }
.dev-change-gate[data-done="true"] .dev-change-bar-fill[data-state="done"] { background: var(--state-ok); }
.dev-change-bar-fill[data-state="bad"] { background: var(--state-blocked); }
.dev-change-gate-note { grid-column: 1 / -1; margin: 8px 0 0; font-size: 13px; line-height: 1.4; color: var(--text-muted); }
.dev-change-gate-facts { grid-column: 1 / -1; margin-top: 8px; display: grid; gap: 2px; font-size: 13px; line-height: 1.4; color: var(--text-muted); font-variant-numeric: tabular-nums; }
.dev-change-gate-facts p { margin: 0; }
.dev-change-gate-facts [data-change-vote-fact="tally"] { color: var(--text-primary); }
.dev-change-gate-facts [data-ask="true"] { color: var(--accent); font-weight: 600; }
.dev-change-gate-link {
  appearance: none;
  border: 0;
  background: none;
  padding: 0;
  cursor: pointer;
  font: inherit;
  font-weight: 600;
  color: var(--accent);
}
.dev-change-gate-link:hover { text-decoration: underline; }
/* A failed run: what went wrong, in the card's own ink over the muted line,
   then the author's Fix it with the re-run beside it, and a refusal under
   them when the agent could not take it. */
.dev-change-gate-why { grid-column: 1 / -1; margin: 10px 0 0; font-size: 14px; line-height: 1.45; color: var(--text-primary); overflow-wrap: anywhere; }
.dev-change-gate-fix { grid-column: 1 / -1; display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin-top: 10px; }
.dev-change-gate-fix .gc-vote-btn {
  height: 34px;
  padding: 0 14px;
  gap: 6px;
  font-size: 14px;
  font-weight: 600;
}
@media (prefers-reduced-motion: reduce) {
  .dev-change-bar-fill { transition: none; }
}
/* Reduce motion setting (#6510): the same, when Settings asks for it. */
:where(html[data-motion="reduce"]) .dev-change-bar-fill { transition: none; }

/* The cards' buttons at Messages' size: Preview a neutral pill, the
   re-run the accent one; Vote is the card's own picker button. */
.dev-change-gate-act .gc-vote-btn {
  height: 34px;
  padding: 0 14px;
  gap: 6px;
  font-size: 14px;
  font-weight: 600;
}
.dev-change-gate-act .gc-vote-btn svg { width: 16px; height: 16px; }
.dev-change-gate-act .gc-vote-btn-preview {
  color: var(--text-primary);
  background: var(--messages-surface-2);
  border-color: transparent;
}
.dev-change-gate-act .gc-vote-btn-preview:hover { background: var(--accent-tint); color: var(--accent); }
.dev-change-gate-act .gc-conflict-badge { font-size: 13px; }
/* The thanks, on the Addresses row: a quiet chip, as the row's other chips. */
.dev-change-chips .dev-change-thanks > .gc-vote-btn {
  height: 26px;
  padding: 0 10px;
  gap: 4px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-secondary);
  background: var(--messages-surface);
  border-color: var(--messages-hair);
}
.dev-change-chips .dev-change-thanks > .gc-vote-btn:hover { color: var(--accent); background: var(--accent-tint); }
.dev-change-chips .dev-thanks-tail { display: none; }
/* The zero chip stays out of the row: kudos.js sets [hidden] on the wrap
   while the count is 0, but its Tailwind inline-block would beat the
   preflight rule, so restate it at this specificity. */
.dev-change-chips .dev-change-thanks[hidden] { display: none; }

/* VERSIONS (docs/plans/versions.md): an update's From <original> card,
   under its summary (change-head.tsx UpstreamCard). A gate card's surface
   and radius; the original's tile and name as a row (15 over 13); what it
   brings, each with the check a finished gate wears; then "In <version>"
   over what it does here, quieter, each on a dot. A line about data it
   would change is in the attention ink, the one thing here that asks. */
.dev-change-upstream { margin-top: 12px; padding: 12px 14px; border-radius: 16px; background: var(--messages-surface); }
.dev-change-upstream-head { display: flex; align-items: center; gap: 10px; }
.dev-change-upstream-tile {
  width: 32px; height: 32px; border-radius: 9px; flex: none; overflow: hidden;
  display: inline-flex; align-items: center; justify-content: center; font-size: 17px; font-weight: 700;
}
.dev-change-upstream-tile > img { width: 100%; height: 100%; object-fit: cover; }
.dev-change-upstream-name { display: block; font-size: 15px; font-weight: 650; line-height: 20px; color: var(--text-primary); overflow-wrap: anywhere; }
.dev-change-upstream-sub { display: block; font-size: 13px; line-height: 18px; color: var(--text-muted); }
.dev-change-upstream-list { margin: 10px 0 0; padding: 0; list-style: none; display: grid; gap: 6px; }
.dev-change-upstream-list li { display: flex; align-items: flex-start; gap: 8px; font-size: 14px; line-height: 19px; color: var(--text-primary); overflow-wrap: anywhere; }
.dev-change-upstream-glyph { width: 15px; height: 15px; flex: none; margin-top: 2px; color: var(--state-ok); stroke-width: 2.5; }
.dev-change-upstream-label {
  margin: 12px 0 0; padding-top: 10px; border-top: 1px solid var(--app-sheet-line);
  font-size: 13px; font-weight: 650; color: var(--text-secondary); overflow-wrap: anywhere;
}
.dev-change-upstream-here { margin-top: 6px; }
.dev-change-upstream-here li { font-size: 13px; line-height: 18px; color: var(--text-muted); }
.dev-change-upstream-dot { width: 5px; height: 5px; margin: 7px 5px 0; border-radius: 999px; flex: none; background: currentColor; opacity: .55; }
.dev-change-upstream-warn, .dev-change-upstream-here li.dev-change-upstream-warn { color: var(--state-attention); }
/* Not for your version?: under Votes and Testing, quieter than either, a
   hairline rather than a fill, its one button a neutral pill. */
.dev-change-upstream-skip {
  margin-top: 8px; padding-block: 10px 10px; padding-inline: 14px 12px; border-radius: 16px;
  border: 1px solid var(--app-sheet-line); display: flex; align-items: center; gap: 12px;
}
.dev-change-upstream-skip-title { display: block; font-size: 14px; font-weight: 600; line-height: 19px; color: var(--text-primary); }
.dev-change-upstream-skip-sub { display: block; margin-top: 1px; font-size: 12px; line-height: 16px; color: var(--text-muted); overflow-wrap: anywhere; }
.dev-change-upstream-skip-actions { flex: none; display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 6px; }
.dev-change-upstream-skip-btn {
  appearance: none; border: 0; cursor: pointer; padding: 7px 12px; border-radius: 999px;
  font: inherit; font-size: 13px; font-weight: 600;
  background: color-mix(in srgb, var(--text-muted) 14%, transparent); color: var(--text-primary);
}
.dev-change-upstream-skip-btn:disabled { opacity: .5; cursor: default; }
/* Ask Homeroom bot to fit it is the action there: the accent's pill. */
.dev-change-upstream-fit-btn { background: var(--accent); color: #fff; }
@media (max-width: 420px) {
  .dev-change-upstream-skip { flex-wrap: wrap; }
  .dev-change-upstream-skip-actions { width: 100%; justify-content: flex-start; }
}

/* Before and after: the viewer specs use, its switch beside the title. */
.dev-change-card-name { flex: 1 1 auto; min-width: 0; font-size: 15px; font-weight: 600; color: var(--text-primary); }
.dev-change-shots { margin-top: 8px; border-radius: 16px; overflow: hidden; background: var(--messages-surface); }
.dev-change-shots .shots-viewer { border-radius: 0; box-shadow: none; background: transparent; }
.dev-change-shots .shots-bar { padding-block: 10px 8px; padding-inline: 14px 10px; }
.dev-change-shots .shots-stage { margin: 0 10px; border-radius: 12px; border: 0; }
.dev-change-shots .shots-view-notes { padding: 12px 14px 4px; }
.dev-change-shots .shots-claims { padding: 0 14px 12px; }
.dev-change-shots .shots-noticed { padding: 4px 14px 14px; }
.dev-change-shots-plain { padding: 12px 14px 14px; }
.dev-change-shots-line { margin: 8px 0 0; display: flex; align-items: center; gap: 8px; font-size: 14px; color: var(--text-muted); }
/* The previous version's shots keep their picture under a line that says
   whose they are (change-head.tsx PreviousShotsLine): inside the card it
   sits in the card's own padding; over the slider, and over a request
   page's small pair (thread-changes.tsx ShotsPair), it is a line above. */
.dev-change-shots-previous-line { flex-wrap: wrap; }
.dev-change-shots > .dev-change-shots-previous-line { margin: 0; padding: 10px 14px 4px; }
.dev-thread-shots > .dev-change-shots-previous-line { flex-basis: 100%; margin: 0; }
.dev-change-shots-tiles { margin-top: 8px; }
.dev-change-closed-note { margin: 0; padding: 6px 16px 12px; font-size: 15px; color: var(--text-muted); }
/* 1 Nov 2026 (one page per thread): a change on its request's page carries
   what only its own page had. Its ⋯ is the header's disc, smaller, at the
   end of its line beside its status pill. */
.dev-thread-change-menu {
  display: inline-flex; align-items: center; justify-content: center; flex: 0 0 auto;
  width: 32px; height: 32px; border-radius: 9999px; color: var(--text-primary);
  background: var(--messages-surface); box-shadow: var(--messages-disc-shadow); transition: background 150ms;
}
.dev-thread-change-menu:hover { background: var(--messages-surface-2); }
.dev-thread-change-menu svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.dev-thread-change-menu:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.dev-thread-change-summary { margin-top: 6px; }
.dev-thread-change-summary .dev-request-ask-text { font-size: 14px; }
/* Its before and after, small: two stills side by side, then Expand. The
   viewer they open is its page's, kept here as a closed popover: shut it
   takes no room, open it is drawn over the page (.shots-viewer:popover-open). */
.dev-thread-shots { margin-top: 8px; display: flex; align-items: flex-end; gap: 10px; flex-wrap: wrap; }
.dev-thread-shots-pair { display: flex; gap: 6px; padding: 0; border: 0; background: none; cursor: zoom-in; border-radius: 10px; }
.dev-thread-shots-pair:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.dev-thread-shot { position: relative; display: block; width: 112px; height: 70px; border-radius: 10px; overflow: hidden;
  background: var(--messages-surface); outline: 1px solid var(--app-sheet-line); outline-offset: -1px; }
.dev-thread-shot img { display: block; width: 100%; height: 100%; object-fit: cover; object-position: top center; }
.dev-thread-shot-none { display: block; width: 100%; height: 100%; }
.dev-thread-shot-label { position: absolute; inset-inline-start: 4px; bottom: 4px; padding: 1px 6px; border-radius: 9999px;
  font-size: 11px; font-weight: 600; line-height: 16px; color: #fff; background: rgba(0, 0, 0, 0.55); }
.dev-thread-shots-expand { padding: 4px 10px; border: 0; border-radius: 9999px; font-size: 13px; font-weight: 600;
  color: var(--text-primary); background: var(--state-neutral-bg); }
.dev-thread-shots-expand:hover { text-decoration: underline; }
.dev-thread-shots-viewer { flex-basis: 100%; height: 0; }
.dev-thread-shots-viewer > .dev-change-shots-body > :not(.shots-viewer),
.dev-thread-shots-viewer .shots-viewer:not(:popover-open) { display: none; }
/* Competing changes fold under their ballot: a line each, which opens. */
.dev-thread-fold { padding: 8px 0; border-top: 1px solid var(--app-sheet-line); }
.dev-thread-fold:first-child { border-top: 0; }
.dev-thread-fold-head { display: block; padding: 2px 0; border: 0; background: none; border-radius: 8px; }
.dev-thread-fold-head:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
/* A reply written on one of the request's changes says which, after its time. */
.gc-msg-on-change { margin-inline-start: 6px; font-size: 12px; color: var(--text-muted); }
/* #5007: a change built for a request points its replies at the request
   where its conversation lives. The `p` variant sits above the "N replies"
   row; the `div` one replaces the "No replies yet" row and keeps that
   row's hairline. Same spacing and type as the reply-count row. */
p.dev-change-issue-pointer {
  margin: 0;
  padding: 2px 16px 4px;
  color: var(--text-muted);
  font-size: 13px;
}
.dev-change-issue-link { color: var(--accent); font-weight: 600; text-decoration: none; }
.dev-change-issue-link:hover { text-decoration: underline; }

/* Shot details, in the Details sheet. */
.dev-shot-details-claims { margin: 6px 0 0; padding-inline-start: 18px; display: flex; flex-direction: column; gap: 8px; font-size: 13px; }
.dev-shot-details-meta, .dev-shot-details-flow { margin-top: 2px; color: var(--text-muted); }
.dev-shot-details-builds { margin: 10px 0 0; display: flex; flex-wrap: wrap; gap: 6px; font-size: 12px; color: var(--text-muted); }

@media (max-width: 640px) {
  /* The requests take the row's width; the thanks goes on a line of its own. */
  .dev-change-chips { grid-template-columns: auto minmax(0, 1fr); }
  .dev-change-chips .dev-change-thanks { grid-area: 3 / 1 / 4 / -1; justify-self: start; margin-inline-start: 0; }
  .dev-change-chips:not(:has(.dev-change-chips-first)) .dev-change-thanks { grid-area: 1 / 1 / 2 / -1; }
  /* The post's body takes the sheet's width: a small avatar beside the
     name, then the title, the summary and its cards at full width. */
  .dev-change-root { position: relative; display: block; }
  .dev-change-root > [aria-hidden="true"]:first-child {
    position: absolute;
    inset-inline-start: 12px;
    top: 4px;
    width: 24px;
    height: 24px;
    border-radius: 8px;
    font-size: 11px;
  }
  .dev-change-root .messages-message-head { padding-inline-start: 32px; min-height: 24px; align-items: center; }
  /* A taller frame for a shot on a phone. */
  .dev-change-shots .shots-stage { margin: 0 8px; aspect-ratio: 4 / 5; }
  /* The card's buttons take a row of their own, under its line, so the
     name, figure and bar keep the card's width. */
  .dev-change-gate { grid-template-columns: minmax(0, 1fr); }
  .dev-change-gate-act { order: 1; flex-wrap: wrap; margin-top: 10px; }
  .dev-change-gate-head { flex-wrap: nowrap; row-gap: 2px; }
  .dev-change-gate-name { flex: none; min-width: 0; }
  .dev-change-gate-figure { min-width: 0; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
  /* #6419: the stuck pair keeps only the heading, the figure and the vote,
     a little tighter; its note stays on the full card in the thread. The
     Vote button goes back on the card's own line, so the card stays one
     line on a phone as it does on a computer. */
  .dev-change-pair[data-stuck] .dev-change-gate { grid-template-columns: minmax(0, 1fr) auto; padding: 8px 12px; }
  .dev-change-pair[data-stuck] .dev-change-gate-act { order: 0; margin-top: 0; flex-wrap: nowrap; }
}

/* ── The Workshop ──────────────────────────────────────────────────
   features/dev-board/workshop/workshop.tsx. The lander's own chrome:
   the strips above the themes, the theme cards, the folded rows inside
   them. An UNFOLDED row is `.dev-feed-entry` and takes the sheet rules
   above unchanged; what follows is only what surrounds it. Colours come
   from the same tokens the session sheet and the cards read, so the
   Workshop is the board's language and not a second one. */
.dev-ws { display: flex; flex-direction: column; gap: 10px; }
.dev-ws-eyebrow {
  font-size: 11px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase;
  color: var(--text-muted);
}
.dev-ws-strip {
  background-color: var(--dc-sheet-fill);
  backdrop-filter: var(--dc-frost);
  -webkit-backdrop-filter: var(--dc-frost);
  border-radius: 22px;
  padding: 12px 14px;
  box-shadow: 0 0 0 1px var(--app-sheet-line) inset;
  display: flex; flex-direction: column; gap: 8px;
}
/* CENTRE, not baseline. Baseline was right while the only thing beside the
   eyebrow was a 22px pill; with a 30px ring in the line the eyebrow's
   baseline aligned to the bottom of the ring and the two read as two rows. */
.dev-ws-strip-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.dev-ws-strip-text { margin: 0; font-size: 14px; color: var(--text-primary); }
/* ── ONE HEADING, FOR EVERY SECTION ON THE TAB ───────────────────────────
   There were two vocabularies doing one job: three panes wore
   `.dev-ws-eyebrow` — 11px, caps, letterspaced, muted — and the fourth wore
   a sentence-case label with a count beside it and an action at its far
   end. The second is the one that reads as a heading; the caps one reads as
   a tag stuck on a box. So it is this, everywhere, and the sections are
   told apart by what they HOLD rather than by four weights of label.

   `.dev-ws-since-head` keeps its own class because it also carries Clear
   and the disabled state that goes with it; the two match by value. */
.dev-ws-head { display: flex; align-items: center; gap: 8px; }
.dev-ws-head-title { font-size: 14px; font-weight: 600; color: var(--text-primary); }
.dev-ws-head-n {
  height: 19px; min-width: 19px; padding: 0 6px; border-radius: 999px;
  background: var(--brand-tint); color: var(--brand-ink);
  font-size: 11.5px; font-weight: 700;
  display: grid; place-items: center;
  font-variant-numeric: tabular-nums;
}
/* A heading's count in words, muted, beside it ("1 open", "2 since your
   last visit"): a phrase, not a pill (After-Workshop-B). */
.dev-ws-head-sub { font-size: 13px; color: var(--text-muted); }
/* ── The general discussion, at the foot of the dashboard pane ───────────
   No pill and no card. A rounded capsule on a rounded pane is a shape
   inside a shape, and this pane already has an internal rhythm — hairline,
   block, hairline — that the weeks above it use. The row joins it: one more
   rule, then the row, full-bleed to the pane's own padding. */
.dev-ws-chat-row {
  display: flex; align-items: center; gap: 9px; width: 100%;
  margin-top: 12px; padding: 12px 0 0;
  border: 0; border-top: 1px solid var(--app-sheet-line);
  background: none; cursor: pointer;
  font: inherit; font-size: 13px; color: var(--text-secondary); text-align: start;
}
.dev-ws-chat-row:hover .dev-ws-chat-said { color: var(--text-primary); }
.dev-ws-chat-row:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 8px; }
/* The glyph keeps the card's chip geometry but drops its tinted plate: on a
   row this size the plate was the largest object in the line. */
.dev-ws-chat-row > .dev-card-icon {
  flex: none; width: 20px; height: 20px;
  background: transparent; border-radius: 0;
}
.dev-ws-chat-row > .dev-card-icon > svg { width: 17px; height: 17px; }
/* TWO LINES: what this is, then the last thing said. The title is the
   row's own name and wraps never; the saying under it is somebody else's
   sentence of any length, and a row that grows to hold it stops being a
   row — so that one clips. */
.dev-ws-chat-text {
  flex: 1 1 auto; min-width: 0;
  display: flex; flex-direction: column; gap: 1px;
}
.dev-ws-chat-title { font-size: 13px; font-weight: 600; color: var(--text-primary); }
.dev-ws-chat-said {
  min-width: 0; font-size: 12.5px; color: var(--text-muted);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
/* The glyph aligns to the TITLE rather than to the middle of a two-line
   block, which is where a centred row would put it. */
.dev-ws-chat-row { align-items: flex-start; }
.dev-ws-chat-row > .dev-card-icon { margin-top: 1px; }
/* A dated week IS its dates (the since list's headings, workshop.tsx
   SinceWeekBlock), so they take the heading's own weight and ink; the live
   week wears its range as a muted gloss. `tabular-nums` because a column
   of ranges is read down. */
.dev-ws-card-dates { font-variant-numeric: tabular-nums; }
.dev-ws-card-range {
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0;
  color: var(--text-muted);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
/* ── The pane's reveal control ──────────────────────────────────
   ONE style for "put more of this pane on screen": the step backwards
   through the weeks, and the since-list's "Show 8". They are the same act
   and they were two different objects — the first a left-aligned grey pill,
   the second a grey pill in a lane of left-aligned text — and in both cases
   the pill made the most OPTIONAL thing in its block the most solid-looking
   thing in it.

   Quiet and centred instead: no border, no fill, muted 12px, the accent on
   hover, and a caret pointing the way the content arrives. Centred over
   full-width content rather than hung off one side of it. */
.dev-ws-reveal {
  display: flex; align-items: center; justify-content: center; gap: 5px;
  width: 100%; padding: 3px 8px;
  border: 0; background: transparent;
  font-size: 12px; font-weight: 600; letter-spacing: .01em;
  color: var(--text-muted);
  cursor: pointer;
}
.dev-ws-reveal:hover { color: var(--accent); }
.dev-ws-reveal:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 8px; }
/* There is no ChevronUpIcon in the kit and one caret does not earn a 22nd
   module, so UP is ChevronDownIcon turned over — the same trick the lane
   headings already use on their own chevron.

   Which way it points is which way the content arrives: the week walk grows
   UPWARDS (each press puts an older window above the one you were reading),
   so its caret is always up; the since-list opens DOWNWARDS, so its caret
   points down and turns over once the rows are showing. */
/* Left-aligned, in the lane's own text column.
   Centring is right for the week walk: it sits under a stack of full-width
   cards and belongs to all of them. The since-list's control sits in a lane
   of left-aligned type — a bulleted heading and its note — and centred it
   read as a third, unrelated thing floating mid-lane. Indented to the
   note's 16px so the two share a left edge. */
.dev-ws-reveal-start { justify-content: flex-start; padding-inline-start: 16px; }
.dev-ws-reveal-chev { width: 14px; height: 14px; }
/* ── Since your last visit ───────────────────────────────────
   A HEADING over rows, not a disclosure. It was one collapsed line with a
   caret, on the reasoning that most visits do not need the fact — and what
   that produced was a strip nobody opened: the count said something had
   moved and the rows saying what were behind a press. The bargain is the
   LIST'S LENGTH now (three a week, then a few more a press, and `Show an
   earlier week`), not its existence, which is what the week walk one pane
   up already does with its own history.

   `.dev-ws-since-head` is what `.dev-ws-since-row` was, minus everything
   that said "press me": no pill radius, no pointer, no hover ink, no caret.
   It is the pane's eyebrow, with a count riding it.

   These rules live beside the reveal control the strip shares, not under
   the tab they were first written for. They were born inside the old
   Needs-you block, and #2080, rewriting that tab into a feed, took them out
   with the rest of it — while the strip had already moved to Current status
   in #2065 and its markup went on emitting the classes. Two bare inline
   spans were what was left: "Since your last visit2" (#2097). */
.dev-ws-since-head {
  display: flex; align-items: center; gap: 8px;
  width: 100%; padding: 2px 2px 0;
  font-size: 13px; font-weight: 600;
  color: var(--text-muted); text-align: start;
}
.dev-ws-since-label { flex: 1 1 auto; min-width: 0; }
.dev-ws-since-n {
  flex: none; display: inline-flex; align-items: center; justify-content: center;
  min-width: 20px; height: 20px; padding: 0 6px; border-radius: 999px;
  background: var(--brand-tint); color: var(--brand-ink);
  font-size: 11px; font-variant-numeric: tabular-nums;
}
/* `Show an earlier week` steps the since list back a week: `.dev-ws-reveal`,
   centred, caret down at what it is about to reveal, under a stack of
   full-width rows, so it takes the centred form rather than
   `.dev-ws-reveal-start`'s lane indent.
   #3524: under a week it also takes the week's own hairline, the rule the
   week it reveals will arrive under. It sat bare beneath that week's "N
   more new" before, and the two read as one control said twice; the rule
   puts it outside the week, and the week's own reveal stays inside it
   (`.dev-ws-since-week-more`). "N new" further back rides it in the accent:
   a number that asks for the reader. */
.dev-ws-since-more { margin-top: 2px; }
.dev-ws-since-week + .dev-ws-since-more {
  margin-top: 6px; padding-top: 10px;
  border-top: 1px solid var(--app-sheet-line);
}
.dev-ws-since-more-new { color: var(--accent); }
/* #2183: the control is always drawn and DISABLED when the walk is over,
   rather than leaving — so it reads as spent, not pressable. */
.dev-ws-reveal:disabled { color: var(--text-muted); opacity: .45; cursor: default; }
.dev-ws-reveal:disabled:hover { color: var(--text-muted); }
/* `Clear` rides the far end of the heading row (#2183) — the notifications
   sheet's "Mark all read", drawn the same size as the heading's own type
   and in its muted ink, the accent on hover. Pushed right by its own
   margin so the label and the count keep the gap they had. Disabled when
   there is nothing to clear rather than absent, so the row does not reflow
   between a quiet visit and a busy one. */
.dev-ws-since-clear {
  flex: none; margin-inline-start: auto; padding: 2px 6px;
  border: 0; border-radius: 6px; background: transparent;
  font-size: 12px; font-weight: 600; letter-spacing: .01em;
  color: var(--text-muted);
  cursor: pointer;
}
.dev-ws-since-clear:hover { color: var(--accent); }
.dev-ws-since-clear:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.dev-ws-since-clear:disabled { opacity: .45; cursor: default; }
.dev-ws-since-clear:disabled:hover { color: var(--text-muted); }
/* The line across the list (#2183): where a week's rows cross from what is
   new into what the reader has already seen (#3524: in the same column,
   under the same one reveal, rather than behind a fold of their own). The heading's own shape, one
   size down, with the count of the whole rest riding it in plain ink rather
   than the brand tint — these rows are not news. */
.dev-ws-since-seen {
  display: flex; align-items: center; gap: 8px;
  width: 100%; margin-top: 6px; padding: 2px 2px 0;
  font-size: 12px; font-weight: 600;
  color: var(--text-muted); text-align: start;
}
.dev-ws-since-seen-label { flex: 1 1 auto; min-width: 0; }
.dev-ws-since-seen-n {
  flex: none; display: inline-flex; align-items: center; justify-content: center;
  min-width: 20px; height: 20px; padding: 0 6px; border-radius: 999px;
  background: var(--bg-secondary); color: var(--text-muted);
  font-size: 11px; font-variant-numeric: tabular-nums;
}

/* ── The three destinations ──────────────────────────────────
   A segmented rail pinned to the FOOT of the lander. Sticky rather than
   fixed: it belongs to this surface, releases with it, and `bottom: 0`
   works against #dev-forum-scroll for the same reason the pane head's
   `top: 0` does — that scroller is the reading area.

   `.platform-safe-bar` (app.css, top) adds the device's home-indicator
   inset, which is why no bottom padding is written here. */
/* AGAINST THE BOTTOM, always — and neither `sticky` nor `fixed` does that on
   its own here. Sticky pins a bar only while its own container is taller
   than the view, so on a short Current status it sat wherever the content
   happened to end, halfway up the screen. Fixed was worse: an ancestor of
   this surface carries `backdrop-filter`, which makes it the containing
   block for fixed descendants, so "bottom: 0" meant the bottom of a frosted
   panel rather than of the screen.

   So the LANDER is given the reading area's height (the same viewport
   arithmetic the deck uses) and the bar is pushed to its foot with
   `margin-top: auto`. Sticky on top of that keeps it in view while a long
   tab scrolls under it. */
/* `max(100%, …)`, because neither half works alone. In the NATIVE layout
   #dev-forum-scroll has a definite height, so 100% is exactly the reading
   area. In the BROWSER layout it does not (app.css forces #app-view to
   `height: auto` so the page scrolls), and a percentage min-height against
   an indefinite parent resolves to 0 — which is what left the bar floating
   halfway up a short tab. The viewport arithmetic is the floor under that.

   It subtracts the header and the insets and NOT the tab rail: the rail is
   inside this box, pushed to its foot by the tab body's `flex: 1`.
   Subtracting it here as well was the bug — the lander came out one rail
   short of the space it had, and the bar stopped that far above the
   bottom. */
/* ── The lander fills what is left of the scroller ─────────────────────
   `min-height: max(100%, var(--ws-area))` is what this replaces, and it was
   wrong in a way no amount of tuning the rail could reach: in FIREFOX the
   floor is simply not applied. Measured on the real app (Gecko 155, the
   native layout): `.dev-ws` computed `min-height: max(100%, 806.5px)` and
   used a height of 649px, leaving 121px of unused scroller below it. A
   sticky bar cannot sit below its own parent's bottom edge, so the rail
   rested there and every `--ws-gap` adjustment moved a number that was never
   the problem. Chromium applies the same declaration correctly, which is
   exactly why a headless harness reported 8px while the app floated — the
   percentage inside the `max()` is indefinite here, and the two engines
   disagree about what that makes the whole expression.

   So: NO PERCENTAGE, and two mechanisms, one per layout.

   NATIVE — the scroller has a definite height, so the chain flexes and the
   lander takes what is left of it. Nothing is computed from the viewport, so
   nothing depends on `--platform-header-h` being accurate or on how much
   chrome sits above `#dev-body`; measured, that offset is 47px, which a
   viewport subtraction would have to know and does not. Scoped by `:has()`
   so the other Dev views, which share this scroller, keep their block flow.

   BROWSER-SCROLLER — the scroller is auto-height (app.css forces
   `#app-view { height: auto }` so the page scrolls), so there is no
   remaining space to take and flex gives content height. The viewport floor
   is the right tool there, as a PLAIN LENGTH.

   Both verified against the live app rather than a replica: the same two
   mechanisms, applied by hand in the page, closed the gap from 121px to 9px. */
#dev-forum-scroll:has(> #dev-body > #dev-workshop) { display: flex; flex-direction: column; }
#dev-body:has(> #dev-workshop) {
  flex: 1 1 auto; min-height: 0;
  display: flex; flex-direction: column;
}
/* `width: 100%` IS LOAD-BEARING, not belt and braces. `#dev-workshop` centres
   itself with `margin: 0 auto`, and auto margins on the cross axis of a flex
   column ABSORB the free space instead of stretching — so as a flex item it
   shrank to its content. Measured: the pane went 760 to 640 on By category
   and 1432 to 310 on By stage, which is the column collapsing, not widening.
   With an explicit width the auto margins go back to centring a full-width
   box inside its `max-width`, which is what they did as a block. */
#dev-workshop:has(> .dev-ws) {
  flex: 1 1 auto; min-height: 0; width: 100%;
  display: flex; flex-direction: column;
}
#dev-workshop > .dev-ws { flex: 1 1 auto; width: 100%; }
/* ...AND THE FITTED TAB HAS TO BE ABLE TO SHRINK INSIDE IT. `.dev-ws` is a
   flex ITEM of the chain above, and a flex item's automatic minimum size is
   its CONTENT — every other link here carries `min-height: 0` for that
   reason and this one did not. So on Needs you a long summary did not make
   `.dev-ws-needs-scroll` scroll: the deck refused to shrink, the lander grew
   instead, and the answers and the ask box went down with it. Measured at
   402x874 against a nine-paragraph summary: `.dev-ws` 1803px tall with the
   composer 910px below the fold, in the NATIVE layout — the one whose
   definite scroller was supposed to bound it — and at a 34px inset as well
   as at none.
   ONLY THAT TAB. The other two are meant to grow: #dev-forum-scroll is the
   scroller they scroll in, and `.dev-ws-tabbody` is not a scroller itself,
   so shrinking them to the viewport would clip what they hold rather than
   make it reachable. */
#dev-workshop > .dev-ws[data-ws-tab="needs"],
#dev-workshop > .dev-ws[data-ws-tab="discussion"],
#dev-workshop > .dev-ws[data-ws-tab^="c:"] { min-height: 0; }
/* …AND ON THE TWO TABS THAT GROW, THE LINKS ABOVE MUST NOT SHRINK (#3053).
   `min-height: 0` on #dev-body and #dev-workshop is what lets Needs you be
   bounded; on Current status and All items it let both shrink to the
   scroller's height while `.dev-ws` kept its content height and overflowed
   them. A scroller's block-end padding is added after its in-flow CHILDREN,
   not after a descendant that overflows one, so `.platform-safe-scroll` on
   #dev-forum-scroll reserved nothing: at max scroll the last item's foot sat
   exactly at the screen's bottom edge, under the fixed tab bar, with no way
   to scroll it clear. Native layout only — in the browser layout the
   scroller is auto-height and nothing shrinks. `flex-shrink: 0` keeps the
   grow (the lander still fills a short tab) and gives the padding back. */
#dev-body:has(> #dev-workshop > .dev-ws:not([data-ws-tab="needs"]):not([data-ws-tab="discussion"]):not([data-ws-tab^="c:"])),
#dev-workshop:has(> .dev-ws:not([data-ws-tab="needs"]):not([data-ws-tab="discussion"]):not([data-ws-tab^="c:"])) { flex-shrink: 0; }
html[data-browser-scroller] .dev-ws { min-height: var(--ws-area); }
/* ── A SHORT TAB STILL HAS SOMETHING TO SCROLL (#3520) ──────────────────
   "Unable to over scroll down on hub page (but can on workshop)", in the
   installed iPhone app: on the Hub neither end rubber-banded and a pull from
   the top did not stretch, while the Workshop tab of the same page did both.

   Nothing on the Hub turns the gesture off. Measured in the installed layout
   at 390x844 (standalone, an iPhone's agent): both tabs scroll in the one
   #dev-forum-scroll, with the same overflow (auto), overscroll (contain) and
   touch-action (auto) on it and on every ancestor; neither holds a nested
   scroller, a touch-action or an overscroll rule of its own; and the kit's
   pull binds to the scroller on both. What differs is the RANGE. The chain
   above fills the scroller whenever a growing tab is shorter than the screen
   ("the lander still fills a short tab"), to exactly its height and not a
   pixel more: the Hub measured scrollHeight 799 against clientHeight 799,
   nothing to scroll, and so did a fresh project's Workshop tab. The Workshop
   tab the report compares against is the one that runs past the screen once
   a project has history. iOS only rubber-bands a box that can scroll; one
   with no range hands the drag to the document, which the installed shell
   holds still on purpose (`html, body`: `overflow: hidden`,
   `overscroll-behavior-y: none`), so neither end moved.

   So a growing tab is always ONE PIXEL taller than the scroller: a 1px box
   hung 1px below the scroller's bottom edge, which puts that pixel into its
   scrollable overflow whatever the content does. The same range a long tab
   has, so the same bounce at both ends and the same pull at the top as the
   Workshop's. Past the fold it is a transparent pixel in the middle of the
   content and changes nothing.

   ABSOLUTE, AND OFFSET FROM THE SCROLLER'S OWN EDGE, because the two
   obvious ways cannot work here. A 1px spacer in flow is a flex item of this
   chain, and the grow above takes it back: the lander fills what is left and
   the total stays the scroller's height. `min-height: calc(100% + 1px)` is a
   percentage floor in this chain, which is exactly what Firefox dropped (the
   note above). An absolute box's offsets are against its containing block's
   padding box, which is definite in every engine, so the scroller becomes
   that block (`position: relative`, no z-index: no new stacking context; and,
   measured on all three growing tabs, nothing inside it was positioned
   against anything further out). Nor does
   it touch the scroller's bottom padding, the tab-bar clearance #3053 relies
   on.

   ONLY WHERE IT BOUNCES AND ONLY WHERE THIS IS THE SCROLLER: a phone
   (`pointer: coarse` under 700px; a pixel of range would put a scrollbar on
   a desktop window, and from 700px a scrolled strip draws its pinned band),
   and not in a phone browser, where the document scrolls
   (`data-browser-scroller`) and the pixel would lengthen the page. Not Needs
   you or Discussion either: those are fitted on purpose and scroll inside. */
@media (max-width: 699.98px) and (pointer: coarse) {
  html:not([data-browser-scroller]) #dev-forum-scroll:has(> #dev-body > #dev-workshop > .dev-ws:not([data-ws-tab="needs"]):not([data-ws-tab="discussion"]):not([data-ws-tab^="c:"])) {
    position: relative;
  }
  html:not([data-browser-scroller]) #dev-forum-scroll:has(> #dev-body > #dev-workshop > .dev-ws:not([data-ws-tab="needs"]):not([data-ws-tab="discussion"]):not([data-ws-tab^="c:"]))::after {
    content: '';
    position: absolute; inset-inline-start: 0; bottom: -1px;
    width: 1px; height: 1px;
    pointer-events: none;
  }
}
/* The tab body takes the space the tabs above it leave. */
.dev-ws-tabbody {
  flex: 1 1 auto; min-height: 0;
  display: flex; flex-direction: column; gap: 10px;
}
.dev-ws-tabs {
  /* AT THE HEAD OF THE PAGE, IN FLOW (#2767). On a phone this was a pill
     FIXED to the foot of the window, which took a portal out of the Dev
     frame's frost to achieve, a token for its box, a token for the air under
     it and a clearance on every tab so content could scroll out from beneath
     it. The owner moved it to the top, under the header, where the app
     switcher drops down from — and there it is simply the first thing in the
     column, taking its own space, overlaying nothing.

     That also ended #2769: the portal's anchor lived outside #app-view, so
     hiding the app view for Messages, Discover or Me left the pill on screen.

     RELATIVE, not static: the bar is the containing block for the selection
     marker and the element workshop.tsx measures `offsetLeft`/`offsetTop`
     against. Not sticky: the pane head below it is the part that pins, and
     two sticky bands at `top: 0` would stack on each other.

     A ROW, NOT A SURFACE (#2934). This was the pill itself, with the "+" as
     its last cell, and the "+" read as a fourth tab. The pill's material
     moved onto its two items (the tab list and the "+", below), and this gap
     is the air between them. */
  order: 0;
  position: relative;
  display: flex; gap: 6px;
}
/* A GLYPH BESIDE ITS LABEL, 40px tall. It was a glyph OVER its label, 58px,
   while this was a thumb bar at the foot of the window; at the head of the
   page it is a segmented control — the shape the wide layout already draws —
   and a 72px band there would spend a sixth of a phone's height before the
   first card. 40 still clears the shell's 44px minimum once the pill's own
   padding is counted, and the glyph still carries the scanning if a label
   has to ellipsize on the narrowest phone. */
.dev-ws-tab {
  /* CONTENT-WEIGHTED, not equal thirds: "Current status" is twice "All
     items", and three equal cells ellipsized it at 390px while the other two
     sat in air. The spare width is still shared out, so the pill stays full.
     THE "+" TAKES A 50px CIRCLE AFTER THE PILL, 6px off it (#2934; it was a
     40px cell inside it), and the tabs pay for it out of their own padding
     (8px to 4px a side) and glyph gap (5px to 4px), not out of their labels:
     at 400px, the narrowest width that draws the glyphs, measured in the
     headless harness's DejaVu Sans — wider than SF Pro or Roboto — the three
     labels need 316px at rest and the pill leaves them 322, so "Current
     status" is still whole beside the "+" and the spare 6px is shared back
     out. */
  flex: 1 1 auto; min-width: 0;
  display: inline-flex; flex-direction: row;
  align-items: center; justify-content: center; gap: 4px;
  height: 40px; padding: 0 4px;
  border: 0; border-radius: 999px;
  background: transparent;
  color: var(--text-muted);
  font: inherit; font-size: 12px; font-weight: 600; letter-spacing: .01em;
  white-space: nowrap; overflow: hidden;
  cursor: pointer;
}
/* THE TRACK IS INERT ON A PHONE. `.dev-ws-tabs` is itself the full-width
   row there, so the wrapper the desktop layout needs must not introduce a
   box. `display: contents` removes it from the layout entirely and its two
   children — the tab list and the "+" — are the nav's flex items. */
.dev-ws-tabtrack { display: contents; }
/* THE TAB LIST takes the row's width less the "+" and the gap before it. A
   real box at both widths (the `tablist` role lives here, and a role on a
   `display: contents` node is one some screen readers drop), and not
   positioned: the tabs' `offsetLeft` must keep resolving against the nav,
   where the marker is. 2px between segments, the desktop track's own step. */
.dev-ws-tablist { flex: 1 1 auto; min-width: 0; display: flex; gap: 2px; }
/* ── The "+", ending the strip ───────────────────────────────────────
   The prototype's `.tplus`: the last item of the tab row, a bare glyph in the
   selected tab's ink, drawn in the strip's own material so it reads as part
   of the strip rather than as a floating action (it was a violet filled
   square at the end of All items' search row). The tab's own height and
   radius; the MARKER's tint and ring when its menu is open, which is how the
   strip already says "this one is active".
   The wrapper is the dropdown's containing block (actions-row.tsx hangs
   `#dev-plus-menu` off its right edge). */
.dev-ws-plus { position: relative; flex: none; display: flex; }
/* TWO SURFACES, ONE ROW (#2934). The pill's material — padding, hairline,
   fill, rounding — is drawn by the tab list and by the "+"'s wrapper rather
   than by the nav, so the "+" is a round button of its own, a gap after the
   pill, instead of a fourth cell inside it. Everything else is #2914's: the
   same row, the same place, the same metrics. The "+" still sits in a 4px
   ring as a tab does, its tint lands where the marker would, and the row is
   as tall as the pill was (1 + 4 + 40 + 4 + 1).
   ONLY THE STRIP'S "+": the unreachable Board still renders the same
   wrapper at the end of `#dev-actions`, and that surface stays unchanged.
   NO FROST HERE, on purpose: a backdrop-filter makes the tab list a
   stacking context, and the marker, painted before it at `z-index: 0`,
   would go under its fill. `--dc-frost` is `none` everywhere anyway. */
.dev-ws-tablist, .dev-ws-tabtrack > .dev-ws-plus {
  padding: 4px;
  border-radius: 999px;
  border: 1px solid var(--app-sheet-line);
  background-color: var(--dc-sheet-fill);
}
.dev-ws-plus-btn {
  display: inline-flex; align-items: center; justify-content: center;
  width: 40px; height: 40px; padding: 0;
  border: 0; border-radius: 999px;
  background: transparent;
  color: var(--lit-ink);
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
/* Hover only where there IS hover: on touch a tapped button keeps `:hover`
   until the next tap elsewhere, which would leave the "+" tinted after the
   action sheet closes. */
@media (hover: hover) {
  .dev-ws-plus-btn:hover { background: var(--lit-tint); }
}
.dev-ws-plus-btn[aria-expanded="true"] {
  background: var(--lit-tint);
  box-shadow: inset 0 0 0 1px var(--lit-line);
}
.dev-ws-plus-glyph { width: 20px; height: 20px; stroke-width: 2.2; flex: none; }
/* Size lives here, not on the component: icons.tsx has no size variant by
   design, so every call site passes its own class. `flex: none` so a label
   that is trying to fit squeezes itself, not the glyph. */
.dev-ws-tab-glyph { width: 16px; height: 16px; flex: none; }
/* UNDER 400px THE LABELS WIN THE WIDTH. The three labels and their glyphs
   need 316px beside the "+", which a 400px phone has and a 360-390px one
   does not: there "Current status" came out "Current sta…" with its glyph
   still whole, which spends the width on the half a reader cannot read.
   Without the glyphs the labels fit whole down to 340px in DejaVu Sans, and
   down to 320px in Arial's metrics, which are close to SF Pro's and Roboto's. */
@media (max-width: 399px) {
  .dev-ws-tab-glyph { display: none; }
}
.dev-ws-tab-label { min-width: 0; overflow: hidden; text-overflow: ellipsis; }
/* #2915: THE DOT ON ALL ITEMS, while its search or filters are on. They
   narrow that tab alone, so from the other two this is the only sign a search
   is still waiting there. The accent, not the tab's ink: it is a state of the
   tab rather than part of its label, and it has to read on the selected tab's
   tint as well as on the bare track.
   ON A PHONE IT IS A BADGE ON THE GLYPH, AND TAKES NO WIDTH. The pill leaves
   the three labels 8px to spare at 390px (see `.dev-ws-tab`), and a dot after
   the label costs 10: every label lost its last letters to an ellipsis. So it
   is moved to the head of the tab (`order`), its own width and the gap after
   it are handed back (`margin-right`), which lays the glyph over it, and it is
   drawn at the glyph's top-right corner. A transform, so none of that moves
   anything else. Above 700px it goes back after the label, where the segment
   hugs its content and has the room. */
.dev-ws-tab-dot {
  flex: none;
  width: 6px; height: 6px;
  border-radius: 999px;
  background: var(--accent);
  order: -1;
  margin-inline-end: -10px;
  transform: translate(12px, -8px);
}
/* THE ACCENT, not black and no longer the header's periwinkle: `--lit-ink`
   on `--lit-tint` with a hairline of `--lit-line`, the phone's tab bar's own
   lit state, because this is the same kind of thing: where you are, among
   the places you could be. A black pill was the only flat-black object on the
   screen and read as a different product; the periwinkle beside the action
   blue was a second blue for nearly the same meaning.
   The tokens carry their own dark values, so there is no dark variant. */
/* THE INK STAYS ON THE TAB; THE FILL MOVED TO THE MARKER. A background drawn
   by the selected tab itself cannot travel — it can only appear on one and
   vanish from another, which is the snap this replaces. One element that slides
   is the whole idea, so the tab is left with the colour change, which has
   nothing to animate between. */
.dev-ws-tab[aria-selected="true"] {
  color: var(--lit-ink);
}
/* Above the marker, which is painted first and sits at the floor of the
   stacking context. `position: relative` is what puts them on that ladder at
   all — without it the tabs and the marker are both static and the marker,
   coming later in paint order for positioned elements, would cover the
   labels. */
.dev-ws-tab { position: relative; z-index: 1; }
/* WHILE THE "+" MENU IS OPEN the strip outranks the pane head below it. The
   dropdown hangs out of the strip over the tab body, and the strip is a
   stacking context (sticky at `z-index: 30` above 700px), so the menu's own
   `z-30` counts only inside it — and the pane head, which pins at `z-index:
   31` wide and 20 narrow, painted over the menu's rows on All items. Only
   while it is open: at rest the head keeps its place above the strip. A
   click there while the menu is up lands on the strip and dismisses the
   menu, like any outside click. */
.dev-ws-tabs:has(#dev-plus-menu:not(.hidden)) { z-index: 32; }
/* THE MARKER. Every number it uses is measured off the live tab (see
   workshop.tsx), so this rule carries no geometry — which is what lets it
   serve the phone's 58px equal-width pill and the desktop strip's 32px
   content-width segments without a breakpoint of its own.

   `top: 0; left: 0` and then translated: the transform is the only thing that
   moves, and a transform is the one property that animates without asking the
   layout engine anything. */
.dev-ws-tab-marker {
  position: absolute;
  top: 0; inset-inline-start: 0;
  z-index: 0;
  border-radius: 999px;
  background: var(--lit-tint);
  box-shadow: inset 0 0 0 1px var(--lit-line);
  pointer-events: none;
  /* Hidden until measured — see the note in workshop.tsx. */
  opacity: 0;
}
.dev-ws-tab-marker[data-ws-marker-at] { opacity: 1; }
/* THE TRANSITION IS ON A SECOND ATTRIBUTE, and `data-ws-marker-slide` is not
   `data-ws-marker-at`. `at` means MEASURED, which is what the opacity above
   waits for; `slide` means the measurement was caused by the SELECTION
   CHANGING. Only the second is worth animating, and keeping them apart is
   what stops a re-measure of the tab you are already on from replaying the
   slide — see useTabMarker in workshop.tsx, which owns the distinction.

   Both were one attribute, and that conflated three things the marker does.
   The first placement was one: `at` arrives in the same commit as the
   transform, so the transition was live for a change from `none` at zero
   width, and the marker slid in from the nav's left edge on every cold open
   of the All items tab — the exact slide-in the null-until-measured render
   was written to avoid, reintroduced by the rule meant to enforce it. A
   re-measure was the other: any layout shift under the bar re-expressed an
   unmoved tab in new coordinates and the marker animated to where it already
   was. Neither is a selection changing, and neither carries `slide`.

   `width` and `height` are in the list because the desktop segments are
   content-width: "Current status" and "Needs you" are different sizes, so a
   transform alone would slide a box of the wrong width. On the phone all
   three match and those two properties simply never change. */
@media (prefers-reduced-motion: no-preference) {
  .dev-ws-tab-marker[data-ws-marker-slide] {
    transition:
      transform .26s cubic-bezier(.32, .72, 0, 1),
      width .26s cubic-bezier(.32, .72, 0, 1),
      height .26s cubic-bezier(.32, .72, 0, 1);
  }
}
/* Reduce motion setting (#6510): none of the motion above, when Settings asks for it. */
:where(html[data-motion="reduce"]) .dev-ws-tab-marker[data-ws-marker-slide] { transition: none; }

/* ── Needs you: one question, the whole screen ───────────────
   SIZED FROM THE VIEWPORT, not from its ancestors — and that is the second
   attempt. The first was a `height: 100%` chain down from #dev-forum-scroll,
   which has a definite height in the native layout and resolves perfectly
   there. It resolves to nothing in the BROWSER layout: when the root carries
   `data-browser-scroller="dev-forum-scroll"` the rule near the top of this
   file forces `#app-view` to `height: auto !important` so the page itself
   scrolls, and every 100% below it collapses to content height. Two shipped
   layouts, and the chain only worked in one.

   So the deck measures the viewport and subtracts the chrome it can name:
   the platform header, the device insets and the platform's own tab bar.
   `min-height` keeps it usable on a short window rather than letting the
   subtraction win. */
.dev-ws {
  /* THE AIR AT THE FOOT, decided once. The device inset is NOT in this
     number: `#dev-forum-scroll` carries `.platform-safe-scroll`, whose
     padding already reserves the larger of the home-indicator strip and the
     platform's tab bar, and counting either again here is the double spend
     that once left a whole indicator of dead air on a real iOS PWA (the
     headless harnesses report a zero inset and could not see it).

     WHAT IS NOT SUBTRACTED ANY MORE: a Workshop tab bar. On a phone that bar
     floated fixed at the foot of the window, out of flow, so this floor took
     its box and the air under it off by hand. It sits at the head of the page
     now (#2767), in flow INSIDE this box, so the flex chain accounts for it
     and the floor must not take it off a second time — the arithmetic the
     wide layout has always used, at every width.

     THE FIXED STRIPS ABOVE THE HEADER ARE CHROME TOO (QA 2026-09-24 Q8).
     `--browser-banner-h` is the install strip plus the offline strip,
     whichever are up. Body padding reserves them at the head of the page,
     so the page starts that much lower and this floor has to give the same
     length back. Without it a phone browser showing "Get the app" pushed
     the foot of every Needs you card, its chips and the rail's More, under
     the tab bar. The token is 0 with no strip up, hence the fallback; since
     2 Nov 2026 it is declared on every screen (L01), not only the paged ones. */
  --ws-area: calc(
    100dvh - var(--browser-banner-h, 0px)
    - var(--platform-header-h, 56px) - var(--platform-safe-top, 0px)
    - var(--ws-gap) - max(var(--platform-tabs-h, 0px), var(--platform-safe-bottom, 0px))
  );
  /* THE FITTED BOX Needs you takes as a definite height in the browser
     layout (below). While a pill floated over the foot of every tab this was
     a different number from the floor above — the pill overlaid the last
     stretch of it and the tab body's clearance held content off it. Nothing
     overlays the lander now, so the box and the floor are the same length. */
  --ws-fit: var(--ws-area);
}
/* ── Needs you is a FITTED SCREEN on a phone, in both layouts ──────────
   In the NATIVE one #dev-forum-scroll has a definite height, the flex chain
   bounds the deck, and `.dev-ws-needs-scroll` is what takes a long card — so
   the answers, the page arrows and the ask box are pinned.

   In a mobile BROWSER the page itself scrolls (`html[data-browser-scroller]`,
   see browser-scroll.ts), #dev-forum-scroll is `height: auto`, and every
   height below it resolves to content. `--ws-area` is only a FLOOR there, so
   it could not stop a long card growing the deck. So the tab takes `--ws-fit`
   as a definite HEIGHT — the box the native chain arrives at on its own.

   Scoped to the phone as well as to the layout: `data-browser-scroller` is
   set on any coarse pointer (MOBILE_PAGE_QUERY), tablets included, and above
   700px the deck is content-sized at the top of the column instead. 700px is
   the same decision as the `@media (min-width: 700px)` block below and as
   workshop.tsx's `WIDE_QUERY`. */
@media (max-width: 699.98px) {
  html[data-browser-scroller] .dev-ws[data-ws-tab="needs"] {
    height: var(--ws-fit);
    min-height: var(--ws-fit);
  }
}
/* ═══════════════════════════════════════════════════════════════════════
   NEEDS YOU: A FEED OF DECISIONS. One item per screen, the rail of
   actions at the right edge, sheets over the item. workshop.tsx's NeedsFeed
   header is the argument; this is the geometry.

   THE LANDER IS THE STAGE. `.dev-ws-needs` takes what is left between the
   head of the tab and the pill's clearance (the flex chain above, with
   `--ws-fit` on a phone), and the SCROLLER inside it is the snap container:
   every item is exactly its height, `scroll-snap-type: y mandatory` finishes
   any drag on an item boundary, and nothing inside an item scrolls — a long
   summary clamps and the title links to the full page.
   ═══════════════════════════════════════════════════════════════════════ */
.dev-ws-needs {
  flex: 1 1 auto; min-height: 320px;
  position: relative;
  display: flex; flex-direction: column;
}
.dev-ws-needs-scroll {
  flex: 1 1 auto; min-height: 0;
  overflow-y: auto; overscroll-behavior: contain;
  /* #3052: a swiped card travels sideways; the feed must not scroll with it. */
  overflow-x: hidden;
  scroll-snap-type: y mandatory;
  scrollbar-width: none;
  border-radius: 20px;
}
.dev-ws-needs-scroll::-webkit-scrollbar { display: none; }
@media (prefers-reduced-motion: no-preference) {
  .dev-ws-needs-scroll { scroll-behavior: smooth; }
}
/* Reduce motion setting (#6510): none of the motion above, when Settings asks for it. */
:where(html[data-motion="reduce"]) .dev-ws-needs-scroll { scroll-behavior: auto; }
/* ── The item: a card of the page's own ───────────────────────────────
   ONE CARD, IN THE PAGE'S SCHEME, in the light theme and the dark alike,
   like the hub's and the Workshop's grouped cards are: the plane colour
   (--dc-sheet-solid), the 20px corners and the one hairline
   (--app-sheet-line). The picture fills it, and the caption is laid over
   its foot (workshop.tsx FeedItem); the rail stands over the card's right
   edge on a phone, so the caption keeps its lane (80px) free. Everything
   inside reads the theme's own tokens --text-*, --accent, --state-* and
   --app-sheet-line, so the pictures (lib/diagram, What it touches, the
   shots' switch) and the facts follow the viewer's theme without a second
   copy of their rules. The end card is an item too, and keeps the page's
   own scheme. */
.dev-ws-item {
  position: relative;
  height: 100%; box-sizing: border-box;
  scroll-snap-align: start; scroll-snap-stop: always;
  display: flex; flex-direction: column;
  padding: 0;
  border-radius: 20px;
  overflow: hidden;
  background-color: var(--dc-sheet-fill);
}
.dev-ws-item:not(.dev-ws-needs-done) {
  background-color: var(--dc-sheet-solid);
  box-shadow: inset 0 0 0 1px var(--app-sheet-line);
  color: var(--text-primary);
}
/* #4754: THE STAGE. The strip and the scroller share one column, so the
   strip is as wide as the card and sits over it, and neither scrolls. */
.dev-ws-needs-stage {
  flex: 1 1 auto; min-height: 0;
  display: flex; flex-direction: column;
}
/* Where you are, on the page: one segment an item, lit up to the one in
   view. The gaps are a mask, so the count is a number on the line
   (`--ws-n`) rather than an element an item. The page's own colours: the
   base is the sheet hairline and the lit part the ink that marks where you
   are (--lit-ink), where the card drew the line white on the dark. */
.dev-ws-needs-progress {
  flex: 0 0 auto;
  display: flex; align-items: center; gap: 12px;
  height: 20px; margin: 0 6px 6px;
}
.dev-ws-needs-progress-line {
  flex: 1 1 auto; height: 3px; border-radius: 3px;
  background: var(--app-sheet-line);
  -webkit-mask-image: repeating-linear-gradient(90deg, #000 0 calc(100% / var(--ws-n, 1) - 4px), transparent calc(100% / var(--ws-n, 1) - 4px) calc(100% / var(--ws-n, 1)));
  mask-image: repeating-linear-gradient(90deg, #000 0 calc(100% / var(--ws-n, 1) - 4px), transparent calc(100% / var(--ws-n, 1) - 4px) calc(100% / var(--ws-n, 1)));
}
.dev-ws-needs-progress-line > i { display: block; height: 100%; background: var(--lit-ink); }
.dev-ws-needs-of {
  flex: none;
  font-size: 11px; font-weight: 700; letter-spacing: .06em; color: var(--text-muted);
  font-variant-numeric: tabular-nums; white-space: nowrap;
}
.dev-ws-item-top {
  position: relative; z-index: 2;
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  min-height: 20px; margin: 22px 14px 0;
}
.dev-ws-item-top > .dev-ws-eyebrow { font-size: 12px; font-weight: 700; letter-spacing: .06em; color: var(--text-muted); min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
/* #3517: the way back on a phone, at the right end of the card's top line,
   where the counter sat before it moved to the strip (workshop.tsx draws it
   there only, from the second item on). A small round, the rail's own fill,
   drawn at 26px but held to the row's 20px by negative margins.
   `margin-left: auto` takes the row's free space, so it rides at the row's
   right end rather than in the middle of it; the tap target is the 44px
   square around it. */
.dev-ws-item-prev {
  position: relative; flex: none;
  width: 26px; height: 26px; margin-block: -3px -3px; margin-inline: auto -4px; padding: 0;
  display: grid; place-items: center;
  border: 0; border-radius: 9999px;
  background-color: var(--state-neutral-bg);
  color: var(--text-primary); cursor: pointer;
}
.dev-ws-item-prev::after { content: ''; position: absolute; inset: -9px; }
.dev-ws-item-prev-icon { width: 16px; height: 16px; }
/* After a vote the eyebrow IS the confirmation: the same line, in the ok
   tone, with a tick — no toast over the title. */
.dev-ws-item-done {
  display: inline-flex; align-items: center; gap: 7px; min-width: 0;
  font-size: 13px; font-weight: 700; color: var(--state-ok);
}
.dev-ws-item-tick {
  width: 18px; height: 18px; flex: none; padding: 3px; box-sizing: border-box;
  border-radius: 9999px; background: var(--state-ok); color: #fff;
}
/* A no vote (#4568): the confirmation, and its tick, in the blocked red
   instead of the ok green. Yes keeps the rules above. */
.dev-ws-item-done[data-ws-voted="no"] { color: var(--state-blocked); }
.dev-ws-item-done[data-ws-voted="no"] .dev-ws-item-tick { background: var(--state-blocked); }
/* THE PICTURE takes the card from under the counter to its foot, edge to
   edge; the scrim and the caption are laid over its lower part. */
.dev-ws-item-spacer { flex: 1 1 auto; min-height: 0; }
/* What keeps the caption legible over any picture: a fade up from the
   card's foot, into the card's own colour. Open, the caption has the whole
   card, and the picture is washed out in the card's colour under it. Taps
   go through to the picture. */
.dev-ws-item-scrim {
  position: absolute; inset-inline-start: 0; inset-inline-end: 0; bottom: 0; z-index: 1;
  height: 300px; max-height: 75%;
  background: linear-gradient(to top, var(--dc-sheet-solid), transparent);
  pointer-events: none;
}
.dev-ws-item[data-ws-open] > .dev-ws-item-scrim { top: 0; height: auto; max-height: none; background: var(--dc-sheet-solid); opacity: .94; }
/* THE CAPTION, bottom-left, as on a reel. Open ("more") it grows up the
   card and scrolls once it meets the counter. */
.dev-ws-item-caption {
  position: absolute; inset-inline-start: 14px; inset-inline-end: 80px; bottom: 16px; z-index: 2;
  max-height: calc(100% - 64px); box-sizing: border-box;
  display: flex; flex-direction: column; gap: 7px;
}
.dev-ws-item[data-ws-open] > .dev-ws-item-caption {
  overflow-y: auto; overscroll-behavior: contain; scrollbar-width: none;
}
/* #5039: a diagram's picture is words too, so its caption sits below it in
   the flow, still clear of the rail. Open ("more") it keeps the overlay. */
.dev-ws-item:not([data-ws-open]):has(> .dev-ws-diagram) > .dev-ws-item-caption {
  position: relative; inset-inline-start: auto; inset-inline-end: auto; bottom: auto;
  flex: none; margin-block: 12px 16px; margin-inline: 14px 80px;
}
.dev-ws-item-by {
  display: flex; align-items: center; gap: 8px; margin: 0; min-width: 0;
  font-size: 13px; color: var(--text-muted);
}
.dev-ws-item-by-text { min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.dev-ws-item-by b { color: var(--text-primary); font-size: 15px; font-weight: 650; }
.dev-ws-item-avatar {
  width: 30px; height: 30px; border-radius: 9999px; flex: none;
  display: grid; place-items: center;
  color: #fff; font-size: 12.5px; font-weight: 700;
}
.dev-ws-item-caption .dev-ws-item-avatar { box-shadow: 0 0 0 2px var(--dc-sheet-solid); }
.dev-ws-item-title {
  margin: 0;
  font-size: 18px; line-height: 1.22; font-weight: 750; letter-spacing: -.01em;
  color: var(--text-primary);
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
  text-wrap: balance; overflow-wrap: anywhere;
}
.dev-ws-item-title > a { color: inherit; text-decoration: none; }
.dev-ws-item-title > a:hover { text-decoration: underline; text-underline-offset: 3px; }
.dev-ws-item[data-ws-open] .dev-ws-item-title { display: block; overflow: visible; }
/* THE SUMMARY in two lines, its "more" at the end of the second. The
   button floats right, first in the paragraph, held down to the last line
   by a float as tall as the paragraph less one line (the paragraph is a
   flex item, so its height is definite for the float's percentage), and
   the clamp's ellipsis falls just before it. Short, it sits at the end of
   the text. */
.dev-ws-item-summary { display: flex; margin: 0; }
.dev-ws-item-summary-text {
  margin: 0; min-width: 0;
  font-size: 15px; line-height: 1.4; color: var(--text-secondary);
  white-space: pre-line; overflow-wrap: anywhere;
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
}
.dev-ws-item-summary-text::before { content: ''; float: inline-end; height: calc(100% - 1.4em); }
.dev-ws-item-more {
  margin-block: 0 0; margin-inline: 6px 0; padding: 0; border: 0; background: none; cursor: pointer;
  font: inherit; font-style: normal; font-weight: 700; color: var(--text-primary);
}
.dev-ws-item-more-end { float: inline-end; clear: both; }
.dev-ws-item-nosummary { font-style: italic; color: var(--text-muted); }
.dev-ws-item-summary-open { display: block; }
.dev-ws-item-summary-open > .dev-ws-item-summary-text { display: block; overflow: visible; }
.dev-ws-item-summary-open > .dev-ws-item-summary-text::before { content: none; }
.dev-ws-item-words { font-size: 14px; line-height: 1.45; color: var(--text-secondary); overflow-wrap: anywhere; }
.dev-ws-item-words > * { margin: 0 0 8px; }
.dev-ws-item-words > :last-child { margin-bottom: 0; }
.dev-ws-item-words :is(h1, h2, h3, h4, h5, h6) { font-size: 15px; font-weight: 700; color: var(--text-primary); }
.dev-ws-item-words :is(ul, ol) { padding-inline-start: 20px; }
.dev-ws-item-words a { color: var(--text-primary); text-decoration: underline; text-underline-offset: 2px; }
.dev-ws-item-words code { padding: 0 4px; border-radius: 4px; background: var(--state-neutral-bg); font-size: 13px; }
/* A CHANGE WITH NO PICTURE AT ALL (workshop.tsx `pictureless`): the card is
   its words. The caption takes the card from under the counter to its foot
   and sits in the middle of it (auto margins, which give way to the top
   when the words run long), in a larger size, and the summary runs to eight
   lines before "more" is offered. No art stands in for the picture. */
.dev-ws-item[data-ws-picture="none"] > .dev-ws-item-caption { top: 56px; }
/* #5039: the caption's words sit on a solid panel of the card's own colour
   with a hairline, so they read over any picture, light or dark. Every
   pictured card gets it; a pictureless card, where the words fill the card
   and nothing sits behind them, does not. */
.dev-ws-item:not([data-ws-picture="none"]) > .dev-ws-item-caption {
  padding: 10px 12px; border-radius: 16px;
  background: var(--dc-sheet-solid);
  box-shadow: inset 0 0 0 1px var(--app-sheet-line);
}
.dev-ws-item[data-ws-picture="none"] > .dev-ws-item-caption > :first-child { margin-top: auto; }
.dev-ws-item[data-ws-picture="none"] > .dev-ws-item-caption > :last-child { margin-bottom: auto; }
.dev-ws-item[data-ws-picture="none"] .dev-ws-item-title { font-size: 22px; line-height: 1.2; -webkit-line-clamp: 4; }
.dev-ws-item[data-ws-picture="none"] .dev-ws-item-summary-text { font-size: 16px; line-height: 1.45; -webkit-line-clamp: 8; }
.dev-ws-item[data-ws-picture="none"] .dev-ws-item-summary-text::before { height: calc(100% - 1.45em); }
/* What "more" adds under the summary: the declared changes, numbered as
   the picture's outlines are, and what the change touches. */
.dev-ws-item-part { display: flex; flex-direction: column; gap: 6px; }
.dev-ws-item-part-head { margin: 2px 0 0; font-size: 13px; font-weight: 650; color: var(--text-primary); }
.dev-ws-shot-changes.dev-ws-item-changes { margin: 0; }
.dev-ws-item-changes .dev-ws-shot-change { font-size: 14px; font-weight: 500; line-height: 1.45; color: var(--text-secondary); }
.dev-ws-item-touched { margin: 0; font-size: 13px; line-height: 1.45; color: var(--text-muted); }
.dev-ws-item-less {
  align-self: flex-start; margin: 0; padding: 0; border: 0; background: none; cursor: pointer;
  font: inherit; font-size: 14px; font-weight: 700; color: var(--text-primary);
}
/* A request's number on a change's page (topic-head.tsx) is a chip. */
.dev-ws-chip {
  display: inline-flex; align-items: center; height: 24px; padding: 0 9px;
  border-radius: 9999px; font-size: 12px; font-weight: 600; white-space: nowrap;
  background: var(--state-neutral-bg); color: var(--text-secondary);
}
.dev-ws-chip-info { background: var(--accent-tint); color: var(--accent-wash-ink); }
/* THE FACTS: where the vote stands, "your yes puts it live", the status and
   the topic. A line that does not fit wraps to a second one rather than
   losing its end (the topic is last). On a phone the whole line is one quiet
   pill with the people glyph; on a wide window the vote's words are the pill
   and the topic follows it (the wide block). */
.dev-ws-item-facts {
  display: block; align-self: flex-start; max-width: 100%; box-sizing: border-box; margin: 2px 0 0;
  padding: 4px 10px; border-radius: 12px; background: var(--state-neutral-bg);
  font-size: 12px; font-weight: 600; line-height: 16px; color: var(--text-primary);
  white-space: normal; overflow-wrap: anywhere;
}
.dev-ws-item-facts-icon { display: inline-block; width: 12px; height: 12px; margin-inline-end: 6px; vertical-align: -2px; }
.dev-ws-fact + .dev-ws-fact::before,
.dev-ws-item-facts-vote + .dev-ws-fact::before { content: " · "; font-weight: 400; color: var(--text-muted); }
.dev-ws-fact.dev-ws-fact-ok { color: var(--state-ok); }
.dev-ws-fact.dev-ws-fact-progress { color: var(--state-progress); }
.dev-ws-fact.dev-ws-fact-warn { color: var(--state-attention); }
.dev-ws-fact.dev-ws-fact-blocked { color: var(--state-blocked); }
/* The Communities screen's two views (Current status | Needs you,
   `.workshop-scope-tabs`) are gone with the UI overhaul: the list is the
   page, and Needs you is a row at its top that opens the feed below. */
/* ── The Communities screen's Needs you feed (#3270, workshop/needs-reel.tsx) ──
   A project's own Needs you feed since #3488 (NeedsFeed, the stage and the
   item above), in a box a screen tall less the bars around it: the page head
   over it and the tab bar under it. Each item leads with the project it
   belongs to, its tile and its name, a door to its hub. */
.workshop-needs-feed {
  /* NO HEIGHT HERE ANY MORE (#3516): the phone takes it from the flex chain
     below and the desktop from its own rule after that. `min-height` is the
     floor for both: a feed shorter than this is not usable, and on a window
     that short the screen scrolls instead. */
  min-height: 360px;
  margin: 4px 16px 0;
  display: flex; flex-direction: column;
}
/* #6199: the vote-type chips sit INSIDE this box, above the deck, so the feed
   is still the pane's one child (tests/communities-followups.test.js, #3516).
   The box already carries the page's inset, so the rail's own 16px would set
   the chips 16px in from the card's edge; they line up with it instead. */
.workshop-needs-feed > .needs-vote-chips { padding-inline: 0; }
/* ON A PHONE THE FEED ENDS WHERE #workshop-screen'S CLEARANCE BEGINS (#3516).

   It was `height: calc(100dvh - 180px - var(--browser-banner-h, 0px))`: the
   page head and the header over it (116px) and a 56px tab bar with 8px of air
   under it, measured once in a browser with no insets and nothing parked. Three
   things at the foot of a phone were not in that number, and each one put the
   feed's foot under the bar:

   - THE PARKED APP'S STRIP. `--platform-tabs-h` counts it (52px more) the
     moment an app is parked; this number never did. Measured at 390x844 with
     an app parked: the feed ran to 828px against a strip whose top was at
     736 in a phone browser, and to 827 against 716 in the installed layout,
     so the rail's Try it and More and the item's caption sat under the
     strip and the bar.
   - THE INSTALLED APP'S INSETS. An iPhone install reserves the status bar
     at the top (`--platform-safe-top`, 47-62px) and the bar spends part of
     the home indicator at the foot (`--platform-tabs-inset`). Nothing
     parked, the feed still ended 60px under the bar there.
   - THE "GET THE APP" BANNER in a phone browser. `--browser-banner-h` was
     declared only on `html[data-browser-scroller]` routes then, and this
     screen is not one (browser-scroll.ts `PAGES`): its root scrolls itself in
     every layout, so the token read 0 here while the banner pushed the page
     48px down.

   And the foot could not be scrolled into view. `.dev-ws-needs-scroll` is
   `overscroll-behavior: contain`, so a drag on the feed moves between items
   and never reaches the screen behind it; only a drag on the page head moved
   the page.

   SO NO ARITHMETIC: THE SCROLLER'S OWN CLEARANCE BOUNDS IT. #workshop-screen
   is a flex child of the fixed-height body column in both layouts, so it has
   a definite height, and it carries `.platform-safe-scroll`, whose padding is
   `max(--platform-tabs-h, --platform-safe-bottom)`: the tab bar, the parked
   strip when there is one and the home indicator, each counted once, by the
   same token every other screen clears them with. While the feed is up the
   screen, its column and the pane become a flex chain and the feed takes
   what is left above that padding, less `--ws-gap` of air — the line a
   project's own Needs you deck ends on (`.dev-ws`'s `--ws-area`), whatever
   the header, the insets, the banner or the strip add up to. The same
   mechanism the project page uses in the installed layout (see "The lander
   fills what is left of the scroller"), for the same reason: nothing here
   depends on a header height being accurate.

   `flex-shrink: 0` on every link, never `min-height: 0`. On a window too
   short for the 360px floor the column must stay its content's height and
   make the screen scroll: a link allowed to shrink leaves the feed
   overflowing it, and a scroller's block-end padding follows its in-flow
   children, not a descendant that overflows one, so the clearance would
   reserve nothing (#3053 is the same trap on a project page).

   `:not(.hidden)` on the root is load-bearing. The needs pane stays mounted
   while you are on another screen, and an id-specific `display` here would
   otherwise outrank Tailwind's `.hidden` and draw Communities over it.
   `width: 100%` on the column because auto margins on a flex column's cross
   axis shrink an item to its content (`#dev-workshop` above has the same
   note); `max-w-2xl mx-auto` still caps and centres it. Its `pb-8` gives way
   to `--ws-gap`, which is the air this line has always had above the bar.

   Below 768px only: from there the bar is a rail down the side, nothing is
   parked at the foot (the strip gives way to Recents), and the rule below
   keeps the desktop's own line. */
@media (max-width: 767.98px) {
  #workshop-screen:not(.hidden):has(> div > [data-workshop-pane="needs"]) {
    display: flex; flex-direction: column;
  }
  #workshop-screen > div:has(> [data-workshop-pane="needs"]) {
    flex: 1 0 auto; width: 100%;
    display: flex; flex-direction: column;
    padding-bottom: var(--ws-gap);
  }
  #workshop-screen [data-workshop-pane="needs"] {
    flex: 1 0 auto;
    display: flex; flex-direction: column;
  }
  #workshop-screen [data-workshop-pane="needs"] > .workshop-needs-feed { flex: 1 0 0px; }
}
@media (min-width: 768px) {
  /* No tab bar: the stage runs to 8px off the floor, as a project's does, so
     the rail and its arrows clear the key legend under it. */
  .workshop-needs-feed { height: calc(100dvh - 124px - var(--browser-banner-h, 0px)); }
  /* The key legend is centred under the STAGE, not under the stage and the
     rail: this screen's column is narrower than a project's panel, so the
     legend is wider than the stage and, centred on both, ran under the
     rail's arrows. 102px is the rail and its gap. */
  .workshop-needs-feed .dev-ws-keys { inset-inline-end: 102px; }
}

/* ── The AI tab's main view (#6019 follow-up, features/ai/) ──────────────
   A page like Communities: the list on the wallpaper (the screen lists in
   this file name #ai-screen beside #workshop-screen). Its Ask Homeroom bot
   bar sits over the tab bar like a composer, on a phone; from 768px (1 Nov
   2026; it was 1024px) the column docks beside the list instead
   (data-ai-docked), with Main, the chat with the bot, or one thread of it. */
#ai-screen .ai-askbar {
  position: fixed;
  /* Where the page's own content is (the rail and its gutter, mirrored on
     the far edge), so on a wide window whose Main is not docked (yet, or at
     all) the bar is the page's and never runs under the sidebar. Both are 0
     on a phone. */
  inset-inline-start: calc(var(--platform-rail-w, 0px) + var(--platform-gutter, 0px));
  inset-inline-end: var(--platform-gutter, 0px);
  bottom: var(--platform-tabs-h, 56px);
  z-index: 25;
  padding: 6px 12px 8px;
}
#ai-screen .ai-askbar-card {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  text-align: start;
}
#ai-screen .ai-askbar-text {
  flex: 1;
  min-width: 0;
  font-size: 17px;
  line-height: 22px;
  padding: 9px 4px;
  color: var(--text-faint);
}
#ai-screen .ai-askbar-gap { height: 76px; }
#ai-screen[data-ai-docked] .ai-askbar,
#ai-screen[data-ai-docked] .ai-askbar-gap { display: none; }
/* Main's column is the side panel's width (features/side-panel/), so a page
   opened from the list takes its place without the list moving. Held inside
   the window here as well: that width is the one chosen beside an app, kept
   per device and put on <html> at boot, so a width picked on a wide monitor
   would otherwise run Main under the rail and over the list on a narrower
   window. The list keeps the 480px an app keeps beside the panel. Set on
   <body> while the page is up, so the panel (a sibling of the page, not in
   it) takes the same width in Main's place.
   UNTIL A WIDTH IS CHOSEN (30 Oct 2026), Main takes the room the list does
   not need. Since 3 Nov 2026 that is ALL of it, with no 720px upper limit:
   Main is the rest of the window, and only the list's own margins separate
   them. With the old cap at 720px a 1720px window left a band of empty
   background between the two and a narrow, tall column for plan cards. The
   400px floor stays. THE LIST GIVES WHAT IT TAKES (#6495, 9 Nov 2026): while
   something is open beside it the list is the inbox's own measure
   (`--list-pane-w`), so the two list-and-open pages share one layout; with
   nothing open it stays the centred 672px single column (`max-w-2xl`,
   features/ai/index.tsx), as Home and Needs you are.
   A width dragged on Main's edge is Main's own (`--ai-main-chosen-w` and its
   own device key, features/side-panel/resize.ts), so a width chosen for the
   side panel beside an app no longer sizes Main, and the reverse.
   THE ROOM IS BESIDE THE DUO'S COLUMN (1 Nov 2026). `--ai-room` is the
   window less the rail and iPhone Duo's column of system chrome
   (`--platform-strip-w`, THE SIDE STRIP; 0 everywhere else). Unfolded and
   held sideways the Duo is 951px with an 84px column the body pads out, so
   sums taken from 100vw counted the column twice: Main came out 379px and
   the list's card 220px. Since the same day the room is the page's usable
   box (`--platform-usable-w`, THE USABLE BOX beside the rail's tokens),
   which takes the rail and the column off once for every reader: the same
   value, decided in one place.
   THE PINNED COLUMNS RUN UNDER IT (1 Nov 2026), as the header does: Main,
   the side panel in its place and a design's preview reach the screen's
   edge. Stopped at the column instead, Main ended in a hard edge with bare
   wallpaper beside it. The clock, the camera and the Wi-Fi ring sit at the
   column's top, within the height of each column's head, so the heads pad
   their contents by the column (`--ai-edge`). Below that the column is
   plain screen (taps reach the page there, measured on the Duo simulator),
   so Main's chat and the page in the side panel run under it: padded too,
   they left a band of the column's own colour beside a chat that stopped
   short. A design's preview pads the column, as its ✕ is at its top. */
body:has(#ai-screen:not(.hidden)) {
  --ai-room: var(--platform-usable-w);
  --ai-list-min: var(--list-pane-w);
  --ai-main-auto: max(400px, calc(var(--ai-room) - var(--list-pane-w)));
  --ai-main-w: max(320px, min(var(--ai-main-chosen-w, var(--ai-main-auto)), calc(var(--ai-room) - var(--ai-list-min))));
}
html[data-side-strip="right"] body:has(#ai-screen:not(.hidden)) {
  --ai-edge: var(--platform-strip-w, 0px);
}
/* A NOTCH ON THE RIGHT (an iPhone held sideways, THE NOTCH below) is an
   edge the same way, for the columns' width and their heads. Unlike the
   Duo's column it is the camera island halfway down, not plain screen, so
   Main's chat and the page in its place keep clear of it too. */
html:not([data-side-strip]):not([data-side-corner]) body:has(#ai-screen:not(.hidden)) {
  --ai-edge: var(--platform-notch-right, 0px);
}
/* Main stands on the left in Arabic, so the edge beside it is that side's. */
html[dir="rtl"][data-side-strip="right"] body:has(#ai-screen:not(.hidden)) { --ai-edge: 0px; }
html[dir="rtl"][data-side-strip="left"] body:has(#ai-screen:not(.hidden)) { --ai-edge: var(--platform-strip-w, 0px); }
html[dir="rtl"]:not([data-side-strip]):not([data-side-corner]) body:has(#ai-screen:not(.hidden)) { --ai-edge: var(--platform-notch-left, 0px); }
html:not([data-side-strip]):not([data-side-corner]) #ai-screen .ai-main-pane > .messages-layout,
html:not([data-side-strip]):not([data-side-corner]) body:has(#ai-screen:not(.hidden)) .side-panel-body {
  padding-inline-end: var(--ai-edge, 0px);
}
/* 1 Nov 2026: between 768 and 1024px the list keeps 280px, not 480: its
   rows are one line (their numbers left out, as a phone's are), and the
   column is 320px at the least. 280 rather than the 360 first chosen, so
   Main's divider can give the chat most of an iPhone Duo held sideways;
   at its floor the list's title wraps to two lines and its rows shorten,
   which is the reader's choice to make. The divider reads this figure
   (features/side-panel/resize.ts probeLayout). */
@media (max-width: 1023.98px) {
  body:has(#ai-screen:not(.hidden)) { --ai-list-min: 280px; }
}
/* THE COLUMN'S LANE IS KEPT ONLY WHILE IT IS OPEN (6 Nov 2026, #6425): a
   desktop opens on the lists alone, and they take the room the column would
   have. A row, New chat or a link opens it, and the list gives the lane up
   again. */
#ai-screen[data-ai-docked][data-ai-open] { padding-inline-end: var(--ai-main-w); }
/* NO GUTTER AFTER THE RAIL WHILE MAIN IS DOCKED (1 Nov 2026). Every screen
   beside the rail pads a gutter after it and mirrors it on the far edge, so
   a column inside centres. Here Main is the far edge, with no gutter, so the
   list's cards sat 40px after the rail (the gutter and their own 16px) and
   16px from Main. Without it they sit 16px from both, and the list centres
   between them. */
#ai-screen[data-ai-docked] { padding-inline-start: var(--platform-rail-w, 0px); }
/* THE BOT TAB'S LIST FILLS THE ROOM BESIDE THE OPEN COLUMN (#6520, 9 Nov
   2026). With something open beside it the body has the room between the
   rail and the open column (the `--ai-main-w` above) to itself, and it
   takes all of that room, up to the page's own 672px single column
   (`max-w-2xl` in features/ai/index.tsx) and centred in it, rather than
   staying the inbox's 22rem against the rail and leaving the rest bare.
   `--list-pane-w` remains the list's floor through `--ai-list-min`, so
   dragging the column wider still stops where it did. With nothing open
   beside the lists the rule does not match and the body keeps
   `max-w-2xl mx-auto`, a single centred page as Home and Needs you are. */
#ai-screen[data-ai-docked][data-ai-open] .ai-screen-body {
  width: 100%;
  max-width: 42rem;
  margin-inline: auto;
}
/* The aside stays mounted, because a thread is opened from the place it is
   handed (`at`); with nothing open beside the lists it is not drawn. */
#ai-screen:not([data-ai-open]) .ai-main-pane { display: none; }
/* #6147: 8px below the header, as the list's first card and the Workshop's
   side panel (.dev-ws-side) are, not 8px up into its rounded lower edge. The
   preview pane and Main's divider start on the same line. */
#ai-screen .ai-main-pane {
  position: fixed;
  z-index: 20;
  inset-inline-end: 0;
  bottom: 0;
  top: calc(var(--browser-banner-h, 0px) + var(--platform-header-h) + var(--platform-safe-top, 0px) + .5rem);
  width: calc(var(--ai-main-w) + var(--ai-edge, 0px));
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: var(--home-ground);
  border-top: 1px solid var(--app-sheet-line);
  border-inline-start: 1px solid var(--app-sheet-line);
  border-start-start-radius: 1.75rem;
}
/* THE LIST'S HEADING KEEPS ITS LINE WHERE THE LIST IS NARROW (overnight
   audit B13, 2 November 2026). Between 768 and 1024px the list is 280px at
   its floor (below), and its heading's mark, name and + left the name about
   120px: "Homeroom / bot" on two lines and the counts under it a word or two
   a line. Under 340px of heading the mark steps aside, as a phone's
   conversation drops its avatar, and the name has the room. */
#ai-screen [data-ai-hero] { container-type: inline-size; }
@container (max-width: 340px) {
  #ai-screen [data-ai-hero] > img { display: none; }
}
@container (max-width: 260px) {
  #ai-screen [data-ai-hero] h1 { font-size: 1.25rem; }
}
/* NEW CHAT KEEPS ITS WORDS WHERE THE HEADING HAS ROOM FOR THEM (14 Nov
   2026). It is the page's one labelled button, a plus and "New chat" in the
   accent. Beside the bot's picture, its name and search, the words fit from
   about 400px of heading: a desktop's lists. Narrower (a phone, or the lists
   beside an open column), the button is the accent disc with its plus, and
   the words stay its name for a screen reader; a phone's Ask bar says them. */
#ai-screen [data-ai-hero] [data-ai-new-chat] { padding-inline: 14px 16px; }
@container (max-width: 400px) {
  #ai-screen [data-ai-hero] [data-ai-new-chat] { padding-inline: 0; }
  #ai-screen [data-ai-hero] [data-ai-new-chat] > span {
    position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0;
    overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0;
  }
}
/* The chat fills the column (as a project page's chat does). */
#ai-screen .ai-main-pane > .messages-layout { flex: 1 1 auto; height: auto; min-height: 0; }
/* A THREAD FILLS THE COLUMN (31 Oct 2026; 14 Nov 2026: threads only). The
   column is 400 to 720px, and the chat is drawn there as its threads alone
   (EmbeddedConversation `threadsOnly`, `[data-bot-threads]`): one thread, or
   a new chat, under its own head (ReplyThreadPanel `alone`), lying flat as
   the column's one sheet, with no corner, hairline or shadow of its own and
   no divider to drag (the column's edge is the handle). The phone's drawer
   holds the column the same way. */
.messages-layout[data-bot-threads] > .messages-reply-pane {
  flex: 1 1 auto;
  width: 100%;
  margin: 0;
  border-radius: 0;
  border-top: 0;
  box-shadow: none;
}
.messages-layout[data-bot-threads] > .messages-reply-pane > .messages-reply-resizer { display: none; }
/* Its head is the column's head, so it pads its contents by iPhone Duo's
   column of system chrome (`--ai-edge`, 0 everywhere else): unpadded, a
   thread's long title ran under the clock and the Wi-Fi ring (1 Nov 2026). */
#ai-screen .ai-main-pane .messages-thread-header[data-reply-head="alone"] {
  padding-inline-end: calc(16px + var(--ai-edge, 0px));
}
/* A WIDER COLUMN KEEPS A READABLE LINE (3 Nov 2026). With the 720px cap
   gone the column is 800px or more on a wide window, and a plan card's
   sentences ran the width of it. A thread's three standing parts are held to
   720px, the widest the column was before (`--ai-main-auto` above), centred
   by an inline gutter: below that width the gutter is 0 and their own 12px
   or 16px stands, so a narrower column is drawn exactly as it was. The Duo's
   rule below still takes the end side to its column. */
#ai-screen .ai-main-pane .messages-layout[data-bot-threads] :is(.chat-transcript, .chat-status, .chat-composer-bar):not(.dev-request *) {
  padding-inline: max(0px, calc((100% - 720px) / 2));
}
#ai-screen .ai-main-pane .messages-layout[data-bot-threads] .chat-status:not(.dev-request *) {
  padding-inline: max(16px, calc((100% - 720px) / 2));
}
#ai-screen .ai-main-pane .messages-layout[data-bot-threads] .chat-composer-bar:not(.dev-request *) {
  padding-inline: max(12px, calc((100% - 720px) / 2));
}
/* A private thread drawn on a public thread's page (20 Nov 2026, "A PRIVATE
   THREAD IS A PUBLIC THREAD'S PAGE" below) is not held to that measure: it
   fills the column as a request's page does in the same column, and its
   cards keep the page's own 12px. */
/* AND THE CHAT UNDER THE HEAD STOPS AT THE DUO'S COLUMN TOO (overnight
   audit B25, 2 November 2026). Run under it (1 Nov), the chat put its Send
   button, the "Live ›" row's chevron and the New divider's label inside the
   84px column, where the system's own apps put nothing but their bars: every
   other screen, and the column's head above, stop short of it. The sheet
   still reaches the screen's edge, so no band of another colour is left
   beside it: the chat's own sheet carries on under the column as padding,
   and only what is drawn in it stops, its head keeping its own clearance
   above. */
html[data-side-strip] #ai-screen .ai-main-pane .messages-layout[data-bot-threads] > .messages-reply-pane :is(.chat-transcript, .chat-status, .chat-composer-bar):not(.dev-request *) {
  padding-inline-end: var(--ai-edge, 0px);
}
/* A PRIVATE THREAD IS A PUBLIC THREAD'S PAGE (20 Nov 2026). A thread alone
   in the bot tab's column, under the standard and brand looks, is drawn on
   the page a request's thread is drawn on (group-chat/thread-page.tsx), as
   a request's page is drawn in the same column: the head card every thread
   leads with, floating over the page and tightening as it scrolls; the
   opening message as the first card, its foot saying where the thread went;
   the replies as the second; the reply box at the foot, as wide as the
   cards. One set of rules draws both: "ONE THREAD, ONE HEADER" and the
   blocks after it name `:is(#dev-topic-thread, #ai-screen)`, and the panel's
   rules ("THE PAGE ITSELF REACHES THE COLUMN'S EDGES", "IN A PANEL TOO")
   name `#ai-screen .dev-private-thread` beside the panels they already name.

   It was a sheet of its own until now (#6863, 19 Nov 2026): three cards
   held to 446px in the middle of the column, the replies scrolling inside
   the middle one and cut flat at its top edge, and a copy of the public
   head (#6877) whose rules drifted the same afternoon: Preview was forced
   into the 36px round button, its ring through the word. What is left here
   is only what a private thread has and a request's page does not. */
/* The pane is the column's own, with no sheet or ground of its own: the bot
   page's shows through, as it does behind a request's page in the column
   (`.side-panel[data-thread-pill]`). */
html:is(:not([data-skin]), [data-skin="brand"]) #ai-screen .messages-layout[data-bot-threads] > .messages-reply-pane[data-thread-page-host] {
  background: transparent;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}
/* The head's tile is the other member's round face. */
html:is(:not([data-skin]), [data-skin="brand"]) #ai-screen .dev-private-thread:has(.dev-thread-card) .dev-request-bar .dev-thread-bar-tile.dev-thread-bar-face { border-radius: 999px; }
html:is(:not([data-skin]), [data-skin="brand"]) #ai-screen .dev-private-thread .dev-thread-bar-tile.dev-thread-bar-face > * { width: 100%; height: 100%; border-radius: inherit; }
html:is(:not([data-skin]), [data-skin="brand"]) #ai-screen .dev-private-thread .dev-thread-bar-lock { display: inline-block; width: 12px; height: 12px; margin-inline-end: 4px; vertical-align: -1px; }
/* The opening card holds the message itself: its words and pictures, as a
   request's card holds the request's, with neither face nor name (its
   author row gives way, as the card's does: `.dev-thread-card
   .messages-message-head`). */
html:is(:not([data-skin]), [data-skin="brand"]) #ai-screen .dev-private-thread [data-thread-page-post] .messages-message { padding: 0; }
html:is(:not([data-skin]), [data-skin="brand"]) #ai-screen .dev-private-thread [data-thread-page-post] .messages-message > :first-child:not(.min-w-0) { display: none; }
html:is(:not([data-skin]), [data-skin="brand"]) #ai-screen .dev-private-thread [data-thread-page-post] .messages-message-image { max-width: min(240px, 100%); }
/* The replies card's rows are a public thread's: face, name and time on the
   left whoever said it, the words beneath, pictures as thumbnails. */
html:is(:not([data-skin]), [data-skin="brand"]) #ai-screen .dev-private-thread [data-thread-page-replies] .messages-message { padding: 8px 16px; gap: 12px; }
html:is(:not([data-skin]), [data-skin="brand"]) #ai-screen .dev-private-thread [data-thread-page-replies] .messages-message-self .messages-message-head { justify-content: flex-start; }
html:is(:not([data-skin]), [data-skin="brand"]) #ai-screen .dev-private-thread [data-thread-page-replies] .messages-message-image { max-width: min(240px, 100%); }
/* Beside iPhone Duo's column of system chrome (`--ai-edge`) the page stops
   short of it, as the chat it replaced did (B25 below): its ground is the
   column's, so nothing is left there but that ground. */
html[data-side-strip]:is(:not([data-skin]), [data-skin="brand"]) #ai-screen .messages-reply-pane > .dev-private-thread { padding-inline-end: var(--ai-edge, 0px); }
/* A request or a change opened from the list: the side panel in Main's
   place, and Main back when the panel closes. It is drawn as this page's
   own column, not as a panel of its own (29 Oct 2026): Main's width, edge
   and header, with ‹ Main Chat and the project the page is in over it, and none
   of the panel's own controls (side-panel.tsx) but its left edge: that is
   the handle Main's own edge is (30 Oct 2026), and both set one width. */
html[data-side-panel] #ai-screen .ai-main-pane { display: none; }
@media (min-width: 768px) {
  html[data-side-panel] #ai-screen { padding-inline-end: var(--ai-main-w); }
}
/* #6394: a plan, or a change's before and after, open beside a page held in
   the panel is a third column, so the list gives up the room both columns
   take. This outranks the rule above, which keeps the panel's lane only
   while the panel is the whole of that lane. */
html[data-side-panel] #ai-screen[data-ai-preview="three"] {
  padding-inline-end: calc(var(--ai-col-w) + var(--ai-preview-w));
}
body:has(#ai-screen:not(.hidden)) .side-panel {
  width: calc(var(--ai-main-w) + var(--ai-edge, 0px));
  border-start-end-radius: 0;
  border-start-start-radius: 1.75rem;
}
/* #6394: beside a page the panel holds, with a plan or a change's shots open
   beside THAT, the panel is the middle column: as wide as a thread is in
   three columns and ending where the preview begins, its rounded corner
   kept. In halves the list has stepped aside and the panel takes the rest
   of the room beside the preview. */
body:has(#ai-screen:is([data-ai-preview="three"], [data-ai-preview="halves"]):not(.hidden)) .side-panel {
  width: var(--ai-col-w);
  inset-inline-end: calc(var(--ai-preview-w) + var(--ai-edge, 0px));
}
.side-panel-head > :is(.side-panel-ai-close, .side-panel-place, .side-panel-more) { display: none; }
body:has(#ai-screen:not(.hidden)) .side-panel :is(.side-panel-ai-close, .side-panel-place, .side-panel-more) { display: inline-flex; }
/* And the page in it leaves out its own way back, "‹ Workshop": the column's
   × is the way back, and its project is beside it. The class is on the
   panel document's <html> while it stands beside this page (side-panel
   controller BESIDE_AI_CLASS). */
html.in-side-panel.side-panel-beside-ai :is(.dev-topic-backs, .dev-topic-back) { display: none; }
/* AND THE COLUMN IS ONE SHEET (30 Oct 2026), as Main is: the page lies flat
   under the column's heading rather than lifting its own sheets off it.
   AND, SINCE #6431, ONE HEADER: the column's heading names what is open, its
   number, where it stands (the page's own status pill) and everything its ⋯
   holds, so the page's bar is not drawn here at all — a request's or a
   change's, its number included. Two rows and two ⋯ buttons, with the
   actions split between them, were what Evan reported (6 Nov 2026). The page
   itself, everywhere else (the full page, the Workshop's side panel), keeps
   its bar exactly as it was. */
html.in-side-panel.side-panel-beside-ai .dc-lift { border-radius: 0; border-top: 0; box-shadow: none; }
html.in-side-panel.side-panel-beside-ai .dev-request-bar :is([data-request-kicker], .dev-request-bar-title, [data-request-category], [data-change-category]) { display: none; }
html.in-side-panel.side-panel-beside-ai .dev-request-bar { display: none; }
/* AND THE PAGE ITSELF REACHES THE COLUMN'S EDGES (3 Nov 2026). The 30 Oct
   rule above took the sheet's radius, top edge and shadow, but three things
   still drew a second box inside the column: #dev-topic-thread's 12px
   shoulder at the top, .dev-request's 780px cap with its centred 12px side
   margins, and .dc-lift-session's own fill and frost painted over the
   column's strip. The page now lies on the column's one surface, as Main
   Chat does; the 12px the wrapper gave its content moves onto the bar and
   the transcript, whose rows keep their own 16px. The composer's bar (12px)
   and the status line (16px) already carry theirs, so they need nothing.
   The Workshop's panel draws the same page and had the whole rounded,
   shaded box (#dev-topic-thread.dev-ws-side-page inside .dev-ws-side), so
   one rule set serves both. The page's cards, and the full page outside
   these two panels, are untouched. */
:is(html.in-side-panel.side-panel-beside-ai, .dev-ws-side) #dev-topic-thread {
  padding-top: 0;
}
:is(html.in-side-panel.side-panel-beside-ai, .dev-ws-side) .dev-request,
#ai-screen .dev-private-thread {
  /* The page's gutter, which its head, its cards and its reply box keep. */
  --thread-gutter: 12px;
  max-width: none;
  margin-inline: 0;
  padding-inline: 0;
}
:is(html.in-side-panel.side-panel-beside-ai, .dev-ws-side) .dev-request-sheet,
#ai-screen .dev-private-thread > .dev-request-sheet {
  background: transparent;
  border: 0;
  border-start-start-radius: 0;
  border-start-end-radius: 0;
  box-shadow: none;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}
:is(html.in-side-panel.side-panel-beside-ai, .dev-ws-side) :is(.dev-request-bar, .dev-request-scroll),
#ai-screen .dev-private-thread > .dev-request-sheet > :is(.dev-request-bar, .dev-request-scroll) {
  padding-inline: var(--thread-gutter);
}
/* THE COLUMN HAS MAIN CHAT'S SURFACE, #6432. The 30 Oct rules above took the
   page's own sheets away so it would lie flat in the column, but nothing
   painted the column itself: the panel document's body still drew the route
   wallpaper (its star, grain and washes), sized to the column and not lined
   up with the page's own, so Evan saw it through the request (6 Nov 2026).
   Main got a surface under it (#ai-screen .ai-main-pane, --home-ground with
   the --dc-sheet-fill thread pane over it); --dc-sheet-solid is that same
   composite, the list's cards' colour in both themes, so the page lies on it
   here. `background` clears the image too. `!important` is what beats the
   route rule's `:has(:is(#…))` (one id deep) and the brand skin's body
   background; the app-launch cover is written the same way. The fixed layer
   is a second copy the phone's browser scroller paints behind the body, and
   it goes too. No media query: the phone's drawer holds the same page. Only
   the document beside the bot page (a panel document, never the top one) is
   touched, so the full page and the Workshop's .dev-ws-side keep theirs, and
   the thread's own cards keep their fills. */
html.in-side-panel.side-panel-beside-ai body {
  background: var(--dc-sheet-solid) !important;
}
html.in-side-panel.side-panel-beside-ai body::before {
  background: none !important;
}
/* A DESIGN'S PREVIEW, A COLUMN OF ITS OWN (1 Nov 2026, threads, one loop
   C1; features/ai/preview.ts). Opened from a version in a thread, the design
   pane stands beside the thread: list | thread | preview where the three fit
   (1500px and up: the list keeps 480px, the thread 440px at most, the
   preview the rest), the thread and the preview in halves where they do not
   (the list steps aside), and the whole screen on a phone.
   BOTH EDGES ARE HANDLES (#6359, 6 Nov 2026). Each sets the width of the
   column after it and the list takes what is left: the thread's edge
   `--ai-col-chosen-w`, the preview's `--ai-preview-chosen-w`
   (features/side-panel/resize.ts). Until one is dragged the widths are the
   ones above. The floors hold here as in the drag: the list 480px, the
   thread 320px, the preview 360px; a preview dragged wide narrows the
   thread before it squeezes the list. In halves the list has stepped aside,
   so only the preview's edge is a handle there, and the thread is the rest. */
#ai-screen .ai-preview-pane {
  position: fixed;
  z-index: 21;
  inset-inline-end: 0;
  bottom: 0;
  top: calc(var(--browser-banner-h, 0px) + var(--platform-header-h) + var(--platform-safe-top, 0px) + .5rem);
  width: calc(var(--ai-preview-w) + var(--ai-edge, 0px));
  padding-inline-end: var(--ai-edge, 0px);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: var(--dc-sheet-solid, #fff);
  border-top: 1px solid var(--app-sheet-line);
  border-inline-start: 1px solid var(--app-sheet-line);
}
#ai-screen .ai-preview-pane > .messages-design-pane { border-radius: 0; box-shadow: none; padding-top: 4px; }
#ai-screen:not([data-ai-preview="three"])[data-ai-preview] .ai-main-pane > .side-panel-divider { display: none; }
/* THE WIDTHS ARE DECLARED ON THE BODY, NOT ON #ai-screen (#6394, 6 Nov
   2026). While a page is in the side panel, that panel is the middle column
   and it is an island of its own beside #ai-screen, so it can only read these
   through the body the two share. Everything they are made of (`--ai-room`
   and `--ai-main-w` on body, the `--ai-*-chosen-w` on <html>) already
   resolves there. #ai-screen inherits them, and its own padding below still
   takes the list down to where the columns begin. */
body:has(#ai-screen[data-ai-preview="three"]:not(.hidden)) {
  --ai-preview-auto: max(360px, calc(var(--ai-room) - 480px - min(var(--ai-main-w), 440px)));
  --ai-preview-w: max(360px, min(var(--ai-preview-chosen-w, var(--ai-preview-auto)), calc(var(--ai-room) - 800px)));
  --ai-col-w: max(320px, min(var(--ai-col-chosen-w, min(var(--ai-main-w), 440px)), calc(var(--ai-room) - 480px - var(--ai-preview-w))));
}
body:has(#ai-screen[data-ai-preview="halves"]:not(.hidden)) {
  --ai-preview-w: max(320px, min(var(--ai-preview-chosen-w, calc(var(--ai-room) / 2)), calc(var(--ai-room) - 320px)));
  --ai-col-w: calc(var(--ai-room) - var(--ai-preview-w));
}
#ai-screen[data-ai-preview="three"] {
  padding-inline-end: calc(var(--ai-col-w) + var(--ai-preview-w));
}
/* The edges' lines: the thread's and Main's on their pane's own hairline, the
   edge each drags (and outweighing that rule, at THE DIVIDER below), the
   preview's on the hairline where it meets the thread. */
body:has(#ai-screen:not(.hidden)) #ai-screen[data-ai-preview="three"] #ai-main-divider {
  --divider-at: calc(var(--ai-col-w) + var(--ai-preview-w) + var(--ai-edge, 0px));
}
#ai-preview-divider {
  --divider-at: calc(var(--ai-preview-w) + var(--ai-edge, 0px));
  top: calc(var(--browser-banner-h, 0px) + var(--platform-header-h) + var(--platform-safe-top, 0px) + .5rem);
}
#ai-screen[data-ai-preview="halves"] .ai-screen-body { display: none; }
#ai-screen:is([data-ai-preview="three"], [data-ai-preview="halves"]) .ai-main-pane {
  width: var(--ai-col-w);
  inset-inline-end: calc(var(--ai-preview-w) + var(--ai-edge, 0px));
}
/* A phone: the whole of the page, over the drawer, its arrow back to the thread. */
#ai-screen[data-ai-preview="full"] .ai-preview-pane {
  position: absolute;
  inset: 0;
  z-index: 30;
  width: auto;
  border: 0;
}
/* A thread's Preview, in its head: a word, not a glyph, on the disc. */
.messages-thread-action.messages-thread-preview { width: auto; padding: 0 14px; }

/* ── The AI tab on a phone, as a drawer (features/ai/phone-drawer.tsx) ──
   The Messages drawer's strip: the list at 85% of the screen, the thread
   beside it, peeking at the list's right until it is opened, then the whole
   screen. The page does not scroll; the list does. */
#ai-screen[data-ai-drawer] { overflow: hidden; }
.ai-drawer { position: absolute; inset: 0; overflow: hidden; touch-action: pan-y; }
.ai-drawer-strip { position: absolute; inset: 0; will-change: transform; }
/* touch-action stops at a scroller, so the column's chat says pan-y itself, as
   Messages' does: left to `auto`, the browser took a sideways drag there and
   cancelled the pointer, and the swipe back did nothing. */
.ai-drawer .messages-thread-scroll { touch-action: pan-y; }
.ai-drawer-list {
  position: absolute; top: 0; bottom: 0; inset-inline-start: 0; width: 85%;
  overflow-y: auto; overscroll-behavior: contain; touch-action: pan-y;
  /* #6838: a guard only: the list scrolls up and down, never sideways. */
  overflow-x: hidden;
}
.ai-drawer-thread {
  position: absolute; top: 0; bottom: 0; inset-inline-start: 85%; width: 100%;
  display: flex; flex-direction: column; overflow: hidden;
  background: var(--home-ground);
  border-inline-start: 1px solid var(--app-sheet-line);
  box-shadow: calc(-8px * var(--rtl-sign)) 0 24px rgba(0, 0, 0, 0.08);
}
.ai-drawer-pane { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; }
.ai-drawer-pane > .messages-layout { flex: 1 1 auto; height: auto; min-height: 0; }
.ai-drawer-thread .messages-thread-pane { border-radius: 0; border-top: 0; box-shadow: none; }
/* On the list a thread's arrow has nowhere to go: it arrives as the thread
   opens. */
.ai-drawer[data-level="0"] .messages-thread-back { opacity: 0; transform: translateX(calc(8px * var(--rtl-sign))); pointer-events: none; }
/* The Ask bar sits at the list's foot, in its column, not over the screen.
   ON THE TAB BAR, NOT UNDER IT (overnight audit B14, 2 November 2026). The
   list runs to the foot of the screen, under the tab bar, and the bar stuck
   to that foot was behind the tab bar on every phone; in the Android app its
   words showed through under the system's navigation bar. It sticks the
   bar's height up, and keeps that much room after the list's last row, so
   scrolled to the end the last row still clears it. With the keys up the
   bar's height is 0, and so is this. */
#ai-screen .ai-drawer-list .ai-askbar {
  position: sticky; inset-inline-start: auto; inset-inline-end: auto;
  bottom: var(--platform-tabs-h, 0px);
  margin-bottom: var(--platform-tabs-h, 0px);
}
#ai-screen .ai-drawer-list .ai-askbar-gap { display: none; }
.ai-drawer[data-panning] { user-select: none; -webkit-user-select: none; }
/* The list is the whole screen and the column waits off its right edge,
   with no peek (phone-drawer.tsx, FULL_AT; Evan, 1 Nov 2026, and always
   since 3 Nov). Its shadow would show at the list's edge, so it comes only
   with the slide. */
.ai-drawer:not([data-peek]) .ai-drawer-list { width: 100%; }
.ai-drawer:not([data-peek]) .ai-drawer-thread { inset-inline-start: 100%; }
.ai-drawer:not([data-peek])[data-level="0"]:not([data-panning]) .ai-drawer-thread { box-shadow: none; border-inline-start-color: transparent; }
/* Where the window has the room, the feed takes a project's stage width
   (720px) out of the screen's 672px column, as far as that column's own
   margins go. */
@media (min-width: 1180px) {
  .workshop-needs-feed { margin-inline-start: -80px; margin-inline-end: -80px; }
}
.workshop-reel-loading { background: var(--dc-sheet-solid); border-radius: 20px; }
.workshop-reel-app {
  display: inline-flex; align-items: center; gap: 8px; min-width: 0;
  font-size: 13px; font-weight: 650; color: var(--text-primary); text-decoration: none;
}
.dev-ws-item-caption > .workshop-reel-app { align-self: flex-start; max-width: 100%; color: var(--text-primary); }
.workshop-reel-tile {
  width: 26px; height: 26px; flex: none; border-radius: 8px; overflow: hidden;
  display: flex; align-items: center; justify-content: center; font-size: 13px; font-weight: 700;
}
/* A group decision's vote sheet opens its page: the answer button's shape,
   as a link, in the accent. */
.dev-ws-answer-open {
  display: flex; align-items: center; justify-content: center;
  border-color: transparent; background: var(--accent); color: #fff; text-decoration: none;
}
/* ── THE PROJECT HUB'S OWN CARDS (features/dev-board/workshop/hub-cards.tsx) ──
   Under the hero, each part under its small-caps label (SectionHeader):
   For you and Recently live. They are `.dev-ws-strip` cards, and what is
   new here is only what they hold: doors and three pictures. */
.dev-ws-head-end, .dev-ws-hub-head-end { margin-inline-start: auto; }
.dev-ws-hub-head-end { display: inline-flex; align-items: center; gap: 8px; }
.dev-ws-hub-open {
  display: inline-flex; align-items: center; gap: 2px;
  font-size: 13px; font-weight: 600; color: var(--accent);
  background: none; border: 0; padding: 0; cursor: pointer;
}
.dev-ws-hub-needs-join { margin: 0; font-size: 12.5px; color: var(--text-muted); }
/* A part of the hub: its label over its card. A label with a door beside
   it ("All in Workshop") is one row, the door at its far end. */
.dev-ws-hub-section { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.dev-ws-hub-sechead { display: flex; align-items: center; gap: 8px; padding-inline-end: 4px; }
.dev-ws-hub-sechead > .dev-ws-hub-open { margin-inline-start: auto; padding-top: 8px; }
/* FOR YOU (ForYouCard): one card of doors, a hairline between them. Each
   door is the grouped list's row (ListRow, 15 over 13) laid on the card's
   own padding, with at most one pill: a number that asks for you, in the
   accent, or a count in words, muted. */
.dev-ws-strip.dev-ws-foryou { gap: 0; padding: 2px 14px; }
.dev-ws-foryou > * + * { border-top: 1px solid var(--app-sheet-line); }
.dev-ws-foryou .dev-ws-foryou-row { gap: 12px; padding: 12px 2px; background: transparent; }
/* No vote owed: the quiet line in the Needs you row's place, at a row's
   second-line size, from the rows' own edge. */
.dev-ws-foryou > .dev-ws-week-note { margin: 0; padding: 14px 2px; font-size: 13px; text-align: start; }
.dev-ws-foryou-item > .dev-ws-hub-needs-join { padding-block: 0 12px; padding-inline: 46px 2px; margin-top: -6px; }
.dev-ws-foryou-pill {
  flex: none; height: 22px; padding: 0 9px; border-radius: 999px;
  display: inline-grid; place-items: center; white-space: nowrap;
  background: var(--accent); color: #fff;
  font-size: 12.5px; font-weight: 700; font-variant-numeric: tabular-nums;
}
/* The Discussion row's count is NEW TO READ, not waiting on you (#18): the
   grey the sidebar's "2 unread" beside it wears, where the accent made the
   same messages read as a vote owed (audit N04, 1 Nov 2026). */
.dev-ws-foryou-pill[data-ws-channel-unread] { background: var(--text-faint, #8e8e93); }
/* For somebody not in the community, Up for a vote's count says how many,
   not how many wait on them: the accent's light tint, not its fill. */
.dev-ws-foryou-pill.dev-ws-foryou-pill-light { background: color-mix(in srgb, var(--accent) 12%, transparent); color: var(--accent); }
.dev-ws-foryou-count { flex: none; font-size: 13px; color: var(--text-muted); white-space: nowrap; }
.dev-ws-foryou-handle { font-weight: 500; color: var(--text-muted); }
/* The Discussion row's last line: the message gives way, the time stays
   whole (audit P04, 1 Nov 2026). */
[data-ws-channel-last]:has(> [data-ws-channel-ago]) { display: flex; min-width: 0; }
[data-ws-channel-last] > [data-ws-channel-said] { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
[data-ws-channel-last] > [data-ws-channel-ago] { flex: none; white-space: pre; }
/* RECENTLY LIVE (RecentlyLive): three picture cards, each a door to its
   change: its after shot (or a plain tile), its title, who and when. A row
   that scrolls sideways on a phone, three across on a wide window. */
.dev-ws-strip.dev-ws-recent { padding: 14px 0; }
/* Recently live's last row: how many more went live this month, opening the
   Workshop (hub-cards.tsx RecentlyLive). A door in the accent, under the
   pictures, the width of the card. */
.dev-ws-recent-more {
  display: flex; align-items: center; gap: 12px; width: 100%; min-height: 52px;
  margin-top: 12px; margin-bottom: -14px; padding: 8px 14px; box-sizing: border-box;
  border: 0; border-radius: 0 0 22px 22px; cursor: pointer; text-align: start;
  background: transparent; color: var(--accent);
  box-shadow: inset 0 1px 0 var(--app-sheet-line);
  -webkit-tap-highlight-color: transparent;
}
.dev-ws-recent-more-n {
  flex: none; min-width: 56px; height: 32px; padding: 0 8px; box-sizing: border-box;
  display: inline-grid; place-items: center; border-radius: 10px;
  background: color-mix(in srgb, var(--accent) 12%, transparent); color: var(--accent);
  font-size: 13px; font-weight: 700; font-variant-numeric: tabular-nums;
}
.dev-ws-recent-more-words { flex: 1; min-width: 0; font-size: 15px; font-weight: 650; }
@media (hover: hover) {
  .dev-ws-recent-more:hover { background: color-mix(in srgb, var(--accent) 6%, transparent); }
}
.dev-ws-recent-list {
  list-style: none; margin: 0; padding: 0 14px;
  display: flex; gap: 12px; overflow-x: auto; scroll-snap-type: x proximity;
  scrollbar-width: none; overscroll-behavior-x: contain;
}
.dev-ws-recent-list::-webkit-scrollbar { display: none; }
.dev-ws-recent-item { flex: 0 0 210px; min-width: 0; scroll-snap-align: start; }
@media (min-width: 768px) {
  .dev-ws-recent-list { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); overflow: visible; }
  .dev-ws-recent-item { flex: none; }
}
.dev-ws-recent-card {
  display: flex; flex-direction: column; gap: 6px; min-width: 0;
  color: inherit; text-decoration: none; -webkit-tap-highlight-color: transparent;
}
.dev-ws-recent-card:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; border-radius: 12px; }
/* The app's own card, before any change has gone live (RecentlyLive `own`):
   a button that opens the app, its tile where a change's picture would be. */
button.dev-ws-recent-card {
  width: 100%; margin: 0; padding: 0; border: 0; background: none;
  font: inherit; text-align: start; cursor: pointer;
}
.dev-ws-recent-app {
  width: 52px; height: 52px; overflow: hidden; display: grid; place-items: center;
  border-radius: 16px; font-size: 26px; font-weight: 700;
}
.dev-ws-recent-app > img { width: 100%; height: 100%; object-fit: cover; border-radius: 0; }
.dev-ws-recent-app > span { font-size: inherit; line-height: 1; }
.dev-ws-recent-pic {
  position: relative; display: grid; place-items: center; aspect-ratio: 16 / 10; overflow: hidden;
  border-radius: 12px; background: var(--bg-tertiary);
  box-shadow: inset 0 0 0 1px var(--app-sheet-line);
}
.dev-ws-recent-pic > img {
  position: absolute; inset: 0; width: 100%; height: 100%;
  object-fit: cover; object-position: top center;
}
.dev-ws-recent-glyph { width: 26px; height: 26px; color: var(--text-muted); opacity: .6; }
/* A change with no picture, and the app's own card: the project's tile on its
   community's colour, the band's own `--community-tint` (polish board N13),
   where a grey box with a check was. */
.dev-ws-recent-pic:is([data-ws-recent-pic="plain"], [data-ws-recent-pic="app"]) {
  background: var(--community-tint, var(--bg-tertiary));
}
.dev-ws-recent-title {
  font-size: 14px; font-weight: 650; line-height: 1.3; color: var(--text-primary);
  display: -webkit-box; -webkit-line-clamp: 3; line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden;
  overflow-wrap: anywhere;
}
.dev-ws-recent-meta { font-size: 12.5px; color: var(--text-muted); }
.dev-ws-recent-going { color: var(--lit-ink); }
/* ── A page's head: the way back, and the page's name ──────────────────
   workshop.tsx's PageBack, in the bar a page leads with (the Workshop,
   Needs you, All items; the hub has none). The back is the header's own
   back disc, in the header's brand ink, since it does the header's job one
   level down; the name is the page's one heading, under the name of where
   the disc goes. */
.dev-ws-pagehead { display: flex; align-items: center; gap: 10px; min-width: 0; }
.dev-ws-page-back {
  width: 36px; height: 36px; flex: none; padding: 0;
  display: grid; place-items: center;
  border: 0; border-radius: 999px; cursor: pointer;
  background: var(--brand-tint); color: var(--brand-ink);
  -webkit-tap-highlight-color: transparent;
}
.dev-ws-page-back:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.dev-ws-page-back-glyph { width: 18px; height: 18px; stroke-width: 2.2; }
.dev-ws-pagehead-text { display: flex; flex-direction: column; min-width: 0; }
.dev-ws-pagehead-over {
  font-size: 12px; line-height: 16px; color: var(--text-muted);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.dev-ws-pagehead-title {
  margin: 0; font-size: 20px; font-weight: 700; line-height: 24px;
  letter-spacing: -.01em; color: var(--text-primary);
}

/* #2915: a search or filter left on in All items, said where it is out of
   sight (the Workshop's door, All items' See all): the accent, a 6px round. */
.dev-ws-filter-dot { flex: none; width: 6px; height: 6px; border-radius: 999px; background: var(--accent); }
.dev-ws-hub-open .dev-ws-filter-dot { margin: 0 2px; }
/* First version (hub-cards.tsx FirstVersionCard, #4045): the project's
   thumbnail drawn small (sketch-card.tsx ThumbRow: its icon on its colour,
   its name and one line), with "See the plan" as a quiet link at the row's
   end for a member, or one button under the row. Open app wears the hero's
   Open app, in the community's colour, a full row wide. */
.dev-ws-hub-first-row { display: flex; align-items: center; gap: 10px; min-width: 0; }
.dev-ws-hub-first-row > [data-thumb-row] { flex: 1 1 auto; }
/* The ⋯ menu's settings (actions-row.tsx, #4045): behind one "Settings &
   rules" row. On desktop the dropdown turns to them in place, on top of
   the menu's own rows, until its back row or a close turns it back. */
#dev-plus-menu .dev-plus-settings { display: none; }
#dev-plus-menu[data-plus-view="settings"] > :not(.dev-plus-settings) { display: none; }
#dev-plus-menu[data-plus-view="settings"] > .dev-plus-settings { display: block; }

.dev-ws-hub-first-see {
  flex: none; display: inline-flex; align-items: center; min-height: 44px; padding: 0 2px;
  border: 0; background: none; cursor: pointer;
  font: inherit; font-size: 15px; font-weight: 500; white-space: nowrap; color: var(--accent);
}
.dev-ws-hub-first .dev-ws-hub-first-open { width: 100%; height: 40px; justify-content: center; font-size: 16px; font-weight: 600; }

/* The plan, for the people who joined (plan-page.tsx, #4074): a page under
   the Hub. Its head is the disc back to the Hub and Homeroom bot's face and
   name; then the plan as a card, read only; then who decides, and the way
   to the Discussion tab. */
.dev-ws-plan { display: flex; flex-direction: column; gap: 12px; }
.dev-ws-planhead { display: flex; align-items: center; gap: 10px; min-height: 44px; }
.dev-ws-plan-bot { width: 30px; height: 30px; border-radius: 8px; flex: none; object-fit: cover; }
.dev-ws-plan-bot-name { font-size: 17px; font-weight: 650; color: var(--text-primary); }
.dev-ws-plan-ai { font-size: 12px; font-weight: 600; color: var(--text-muted); }
.dev-ws-plan-head { display: flex; flex-direction: column; gap: 2px; padding: 4px 4px 0; }
.dev-ws-plan-title { margin: 0; font-size: 20px; line-height: 26px; font-weight: 700; color: var(--text-primary); }
.dev-ws-plan-step { margin: 0; font-size: 13px; line-height: 18px; color: var(--text-muted); }
/* One row per line of the plan, a grouped list's rows: 15px on a 22px line,
   12px above and below, a hairline between rows from the text's edge. */
.dev-ws-plan-row {
  position: relative; padding: 12px 16px;
  font-size: 15px; line-height: 22px; color: var(--text-primary);
}
.dev-ws-plan-row:not(:last-child)::after {
  content: ''; position: absolute; inset-inline-start: 16px; inset-inline-end: 0; bottom: 0;
  height: 1px; background: var(--app-sheet-line);
}
.dev-ws-plan-q { display: flex; flex-direction: column; gap: 2px; }
.dev-ws-plan-qq { margin: 0; font-size: 13px; line-height: 18px; color: var(--text-muted); }
.dev-ws-plan-qa { margin: 0; font-size: 15px; line-height: 22px; color: var(--text-primary); }
.dev-ws-plan-foot { display: flex; flex-direction: column; align-items: center; gap: 2px; text-align: center; }
.dev-ws-plan-who { margin: 0; font-size: 14px; line-height: 20px; color: var(--text-muted); }
.dev-ws-plan-talk {
  display: inline-flex; align-items: center; min-height: 44px; padding: 0 4px;
  border: 0; background: none; cursor: pointer;
  font: inherit; font-size: 15px; font-weight: 500; color: var(--accent);
}

/* ── Since your last visit, week by week (the Workshop page) ──────────
   Each week is a division of the pane, as the walk's windows were: a
   hairline, the week's heading and range, its line, and what moved in it
   nested under a rule at the left, so the rows read as the line's
   evidence. A week's rows past the first three, new and then already seen,
   come out a few at a time under ONE quiet reveal (#3524). */
.dev-ws-since-week {
  display: flex; flex-direction: column;
  border-top: 1px solid var(--app-sheet-line);
  margin-top: 4px; padding-top: 11px;
}
.dev-ws-since-week-head {
  display: flex; align-items: baseline; flex-wrap: wrap; gap: 4px 10px; margin: 0;
  font-size: 13px; font-weight: 600; letter-spacing: 0.01em; color: var(--text-primary);
}
.dev-ws-since-week-n { font-size: 12px; font-weight: 500; letter-spacing: 0; color: var(--text-muted); }
.dev-ws-since-week-line { margin: 6px 0 0; font-size: 14px; line-height: 1.45; color: var(--text-primary); }
.dev-ws-since-nest {
  display: flex; flex-direction: column; gap: 4px;
  margin: 10px 0 0; padding-inline-start: 10px;
  border-inline-start: 2px solid var(--app-sheet-line);
}
/* #3524: the week's one reveal. It was two grey 36px pill rows stacked
   here ("N more new" in the accent, "N more you have seen" with a check),
   the most solid-looking things in the week and two different chevrons
   side by side. Now it is the pane's own `.dev-ws-reveal`, the gesture
   every other "more" in the pane uses, set to the LEFT, inside the week's
   rule, so it belongs to the rows above it and not to `Show an earlier
   week` below. The count still hidden rides it in the lighter weight. */
.dev-ws-since-week-more { justify-content: flex-start; padding: 4px 12px 2px; }
.dev-ws-since-week-left { font-weight: 500; }
.dev-ws-since-nest > .dev-ws-since-seen { margin-top: 2px; padding-inline-start: 0; }

/* ── Share it (community-card.tsx ShareItCard) ──────────────────────
   A project that is just yours: its two ways to grow, side by side. The
   "Open it up" question hangs from its button's LEFT here, since the
   buttons lead the row and a popup opening leftward would leave the screen.
   Once a link is out, one muted line over the card's text says so, who
   came in and how long it has left (inviteSentLine), at the rows' 13. */
.dev-ws-share-sent { margin: 0; font-size: 13px; line-height: 18px; color: var(--text-muted); }
.dev-ws-share-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
/* A version's Update card (hub-cards.tsx UpdateCard, docs/plans/versions.md)
   is drawn as Share it is, `.dev-ws-share` and all: a title, a line, a row
   of pills. Its line can be a change's whole title, so it wraps rather than
   running off the card. */
.dev-ws-update .dev-ws-strip-text { overflow-wrap: anywhere; }
/* The ✕ that closes Share it, or "What do you want to change?", for good
   (community-card.tsx HubCardClose): at the far end of the card's head,
   muted, a circle that shows only when pressed or hovered. */
.dev-ws-card-close {
  margin-block: -6px -6px; margin-inline: auto -6px; flex: none;
  width: 30px; height: 30px; border-radius: 999px;
  display: grid; place-items: center;
  color: var(--text-muted); background: transparent;
}
.dev-ws-card-close:hover { background: var(--bg-tertiary); color: var(--text-primary); }
.dev-ws-card-close:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
.dev-ws-card-close svg { width: 16px; height: 16px; }
.dev-ws-share .dev-ws-join-anchor { margin-inline-start: 0; }
.dev-ws-share .dev-ws-join-pop { inset-inline-start: -6px; inset-inline-end: auto; }
.dev-ws-share .dev-ws-join-pop::before { inset-inline-start: 26px; inset-inline-end: auto; }
@media (prefers-reduced-motion: no-preference) {
  .dev-ws-share .dev-ws-join-pop { transform-origin: 32px 0; }
}
.dev-ws-share:has(.dev-ws-join-pop) { position: relative; z-index: 5; }

/* ── First look (hub-cards.tsx FirstLookView, newcomer run six) ──────
   The maker's First version card while their first version is built
   (21 Oct 2026; a card of its own after For you until then): the picture
   Homeroom bot drew of its main screen, small and phone-shaped (cropped
   from the top, as a phone shows a screen), beside the project's name as
   the thumbnail row draws it, the build line, one line in Share it's own
   type, and its button. The picture's box is fixed, so nothing moves as it
   loads. */
.dev-ws-strip.dev-ws-first-look { position: relative; flex-direction: row; align-items: flex-start; gap: 14px; }
/* #5618: the picture and the words open the maker's chat with Homeroom
   bot. The door is an empty button over the card, under its Watch button,
   so the card keeps its look: only a hover tint and the focus ring show it. */
.dev-ws-first-look-open {
  position: absolute; inset: 0; z-index: 1; border: 0; padding: 0;
  background: transparent; border-radius: inherit; cursor: pointer;
}
.dev-ws-first-look-open:hover { background: rgba(10, 10, 10, 0.03); }
.dark .dev-ws-first-look-open:hover { background: rgba(255, 255, 255, 0.04); }
.dev-ws-first-look-open:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.dev-ws-first-look-shot {
  flex: none; width: 64px; height: 138px; border-radius: 12px;
  object-fit: cover; object-position: top;
  background: var(--bg-secondary);
  box-shadow: 0 0 0 1px var(--app-sheet-line);
}
.dev-ws-first-look-body {
  flex: 1 1 auto; min-width: 0;
  display: flex; flex-direction: column; align-items: flex-start; gap: 4px;
}
.dev-ws-first-look-name {
  margin: 0; max-width: 100%; font-size: 15px; font-weight: 650; line-height: 20px;
  color: var(--text-primary); overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.dev-ws-first-look-body .dev-ws-strip-text { color: var(--text-muted); }
/* Its buttons keep their own taps, over the door (#5618). */
.dev-ws-first-look-body > button { position: relative; z-index: 2; margin-top: 8px; }

/* ── Approval rules (community-card.tsx ApprovalRules) ─────────────── */
.dev-ws-rules-line { margin: 0; font-size: 14px; line-height: 1.45; color: var(--text-primary); }

/* ── Swipe to vote, on a phone (#3052) ─────────────────────────────────
   workshop.tsx's `useSwipeVote` is the gesture; this is how it looks. A
   card the viewer can vote on is `[data-ws-swipeable]`, and while a drag is
   on it carries `--ws-swipe-x` (px, right is Yes), `--ws-swipe-p` (0 to 1,
   how near the line) and `[data-ws-swipe]` naming the side. Both come off
   once it is back at rest, so an untouched card has no transform.

   `touch-action: pan-y` hands the vertical drag to the scroller, as ever,
   and keeps the sideways one for the gesture. Anything narrower would take
   the pan the feed pages on away from every touch that starts on a card,
   the trap #1762 fell into on Home.

   The hints are stamps half way down the card, on the side the card is
   leaving from, where the title and summary are not: the text sits at the
   top and the middle is the picture or air. Each is laid on the page
   colour, so it reads the same over a dark capture as over the tint, and it
   fades in with the drag, never past 0.9. Where motion is unwelcome the
   card itself does not travel or spring: only the hint says what letting
   go would do. */
.dev-ws-swipe-hint {
  position: absolute; top: 50%; z-index: 2;
  padding: 3px 14px; border: 2px solid currentColor; border-radius: 12px;
  font-size: 28px; font-weight: 800; line-height: 1.2; letter-spacing: .05em;
  text-transform: uppercase;
  background-color: var(--bg-primary);
  opacity: 0; pointer-events: none;
}
.dev-ws-swipe-yes {
  inset-inline-start: 20px; color: var(--state-ok);
  background-image: linear-gradient(var(--state-ok-bg), var(--state-ok-bg));
  transform: translateY(-50%) rotate(-10deg);
}
.dev-ws-swipe-no {
  inset-inline-end: 90px; color: var(--state-blocked);
  background-image: linear-gradient(var(--state-blocked-bg), var(--state-blocked-bg));
  transform: translateY(-50%) rotate(10deg);
}
.dev-ws-item[data-ws-swipe="yes"] > .dev-ws-swipe-yes,
.dev-ws-item[data-ws-swipe="no"] > .dev-ws-swipe-no { opacity: calc(var(--ws-swipe-p, 0) * .9); }
@media (max-width: 699.98px) {
  .dev-ws-needs-scroll { overflow-x: hidden; }
  .dev-ws-item[data-ws-swipeable] { touch-action: pan-y; }
  .dev-ws-item[data-ws-swiping] { user-select: none; -webkit-user-select: none; }
}
@media (max-width: 699.98px) and (prefers-reduced-motion: no-preference) {
  .dev-ws-item[data-ws-swipe] { transform: translateX(var(--ws-swipe-x, 0px)); }
  .dev-ws-item[data-ws-swipe]:not([data-ws-swiping]) { transition: transform .26s cubic-bezier(.2, .8, .2, 1); }
  .dev-ws-item[data-ws-swipe]:not([data-ws-swiping]) > .dev-ws-swipe-hint { transition: opacity .2s ease; }
}
/* Reduce motion setting (#6510): none of the motion above, when Settings asks for it. */
@media (max-width: 699.98px) {
  :where(html[data-motion="reduce"]) .dev-ws-item[data-ws-swipe] { transform: none; }
  :where(html[data-motion="reduce"]) .dev-ws-item[data-ws-swipe]:not([data-ws-swiping]) { transition: none; }
  :where(html[data-motion="reduce"]) .dev-ws-item[data-ws-swipe]:not([data-ws-swiping]) > .dev-ws-swipe-hint { transition: none; }
}

/* ── The picture: the two stills, cropped to what changed ──────────────
   The view is the box the still is placed in; the still keeps its natural
   size and is moved and scaled with a transform (workshop.tsx computes the
   crop), so the outline can sit on the changed region in the same
   coordinates. It fills the card from under its switch to its foot, edge
   to edge, under the caption, and never scrolls. */
.dev-ws-media {
  position: relative;
  flex: 1 1 auto; min-height: 120px;
  margin: 12px 0 0;
  display: flex; flex-direction: column;
}
.dev-ws-media-view {
  position: relative; flex: 1 1 auto; min-height: 0;
  overflow: hidden;
  background: #111114;
}
.dev-ws-media-img { position: absolute; inset-inline-start: 0; top: 0; max-width: none; transform-origin: 0 0; display: block; }
.dev-ws-media-spot {
  position: absolute; pointer-events: none;
  border: 2px solid #16a34a; border-radius: 8px;
  box-shadow: 0 0 0 3px rgba(22, 163, 74, .25), 0 0 22px rgba(22, 163, 74, .35);
}
.dev-ws-media-wait {
  position: absolute; inset: 0;
  background: linear-gradient(90deg, rgba(255, 255, 255, .04), rgba(255, 255, 255, .10), rgba(255, 255, 255, .04));
}
/* The switch and the way out sit in a bar ABOVE the picture, never on it:
   laid over the still they covered the corner a change often is. */
.dev-ws-media-bar {
  display: flex; align-items: center; justify-content: space-between; gap: 8px;
  margin: 0 14px 8px; min-height: 30px;
}
.dev-ws-media-full {
  flex: none; padding: 6px 11px; border: 0; border-radius: 9999px; cursor: pointer;
  font: inherit; font-size: 12px; font-weight: 600; line-height: 1.2;
  background: var(--state-neutral-bg); color: var(--text-secondary);
}
.dev-ws-seg {
  display: inline-flex; flex: none; padding: 2px; border-radius: 9999px;
  background: var(--state-neutral-bg);
}
.dev-ws-seg-btn {
  padding: 5px 12px; border: 0; border-radius: 9999px; cursor: pointer;
  font: inherit; font-size: 12px; font-weight: 700;
  background: none; color: var(--text-secondary);
}
.dev-ws-seg-btn[aria-pressed="true"] { background: #fff; color: #14171f; box-shadow: 0 1px 2px rgba(0, 0, 0, .14); }
.dev-ws-seg-one { padding: 5px 12px; font-size: 12px; font-weight: 700; color: var(--text-secondary); }
/* With a run's outlines the switch wears their colours: red where it was,
   green where it is now. */
.dev-ws-seg-btn.dev-ws-seg-before[aria-pressed="true"] { background: #dc2626; color: #fff; }
.dev-ws-seg-btn.dev-ws-seg-after[aria-pressed="true"] { background: #15803d; color: #fff; }
.dev-ws-media-size { font-size: 12px; font-weight: 600; color: var(--text-muted); }

/* ── The picture from a before & after run (workshop.tsx ShotsPicture) ──
   One screen, cropped to the areas the run outlined. Both sides are laid in
   the view with the same transform and one is hidden, so a flip never moves
   the crop; the outlines are drawn in the view's own pixels over them, so a
   line and a number stay crisp whatever the scale. */
.dev-ws-media-shots .dev-ws-media-view { cursor: pointer; }
.dev-ws-media-shots .dev-ws-media-view:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.dev-ws-shot-side { position: absolute; inset-inline-start: 0; top: 0; transform-origin: 0 0; }
.dev-ws-shot-side > img { display: block; width: 100%; height: 100%; max-width: none; }
.dev-ws-media-shots[data-side="after"] .dev-ws-shot-before,
.dev-ws-media-shots[data-side="before"] .dev-ws-shot-after,
.dev-ws-media-shots[data-side="after"] .dev-ws-shot-on-before,
.dev-ws-media-shots[data-side="before"] .dev-ws-shot-on-after { visibility: hidden; }
.dev-ws-shot-box { position: absolute; pointer-events: none; border: 2px solid #16a34a; border-radius: 6px; background: rgba(22, 163, 74, .1); }
.dev-ws-shot-box.dev-ws-shot-on-before { border-color: #dc2626; background: rgba(220, 38, 38, .1); }
.dev-ws-shot-box.dev-ws-shot-box-other { border: 1.5px dashed rgba(161, 161, 170, .95); background: transparent; }
/* Lifted by its own width, so a line at the very foot of a shot shows. */
.dev-ws-shot-mark { position: absolute; pointer-events: none; height: 0; margin-top: -2px; border-top: 2px dashed #16a34a; }
.dev-ws-shot-mark.dev-ws-shot-on-before { border-top-color: #dc2626; }
.dev-ws-shot-n {
  flex: none; width: 20px; height: 20px; border-radius: 9999px; display: inline-grid; place-items: center;
  font-size: 11px; font-weight: 700; line-height: 1; color: #fff; background: #16a34a; font-variant-numeric: tabular-nums;
}
.dev-ws-shot-box > .dev-ws-shot-n, .dev-ws-shot-mark > .dev-ws-shot-n {
  position: absolute; inset-inline-start: -9px; top: -9px; box-shadow: 0 0 0 2px #111114;
}
.dev-ws-media-shots[data-side="before"] .dev-ws-shot-n { background: #dc2626; }
/* The changes its outlines are numbered by: the caption's "more" lists
   them. */
.dev-ws-shot-changes { list-style: none; margin: 0; padding: 0; display: grid; gap: 6px; }
.dev-ws-shot-change { display: flex; align-items: flex-start; gap: 8px; min-width: 0; font-size: 15px; font-weight: 650; line-height: 1.3; color: var(--text-primary); }
.dev-ws-shot-change > .dev-ws-shot-n { margin-top: 1px; }
/* A long URL or word in a change's words wraps in its row (and the row in
   the list's grid column) instead of widening the caption. */
.dev-ws-shot-change > :not(.dev-ws-shot-n) { min-width: 0; overflow-wrap: anywhere; }
.dev-ws-shot-text { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }

/* ── A change's diagram and "What it touches" (#4490, lib/diagram) ──
   The picture a change shows when it has no before & after shots: a
   rounded sheet on a change's page, the card's type scale (15 over 13,
   small caps for the one label) and the one accent. The new word or step is
   in the accent blue, the old one muted and struck through; nothing is
   filled green or red. A long word wraps; the picture never scrolls inside
   the card. On a Needs-you card it is drawn straight on the dark, larger,
   from the top of the picture's space down (the caption covers the foot). */
.dev-ws-diagram {
  display: flex; flex-direction: column; gap: 12px; min-width: 0;
  padding: 16px; border-radius: 18px;
  background: var(--dc-sheet-solid);
  box-shadow: inset 0 0 0 1px var(--app-sheet-line);
  color: var(--text-primary); overflow-wrap: anywhere;
}
.dev-ws-item > .dev-ws-diagram {
  flex: 1 1 auto; min-height: 0; margin: 16px 0 0; padding-block: 0 16px; padding-inline: 24px 80px; overflow: hidden;
  gap: 14px; border-radius: 0; background: none; box-shadow: none;
}
.dev-ws-item > .dev-ws-diagram .dev-ws-diagram-src { margin: 2px 0 0; font-size: 12.5px; }
.dev-ws-item > .dev-ws-diagram .dev-ws-diagram-rows { gap: 12px; }
.dev-ws-item > .dev-ws-touches .dev-ws-diagram-what { font-size: 15px; font-weight: 650; }
.dev-ws-item > .dev-ws-touches .dev-ws-diagram-bar { height: 9px; }
.dev-ws-item > .dev-ws-diagram[role="button"] { cursor: pointer; }
.dev-ws-diagram[role="button"]:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.dev-ws-diagram-kicker {
  font-size: 12px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--text-muted);
}
.dev-ws-diagram-body { display: flex; flex-direction: column; gap: 12px; min-height: 0; }
.dev-ws-diagram-src { margin: auto 0 0; font-size: 12px; line-height: 1.35; color: var(--text-muted); }
.dev-ws-diagram-arrow { flex: none; color: var(--text-muted); }
.dev-ws-diagram-old { color: var(--text-muted); text-decoration: line-through; text-decoration-thickness: 2px; }
.dev-ws-diagram-new { color: var(--accent); }
/* Rename: a big "old → new", then the places it changes. */
.dev-ws-diagram-rename {
  display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: 10px 14px; padding: 8px 0 2px;
}
.dev-ws-diagram-rename > .dev-ws-diagram-arrow { font-size: 26px; }
.dev-ws-diagram-word {
  font-size: 30px; line-height: 1.15; font-weight: 750; letter-spacing: -.02em;
  padding: 6px 14px; border-radius: 14px; text-align: center; max-width: 100%;
}
.dev-ws-diagram-word.dev-ws-diagram-old { background: var(--state-neutral-bg); }
.dev-ws-diagram-word.dev-ws-diagram-new { background: var(--accent-tint); }
.dev-ws-diagram-places { display: flex; flex-wrap: wrap; gap: 6px; }
.dev-ws-diagram-place {
  font-size: 13px; font-weight: 600; padding: 4px 10px; border-radius: 9999px;
  background: var(--state-neutral-bg); color: var(--text-secondary);
}
.dev-ws-diagram-note { margin: 0; font-size: 13px; line-height: 1.4; color: var(--text-muted); }
/* Before → after: two rows of steps, the ones that differ marked. */
.dev-ws-diagram-flow { display: flex; flex-direction: column; gap: 12px; }
.dev-ws-diagram-flow-row { display: flex; flex-direction: column; gap: 6px; }
.dev-ws-diagram-flow-label { font-size: 13px; color: var(--text-muted); }
.dev-ws-diagram-flow-steps { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
.dev-ws-diagram-flow-item { display: inline-flex; align-items: center; gap: 6px; min-width: 0; }
.dev-ws-diagram-step {
  font-size: 15px; font-weight: 650; line-height: 1.25; padding: 5px 10px; border-radius: 10px;
  box-shadow: inset 0 0 0 1px var(--app-sheet-line); color: var(--text-primary);
}
.dev-ws-diagram-step.dev-ws-diagram-new { color: var(--accent); background: var(--accent-tint); box-shadow: inset 0 0 0 1.5px var(--accent); }
/* What changes / Numbers / What it touches: rows of 15 over 13. */
.dev-ws-diagram-rows { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 10px; }
.dev-ws-diagram-change { display: grid; grid-template-columns: 72px minmax(0, 1fr); gap: 10px; align-items: baseline; }
.dev-ws-diagram-op { font-size: 13px; color: var(--text-muted); }
.dev-ws-diagram-what { display: flex; flex-direction: column; gap: 2px; min-width: 0; font-size: 15px; font-weight: 650; line-height: 1.3; color: var(--text-primary); }
.dev-ws-diagram-detail { font-size: 13px; font-weight: 400; color: var(--text-muted); }
.dev-ws-diagram-change[data-op="added"] .dev-ws-diagram-what > .dev-ws-diagram-new { color: var(--accent); }
.dev-ws-diagram-number { display: flex; flex-direction: column; gap: 6px; }
.dev-ws-diagram-number-head { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; }
.dev-ws-diagram-figures { display: inline-flex; align-items: baseline; gap: 6px; flex: none; font-size: 15px; font-weight: 650; }
.dev-ws-diagram-old-figure { color: var(--text-muted); font-weight: 500; }
.dev-ws-diagram-new-figure { color: var(--accent); }
.dev-ws-diagram-bars { display: flex; flex-direction: column; gap: 4px; }
.dev-ws-diagram-bar { display: block; height: 8px; border-radius: 9999px; background: var(--state-neutral-bg); overflow: hidden; }
.dev-ws-diagram-bar > i { display: block; height: 100%; border-radius: 9999px; background: var(--accent); }
.dev-ws-diagram-bar-before > i { background: var(--text-muted); opacity: .45; }
.dev-ws-touches-row {
  display: grid; grid-template-columns: 84px minmax(0, 1fr) 64px; gap: 10px; align-items: center; opacity: .45;
}
.dev-ws-touches-row[data-touched] { opacity: 1; }
.dev-ws-touches-row > .dev-ws-diagram-what { font-size: 15px; overflow-wrap: normal; }
.dev-ws-touches-n { font-size: 13px; color: var(--text-muted); text-align: end; white-space: nowrap; }
/* #5039: where the browser can subgrid, the name and count columns are as
   wide as the longest entry in any row, so the bars stay aligned and an
   area's name is never cut ("Database" whole, whatever the text size). */
@supports (grid-template-columns: subgrid) {
  .dev-ws-touches > .dev-ws-diagram-rows { display: grid; grid-template-columns: max-content minmax(0, 1fr) max-content; }
  .dev-ws-touches-row { grid-column: 1 / -1; grid-template-columns: subgrid; }
}
/* #6832: the three pictures a change that changes nothing on screen gets in
   place of "What it touches" — what you'd see, what happened, and how it
   works. The same sheet, label and foot; the after side in the accent, the
   old words muted. The small drawings are currentColor plus the one accent,
   so they follow the page's theme with no branch of their own. */
.dev-ws-diagram-seen, .dev-ws-diagram-moment, .dev-ws-diagram-steps-two { display: flex; flex-direction: column; gap: 12px; }
.dev-ws-diagram-seen-where, .dev-ws-diagram-moment-when { font-size: 13px; color: var(--text-muted); }
.dev-ws-diagram-seen-sides { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 12px; }
@media (max-width: 419px) { .dev-ws-diagram-seen-sides { grid-template-columns: minmax(0, 1fr); } }
.dev-ws-diagram-seen-col { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.dev-ws-diagram-seen-label, .dev-ws-diagram-steps-label { font-size: 13px; color: var(--text-muted); }
.dev-ws-diagram-seen-col:last-child > .dev-ws-diagram-seen-label,
.dev-ws-diagram-steps-row[data-steps-side="after"] > .dev-ws-diagram-steps-label { color: var(--accent); }
.dev-ws-diagram-seen-side {
  display: flex; flex-direction: column; gap: 4px; min-width: 0; padding: 12px; border-radius: 14px;
  background: var(--dc-sheet-solid); box-shadow: inset 0 0 0 1px var(--app-sheet-line); overflow-wrap: anywhere;
}
.dev-ws-diagram-seen-side[data-side="after"] { background: var(--accent-tint); box-shadow: inset 0 0 0 1.5px var(--accent); }
.dev-ws-diagram-seen-title { font-size: 15px; font-weight: 650; line-height: 1.3; }
.dev-ws-diagram-seen-side[data-seen-look="status"] .dev-ws-diagram-seen-line,
.dev-ws-diagram-seen-side[data-seen-look="notice"] .dev-ws-diagram-seen-line { font-size: 13px; color: var(--text-muted); }
.dev-ws-diagram-seen-side[data-seen-look="notice"] { border-inline-start: 3px solid var(--accent); }
.dev-ws-diagram-seen-side[data-seen-look="message"] { border-end-start-radius: 14px; border-end-end-radius: 4px; }
.dev-ws-diagram-seen-side[data-seen-look="count"] .dev-ws-diagram-seen-title { font-size: 26px; font-weight: 700; letter-spacing: -0.02em; }
.dev-ws-diagram-seen-side[data-seen-look="count"] .dev-ws-diagram-seen-line { font-size: 13px; color: var(--text-muted); }

.dev-ws-diagram-moment-events { margin: 0; padding-inline-start: 18px; font-size: 15px; font-weight: 650; line-height: 1.5; }
.dev-ws-diagram-moment-now { font-size: 13px; color: var(--accent); }
.dev-ws-diagram-moment-after { color: var(--accent); }

.dev-ws-diagram-steps-row { display: flex; flex-direction: column; gap: 6px; }
.dev-ws-diagram-steps { display: flex; gap: 28px; align-items: flex-start; flex-wrap: wrap; }
.dev-ws-diagram-step-pic { width: 88px; flex: none; text-align: center; }
.dev-ws-diagram-step-pic > svg { display: block; margin: 0 auto; color: var(--text-primary); }
.dev-ws-diagram-steps-row[data-steps-side="after"] .dev-ws-diagram-step-pic > svg { color: var(--accent); }
.dev-ws-diagram-step-caption { font-size: 13px; font-weight: 650; line-height: 1.3; }
.dev-ws-diagram-step-retry { margin-inline-start: 4px; color: var(--text-muted); font-weight: 600; }
.dev-ws-diagram-step-note { margin-top: 4px; font-size: 12px; font-weight: 400; line-height: 1.35; color: var(--text-muted); text-align: start; }
/* On a 390px phone a five-step row at 88px would clip or scroll sideways
   inside the card: drop to 56px columns with a 12px gap and 32px drawings,
   and let a caption run to two lines. Five fit inside the card's gutters. */
@media (max-width: 419px) {
  .dev-ws-diagram-steps { gap: 12px; }
  .dev-ws-diagram-step-pic { width: 56px; }
  .dev-ws-diagram-step-pic > svg { width: 32px; height: 32px; }
  .dev-ws-diagram-step-caption { font-size: 12px; line-height: 1.25; overflow-wrap: anywhere; }
  /* The card's picture keeps the other kinds' generous inline padding, which
     on a phone squeezes a five-step row: 390 less the card's 32px gutters and
     104px of padding leaves 254px for a row of 328px. Narrower padding lets
     the row fit inside the gutters without wrapping or scrolling sideways. */
  .dev-ws-item > .dev-ws-diagram { padding-inline: 12px; }
}

/* Mermaid: the library's SVG, scaled to the sheet. */
.dev-ws-diagram-svg { display: flex; justify-content: center; min-height: 0; }
.dev-ws-diagram-svg > svg { display: block; max-width: 100%; height: auto; max-height: 360px; }
.dev-ws-diagram-wait { display: block; min-height: 120px; }
/* A change's page leads with it, above the description. */
.dev-change-diagram { margin: 12px 0 4px; }
.dev-change-diagram-failed { margin: 12px 0 4px; font-size: 13px; color: var(--text-muted); }
.dev-change-diagram-failed > p { margin: 0 0 4px; }
.dev-change-diagram-failed pre { margin: 6px 0 0; padding: 10px; border-radius: 10px; font-size: 12px; white-space: pre-wrap; background: var(--state-neutral-bg); color: var(--text-secondary); }

/* ── The rail ─────────────────────────────────────────────────────────
   One column of round buttons at the right edge, bottom-aligned with the
   caption. On a phone it stands over the card's right edge, so each disc
   is solid in the card's own colour with a hairline and a small drop, and
   the words under it get a soft halo in that colour: they read over any
   picture, light or dark (#5298: Comments nearly disappeared over a light
   shot). Vote is filled in the accent: it is the thing to press. Beside
   the card on a wide window (the wide block) it is drawn on the page. */
.dev-ws-rail {
  position: absolute; inset-inline-end: 8px; bottom: 10px; z-index: 3;
  display: flex; flex-direction: column; align-items: center; gap: 10px;
}
.dev-ws-rail-btn {
  display: flex; flex-direction: column; align-items: center; gap: 4px;
  width: 60px; margin: 0; padding: 0; border: 0; background: none;
  color: var(--text-secondary); font: inherit; cursor: pointer;
}
.dev-ws-rail-btn:disabled { opacity: .4; cursor: default; }
.dev-ws-rail-ic {
  width: 44px; height: 44px; border-radius: 9999px;
  display: grid; place-items: center;
  background-color: var(--dc-sheet-solid);
  color: var(--text-primary);
  box-shadow: inset 0 0 0 1px var(--app-sheet-line), 0 1px 3px rgba(0, 0, 0, .12);
}
.dev-ws-rail-ic > svg { width: 23px; height: 23px; }
.dev-ws-rail-lab { font-size: 11.5px; font-weight: 650; line-height: 1; color: var(--text-primary); text-shadow: 0 0 3px var(--dc-sheet-solid), 0 0 6px var(--dc-sheet-solid); white-space: nowrap; font-variant-numeric: tabular-nums; }
.dev-ws-rail-vote .dev-ws-rail-ic { width: 48px; height: 48px; background-color: var(--accent); color: #fff; box-shadow: 0 2px 12px rgba(10, 110, 224, .45); }
.dev-ws-rail-vote.is-on .dev-ws-rail-ic { background-color: var(--state-ok); border-color: var(--state-ok); box-shadow: 0 2px 8px rgba(21, 128, 61, .28); }
/* The same no vote (#4568): the rail button red, with the red glow. */
.dev-ws-rail-vote.is-on[data-ws-voted="no"] .dev-ws-rail-ic { background-color: var(--state-blocked); border-color: var(--state-blocked); box-shadow: 0 2px 8px rgba(220, 38, 38, .28); }
/* The sheet a button opens is up: its round turns over to the page's ink. */
.dev-ws-rail-btn[aria-expanded="true"] .dev-ws-rail-ic { background-color: var(--text-primary); color: var(--dc-sheet-solid); }
.dev-ws-rail-vote[aria-expanded="true"] .dev-ws-rail-ic { background-color: var(--accent); color: #fff; box-shadow: 0 0 0 3px var(--accent-wash); }
.dev-ws-move { display: none; }
.dev-ws-keys { display: none; }

/* ── The Needs-you deck's sheets ──────────────────────────────────────
   Fixed to the viewport, over the whole screen: the header, the tab bar and
   the Resume strip go under the scrim with everything else (see "ABOVE THE
   BARS" below).

   KEYED ON `.dev-ws-sheet-modal`, AND NOT ON `.dev-ws-sheet`, WHICH IS A
   DIFFERENT OBJECT. `.dev-ws-sheet` is the OPEN CARD — the sheet a folded
   row unfolds into (card/fold.tsx, `.dev-ws-rowwrap-open > .dev-ws-sheet >
   .gc-vote-item`), and it has carried that name since the Workshop shipped;
   two declared checks select it that way. #2080 gave the deck's three
   dialogs the same bare class, so this rule landed on every unfolded card on
   every Workshop surface: the card left its column or its strip, became a
   full-viewport `position: fixed` box at `z-index: 30` painting its own fill
   over the board, and swallowed every click underneath it. That is "the
   whole board goes opaque and stops responding" on By stage and By category,
   and "the card opens but the layout is wrong" on Current status — one rule,
   three screens.

   So the deck's dialogs carry a base class of their own and the bare name
   stays the fold's. The `.dev-ws-sheet-*` PARTS below (card, handle, head,
   title, sub, x, body) are the deck's either way — they appear in no folded
   card — as are the breakpoint rules further down, which were already keyed
   on the -vote / -ask / -comments modifiers. */
/* The floor lifts by what the on-screen keyboard took, so the field being
   typed into is above the keys rather than under them.

   THE NUMBER IS THE KIT'S, not this screen's. workshop.tsx used to measure the
   visual viewport itself and publish `--ws-kb` — a third copy of
   `innerHeight - vv.height - vv.offsetTop`, which is the expression #1938
   found to be wrong on iOS: `innerHeight` collapses to the visual viewport
   there, so it came out negative, the `Math.max(0, …)` around it clamped to 0,
   and this sheet never moved on an iPhone. `--un-kb-inset` is one tracker's
   answer for the whole page (usernode-native/v1/native.js), which is what
   keeps this surface and the composer columns from drifting apart again.

   It resolves to 0 with no keyboard, so no `html.un-kb` guard is needed here.
   The wide block below makes these panels `position: relative; inset: auto`,
   which drops this `bottom` with it — a docked panel has no floor to lift.

   ABOVE THE BARS (run-through in the iOS app, 5 October 2026). On a phone a
   sheet is a dialog over the whole screen, and the tab bar and the Resume
   strip are part of that screen: they belong under its scrim, as they are
   under the kit's own sheets (`.un-sheet`, z-index 9991). This was z-index
   30, the tab bar's own number, so the tie went to the bar, which comes
   later in <body>; and the vote sheet, rendered inside the rail, was held
   at the rail's 3 (the rule after the card's). Either way the bar and the
   strip were drawn over the sheet's foot: Cancel and Vote yes sat under
   them and a tap there opened Me (at 375x812, elementFromPoint at Vote
   yes's centre was #platform-tab-me). 40 is the tier `.platform-tabs`
   leaves for panels, sheets and dialogs. The wide block gives every variant
   a z-index of its own, so a docked panel and the popover are unchanged. */
.dev-ws-sheet-modal { position: fixed; inset: 0; z-index: 40; bottom: var(--un-kb-inset, 0px); display: flex; flex-direction: column; justify-content: flex-end; }
.dev-ws-scrim {
  position: absolute; inset: 0; border: 0; padding: 0; margin: 0; cursor: default;
  background: var(--pane-scrim);
}
.dev-ws-sheet-card {
  position: relative;
  display: flex; flex-direction: column; gap: 8px;
  max-height: 66%; min-height: 0;
  padding: 8px 16px calc(12px + var(--platform-safe-bottom, 0px)); box-sizing: border-box;
  border-start-start-radius: 22px; border-start-end-radius: 22px; border-end-end-radius: 0; border-end-start-radius: 0;
  background-color: var(--dc-sheet);
  box-shadow: 0 -10px 30px rgba(24, 39, 75, .2);
}
.dev-ws-sheet-vote .dev-ws-sheet-card { padding-bottom: calc(22px + var(--platform-safe-bottom, 0px)); }
/* THE VOTE SHEET LIVES IN THE RAIL (on a wide window it is a popover on the
   rail's button), and on a phone the rail is `z-index: 3`, a stacking
   context: whatever the sheet's own z-index said, it painted at the rail's
   level, under the bars and the header. While it is up the rail is not one,
   so the sheet stacks with the page. Its buttons are under the scrim then,
   so their order against the item no longer shows. (Wide, the rail is
   `z-index: auto` already.) */
.dev-ws-needs[data-ws-sheet="vote"] > .dev-ws-rail { z-index: auto; }
/* With the keyboard up the sheet is short; let the card have all of it, short
   of the status bar. `[data-ws-kb]` is workshop.tsx's, set while the kit's
   `un-kb` or the page's own `platform-kb-open` is on (lib/keyboard-open.ts:
   in the Homeroom app the web view ends at the keys and `un-kb` never comes
   on). The home indicator is behind the keys, so the foot keeps 12px rather
   than 12px plus the inset. */
.dev-ws-needs[data-ws-kb] .dev-ws-sheet-card { max-height: calc(100% - var(--platform-safe-top, 0px)); padding-bottom: 12px; }
/* A SHEET TALLER THAN THE SCREEN SCROLLS, AND THE VOTE KEEPS ITS BUTTONS.
   The card was capped and its content was not: past the cap it ran out of
   the card's foot, off the screen, and nothing scrolled. In the Homeroom app
   with the keyboard up (the web view ends at the keys: 494px at 402x874) the
   vote form is taller than the cap, and Cancel and Vote no hung below the
   page's edge, behind the keys.

   So the card scrolls, and on the vote sheet the action row is sticky at its
   foot: whatever the form's height, Cancel and the send are on screen and
   the rest scrolls under them. The row takes over the clearance the card's
   foot had (`--ws-vote-foot`: the home indicator, or 12px with the keys up)
   and draws on the sheet's own fill, so what scrolls under it never shows
   below the buttons. The card's scroll padding is the row's height (its
   10px top padding, a 44px button and the foot), so a field focused or
   scrolled into view lands above the row rather than under it. `:has()`
   because the group decision's fallback (Open to decide, Decide later) has
   no such row and keeps the card's own clearance.

   Phone only: on a wide window the vote is a popover whose arrow hangs
   outside its card, which a scroller would clip, and the panels scroll
   their own bodies. */
@media (max-width: 699.98px) {
  .dev-ws-sheet-card { overflow-y: auto; overscroll-behavior: contain; }
  .dev-ws-sheet-vote .dev-ws-sheet-card:has(> .dev-ws-vote-form) {
    --ws-vote-foot: calc(22px + var(--platform-safe-bottom, 0px));
    padding-bottom: 0;
    scroll-padding-bottom: calc(54px + var(--ws-vote-foot));
  }
  .dev-ws-needs[data-ws-kb] .dev-ws-sheet-vote .dev-ws-sheet-card:has(> .dev-ws-vote-form) { --ws-vote-foot: 12px; }
  .dev-ws-sheet-vote .dev-ws-vote-form > .dev-vote-reason-actions {
    position: sticky; bottom: 0; z-index: 1;
    padding-bottom: var(--ws-vote-foot);
    background-color: var(--dc-sheet);
  }
}
/* ── Open and close MOVE. The card rises from the floor and the scrim fades
   in; on the way out (`[data-ws-leaving]`, which workshop.tsx keeps mounted
   for exactly this long) both reverse. The names are variables so the wide
   block can swap them for a panel's slide and a popover's pop without a
   second reduced-motion query of its own. */
.dev-ws-sheet-modal { --ws-sheet-in: dev-ws-sheet-up; --ws-sheet-out: dev-ws-sheet-down; }
/* A leaving sheet catches nothing: its scrim (transparent and full-screen
   behind the wide popover) and its buttons would otherwise swallow the next
   tap for the 220ms it stays mounted. Outside the motion query on purpose. */
.dev-ws-sheet-modal[data-ws-leaving] { pointer-events: none; }
@media (prefers-reduced-motion: no-preference) {
  .dev-ws-sheet-modal > .dev-ws-scrim { animation: dev-ws-scrim-in .22s ease-out both; }
  .dev-ws-sheet-modal > .dev-ws-sheet-card {
    animation-name: var(--ws-sheet-in); animation-duration: .28s;
    animation-timing-function: cubic-bezier(.32, .72, 0, 1); animation-fill-mode: both;
  }
  .dev-ws-sheet-modal[data-ws-leaving] > .dev-ws-scrim { animation: dev-ws-scrim-out .2s ease-in both; }
  .dev-ws-sheet-modal[data-ws-leaving] > .dev-ws-sheet-card {
    animation-name: var(--ws-sheet-out); animation-duration: .2s;
    animation-timing-function: ease-in; animation-fill-mode: both;
  }
}
/* Reduce motion setting (#6510): none of the motion above, when Settings asks for it. */
:where(html[data-motion="reduce"]) .dev-ws-sheet-modal > .dev-ws-scrim { animation: none; }
:where(html[data-motion="reduce"]) .dev-ws-sheet-modal > .dev-ws-sheet-card { animation: none; }
:where(html[data-motion="reduce"]) .dev-ws-sheet-modal[data-ws-leaving] > .dev-ws-scrim { animation: none; }
:where(html[data-motion="reduce"]) .dev-ws-sheet-modal[data-ws-leaving] > .dev-ws-sheet-card { animation: none; }
@keyframes dev-ws-sheet-up { from { transform: translateY(100%); } to { transform: none; } }
@keyframes dev-ws-sheet-down { from { transform: none; } to { transform: translateY(100%); } }
@keyframes dev-ws-scrim-in { from { opacity: 0; } to { opacity: 1; } }
@keyframes dev-ws-scrim-out { from { opacity: 1; } to { opacity: 0; } }
@keyframes dev-ws-panel-in { from { opacity: 0; transform: translateX(calc(28px * var(--rtl-sign))); } to { opacity: 1; transform: none; } }
@keyframes dev-ws-panel-out { from { opacity: 1; transform: none; } to { opacity: 0; transform: translateX(calc(28px * var(--rtl-sign))); } }
@keyframes dev-ws-pop-in { from { opacity: 0; transform: translateX(calc(10px * var(--rtl-sign))) scale(.96); } to { opacity: 1; transform: none; } }
@keyframes dev-ws-pop-out { from { opacity: 1; transform: none; } to { opacity: 0; transform: translateX(calc(10px * var(--rtl-sign))) scale(.96); } }
.dev-ws-sheet-handle { width: 36px; height: 4px; border-radius: 2px; background: var(--border); margin: 0 auto 4px; flex: none; }
.dev-ws-sheet-x {
  width: 32px; height: 32px; padding: 0; border: 0; border-radius: 9999px; cursor: pointer;
  display: grid; place-items: center;
  background: none; color: var(--text-muted);
}
.dev-ws-sheet-x:hover { background: var(--state-neutral-bg); color: var(--text-primary); }
.dev-ws-sheet-x-ic { width: 18px; height: 18px; }
.dev-ws-sheet-body { flex: 1 1 auto; min-height: 0; overflow-y: auto; display: flex; flex-direction: column; gap: 10px; padding-top: 4px; }
/* ── Comments and Ask: one sheet, two tabs (workshop.tsx) ──────────────
   On a phone a tall sheet from the floor, the same height whichever tab is
   up, so switching never jumps: the two tabs over the tab's own body, a
   round Close at the right of them, and the body scrolling under its own
   composer. The head that repeats the card's caption is the wide panel's
   alone (the wide block); here the card's top still shows above the sheet.
   Both tabs stay mounted while the sheet is up, the other one `hidden`. */
.dev-ws-sheet-talk > .dev-ws-sheet-card {
  height: 66%; padding-inline-start: 0; padding-inline-end: 0; gap: 0; overflow: hidden;
}
.dev-ws-needs[data-ws-kb] .dev-ws-sheet-talk > .dev-ws-sheet-card { height: calc(100% - var(--platform-safe-top, 0px)); }
.dev-ws-talk-head { display: none; }
.dev-ws-talk-tabs {
  position: relative; flex: none;
  display: flex; align-items: center; justify-content: center;
  padding: 0 52px; border-bottom: 1px solid var(--border-light);
}
.dev-ws-talk-tablist { display: flex; gap: 24px; }
.dev-ws-talk-tab {
  display: inline-flex; align-items: center; gap: 5px;
  height: 44px; margin-bottom: -1px; padding: 0 2px;
  border: 0; border-bottom: 2px solid transparent; background: none; cursor: pointer;
  font: inherit; font-size: 15px; font-weight: 600; color: var(--text-muted);
}
.dev-ws-talk-tab[aria-selected="true"] { border-bottom-color: var(--text-primary); color: var(--text-primary); }
.dev-ws-talk-n { margin-inline-start: 4px; font-weight: 500; color: var(--text-muted); }
.dev-ws-talk-tab-ic { width: 15px; height: 15px; }
.dev-ws-talk-tabs > .dev-ws-sheet-x { position: absolute; inset-inline-end: 10px; top: 6px; }
.dev-ws-talk > .dev-ws-sheet-body { padding: 4px 16px 0; }
/* The thread fills the tab and its reply box stays at the foot, on the
   sheet's own fill, as a comment box under a reel does. */
.dev-ws-talk > .dev-ws-sheet-body > .dev-feed-thread { flex: 1 0 auto; }
.dev-ws-talk > .dev-ws-sheet-body > .dev-feed-thread > form {
  position: sticky; bottom: 0; margin-top: auto; padding: 8px 0 4px;
  background-color: var(--dc-sheet);
}
.dev-ws-talk > .dev-ws-ask { flex: 1 1 auto; min-height: 0; padding: 0 16px; }
.dev-ws-talk > [role="tabpanel"][hidden] { display: none; }
/* The vote sheet's own lines. */
.dev-ws-ask-q { margin: 6px 0 0; font-size: 20px; font-weight: 700; letter-spacing: -.01em; color: var(--text-primary); }
.dev-ws-vote-sub { margin: 0 0 8px; font-size: 14px; line-height: 1.4; color: var(--text-muted); }
.dev-ws-answer-row { display: flex; gap: 10px; }
.dev-ws-answer-btn {
  flex: 1 1 0; min-width: 0; height: 56px;
  border: 1.5px solid currentColor; border-radius: 14px; cursor: pointer;
  font: inherit; font-size: 18px; font-weight: 700;
}
.dev-ws-answer-btn:disabled { opacity: .4; cursor: default; }
.dev-ws-answer-yes { background: var(--state-ok-bg); color: var(--state-ok); }
.dev-ws-answer-no { background: var(--state-blocked-bg); color: var(--state-blocked); }
.dev-ws-vote-later {
  margin: 6px auto 0; border: 0; background: none; padding: 6px 12px; cursor: pointer;
  font: inherit; font-size: 14px; font-weight: 600; color: var(--text-muted);
}
.dev-ws-keys-hint { display: none; }

/* ── Join, under the Join button (communities) ─────────────────────────
   The community card's question (features/dev-board/workshop/
   community-card.tsx), asked the way the vote is asked: the vote popover's
   question, its muted line, an answer button and a quiet "later" under it
   — the classes above — in a popover that hangs from the button rather than
   from a rail. At every width, because the button is inside a card, not at
   the floor of a feed: it opens where the thumb already is.

   Right-aligned to the button, which ends the card's first row, with the
   arrow over the button's middle. The width stops short of the viewport on
   a phone, so the popover never meets the screen edge, nor the Duo's
   column (the float box, THE USABLE BOX; 1 November 2026). */
.dev-ws-join-anchor { position: relative; margin-inline-start: auto; flex: none; }
.dev-ws-join-pop {
  position: absolute; top: calc(100% + 12px); inset-inline-end: -6px; z-index: 7;
  width: min(300px, calc(var(--platform-float-w) - 56px));
  display: flex; flex-direction: column; gap: 8px;
  padding: 16px 16px 10px; box-sizing: border-box;
  border-radius: 18px; border: 1px solid var(--app-sheet-line);
  background-color: var(--dc-sheet);
  box-shadow: 0 18px 50px rgba(24, 39, 75, .22);
  text-align: start;
}
.dev-ws-join-pop::before {
  content: ""; position: absolute; top: -8px; inset-inline-end: 26px; width: 14px; height: 14px;
  background: var(--dc-sheet);
  border-inline-start: 1px solid var(--app-sheet-line); border-top: 1px solid var(--app-sheet-line);
  transform: rotate(45deg);
}
.dev-ws-join-pop .dev-ws-ask-q { margin: 0; font-size: 18px; }
.dev-ws-join-pop .dev-ws-vote-sub { margin: 0 0 4px; font-size: 13px; }
.dev-ws-join-pop .dev-ws-answer-btn { height: 46px; font-size: 15px; border-radius: 12px; }
.dev-ws-join-pop .dev-ws-vote-later { margin-top: 0; }
.dev-ws-answer-join { background: var(--brand-tint); color: var(--brand-ink); }
@media (prefers-reduced-motion: no-preference) {
  .dev-ws-join-pop { animation: dev-ws-join-pop-in .18s ease-out both; transform-origin: calc(100% - 32px) 0; }
}
/* Reduce motion setting (#6510): none of the motion above, when Settings asks for it. */
:where(html[data-motion="reduce"]) .dev-ws-join-pop { animation: none; }
@keyframes dev-ws-join-pop-in { from { opacity: 0; transform: translateY(-4px) scale(.96); } to { opacity: 1; transform: none; } }

/* ── The project card (features/guest/project-card.tsx) ────────────────
   The hub's hero for somebody signed in who has not joined: the project's
   colour, its picture, and Open app · Join · ⋯ in one row of 50px buttons
   (52px from 768px). Join is the hub's own (its popup hangs under it, in
   the page's ink rather than the card's white), and the ⋯ is the hero's
   menu on a round glass button. The card lifts over what follows while
   either is open. Under it, the people card: the hero's faces, ringed in
   the card's white. */
.dev-ws-project-card .dev-ws-join-anchor { margin-inline-start: 0; }
.dev-ws-project-card .dev-ws-join-pop {
  color: var(--text-primary);
  /* Join is mid-row here, not at the row's end: the popup hangs centred
     under it, so on a phone it stays on the screen. */
  inset-inline-end: auto; inset-inline-start: 50%;
  margin-inline-start: calc(min(300px, var(--platform-float-w) - 56px) / -2);
  transform-origin: 50% 0;
}
.dev-ws-project-card .dev-ws-join-pop::before { inset-inline-end: auto; inset-inline-start: calc(50% - 7px); }
.dev-ws-project-card:has(#dev-plus-menu:not(.hidden)) { position: relative; z-index: 5; }
.dev-ws-plus-btn.dev-ws-plus-btn-card { width: 50px; height: 50px; }
.dev-ws-plus-btn.dev-ws-plus-btn-card .dev-ws-plus-glyph { width: 22px; height: 22px; }
.dev-ws-plus-btn.dev-ws-plus-btn-card[aria-expanded="true"] { background: rgba(255, 255, 255, .3); box-shadow: none; }
@media (min-width: 768px) {
  .dev-ws-plus-btn.dev-ws-plus-btn-card { width: 52px; height: 52px; }
}
[data-ws-people-card] .dev-ws-hero-face { box-shadow: 0 0 0 2px #fff; }
.dark [data-ws-people-card] .dev-ws-hero-face { box-shadow: 0 0 0 2px #18181b; }
/* Who it is for, in the card's corner: the audience's name in the row
   title's ink, the count muted, "Public community · 91 members". */
[data-ws-people-card] .dev-ws-hero-count { font-size: 13px; font-weight: 400; color: var(--text-muted); }
[data-ws-people-card] .dev-ws-hero-audience b { color: var(--text-primary); }
/* A phone keeps "34 active this week" on one line beside the faces. */
@media (max-width: 767px) {
  [data-ws-people-card] .dev-ws-hero-active { gap: 10px; }
  [data-ws-people-card] .dev-ws-hero-active .dev-ws-hero-face { width: 30px; height: 30px; margin-inline-end: -10px; font-size: 12px; }
}

/* ── The project page's hero (community-card.tsx) ──────────────────────
   On the ground, not in a card: who is here and who it is for, what it is,
   what you can do, and how lively it has been. The name and tile are the
   coloured header's (#852), so the hero has no heading of its own. The type
   is the scale AGENTS.md "Type and colour" sets: the rows' 15/13. */
.dev-ws-hero { display: flex; flex-direction: column; gap: 12px; padding: 6px 4px 4px; }
/* THE HUB'S GUTTER ON A PHONE IS EVERY SCREEN'S 16px (audit P03, 1 Nov
   2026). The page's column starts 4px in, so the For you card and the cards
   under it ran to within 4px of the screen's edges while the hero's tile sat
   at 12 and the label at 8: three left edges, and the hub wider than
   Communities, Profile and Settings. The body takes 12px more, and the hero
   its own 4px less, so the tile, the cards and the labels line up on 16. */
@media (max-width: 767.98px) {
  .dev-ws[data-ws-tab="status"] > .dev-ws-tabbody { padding-inline: 12px; }
  .dev-ws[data-ws-tab="status"] > .dev-ws-tabbody > .dev-ws-hero { padding-inline: 0; }
}
.dev-ws-hero-actions { display: flex; align-items: center; gap: 8px; }
.dev-ws-hero-actions:empty { display: none; }
.dev-ws-hero-desc { margin: 0; font-size: 15px; line-height: 21px; color: var(--text-primary); }
/* Two lines at most (#3572), with an ellipsis: the measure the create
   screen's limit was taken against (services/create-options.js
   DESCRIPTION_MAX), so a description made there shows whole on a phone,
   and a longer one from a repository's own dapp.json no longer pushes the
   hub's actions down the screen. The same three-property clamp as
   `.home-discover-blurb`. */
.dev-ws-hero-desc {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  overflow: hidden;
}
.dev-ws-hero-line { margin: 0; font-size: 13px; line-height: 18px; color: var(--text-muted); }
/* WHO IS HERE, IN THE HERO (#3268). The people row: up to five faces, then
   "Public community · 23 members". A public or private community draws it as
   the pulse below, with this week's activity under the count; the row is
   Just you's, and the invite preview's.

   THE ROW WRAPS (#3276). Nothing in it can shrink: the faces are a fixed
   stack and the count is `nowrap`. So when five faces and the count come to
   more than a phone's width, the count drops to a line of its own rather than
   running past the screen's edge and scrolling the hub sideways. */
.dev-ws-hero-people { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 10px; min-height: 32px; }
.dev-ws-hero-faces { display: inline-flex; align-items: center; flex: none; }
.dev-ws-hero-face {
  width: 26px; height: 26px; margin-inline-end: -6px; border-radius: 9999px;
  display: grid; place-items: center;
  color: #fff; font-size: 11.5px; font-weight: 700;
  box-shadow: 0 0 0 2px var(--home-ground, var(--bg-primary));
}
.dev-ws-hero-face:last-child { margin-inline-end: 0; }
.dev-ws-hero-count { font-size: 14px; font-weight: 650; color: var(--text-primary); white-space: nowrap; }
/* WHO IS AROUND THIS WEEK (community-card.tsx HeroActive): up to five faces
   and "+N", then "40 active this week" over their names, the rows' 15 over
   13. The names keep to one line, cut short with an ellipsis on a phone. */
.dev-ws-hero-active { display: flex; align-items: center; gap: 12px; min-width: 0; }
.dev-ws-hero-active .dev-ws-hero-face {
  width: 32px; height: 32px; margin-inline-end: -8px; font-size: 12.5px;
}
.dev-ws-hero-active .dev-ws-hero-face:last-child { margin-inline-end: 0; }
.dev-ws-hero-active .dev-ws-hero-face-more { background: var(--bg-tertiary); color: var(--text-primary); font-size: 11px; }
.dev-ws-hero-active-words { min-width: 0; display: flex; flex-direction: column; gap: 1px; }
.dev-ws-hero-active-n { font-size: 15px; font-weight: 650; line-height: 20px; color: var(--text-primary); }
.dev-ws-hero-active-names {
  font-size: 13px; line-height: 18px; color: var(--text-muted);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
/* A change to who it is for, up for a vote: the one line on the hero that
   asks for something, so it carries the accent and goes to the proposal. */
a.dev-ws-hero-pending {
  display: inline-flex; align-items: center; gap: 2px; align-self: flex-start;
  color: var(--accent); font-weight: 600; text-decoration: none;
}
.dev-ws-audience-error { margin: 0; font-size: 12.5px; color: var(--state-blocked); }
/* THE ⋯ ENDS THE MEMBERS ROW, Invite's height and fill (actions-row.tsx
   draws the fill), a circle. Its menu hangs below it over the cards under
   the hero, so the hero lifts while the menu is open, as it does for the
   Join popup. */
/* A BIGGER ⋯ (request 6654): 32px with an 18px glyph read as a detail and
   was easy to miss. 48px, bolder dots and a hairline ring, so it stands as a
   control of its own beside Open app. */
.dev-ws-hero .dev-ws-plus-btn { width: 48px; height: 48px; box-shadow: inset 0 0 0 1px var(--app-sheet-line); }
.dev-ws-hero .dev-ws-plus-glyph { width: 24px; height: 24px; stroke-width: 2.6; }
.dev-ws-hero:has(#dev-plus-menu:not(.hidden)) { position: relative; z-index: 5; }
/* It hangs from the ⋯'s LEFT edge and opens rightward, into the column: the
   ⋯ is near the row's start (after Open app and Invite), and a menu opening
   leftward from there ran under the sidebar. */
.dev-ws-hero #dev-plus-menu { inset-inline-start: 0; inset-inline-end: auto; }
/* THE HUB'S HEAD (community-card.tsx, `.dev-ws-hero-summary`, on every
   project from its first day): the tile and the name over who it is for,
   the description, who is around, then what you can do. On a wide window the
   actions sit across from the name: the grid packs the row of actions into
   the hole beside the name (`dense`), whatever came before them, and
   everything else takes the full width in the order it is written. Its ⋯
   menu then hangs from the ⋯'s right edge and opens leftward, into the
   column. */
.dev-ws-hero-summary { gap: 14px; padding: 10px 8px 8px; }
.dev-ws-hero-id { display: flex; align-items: center; gap: 12px; min-width: 0; }
.dev-ws-hero-tile {
  flex: none; width: 52px; height: 52px; overflow: hidden;
  display: grid; place-items: center;
  border-radius: 16px; font-size: 26px; font-weight: 700;
}
.dev-ws-hero-tile > img { width: 100%; height: 100%; object-fit: cover; border-radius: 0; }
.dev-ws-hero-tile > span { font-size: inherit; line-height: 1; }
.dev-ws-hero-id-text { min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.dev-ws-hero-name {
  margin: 0; font-size: 24px; font-weight: 750; line-height: 1.15; letter-spacing: -0.02em;
  color: var(--text-primary); overflow-wrap: anywhere;
}
.dev-ws-hero-id-sub { font-size: 13px; line-height: 18px; color: var(--text-muted); }
/* VERSIONS (docs/plans/versions.md): "Made from Tier list · Gets its
   updates" on a version, "214 versions · 160 get its updates" on an
   original (community-card.tsx HeroLineage). Under who it is for, in the
   same size and muted ink: a note about the project, not a status. The
   original's name is the one link, in the secondary ink, underlined on
   hover. */
.dev-ws-hero-lineage { display: block; font-size: 13px; line-height: 18px; color: var(--text-muted); }
.dev-ws-hero-lineage-link { color: var(--text-secondary); font-weight: 600; text-decoration: none; }
.dev-ws-hero-lineage-link:hover { text-decoration: underline; }
/* INVITE, AS A CARD (community-card.tsx InviteHeroCard, request 6654):
   Home's New project card on the hub. A lilac card: faces of people already
   here fanned out with an open seat after them, a question, what an invite
   does, one full-width dark button and how many are in. Under the hero on a
   phone; beside it on a wide window ("THE HUB IN TWO COLUMNS" below). */
.dev-ws-invite-hero {
  position: relative;
  display: flex; flex-direction: column; gap: 10px; min-width: 0;
  padding: 20px 20px 16px; border-radius: 20px;
  background: #f6f2fc; box-shadow: inset 0 0 0 1px #d9d0ec;
}
.dark .dev-ws-invite-hero { background: #201b2f; box-shadow: inset 0 0 0 1px #3a3152; }
/* Its ✕ (request 6687), the same button Share it's head carries: the card
   has no head row, so it sits in the top corner, over the faces' right. */
.dev-ws-invite-hero > .dev-ws-card-close {
  position: absolute; top: 12px; inset-inline-end: 12px; margin: 0;
}
.dev-ws-invite-hero-fan { display: flex; align-items: center; margin-bottom: 2px; }
.dev-ws-invite-hero-face {
  flex: none; width: 40px; height: 40px; margin-inline-end: -10px;
  display: grid; place-items: center; border-radius: 999px;
  font-size: 15px; font-weight: 700; color: #fff;
  box-shadow: 0 0 0 2.5px #f6f2fc;
}
.dark .dev-ws-invite-hero-face { box-shadow: 0 0 0 2.5px #201b2f; }
.dev-ws-invite-hero-face:nth-child(odd) { transform: rotate(-5deg); }
.dev-ws-invite-hero-face:nth-child(even) { transform: rotate(5deg); }
.dev-ws-invite-hero-seat {
  margin-inline-end: 0; transform: none !important;
  background: #fff; color: #6b4fb3; font-size: 20px; font-weight: 500;
  border: 1.5px dashed #b9a7e3; box-shadow: none;
}
.dark .dev-ws-invite-hero-seat { background: #2a2340; color: #cdbdf5; border-color: #5a4b85; box-shadow: none; }
.dev-ws-invite-hero-title { margin: 0; font-size: 18px; font-weight: 750; line-height: 23px; letter-spacing: -0.01em; color: var(--text-primary); }
.dev-ws-invite-hero-text { margin: 0; font-size: 14px; line-height: 20px; color: var(--text-secondary); }
.dev-ws-invite-hero-btn { margin-top: 4px; background: #18181b; }
.dev-ws-invite-hero-btn:hover { background: #27272a; }
.dark .dev-ws-invite-hero-btn { background: #fafafa; color: #18181b; }
.dark .dev-ws-invite-hero-btn:hover { background: #e4e4e7; }
.dev-ws-invite-hero-count { margin: 0; font-size: 13px; line-height: 18px; text-align: center; color: var(--text-muted); }
/* THE HUB IN TWO COLUMNS (request 6654). On a wide window the hub was one
   760px column with a wide empty margin either side. Its page is 1080px
   there, and two pairs sit side by side in equal halves: the hero with the
   Invite card, and For you with Topics. Everything else keeps the full
   width, in the order it is written. Each pair is side by side only when
   both are there and adjacent, so a hub without topics, or without the
   Invite card, is one column as before. Not under a look (`data-skin`),
   whose kit has a column of its own. */
@media (min-width: 1100px) {
  html:not([data-skin]) #dev-workshop:has(> .dev-ws[data-ws-tab="status"]) { max-width: 1080px; }
  html:not([data-skin]) .dev-ws[data-ws-tab="status"] > .dev-ws-tabbody {
    display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    column-gap: 16px; align-content: start; align-items: start;
  }
  html:not([data-skin]) .dev-ws[data-ws-tab="status"] > .dev-ws-tabbody > * { grid-column: 1 / -1; }
  html:not([data-skin]) .dev-ws[data-ws-tab="status"] > .dev-ws-tabbody > .dev-ws-hero:has(+ .dev-ws-invite-hero),
  html:not([data-skin]) .dev-ws[data-ws-tab="status"] > .dev-ws-tabbody > [data-ws-hub-for-you]:has(+ [data-ws-hub-topics]) { grid-column: 1; }
  html:not([data-skin]) .dev-ws[data-ws-tab="status"] > .dev-ws-tabbody > .dev-ws-hero + .dev-ws-invite-hero,
  html:not([data-skin]) .dev-ws[data-ws-tab="status"] > .dev-ws-tabbody > [data-ws-hub-for-you] + [data-ws-hub-topics] { grid-column: 2; }
}
@media (min-width: 768px) {
  .dev-ws-hero-summary {
    display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-auto-flow: row dense;
    column-gap: 16px; padding: 4px 4px 8px;
  }
  .dev-ws-hero-summary > * { grid-column: 1 / -1; }
  .dev-ws-hero-summary > .dev-ws-hero-id { grid-column: 1; }
  .dev-ws-hero-summary > .dev-ws-hero-row { grid-column: 2; align-self: center; }
  .dev-ws-hero-summary #dev-plus-menu { inset-inline-start: auto; inset-inline-end: 0; }
  .dev-ws-hero-tile { width: 60px; height: 60px; border-radius: 18px; font-size: 30px; }
  .dev-ws-hero-name { font-size: 28px; }
  .dev-ws-hero-id-sub { font-size: 14px; line-height: 20px; }
  .dev-ws-hero-lineage { font-size: 14px; line-height: 20px; }
}

/* ── The project's colour: its header and its tabs ─────────────────────
   Inside a project, the bar wears its community's colour (lib/community-
   color.ts: dapp.json's `icon.color`, else one read off its icon, always dark
   enough for white text), so which community you are in reads before any
   word does. The header puts it on <html> as `--community-tint`
   (`data-community-tint`, features/header/community-tint.ts) on the
   project's pages only, never in the running app, whose bar stays the
   standard one and takes the app's tone (#1945); and it holds the colour
   across a switch from one community to the next.

   THE HEADER. On the project's pages its fill is the faked-glass layer
   ("FAKED GLASS" below), whose tint is `--fake-glass-tint`; an opaque tint
   covers the washes, so the bar is the colour, flat. The background is set
   as well, for a frame where the layer is not drawn. Its controls re-ink
   white through the same tokens the app-tone rules move (--brand-*), and its
   rounded foot squares off, because the band under it continues it. */
html[data-community-tint] body:has(#app-view:not(.hidden)) #platform-header {
  --fake-glass-tint: var(--community-tint);
  --brand-ink: #fff;
  --brand-tint: rgba(255, 255, 255, .16);
  --brand-line: rgba(255, 255, 255, .32);
  background-color: var(--community-tint);
  color: #fff;
  clip-path: inset(0);
  border-end-start-radius: 0;
  border-end-end-radius: 0;
}
/* The tile's light ring is drawn INSIDE its edge (#4237). It was an outer
   box-shadow, and the h1 around the tile is `truncate` (overflow: hidden)
   with a line box exactly the tile's 28px, so the ring was clipped on the
   top, bottom and left and only its right edge showed: the tile read as
   nudged off its place. An outline pulled in by its own width paints over
   the icon's edge, inside the box nothing clips. */
html[data-community-tint] body:has(#app-view:not(.hidden)) #platform-header #header-app-tile:not(:focus-visible) {
  outline: 1.5px solid rgba(255, 255, 255, .55);
  outline-offset: -1.5px;
}
/* ON ITS OWN, THE BAR'S ROW IS CENTRED (#4237). The band under the bar is
   the page's own ink at every width now (#4703: on a phone the band is gone
   and the header is the one coloured row), so the tinted bar ends at its own
   52px foot everywhere, and its pt-2/pb-4 (8px over the row, 16px under) put
   every control in it 4px above its middle. The same 52px, split 12 and 12.
   The top keeps the safe-area inset, and the browser-tab clamp (#2509) keeps
   its zero inset. */
html[data-community-tint] body:has(#app-view:not(.hidden)) #platform-header {
  padding-bottom: 0.75rem;
}
@supports (padding: env(safe-area-inset-top)) {
  html[data-community-tint] body:has(#app-view:not(.hidden)) #platform-header.un-safe-top-extend {
    padding-top: calc(0.75rem + var(--un-safe-inset-top, env(safe-area-inset-top, 0px))) !important;
  }
  html.web-browser-chrome[data-community-tint] body:has(#app-view:not(.hidden)) #platform-header.un-safe-top-extend {
    padding-top: 0.75rem !important;
  }
}
/* THE BAND: the place bar (#4417, place-bar.tsx; it held the four tabs,
   Hub, Discussion, Needs you, Workshop, until the places became one list),
   under the header, in its colour. It keeps the old strip's box (`.dev-ws-tabs` > `.dev-ws-tabtrack`)
   for the two hooks that measure it, and bleeds to the column's edges and
   up under the header's overlap (`-mb-2` on the bar, plus the body's own
   top padding), so the colour runs unbroken from the top of the screen to
   the tabs' underline.

   THE SIDES CANCEL 4px, NOT 12 (#3499). `#dev-body` is `px-3`, but holding
   the Workshop it narrows to 4px at the sides (`#dev-body:has(>
   #dev-workshop)`), and the band's bleed was written against the 12. It ran
   8px past both edges of the screen: harmless where the page itself scrolls
   (a mobile browser clips #dev-forum-scroll's x-axis), but in an installed
   app or the native WebView #dev-forum-scroll is the scroller, and its
   `overflow-y: auto` made those 8px a sideways scroll of the whole hub. */
.dev-ws-tabs.dev-ws-band {
  margin: -18px -4px 0;
  /* 18px, not 8: the header's foot overlaps the band's top by ten, and the
     count's badge rises above its word into that strip. */
  padding: 18px 8px 0;
  background: var(--community-tint, #2a2e34);
  gap: 0;
}
/* #4417: THE BAND HOLDS THE PLACE BAR (place-bar.tsx): the tray's button
   and the place's name, one row. The four cells it held are retired with
   the tabs (project-band.tsx); the places are one list now. */
/* On a phone the band is the page's own: no pinned sheet behind it (the
   strip's band below is for the pill it replaced). */
.dev-ws-tabs.dev-ws-band::before { content: none; }

/* ON A PHONE THE BAND PINS UNDER THE HEADER (#3522). It scrolled away with
   the page, so a long Hub or Workshop left you nowhere to change tab without
   scrolling back up. It is sticky now at exactly where it rests, so it never
   moves: the header's coloured foot and the band stay one piece while the
   page slides under them. From 700px the strip's own pinning takes over (the
   `min-width: 700px` block, with the pane head measured under it).

   WHERE IT RESTS depends on which element scrolls. In the installed app and
   the native WebView #dev-forum-scroll does, and its top edge is the
   scrollport's: the band rests 18px above the HEADER'S MEASURED FOOT less
   #dev-body's 8px top padding, the part the header covers (that foot is
   `--dev-ws-head-foot`, published by workshop.tsx; see #3726 below). On   a phone browser the document scrolls, under the sticky header, so the band
   rests the header's height less its 17px tuck below the viewport's top.
   `--ws-band-top` carries whichever it is, and the pane head on All items,
   which pins too, comes to rest under the band (58px: its 18px tuck and its
   40px row) rather than sliding beneath it.

   Z-INDEX 29: over the cards that scroll under it, and under the header (30)
   whose foot overlaps its top. */
@media (max-width: 699.98px) {
  /* #3726: THE BAND RESTS ON THE HEADER'S FOOT, MEASURED. The two literals
     below are the same fact when the header is exactly 3.25rem and its foot
     overlaps the scroller's top by 7px, which is the ordinary case: -10px is
     the band's 18px tuck less #dev-body's 8px padding, and the 7px overlap
     comes out of the scroller top being 45. In-flow chrome between the header
     and the frame (a strip that is not fixed, the non-admin reminder) moves
     the scroller's top without moving the header, and the literal no longer
     reaches the foot: a gap opens and the tabs separate. `--dev-ws-head-foot`
     is the header's measured foot in the scroller's frame, published by
     workshop.tsx, and the band rests 18px above it less the body's 8px. The
     calc is the fallback for the frame before the first measurement, and the
     phone-browser form (the document scrolls, so the property is absent) keeps
     its own arithmetic. */
  #dev-workshop { --ws-band-top: calc(var(--dev-ws-head-foot, 7px) - 17px); }
  html[data-browser-scroller="dev-forum-scroll"] #dev-workshop {
    --ws-band-top: calc(var(--browser-banner-h) + var(--platform-header-h) + var(--platform-safe-top) - 17px);
  }
  .dev-ws-tabs.dev-ws-band {
    position: sticky;
    top: var(--ws-band-top);
    z-index: 29;
  }
  /* #4703: the band is 18px on a phone now — its tuck, with the row it held
     gone into the header — so the head comes to rest right under the
     header's foot (the band's bottom edge, where its box still ends). */
  #dev-workshop .dev-ws-pane-head { top: calc(var(--ws-band-top) + 18px); }
}
/* A PULL TO REFRESH MOVES ONLY THE PAGE UNDER THE TABS (pull-to-refresh
   under the tabs, evan, 2026-10-01). "When you pull down on a community
   page, the tabs move down too? I think the tabs should be fixed, and only
   the page under them move and reveal the refresh."

   The kit's pull slid the whole of #dev-forum-scroll, and the band lives in
   it, so the header stayed and the band rode down with the page. #3514 then
   painted the gap that opened between them in the community's colour (a
   `--ptr-gap` that workshop.tsx read back off the kit's transform), so the
   two read as one band stretching. That rule is gone with the gap it
   painted: nothing opens under the header any more.

   app-view.js now opts the scroller into the kit's `pullProperty`: the
   scroller holds still and carries the pull as `--dev-ptr-pull`, and this
   slides what comes after the band (the tab body, and All items' back bar
   with it) by exactly that much. The header, the band and anything above
   the band stay where they are. The gap opens between the band and the
   page, and shows the page's own plane, as the air around its cards does:
   every box from the tab body up to the scroller is transparent, so the
   kit's layer behind them (anchored at the band's bottom edge, where the
   spinner hangs) is what shows, and it paints only the spinner.

   UNSET AT REST, so at rest this is no rule at all: `var()` with no
   fallback and nothing to read is invalid at computed-value time, which
   leaves `transform: none`, so no stacking context and no containing block
   where there was none before. A fallback of 0px would make both permanent
   on the tab body (none of these boxes has a transform of its own for this
   to override).

   NO BAND (the Workshop still loading, an app that could not load): the
   kit hangs the spinner from the scroller's top instead (app-view.js's
   `topEl` finds no band), and everything in the scroller slides, as it all
   did. AT EVERY WIDTH, outside the phone block above: the kit only pulls on
   a touch device, and an iPad's row of tabs holds still the same way (the
   row the band becomes from 768px is the same `.dev-ws-band`).

   A CLASS, NOT `:has()`. This was `#dev-forum-scroll:not(:has(.dev-ws-band))
   > *`, and a `:has()` on the scroller that picks its children is a question
   the browser has to ask again whenever anything is added inside it: every
   comment the board filled in re-applied the stylesheet to the whole board
   (about 9,000 elements with every card open, 67ms a time). The Workshop
   sets `dev-ws-has-band` while its band is on screen and the pull re-reads
   it when it starts (workshop.tsx `useWorkshopHostState`, app-view.js
   `topEl`). The same holds for `dev-ws-has-board` and `dev-ws-on-needs` on
   #dev-workshop further down. Each selector weighs what its `:has()` form
   did, except the Needs release of the column, which now weighs what the
   board's has always weighed. */
#dev-forum-scroll .dev-ws > .dev-ws-band ~ *,
#dev-forum-scroll:not(.dev-ws-has-band) > * {
  transform: translateY(var(--dev-ptr-pull));
}

/* ON A WIDE WINDOW THE BAR IS THE PANEL'S FIRST ROW (#852 review: the tabs
   sat in the coloured header's row for a round). Not a band: the header
   above already says whose page this is, so the row is the page's own ink,
   and since #4417 it is the page's title, naming the place (the list is
   nested under the community's row in the sidebar). It pins under the header's edge as the
   old strip did, on the sheet band that strip drew while pinned
   (`data-ws-pinned`, usePinnedStrip). */
@media (min-width: 768px) {
  .dev-ws-tabs.dev-ws-band {
    margin: 0 0 4px;
    padding: 0;
    background: none;
    box-shadow: inset 0 -1px 0 var(--app-sheet-line);
  }
  .dev-ws-tabs.dev-ws-band::before { content: ''; }
}

/* ── #4417: A PROJECT'S PLACES (project-places.tsx) ───────────────────
   One list where the four tabs were: Hub, Needs you, Workshop, a line, then
   Channels (#general) and Topics, each under its own small-caps heading.
   Rows are the left rail's: 40px, a 20px glyph, 15px words, and the place
   you are on in the rail's lit-row treatment (`--lit-tint`, `--lit-ink`).
   A count is the accent, a number that asks for you; a zero is not drawn. */
.dev-ws-places { display: flex; flex-direction: column; min-height: 100%; }
.dev-ws-places-nav { display: flex; flex-direction: column; gap: 2px; }
.dev-ws-place {
  display: flex; align-items: center; gap: 10px;
  width: 100%; height: 40px; padding: 0 10px; border-radius: 10px;
  border: 0; background: none; text-align: start;
  font: inherit; font-size: 15px; line-height: 20px; white-space: nowrap;
  color: var(--text-primary); text-decoration: none; cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
@media (hover: hover) {
  .dev-ws-place:not([aria-current="page"]):hover { background: var(--bg-secondary); }
}
.dev-ws-place:focus-visible { outline: 2px solid var(--accent); outline-offset: -2px; }
.dev-ws-place[aria-current="page"] { background: var(--lit-tint); color: var(--lit-ink); font-weight: 600; }
.dev-ws-place-glyph { width: 20px; height: 20px; flex: 0 0 20px; color: var(--text-muted); }
.dev-ws-place-hash { width: 18px; height: 18px; margin: 0 1px; }
.dev-ws-place[aria-current="page"] .dev-ws-place-glyph { color: inherit; }
.dev-ws-place-label { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
/* The App row's "still open" dot (features/app-frame/live-apps.tsx), at the
   row's end where a count sits, without the ring a launcher tile needs. */
.dev-ws-place-live { width: 8px; height: 8px; margin-inline-end: 4px; box-shadow: none; }
.dev-ws-place-count {
  flex-shrink: 0; min-width: 20px; height: 20px; padding: 0 6px; box-sizing: border-box;
  border-radius: 999px; background: var(--accent); color: #fff;
  font-size: 12px; font-weight: 700; line-height: 20px; text-align: center;
}
/* A channel's count is new to read, not waiting on you (#18): the grey the
   tab bar's unread count wears. Needs you keeps the accent. */
.dev-ws-place:is([data-place="discussion"], [data-place^="c:"]) .dev-ws-place-count {
  background: var(--text-faint, #8e8e93);
}
.dev-ws-place .dev-ws-filter-dot { position: static; flex-shrink: 0; background: var(--accent); }
.dev-ws-places-line { height: 1px; margin: 8px 10px; background: var(--app-sheet-line); }
.dev-ws-places-group { display: flex; flex-direction: column; gap: 2px; }
.dev-ws-places-head {
  padding: 4px 10px; font-size: 12px; font-weight: 700; line-height: 16px;
  letter-spacing: 0.06em; text-transform: uppercase; color: var(--text-muted);
}
.dev-ws-places-group + .dev-ws-places-group .dev-ws-places-head { padding-top: 12px; }
.dev-ws-places-foot { margin-top: auto; padding-top: 12px; }

/* THE PLACE BAR (place-bar.tsx): the band's box, one row: the place's
   name. On a phone it is the band, in the community's colour. */
.dev-ws-placebar .dev-ws-tabtrack {
  display: flex; align-items: center; gap: 4px; min-width: 0; height: 44px;
}
.dev-ws-places-btn {
  position: relative; flex-shrink: 0;
  display: inline-flex; align-items: center; justify-content: center;
  width: 44px; height: 44px; margin-inline-start: -6px;
  border: 0; background: none; border-radius: 10px;
  color: #fff; cursor: pointer; -webkit-tap-highlight-color: transparent;
}
.dev-ws-places-btn:focus-visible { outline: 2px solid #fff; outline-offset: -4px; }
.dev-ws-places-btn-glyph { width: 22px; height: 22px; }
/* Something waits in the places (votes, unread talk). WHITE on the
   community's colour, not red (#18 of the 19 Oct polish board): red is the
   bell's alone, and the places' own counts say which it is when opened. */
.dev-ws-places-dot {
  position: absolute; top: 9px; inset-inline-end: 8px; width: 9px; height: 9px; border-radius: 999px;
  background: #fff; box-shadow: 0 0 0 2px var(--community-tint, #2a2e34);
}
.dev-ws-place-title {
  min-width: 0; margin: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  font-size: 17px; font-weight: 650; letter-spacing: -0.01em; line-height: 22px; color: #fff;
}
.dev-ws-place-title-hash { margin-inline-end: 3px; opacity: 0.6; }
@media (min-width: 768px) {
  .dev-ws-placebar .dev-ws-tabtrack { height: 52px; }
  .dev-ws-place-title { font-size: 20px; font-weight: 700; color: var(--text-primary); }
  /* ON THE HUB THE HERO IS THE PAGE'S HEADING (audit P02, 1 Nov 2026): its
     name is the one large heading, so "Hub" above it is the band's quiet
     name of where you are, not a second 20px title over the project's
     28px one. The other places have no hero, and keep theirs. */
  .dev-ws-placebar[data-place-bar="status"] .dev-ws-place-title { font-size: 15px; font-weight: 600; color: var(--text-muted); }
}

/* THE MERGED HEADER (#4703): on a phone the place bar's contents live in the
   platform header, and the second coloured row is gone. The band keeps its
   box — the margin, the padding and the 18px tuck the pinned head and the
   pull to refresh are measured against — but it paints nothing and takes no
   taps: its track is collapsed to nothing, and the h2 stays in the DOM for
   screen readers and the declared checks.
   The header draws its own button (place-bar.tsx HeaderPlace), 28px like the
   header's other controls, and the place's name beside the switcher as a
   small quiet tag (below); the tint they sit on and the dot's ring are the
   community's, as the band's were. The place name holds its ground (`flex-shrink: 0`, capped) so a long
   community name shortens in the switcher first, which is the name the old
   second row did not show. On Homeroom's own pages that name is the
   wordmark drawing, which has no shorten-with-ellipsis of its own: it scales
   into the room left instead of clipping mid-letter. */
/* The name is phone-only, and the phone-ness is CSS, not a width query in
   the header's code (#3271): hidden at every width, shown on a phone only,
   where the band's row is collapsed. */
#platform-header .header-place-name { display: none; }
@media (max-width: 767.98px) {
  .dev-ws-tabs.dev-ws-band { background: none; pointer-events: none; }
  .dev-ws-placebar .dev-ws-tabtrack { height: 0; overflow: hidden; }
  #platform-header .header-places-btn { width: 28px; height: 28px; margin-inline-start: 0; }
  #platform-header .header-places-btn .dev-ws-places-dot { top: 1px; inset-inline-end: 0; }
  #platform-header:has(.header-place-name) #header-title-name > svg {
    width: 100%; height: auto;
  }
  #platform-header .header-place-name {
    display: inline-block;
    flex-shrink: 0; min-width: 0; max-width: 45%; overflow: hidden;
    text-overflow: ellipsis; white-space: nowrap;
    /* A SMALL QUIET TAG, CENTRED ON THE TITLE'S LINE (newcomer run six,
       14 Oct 2026). It was a subscript dropped to the chip's foot, 11px
       with `align-self: flex-end`, and "Club Votes ⌄ Hub" read as a word
       that had slipped a few points under the name's baseline. Now it is a
       pill in the header's own ink, as the bell and the back disc are
       (`--brand-tint` / `--brand-ink`: white on the community's tint
       here), centred on the row beside the switcher, so it reads as a
       label on the name rather than a second line. */
    align-self: center;
    padding: 2px 8px; border-radius: 999px;
    background: var(--brand-tint); color: var(--brand-ink);
    font-size: 12px; font-weight: 600; line-height: 16px;
  }  /* The Needs you run's tag is a community's name, longer than a place's,
     beside a title that never changes: it may take the rest of the row. */

}

/* THE TRAY (places-tray.tsx): the list, slid in from the left over a
   scrim, on a phone. #5384: it opens UNDER the header, which stays as it
   is, undimmed and pressable, its bottom edge the offset the other layers
   under it use; it reaches down over the tab bar (z 60), under a dialog.
   The header covers the status bar, so the list keeps only its own 16px.
   At most the float box less 56px of scrim beside it (THE USABLE BOX; 1
   November 2026), so the tray leaves a strip to tap away on the Duo too. */
.dev-ws-tray-root {
  position: fixed; inset-inline-start: 0; inset-inline-end: 0; bottom: 0; z-index: 60;
  top: calc(var(--browser-banner-h, 0px) + var(--platform-header-h) + var(--platform-safe-top, 0px));
}
.dev-ws-tray-scrim { position: absolute; inset: 0; background: rgba(0, 0, 0, 0.45); animation: dev-ws-tray-fade 160ms ease-out; }
.dev-ws-tray {
  position: absolute; top: 0; bottom: 0; inset-inline-start: 0;
  width: min(296px, calc(var(--platform-float-w) - 56px));
  padding: 16px 12px calc(16px + var(--platform-safe-bottom, 0px));
  overflow-y: auto; overscroll-behavior: contain;
  background: var(--dc-sheet-solid, var(--bg-primary));
  box-shadow: 0 0 40px rgba(0, 0, 0, 0.25);
  animation: dev-ws-tray-in 200ms cubic-bezier(.2, .8, .2, 1);
}
@keyframes dev-ws-tray-in { from { transform: translateX(calc(-100% * var(--rtl-sign))); } to { transform: none; } }
@keyframes dev-ws-tray-fade { from { opacity: 0; } to { opacity: 1; } }
/* The close (#5386): the open in reverse. The leaving tray takes no presses
   (they go to the page under it) and the card calls its own end. */
.dev-ws-tray-root.is-closing { pointer-events: none; }
.dev-ws-tray-root.is-closing .dev-ws-tray { animation: dev-ws-tray-out 200ms cubic-bezier(.2, .8, .2, 1) forwards; }
.dev-ws-tray-root.is-closing .dev-ws-tray-scrim { animation: dev-ws-tray-fade-out 160ms ease-out forwards; }
@keyframes dev-ws-tray-out { from { transform: none; } to { transform: translateX(calc(-100% * var(--rtl-sign))); } }
@keyframes dev-ws-tray-fade-out { from { opacity: 1; } to { opacity: 0; } }
@media (prefers-reduced-motion: reduce) {
  .dev-ws-tray, .dev-ws-tray-scrim { animation: none; }
  .dev-ws-tray-root.is-closing .dev-ws-tray, .dev-ws-tray-root.is-closing .dev-ws-tray-scrim { animation: none; }
}
/* Reduce motion setting (#6510): the same, when Settings asks for it. */
:where(html[data-motion="reduce"]) .dev-ws-tray,
:where(html[data-motion="reduce"]) .dev-ws-tray-scrim { animation: none; }
:where(html[data-motion="reduce"]) .dev-ws-tray-root.is-closing .dev-ws-tray,
:where(html[data-motion="reduce"]) .dev-ws-tray-root.is-closing .dev-ws-tray-scrim { animation: none; }

/* ── THE PHONE'S COMMUNITY HEADER (features/nav-drawer/) ──────────────
   Evan's design (18 Oct 2026). Under 768px a community's page drew its
   header from a drawer: your communities at 85%, the community's places at
   80%, then the page, on one strip. The strip is gone (3 Nov 2026): the
   Hub's rows lead to the places and All communities is a page, so only the
   header's rules are left, below. */

/* THE HEADER WITH THE DRAWER (header-drawer.tsx). The arrow (on a Hub,
   the grid) is the bar's back disc; the titles are absolutely placed in the
   h1, so the h1 lets a list's title ("Messages") sit out past its edge where
   the arrow is not, and each title shortens itself. The bar's colour: the
   tinted rules above still paint it, and DrawerUntint lays the bar as it is
   off a community over them, faded out with depth (`--nav-k`); a
   community's page rests at 1, the tinted bar with white ink. */
@media (max-width: 767.98px) {
  html[data-nav-drawer] body {
    --nav-brand-ink: var(--brand-ink);
    --nav-brand-tint: var(--brand-tint);
    --nav-brand-line: var(--brand-line);
    --nav-ink: var(--text-primary);
  }
  html[data-nav-drawer][data-community-tint] body:has(#app-view:not(.hidden)) #platform-header {
    --brand-ink: color-mix(in srgb, #fff calc(var(--nav-k, 1) * 100%), var(--nav-brand-ink));
    --brand-tint: color-mix(in srgb, rgba(255, 255, 255, 0.16) calc(var(--nav-k, 1) * 100%), var(--nav-brand-tint));
    --brand-line: color-mix(in srgb, rgba(255, 255, 255, 0.32) calc(var(--nav-k, 1) * 100%), var(--nav-brand-line));
    color: color-mix(in srgb, #fff calc(var(--nav-k, 1) * 100%), var(--nav-ink));
  }
  .nav-drawer-untint {
    position: fixed; inset: 0; z-index: -1; pointer-events: none; opacity: 0;
    background:
      linear-gradient(var(--dc-sheet-fill), var(--dc-sheet-fill)),
      var(--home-washes, var(--dc-sheet-solid));
  }
  #header-title:has(> .nav-drawer-titles) { overflow: visible; }
  .nav-drawer-back { will-change: transform, opacity; }
  .nav-drawer-titles { position: relative; display: block; width: 100%; height: 28px; }
  .nav-drawer-title {
    position: absolute; inset-inline-start: 0; inset-inline-end: 0; top: 50%; margin-top: -17px;
    display: flex; flex-direction: column; align-items: flex-start;
    line-height: 1.15; white-space: nowrap;
    will-change: transform, opacity;
  }
  .nav-drawer-title:first-child { opacity: 0; }
  .nav-drawer-title-name {
    max-width: 100%; overflow: hidden; text-overflow: ellipsis;
    font-size: 17px; font-weight: 650; letter-spacing: -0.01em;
  }
  .nav-drawer-title-mark { display: block; width: 77.5px; height: 20px; }
  .nav-drawer-title-page {
    max-width: 100%; overflow: hidden; text-overflow: ellipsis;
    font-size: 12px; font-weight: 600; opacity: 0.78;
  }
}
/* ── MESSAGES ON THE SAME DRAWER (features/messages/phone-drawer.tsx) ──
   Evan's design (18 Oct 2026), on a phone: the conversation list at 85% of
   the screen in the column's styling (the desktop's sidebar rows: no cards,
   the conversation you were in lit), the last conversation peeking at its
   right, and the conversation over the whole screen, moved by transform
   between the two. The panes stay the inbox's own (#messages-screen >
   .messages-layout > …), so the declared checks and the wide window's
   rules are untouched; `messages-drawer` is only ever set under 768px. */
@media (max-width: 767.98px) {
  .messages-layout.messages-drawer { position: relative; overflow: hidden; touch-action: pan-y; }
  /* touch-action stops at a scroller: the list and the conversation say
     pan-y themselves, so a sideways drag on them is the drawer's. */
  .messages-layout.messages-drawer .messages-list-scroll,
  .messages-layout.messages-drawer .messages-thread-scroll { touch-action: pan-y; }
  .messages-layout.messages-drawer > .messages-list-pane {
    position: absolute; top: 0; bottom: 0; inset-inline-start: 0; width: 85%;
    will-change: transform;
  }
  .messages-layout.messages-drawer.messages-drawer-alone > .messages-list-pane { width: 100%; }
  .messages-layout.messages-drawer > .messages-thread-pane {
    position: absolute; top: 0; bottom: 0; inset-inline-start: 0; width: 100%;
    margin-top: 0;
    box-shadow: calc(-8px * var(--rtl-sign)) 0 24px rgba(0, 0, 0, 0.08);
    will-change: transform;
  }
  .messages-layout.messages-drawer > .messages-thread-pane.messages-no-selection { display: none; }
  /* The list's rows: the column's, one name a row with its last line small under it. */
  .messages-layout.messages-drawer > .messages-list-pane .messages-toolbar { margin: 12px 12px 4px; }
  .messages-layout.messages-drawer > .messages-list-pane .messages-list-scroll { padding: 0 8px 12px; }
  .messages-layout.messages-drawer > .messages-list-pane .messages-section-head { padding: 12px 10px 4px; }
  .messages-layout.messages-drawer > .messages-list-pane .messages-section-card {
    display: flex; flex-direction: column; gap: 2px;
    margin: 0; overflow: visible; border-radius: 0; background: none; box-shadow: none;
  }
  .messages-layout.messages-drawer > .messages-list-pane .messages-conversation-row {
    min-height: 48px; gap: 10px; padding: 4px 10px; border-radius: 10px;
  }
  .messages-layout.messages-drawer > .messages-list-pane .messages-conversation-row::after { display: none; }
  .messages-layout.messages-drawer > .messages-list-pane .messages-conversation-row > :first-child {
    flex: 0 0 28px; width: 28px; height: 28px; border-radius: 8px; font-size: 11px;
  }
  .messages-layout.messages-drawer > .messages-list-pane .messages-conversation-row > .messages-group-faces > :first-child {
    position: static; width: 28px; height: 28px; border-radius: 8px; font-size: 11px;
  }
  .messages-layout.messages-drawer > .messages-list-pane .messages-conversation-row > .messages-group-faces > :last-child { display: none; }
  /* AUDIT C03 (2 Nov 2026): the column keeps the rows' own type, 15 over
     13 at the house weight, and their time: a 400-weight title and a 12px
     line with no time made the same list two designs, upright and
     sideways. Only the members chip goes, for the narrower column. */
  .messages-layout.messages-drawer > .messages-list-pane .messages-conversation-row .messages-group-tag { display: none; }
  .messages-layout.messages-drawer > .messages-list-pane .messages-conversation-active { background: var(--lit-tint); color: var(--lit-ink); }
  .messages-layout.messages-drawer > .messages-list-pane .messages-conversation-active .messages-row-name { color: inherit; }
  /* In a conversation the header names it, so its sheet keeps only its discs.
     Over the Homeroom bot's Activity strip they float at the top-right
     corner, on the strip's right end, which it leaves them (polish N15: a
     48px row held the ⋯ alone). */
  .messages-layout.messages-drawer > .messages-thread-pane > .messages-thread-header {
    position: absolute; top: 4px; inset-inline-end: 12px; z-index: 25; padding: 0; gap: 8px;
  }
  /* WITH NO STRIP UNDER THEM THEY TAKE A SLIM ROW (audit C01, 2 Nov 2026).
     Floating over a group's or a DM's transcript, the members and ⋯ discs
     sat on the top bubble's words and sender line, and a tap meant for the
     bubble opened the menu. A 40px band, the discs at its right end, keeps
     the transcript below them. */
  .messages-layout.messages-drawer > .messages-thread-pane > .messages-thread-header:not(:has(+ [data-bot-strip])) {
    position: static; padding: 4px 12px; justify-content: flex-end;
  }
  .messages-layout.messages-drawer > .messages-thread-pane > .messages-thread-header .messages-thread-action { width: 32px; height: 32px; }
  .messages-layout.messages-drawer > .messages-thread-pane > .messages-thread-header .messages-thread-action svg { width: 18px; height: 18px; }
  .messages-layout.messages-drawer > .messages-thread-pane [data-bot-strip-toggle] { padding-inline-end: 56px; }
}

/* ── The hero's rows (community-card.tsx) ──
   Who is here: the faces, then "Public community · 23 members" as one
   phrase, the audience's glyph leading it. Then one row of what you can do:
   Open app in the community's colour, Invite, the ⋯, and Join at the far
   end. Leave is a row of the ⋯ (#4045). */
/* The words sit on the line's own baseline, so "Public community" and
   " · 23 members" read as one line; only the glyph is centred. A
   `vertical-align` nudge here dropped the audience 3px below the count. */
.dev-ws-hero-audience { display: inline-flex; align-items: baseline; gap: 4px; }
.dev-ws-hero-audience b { font-weight: 650; }
.dev-ws-hero-audience svg { width: 16px; height: 16px; flex: none; align-self: center; color: var(--text-muted); }
.dev-ws-hero-row { display: flex; align-items: center; gap: 8px; min-width: 0; min-height: 32px; }
.dev-ws-hero-row > .dev-ws-hero-actions { flex: 1 1 auto; min-width: 0; flex-wrap: wrap; }
.dev-ws-hero-member { margin-inline-start: auto; flex: none; display: flex; }
.dev-ws-open-app {
  display: inline-flex; align-items: center; gap: 6px; flex: none;
  height: 32px; padding: 0 14px;
  border: 0; border-radius: 999px;
  background: var(--community-tint, var(--accent)); color: #fff;
  font: inherit; font-size: 14px; font-weight: 650; white-space: nowrap;
  cursor: pointer;
}
@media (hover: hover) {
  .dev-ws-open-app:hover { filter: brightness(1.1); }
}
/* Join's popup hangs from the RIGHT: Join ends the row, so a popup opening
   rightward would leave the screen. The arrow moves with it. */
.dev-ws-hero .dev-ws-join-anchor { margin-inline-start: 0; }
.dev-ws-hero .dev-ws-hero-member .dev-ws-join-pop { inset-inline-start: auto; inset-inline-end: -6px; }
.dev-ws-hero .dev-ws-hero-member .dev-ws-join-pop::before { inset-inline-start: auto; inset-inline-end: 26px; }
@media (prefers-reduced-motion: no-preference) {
  .dev-ws-hero .dev-ws-hero-member .dev-ws-join-pop { transform-origin: calc(100% - 32px) 0; }
}
/* ── Opened from an invite link (#3700, invite-offer.ts) ──
   Who invited them, their note, and one Join as the screen's primary
   button, first in the hero, so the decision sits on the page it is about
   and is on screen without scrolling on a phone. A card on the hero's
   ground, in the Join question's own surface. The button fills the card,
   and a question a refusal asks hangs from its right edge as from the row's
   Join. */
.dev-ws-invite {
  display: flex; flex-direction: column; gap: 10px;
  padding: 14px;
  border-radius: 18px;
  background-color: var(--dc-sheet);
  box-shadow: inset 0 0 0 1px var(--app-sheet-line);
}
.dev-ws-invite-from { margin: 0; font-size: 16px; line-height: 21px; font-weight: 650; color: var(--text-primary); }
.dev-ws-invite-note { margin: 0; font-size: 15px; line-height: 21px; color: var(--text-primary); }

/* ── "Your communities" (features/workshop/community-switcher.tsx) ──
   The switcher behind the Communities tab: a sheet from the floor on a
   phone (the kit's own when it adopts it; this scrim and panel when not),
   and a menu hung off whatever opened it on a wide window. Rows are the
   shell's 15 over 13, each community's tile at 40px, and the one you are on
   is tinted in its colour with a tick (set inline, since the colour is the
   community's). */
.community-switcher-scrim {
  position: fixed; inset: 0; z-index: 60;
  background: rgba(0, 0, 0, .32);
  display: flex; align-items: flex-end;
}
.community-switcher {
  box-sizing: border-box;
  display: flex; flex-direction: column;
  background: var(--dc-sheet);
  color: var(--text-primary);
}
.community-switcher-sheet {
  width: 100%; max-height: 82dvh;
  padding: 6px 8px calc(12px + var(--platform-safe-bottom, 0px));
  border-start-start-radius: 22px; border-start-end-radius: 22px; border-end-end-radius: 0; border-end-start-radius: 0;
  box-shadow: 0 -8px 30px rgba(0, 0, 0, .18);
}
.community-switcher-grab {
  align-self: center; flex: none;
  width: 36px; height: 5px; margin: 2px 0 8px; border-radius: 3px;
  background: var(--border, rgba(0, 0, 0, .15));
}
.community-switcher-menu {
  position: fixed; z-index: 60;
  /* 364px: "All communities" whole beside its "34 to vote" and the tick. */
  width: 364px; max-height: min(70vh, 560px);
  padding: 6px;
  border-radius: 16px;
  box-shadow: 0 0 0 1px var(--app-sheet-line), 0 14px 40px rgba(0, 0, 0, .18);
}
.community-switcher-head { padding: 8px 12px 6px; }
.community-switcher-title { margin: 0; font-size: 17px; font-weight: 700; line-height: 22px; }
.community-switcher-menu .community-switcher-title { font-size: 13px; font-weight: 700; text-transform: uppercase; letter-spacing: .06em; color: var(--text-muted); }
/* #5290: the search first, as the phone drawer's search box draws it. */
.community-switcher-search {
  flex: none; height: 38px; margin: 2px 4px 6px; padding: 0 12px;
  display: flex; align-items: center; gap: 8px;
  border-radius: 12px; background: var(--bg-secondary);
  color: var(--text-muted);
}
.community-switcher-search:focus-within { box-shadow: inset 0 0 0 2px var(--accent); }
.community-switcher-search-glyph { flex: none; width: 18px; height: 18px; }
.community-switcher-search-input {
  flex: 1 1 auto; min-width: 0; height: 100%; padding: 0; border: 0; outline: none;
  background: transparent; color: var(--text-primary);
  font: inherit; font-size: 16px;
  -webkit-appearance: none; appearance: none;
}
.community-switcher-search-input::placeholder { color: var(--text-muted); }
.community-switcher-search-input::-webkit-search-cancel-button { -webkit-appearance: none; display: none; }
.community-switcher-list {
  display: flex; flex-direction: column; gap: 2px;
  min-height: 0; overflow-y: auto; overscroll-behavior: contain;
}
.community-switcher-row {
  display: flex; align-items: center; gap: 12px;
  width: 100%; min-height: 60px; padding: 8px 12px; box-sizing: border-box;
  border: 0; border-radius: 14px; background: transparent;
  color: inherit; font: inherit; text-align: start; cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.community-switcher-menu .community-switcher-row { min-height: 52px; border-radius: 10px; }
@media (hover: hover) {
  .community-switcher-row:not([aria-current="true"]):hover { background: var(--bg-secondary); }
}
.community-switcher-row:focus-visible { outline: 2px solid var(--accent); outline-offset: -2px; }
.community-switcher-tile {
  flex: none; width: 40px; height: 40px; overflow: hidden;
  display: grid; place-items: center;
  border-radius: 11px; font-size: 20px; font-weight: 700;
}
.community-switcher-menu .community-switcher-tile { width: 34px; height: 34px; border-radius: 9px; font-size: 17px; }
.community-switcher-tile > img { width: 100%; height: 100%; object-fit: cover; border-radius: 0; }
/* An emoji tile's glyph at the tile's own size, not the launcher's. */
.community-switcher-tile > span { font-size: inherit; line-height: 1; }
/* ALL COMMUNITIES WEARS THE PEOPLE GLYPH (#3663), the Communities tab's
   own, in a square ring, in the row's own ink. It was a filled near-black
   tile, which in the same list as
   Homeroom's own (a cream H on near-black) read as a second Homeroom. The
   ring is the tab's 2px at the tile's size, and the glyph is the tab's
   share of it (18px in 28px) with the tab's 1.8 stroke. */
.community-switcher-tile-all {
  background: transparent; color: inherit;
  box-shadow: inset 0 0 0 2px currentColor;
}
.community-switcher-tile-all > svg { width: 26px; height: 26px; stroke-width: 1.8; }
.community-switcher-menu .community-switcher-tile-all > svg { width: 22px; height: 22px; }
.community-switcher-tile-add {
  background: transparent; color: var(--text-muted);
  box-shadow: inset 0 0 0 1.5px var(--app-sheet-line);
}
.community-switcher-text { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
.community-switcher-name {
  font-size: 15px; font-weight: 650; line-height: 20px;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.community-switcher-sub { font-size: 13px; line-height: 17px; color: var(--text-muted); }
.community-switcher-waiting {
  flex: none; height: 22px; padding: 0 8px; border-radius: 999px;
  display: inline-flex; align-items: center;
  background: color-mix(in srgb, var(--accent) 12%, transparent); color: var(--accent);
  font-size: 12px; font-weight: 650; white-space: nowrap;
}
.community-switcher-tick { flex: none; width: 20px; display: grid; place-items: center; color: var(--text-primary); }
.community-switcher-note { margin: 0; padding: 10px 12px; font-size: 13px; color: var(--text-muted); }
/* A small caps label over a part of the switcher (Recent, #5290), as the
   Communities screen labels its sections. */
.community-switcher-section {
  display: flex; align-items: center; gap: 6px;
  margin: 0; padding: 12px 12px 4px;
  font-size: 12px; font-weight: 700; line-height: 16px;
  text-transform: uppercase; letter-spacing: .06em; color: var(--text-muted);
}

/* THE DISCUSSION TAB (project-discussion.tsx): the channel's own pane, a
   FITTED SCREEN like Needs you, so its composer rests on the foot of the
   reading area and the stream scrolls inside it rather than the page. It
   was a guessed `calc(100dvh - 210px)`, which stopped short of the bottom
   (#852 review). The flex chain above bounds it in the native layout;
   in a mobile browser, where the page scrolls, the tab takes `--ws-fit` as
   a definite height, at every width. The pane draws its own sheet
   (general-chat.tsx's `dc-lift dc-lift-session`), which runs off the
   bottom as it does in Messages, so on a phone it spans the band's width:
   the screen's, by cancelling the same 4px of `#dev-body` the band does
   (#3499), not 12. */
html[data-browser-scroller] .dev-ws[data-ws-tab="discussion"],
html[data-browser-scroller] .dev-ws[data-ws-tab^="c:"] {
  height: var(--ws-fit);
  min-height: var(--ws-fit);
}
.dev-ws-discussion { flex: 1 1 auto; min-height: 320px; display: flex; flex-direction: column; }
.dev-ws-discussion-host { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; }
.dev-ws-discussion-host > * { flex: 1 1 auto; min-height: 0; }
@media (max-width: 767.98px) {
  .dev-ws-discussion { margin: 0 -4px; }
}
/* WITH THE KEYBOARD UP IN A PHONE BROWSER, THE ROOM IS WHAT IS SEEN
   (iOS Safari, 5 October 2026: an invitee opened a project's Discussion to
   talk, tapped the message box, and saw a blank cream page with the keys
   up; no messages, no composer, no header). In a phone browser the page is
   the scroller (#1518), so this fitted box sits in the document's flow, and
   the fixed-shell physics every other chat relies on did not hold here:
   iOS scrolled the page to put the message box over the keys, then the
   column's keyboard reservation (`.platform-kb-column`, `--un-kb-inset`)
   lifted the box a keyboard's height again inside a page that had already
   moved by it, and the kit's pan reset only runs in a bounded shell. What
   was left on screen was the column's empty padding.

   So while the keyboard is open (`platform-kb-open`, lib/keyboard-open.ts)
   the room is laid on the band of the page that is actually visible: from
   the pan (`--platform-vv-top`) to the top of what covers the foot
   (`--platform-kb-cover`: the keys, and Safari's pill and form bar over
   them). Its column reserves nothing more, the transcript fills what is
   left above the composer, and the conversation's own stick-to-bottom
   (with its keyboard hold, lib/keyboard-hold.ts) keeps the newest line in
   view as it shrinks. The tab's box keeps its height in the page, so the
   page under it does not move, and the room drops back into it when the
   keys go. In the bounded shell (the app, an installed app) none of this
   applies: there is no `data-browser-scroller`. */
@media (max-width: 767px) {
  html[data-browser-scroller].platform-kb-open .dev-ws-discussion {
    position: fixed;
    inset-inline-start: 0;
    inset-inline-end: 0;
    top: var(--platform-vv-top, 0px);
    bottom: var(--platform-kb-cover, 0px);
    z-index: 35;
    min-height: 0;
    margin: 0;
  }
  html[data-browser-scroller].platform-kb-open .dev-ws-discussion .platform-kb-column {
    padding-bottom: 0;
  }
}
/* THE COMPOSER'S FOOT IS ALREADY CLEAR. `.platform-safe-bar` adds the tab
   bar's height under every composer, on the rule that inside #app-view the
   bar is hidden; a project page under the Communities tab shows it, and
   this fitted box already ends above it, so that reserve left a strip of
   empty pane under the composer. The bar's own 8px base gap stays. */
.dev-ws-discussion .platform-safe-bar { padding-bottom: 0.5rem !important; }
/* HOMEROOM'S ROOM, #general, IN PLACE TOO (#3494). It is Messages' own
   thread (EmbeddedConversation) rather than the group chat's pane, so it
   drops the margins it keeps on the Messages strip and fills the tab edge to
   edge, as a project's own chat does. A reply thread opens beside it on a
   desktop and over it on a phone, as it does in Messages. */
.dev-ws-discussion > .messages-layout { flex: 1 1 auto; height: auto; min-height: 0; }
.messages-layout-embedded > .messages-thread-pane,
.messages-layout-embedded > .messages-reply-pane { margin: 0; }
@media (min-width: 768px) {
  .messages-layout-embedded > .messages-reply-pane { margin-inline-start: 8px; }
}
/* #6071 follow-up: a new chat with Homeroom bot on its tab
   (features/messages/new-thread.tsx) takes the column, docked beside the
   lists or not: it is a fresh start, and its ✕ gives the lists back. */
.messages-layout-embedded.messages-has-blank-thread > .messages-thread-pane { display: none; }
.messages-layout-embedded.messages-has-blank-thread > .messages-reply-pane { flex: 1 1 auto; margin-inline-start: 0; }
/* THE BLANK THREAD'S OPENING (5 Nov 2026, new-thread.tsx). In the middle of
   the empty thread, where the first message will land: the bot's face, what
   it asks, and the ways to start, each its own pill. A pill is set in the
   message box's own type (`.messages-composer-input`: 17px over 22px, 15px
   from 768px) because it is the words a tap writes into the box; its "…" is
   the box's placeholder ink. The one the message begins with wears the
   card's focus ring. Auto margins centre the block in a scroller that keeps
   its `justify-end`, and let it scroll when a short screen cannot hold it. */
.messages-starts {
  margin-block: auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  padding: 12px 16px;
}
.messages-starts-hello { display: flex; flex-direction: column; align-items: center; gap: 4px; text-align: center; }
.messages-starts-hello > img { width: 40px; height: 40px; margin-bottom: 6px; border-radius: 12px; object-fit: cover; }
.messages-starts-title { margin: 0; color: var(--text-primary); font-size: 17px; font-weight: 700; line-height: 22px; text-wrap: balance; }
.messages-starts-sub { margin: 0; color: var(--text-muted); font-size: 13px; line-height: 17px; }
.messages-starts-list { display: flex; flex-direction: column; align-items: center; gap: 8px; width: 100%; }
.messages-start {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  max-width: 100%;
  min-height: 44px;
  padding-block: 10px;
  padding-inline: 14px 18px;
  border-radius: 9999px;
  color: var(--text-primary);
  background: var(--messages-surface);
  box-shadow: var(--messages-disc-shadow), 0 6px 16px -10px var(--app-sheet-shadow-near);
  font-size: 17px;
  line-height: 22px;
  text-align: start;
  transition: background 150ms, box-shadow 150ms;
}
.messages-start > svg {
  flex: 0 0 auto;
  width: 20px;
  height: 20px;
  color: var(--text-muted);
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.messages-start:hover { background: var(--messages-surface-2); }
.messages-start:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.messages-start[aria-pressed="true"] { box-shadow: var(--messages-disc-shadow), 0 0 0 2px var(--accent); }
.messages-start-more { color: var(--text-faint); }
@media (min-width: 768px) {
  .messages-start { font-size: 15px; }
}
/* THE PROJECT IT IS FOR, floating over the box: a disc of its own above the
   card, not a row inside it, which opens the "Your communities" rows
   (project-picker.tsx). A project picked tints it in its community's colour,
   as the switcher tints the row you are on. */
.messages-project-row { display: flex; flex-wrap: wrap; gap: 8px; padding-bottom: 8px; }
.messages-project-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  max-width: 100%;
  height: 34px;
  padding-inline: 6px 11px;
  border-radius: 9999px;
  color: var(--text-secondary);
  background: var(--messages-surface);
  box-shadow: var(--messages-disc-shadow), 0 6px 16px -8px var(--app-sheet-shadow-near);
  font-size: 13px;
  font-weight: 600;
  transition: background 150ms;
}
.messages-project-chip:hover { background: var(--messages-surface-2); }
.messages-project-chip:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.messages-project-chip[data-picked] {
  color: var(--text-primary);
  background: color-mix(in srgb, var(--project-ink) 14%, var(--messages-surface));
}
.messages-project-chip-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.messages-project-chip-tile {
  flex: 0 0 auto;
  width: 22px;
  height: 22px;
  overflow: hidden;
  display: grid;
  place-items: center;
  border-radius: 7px;
  font-size: 13px;
  font-weight: 700;
}
.messages-project-chip-tile > img { width: 100%; height: 100%; object-fit: cover; border-radius: 0; }
.messages-project-chip-tile > span { font-size: inherit; line-height: 1; }
.messages-project-chip-any { color: var(--text-muted); box-shadow: inset 0 0 0 1.5px var(--app-sheet-line); }
.messages-project-chip-any > svg,
.messages-project-chip-chev {
  flex: 0 0 auto;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.messages-project-chip-any > svg { width: 14px; height: 14px; stroke-width: 1.8; }
.messages-project-chip-chev { width: 14px; height: 14px; color: var(--text-muted); stroke-width: 2.4; }
@media (prefers-reduced-motion: reduce) {
  .messages-start,
  .messages-project-chip { transition: none; }
}
/* Reduce motion setting (#6510): the same, when Settings asks for it. */
:where(html[data-motion="reduce"]) .messages-start,
:where(html[data-motion="reduce"]) .messages-project-chip { transition: none; }
/* WHO WORKS ON IT (10 Nov 2026, thread-builder.tsx). The second chip in the
   row above is the project chip's own class, tinted in the accent once the
   person's own Claude Code or ChatGPT is picked. Then the send is not a send:
   it opens the product in a new tab, so the disc widens into a pill that
   says Open beside the leaving-arrow. */
.messages-send.messages-send-open {
  width: auto;
  gap: 4px;
  padding-inline: 14px 12px;
  font-size: 15px;
  font-weight: 600;
}
.messages-send.messages-send-open svg { width: 18px; height: 18px; stroke-width: 2; }
/* Files cannot ride a link, so the box's "+" (Attach files) is not offered
   while the thread is for the person's own Claude Code or ChatGPT; a file
   dropped or pasted all the same is refused in words when Open is pressed. */
.messages-reply-pane[data-bot-new-thread-own] .messages-composer-add { display: none; }
/* Its connector is not there yet: the steps to add one take the place of the
   starts and the box, which stay mounted behind them so what was typed is
   kept. One column that scrolls, its two buttons at its end. */
.messages-reply-pane[data-bot-new-thread-setup] > .messages-thread-scroll,
.messages-reply-pane[data-bot-new-thread-setup] > .messages-composer { display: none; }
.messages-builder-setup {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 12px;
  /* Clear of the phone's tab bar or home strip, whichever is taller, as
     `.platform-safe-bar` clears a composer, and 16px over it. */
  padding: 8px 16px calc(16px + max(var(--platform-tabs-h, 0px), var(--platform-safe-bottom, 0px)));
}
/* A PROJECT'S OWN CHANNEL'S REPLY THREAD, IN PLACE TOO (#3653). The pane
   Messages opens beside an app channel (AppReplyThreadPane) opens beside the
   group chat's pane here: to its right on a desktop, over it on a phone,
   where its ✕ brings the room back. The host itself is never restyled from
   outside: only the section's class says a thread is open. */
.dev-ws-discussion-threaded > .messages-reply-pane { margin: 0; }
@media (max-width: 767.98px) {
  .dev-ws-discussion-threaded > .dev-ws-discussion-host { display: none; }
}
@media (min-width: 768px) {
  .dev-ws-discussion-threaded { flex-direction: row; }
  .dev-ws-discussion-threaded > .dev-ws-discussion-host { min-width: 0; }
  .dev-ws-discussion-threaded > .messages-reply-pane { margin-inline-start: 8px; }
}
/* A TOPIC'S CHANNEL (#4417, project-discussion.tsx TopicChannel). The same
   fitted pane as #general, with one line above the room: what the topic is
   for, and how many requests are filed under it as a link to them
   (topic-head.tsx). 13px muted, like every fact under a title; the link is
   the accent, because it is an action. A retired topic's line says what
   became of it, and the room under it takes no messages. */
.dev-ws-topic-head {
  margin: 0 0 8px; padding: 0 4px;
  font-size: 13px; line-height: 18px; color: var(--text-muted);
  overflow-wrap: anywhere;
}
.dev-ws-topic-head-link { color: var(--accent); text-decoration: none; white-space: nowrap; }
.dev-ws-topic-head-link:hover { text-decoration: underline; }
/* #4417 follow-up: A TOPIC'S REPLY THREAD OPENS AS #general's DOES, beside
   the room on a desktop and over it on a phone (the rules above). The
   topic's line sits over the room, so beside a thread it runs over both:
   two rows, the room and the thread side by side in the second, the thread
   as wide as it is beside an app channel. On a phone it goes with the room. */
@media (max-width: 767.98px) {
  .dev-ws-topic-channel.dev-ws-discussion-threaded > .dev-ws-topic-head { display: none; }
}
@media (min-width: 768px) {
  .dev-ws-topic-channel.dev-ws-discussion-threaded {
    display: grid;
    grid-template-columns: minmax(0, 1fr) min(420px, 42%);
    grid-template-rows: auto minmax(0, 1fr);
  }
  .dev-ws-topic-channel.dev-ws-discussion-threaded > .dev-ws-topic-head { grid-column: 1 / -1; }
}
/* #5303: #general's LINE (channel-head.tsx). The topic's line, for #general:
   what the channel is for and how many members it reaches, with Mute at its
   end. Over a reply thread it does what a topic's line does: over both on a
   desktop, gone with the room on a phone. */
.dev-ws-channel-head {
  display: flex; align-items: center; gap: 12px;
  margin: 0 0 8px; padding: 0 4px;
}
.dev-ws-channel-head > .dev-ws-channel-head-line { flex: 1 1 auto; min-width: 0; margin: 0; padding: 0; }
@media (max-width: 767.98px) {
  .dev-ws-general-channel.dev-ws-discussion-threaded > .dev-ws-channel-head { display: none; }
}
@media (min-width: 768px) {
  .dev-ws-general-channel.dev-ws-discussion-threaded {
    display: grid;
    grid-template-columns: minmax(0, 1fr) min(420px, 42%);
    grid-template-rows: auto minmax(0, 1fr);
  }
  .dev-ws-general-channel.dev-ws-discussion-threaded > .dev-ws-channel-head { grid-column: 1 / -1; }
}
/* A TOPIC'S FIGURES (topic-figures.tsx; services/topic-figures.js): between
   the topic's line and its room, the numbers its dapp.json entry names. The
   label over the card is the section header; the card is the plane colour,
   20px, one hairline (AGENTS.md, "Type and colour"), one cell per figure
   with a hairline between them (the card's own fill showing through a 1px
   gap). A split figure lists Homeroom over Other projects, each name with
   its number, the number falling under its name where the cell is too
   narrow for both. Colour only for a figure off its target: the attention
   ink, with its glyph, on the value and its line, or on the side that is
   off. The tiles wrap (#6273): as many at least 170px wide as fit a row,
   so twelve figures are three rows of readable tiles and never one row of
   slivers; the card's own fill is the plane colour, and each tile draws
   the hairline above and before it, so the room a short last row leaves is
   plain. A value keeps its words whole: it wraps at a space or not at all,
   never "7 tim / es". With under 560px of room the figures sit two by two,
   and the bot's grid puts each row's name across its row. Beside a thread
   it goes where the topic's line goes. */
.dev-ws-figs { flex: none; margin: 0 0 10px; container-type: inline-size; }
.dev-ws-figs-head {
  display: flex; align-items: center; justify-content: space-between; gap: 8px;
  min-height: 32px; padding: 0 4px 2px;
}
.dev-ws-figs-card {
  display: grid; gap: 1px; overflow: hidden;
  border: 1px solid var(--app-sheet-line); border-radius: 20px;
  background: var(--app-sheet-line);
}
.dev-ws-figs-tiles {
  grid-template-columns: repeat(auto-fill, minmax(170px, 1fr)); gap: 0;
  background: var(--dc-sheet-solid);
}
.dev-ws-figs-tiles > .dev-ws-fig { box-shadow: -1px -1px 0 0 var(--app-sheet-line); }
.dev-ws-fig {
  display: flex; flex-direction: column; align-items: flex-start; gap: 2px; min-width: 0;
  padding: 12px 16px 14px;
  background: var(--dc-sheet-solid);
}
.dev-ws-fig-label { font-size: 13px; line-height: 18px; font-weight: 500; color: var(--text-muted); }
.dev-ws-fig-label-end { white-space: nowrap; }
.dev-ws-fig-info {
  position: relative; display: inline-flex; vertical-align: -3px;
  width: 16px; height: 16px; margin-inline-start: 4px; padding: 0;
  border: 0; border-radius: 50%; background: none; color: var(--text-muted); cursor: help;
}
/* The glyph is small; the place to press is not. */
.dev-ws-fig-info::after { content: ''; position: absolute; inset: -12px; }
.dev-ws-fig-info svg { width: 16px; height: 16px; }
.dev-ws-fig-info:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
.dev-ws-fig-value {
  font-size: 22px; line-height: 28px; font-weight: 650; letter-spacing: -0.01em;
  color: var(--text-primary); white-space: normal; overflow-wrap: normal; word-break: keep-all;
}
.dev-ws-fig-value-muted { font-size: 15px; font-weight: 600; letter-spacing: 0; color: var(--text-muted); }
.dev-ws-fig-value-warn { color: var(--state-attention); }
.dev-ws-fig-value-warn > .dev-ws-fig-warn { width: 16px; height: 16px; margin: 0 4px 0 0; vertical-align: -1px; }
.dev-ws-fig-sub { display: inline-flex; align-items: flex-start; gap: 4px; font-size: 12px; line-height: 16px; color: var(--text-muted); }
.dev-ws-fig-sub-warn { font-weight: 600; color: var(--state-attention); }
.dev-ws-fig-warn { flex: none; width: 13px; height: 13px; margin-top: 1px; }
.dev-ws-fig-sides { display: flex; flex-direction: column; gap: 4px; align-self: stretch; margin: 4px 0 2px; }
.dev-ws-fig-side {
  display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between;
  column-gap: 8px; min-width: 0;
}
.dev-ws-fig-side-name { min-width: 0; font-size: 13px; line-height: 20px; color: var(--text-secondary); }
.dev-ws-fig-side-value {
  display: inline-flex; align-items: center; gap: 4px;
  font-size: 17px; line-height: 22px; font-weight: 650; white-space: nowrap;
  font-variant-numeric: tabular-nums; color: var(--text-primary);
}
.dev-ws-fig-side-value-muted { font-size: 13px; line-height: 20px; font-weight: 600; color: var(--text-muted); }
.dev-ws-fig-side-value-warn { color: var(--state-attention); }
.dev-ws-fig-side-value-warn .dev-ws-fig-warn { margin-top: 0; }
.dev-ws-fig-side-detail { flex-basis: 100%; font-size: 12px; line-height: 16px; color: var(--text-muted); }
/* The Homeroom bot's grid: a corner and the three column heads, then a row
   per group, its name first, and the rows a group runs on into under it. */
.dev-ws-figs-grid { grid-template-columns: 140px repeat(3, minmax(0, 1fr)); }
.dev-ws-figs-row { display: contents; }
.dev-ws-figs-corner,
.dev-ws-figs-colhead,
.dev-ws-figs-rowhead { background: var(--dc-sheet-solid); }
.dev-ws-figs-colhead { padding: 8px 16px 6px; font-size: 12px; line-height: 16px; font-weight: 700; color: var(--text-muted); }
.dev-ws-figs-rowhead { display: flex; flex-direction: column; justify-content: center; gap: 2px; padding: 12px 16px; }
.dev-ws-figs-rowname { font-size: 15px; line-height: 20px; font-weight: 650; color: var(--text-primary); }
.dev-ws-figs-rowabout { font-size: 12px; line-height: 16px; color: var(--text-muted); }
.dev-ws-figs-note { margin: 6px 4px 0; font-size: 12px; line-height: 16px; color: var(--text-muted); }
/* #5683: most of a strip's figures still waiting for enough people fold into
   one quiet sentence under "Last 30 days", with the ⓘ that explains them. */
.dev-ws-figs-folded {
  display: block; margin: 6px 4px 0;
  font-size: 13px; line-height: 18px; color: var(--text-muted);
}
@media (max-width: 767.98px) {
  /* #5683: the topic's line and the figures' lines keep the page's 16px
     gutter on a phone, as the room under them does. */
  .dev-ws-topic-head,
  .dev-ws-figs-head,
  .dev-ws-figs-note,
  .dev-ws-figs-folded { padding-inline-start: 12px; padding-inline-end: 12px; }
}
/* #5683: an empty topic channel invites the first post, centred, as the
   Messages app's empty states are; a viewer who cannot post reads the same
   block without the invitation. */
.gc-channel-empty {
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 4px; min-height: 240px; padding: 24px;
  text-align: center; color: var(--text-muted);
}
.gc-channel-empty-hash { font-size: 28px; line-height: 32px; font-weight: 700; color: var(--text-muted); }
.gc-channel-empty-title { font-size: 15px; line-height: 20px; font-weight: 650; color: var(--text-primary); }
.gc-channel-empty-about,
.gc-channel-empty-invite { margin: 0; font-size: 13px; line-height: 18px; }
@container (max-width: 560px) {
  .dev-ws-figs-tiles { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .dev-ws-figs-tiles > .dev-ws-fig:last-child:nth-child(odd) { grid-column: 1 / -1; }
  .dev-ws-fig { padding: 10px 12px 12px; }
  .dev-ws-fig-label { font-size: 12px; line-height: 16px; }
  .dev-ws-fig-value { font-size: 20px; line-height: 26px; }
  .dev-ws-fig-value-muted { font-size: 14px; }
  .dev-ws-figs-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .dev-ws-figs-corner { display: none; }
  .dev-ws-figs-colhead { padding: 8px 10px 6px; }
  .dev-ws-figs-rowhead { grid-column: 1 / -1; flex-direction: row; justify-content: flex-start; align-items: baseline; gap: 6px; padding: 8px 10px 4px; }
  .dev-ws-figs-rowhead-more { display: none; }
  .dev-ws-figs-rowname { font-size: 13px; line-height: 18px; }
  .dev-ws-figs-grid .dev-ws-fig { padding: 6px 10px 10px; }
  .dev-ws-figs-grid .dev-ws-fig-value { font-size: 18px; line-height: 24px; }
  .dev-ws-figs-grid .dev-ws-fig-sub { font-size: 11px; line-height: 15px; }
  .dev-ws-fig-side-name { font-size: 12px; line-height: 18px; }
  .dev-ws-fig-side-value { font-size: 15px; line-height: 20px; }
}
/* What a figure means: drawn on the body, under its glyph, so the card's
   rounded edge does not cut it off. */
.dev-ws-fig-tip {
  position: fixed; z-index: 60; box-sizing: border-box;
  padding: 10px 12px; border-radius: 12px;
  background: #ffffff;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.14), 0 0 0 1px var(--app-sheet-line);
  font-size: 13px; line-height: 18px; color: var(--text-secondary);
  pointer-events: none;
}
.dark .dev-ws-fig-tip { background: var(--dc-raised); box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5), 0 0 0 1px var(--app-sheet-line); }
@media (max-width: 767.98px) {
  .dev-ws-topic-channel.dev-ws-discussion-threaded > .dev-ws-figs { display: none; }
}
@media (min-width: 768px) {
  .dev-ws-topic-channel.dev-ws-discussion-threaded:has(> .dev-ws-figs) { grid-template-rows: auto auto minmax(0, 1fr); }
  .dev-ws-topic-channel.dev-ws-discussion-threaded > .dev-ws-figs { grid-column: 1 / -1; }
}
/* "Discuss in #name ›" at the foot of a topic's card in By category. */
.dev-ws-topic-link { display: inline-block; margin-top: 6px; font-size: 13px; font-weight: 600; }
/* AFTER A MERGE, A CARD MARKS IT (merged-topic-card.tsx): a row in the
   survivor's history where the merge applied, drawn like a date divider
   rather than a message: no author, no bubble, a hairline box on the room. */
.dev-ws-merged-card {
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  margin: 10px 12px; padding: 9px 12px; border-radius: 12px;
  border: 1px solid var(--messages-hair, var(--border-light));
  font-size: 13px; line-height: 18px; color: var(--text-muted);
}
.dev-ws-merged-card-text { min-width: 0; overflow-wrap: anywhere; }
.dev-ws-merged-card-link { flex-shrink: 0; color: var(--accent); font-weight: 600; text-decoration: none; }
.dev-ws-merged-card-link:hover { text-decoration: underline; }
/* The Topics dialog (features/dialogs/topics.tsx): a row's ⋯, and the three
   changes it offers, as a row of quiet pills under it. */
.topics-row-more {
  display: inline-flex; align-items: center; justify-content: center;
  width: 36px; height: 36px; flex-shrink: 0; border-radius: 999px;
  font-size: 18px; line-height: 1; color: var(--text-muted);
}
.topics-row-more:hover, .topics-row-more[aria-expanded="true"] { background: var(--bg-secondary); }
.topics-row-actions { display: flex; flex-wrap: wrap; gap: 6px; padding-block: 0 12px; padding-inline: 64px 16px; }
.topics-row-actions > button {
  min-height: 32px; padding: 0 12px; border-radius: 999px;
  font-size: 13px; font-weight: 600;
  background: var(--bg-secondary); color: var(--text-primary);
}
.topics-into {
  width: 100%; min-height: 40px; padding: 0 10px; border-radius: 10px;
  border: 1px solid var(--border-light); background: transparent;
  font-size: 15px; color: var(--text-primary);
}

/* ── The ask pane, the sheet's Ask tab ─────────────────────────────── */
.dev-ws-ask { display: flex; flex-direction: column; gap: 8px; }
.dev-ws-ask-private { margin: 8px 0 0; font-size: 12.5px; line-height: 1.35; color: var(--text-muted); }
.dev-ws-ask-log {
  flex: 1 1 auto; min-height: 0; overflow-y: auto;
  display: flex; flex-direction: column; gap: 8px; padding: 6px 0 2px;
}
.dev-ws-ask-hint { margin: 0; font-size: 13px; color: var(--text-muted); font-style: italic; }
.dev-ws-ask-msg {
  margin: 0; max-width: 88%; padding: 9px 13px; border-radius: 17px;
  font-size: 15px; line-height: 1.36; white-space: pre-wrap;
}
.dev-ws-ask-you { align-self: flex-end; background: var(--accent); color: #fff; border-end-end-radius: 6px; }
.dev-ws-ask-ai { align-self: flex-start; background: var(--bg-secondary); color: var(--text-primary); border-end-start-radius: 6px; }
/* The answer on its way: a breathing bubble, still while it grows. */
.dev-ws-ask-pending {
  color: var(--text-muted);
  animation: dev-ws-ask-breathe 1.6s ease-in-out infinite;
}
@keyframes dev-ws-ask-breathe { 0%, 100% { opacity: 1; } 50% { opacity: 0.55; } }
@media (prefers-reduced-motion: reduce) {
  .dev-ws-ask-pending { animation: none; }
}
/* Reduce motion setting (#6510): the same, when Settings asks for it. */
:where(html[data-motion="reduce"]) .dev-ws-ask-pending { animation: none; }
.dev-ws-ask-failed { color: var(--state-blocked); background: var(--state-blocked-bg); }
/* THE COMPOSER is a card padded evenly, so its resting line sits on its
   own middle. */
.dev-ws-ask-composer { display: flex; flex-direction: column; gap: 6px; padding: 12px 14px; flex: none; }
.dev-ws-ask-line { display: flex; align-items: center; gap: 8px; min-width: 0; }
.dev-ws-ask-line > .dev-ws-ask-input { flex: 1 1 auto; }
.dev-ws-ask-input {
  min-width: 0; border: 0; background: none; padding: 6px 0;
  font: inherit; font-size: 16px; color: var(--text-primary);
}
.dev-ws-ask-input:focus { outline: none; }
.dev-ws-ask-input::placeholder { color: var(--text-muted); }
.dev-ws-ask-row { display: flex; align-items: center; gap: 8px; min-width: 0; }
.dev-ws-ask-row > .dev-ws-ask-send { margin-inline-start: auto; }
.dev-ws-ask-model { display: flex; align-items: center; gap: 3px; min-width: 0; max-width: 100%; }
.dev-ws-ask-model > select { min-width: 0; max-width: 100%; flex: 0 1 auto; }
.dev-ws-ask-model-chev { flex: none; width: 14px; height: 14px; color: var(--text-muted); }
.dev-ws-ask-send { width: 34px; height: 34px; }
.dev-ws-ask-send-icon { width: 17px; height: 17px; }
.dev-ws-ask-send:disabled { opacity: .45; cursor: default; }

/* ── The end of the feed ──────────────────────────────────────────────
   One card past the last item, always (#2172): the same snap slot as an
   item, in the page's own scheme rather than the reels' dark, so the swipe
   that lands here reads as arriving somewhere rather than as one more
   decision. On top, a note when your Yes met a change's rule; under it the
   card itself, in the plane colour with one hairline: the tick, the
   headline, what the pass did, and the buttons at its foot. */
.dev-ws-needs-done {
  gap: 8px; padding: 0;
  background-color: transparent;
}
.dev-ws-done-over {
  flex: none; display: flex; align-items: flex-start; gap: 10px;
  padding: 12px 14px; border-radius: 18px;
  background-color: var(--dc-sheet-solid);
  box-shadow: inset 0 0 0 1px var(--app-sheet-line), 0 6px 20px rgba(0, 0, 0, .08);
}
.dev-ws-done-over-ic {
  flex: none; width: 28px; height: 28px; border-radius: 9999px;
  display: grid; place-items: center;
  background: var(--state-ok-bg); color: var(--state-ok);
}
.dev-ws-done-over-ic > svg { width: 16px; height: 16px; }
.dev-ws-done-over-text { min-width: 0; display: flex; flex-direction: column; gap: 1px; }
.dev-ws-done-over-line { font-size: 15px; font-weight: 650; line-height: 1.3; color: var(--text-primary); }
.dev-ws-done-over-sub { font-size: 13px; line-height: 1.35; color: var(--text-muted); }
.dev-ws-done-body {
  flex: 1 1 auto; min-height: 0; box-sizing: border-box; overflow-y: auto;
  display: flex; flex-direction: column; align-items: center; gap: 8px;
  padding: 26px 18px 16px; border-radius: 22px; text-align: center;
  background-color: var(--dc-sheet-solid);
  box-shadow: inset 0 0 0 1px var(--app-sheet-line);
}
.dev-ws-done-tick {
  flex: none; width: 56px; height: 56px; border-radius: 18px;
  display: grid; place-items: center;
  background: var(--state-ok-bg); color: var(--state-ok);
}
.dev-ws-done-tick > svg { width: 28px; height: 28px; }
.dev-ws-needs-done-line { margin: 0; font-size: 24px; font-weight: 800; letter-spacing: -.02em; color: var(--text-primary); }
.dev-ws-needs-done-sub { margin: 0; max-width: 34ch; font-size: 15px; line-height: 1.4; color: var(--text-secondary); }
/* What your votes did: a row each, its title cut short beside its status. */
.dev-ws-done-did { align-self: stretch; display: flex; flex-direction: column; margin-top: 10px; text-align: start; }
.dev-ws-done-did-head { margin: 0 0 2px; font-size: 13px; font-weight: 650; color: var(--text-primary); }
.dev-ws-done-did-list { list-style: none; margin: 0; padding: 0; }
.dev-ws-done-did-row { display: flex; align-items: center; gap: 10px; padding: 10px 0; }
.dev-ws-done-did-row + .dev-ws-done-did-row { border-top: 1px solid var(--app-sheet-line); }
.dev-ws-done-did-title {
  flex: 1 1 auto; min-width: 0;
  font-size: 15px; font-weight: 600; line-height: 1.3; color: var(--text-primary);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.dev-ws-done-status {
  flex: none; display: inline-flex; align-items: center; gap: 4px; height: 22px; padding: 0 8px;
  border-radius: 9999px; font-size: 12px; font-weight: 600; white-space: nowrap;
  background: var(--state-neutral-bg); color: var(--text-secondary);
}
.dev-ws-done-status-ok { background: var(--state-ok-bg); color: var(--state-ok); }
.dev-ws-done-status-progress { background: var(--accent-tint); color: var(--accent-wash-ink); }
.dev-ws-done-status-blocked { background: var(--state-blocked-bg); color: var(--state-blocked); }
.dev-ws-done-status-ic { width: 12px; height: 12px; flex: none; }
.dev-ws-done-actions { align-self: stretch; display: flex; gap: 8px; margin-top: auto; padding-top: 14px; }
.dev-ws-done-cta, .dev-ws-done-hub {
  flex: 1 1 0; min-width: 0; height: 46px; padding: 0 14px; border: 0; border-radius: 9999px; cursor: pointer;
  font: inherit; font-size: 15px; font-weight: 650;
}
.dev-ws-done-cta { background: var(--accent); color: #fff; }
.dev-ws-done-hub { background: var(--dc-sheet); color: var(--text-primary); box-shadow: inset 0 0 0 1px var(--border); }
/* The way back to what was passed over: a quiet action under the two,
   drawn only when there is something above to go back to. */
.dev-ws-done-back {
  flex: none; height: 40px; padding: 0 16px; border: 0; border-radius: 9999px; cursor: pointer;
  font: inherit; font-size: 14px; font-weight: 600;
  background: transparent; color: var(--accent);
}
.dev-ws-done-back:hover { background: var(--accent-wash); }

/* ── The deck at the top, on a wide screen ───────────────────
   On a phone the deck fills the reading area and the answers sit at the
   floor, which is where the thumb is. On a desktop that same rule spends
   half a 900px window on the gap between a two-line summary and three
   buttons, and empty space that large reads as something failing to render
   rather than as breathing room.

   So above 700px the deck is content-sized and sits at the top: the
   question and its answers follow the card immediately. The tab rail is
   unaffected — it is pushed to the foot of the lander by `margin-top:
   auto`, not by the deck's height. The ask log takes a cap instead of a
   fraction of the screen for the same reason. */
@media (min-width: 700px) {

  /* ── A wide window reads the tabs at the TOP, as a segmented control ───
     A pill pinned to the floor of a 900px window puts the switch as far from
     the reading as the window allows, and the eye crosses the whole height to
     use it — a phone convention wearing a desktop out. Above 700px the bar
     comes off the floor and sits at the head of the column.

     `order: 0` is the move that gets it there. The nav is already first in the
     DOM, so dropping the phone's `order: 1` paints it where it is written —
     and on the width where a keyboard is likeliest, focus order and reading
     order agree.

     WHAT IT IS NOT, ANY MORE: three underlined words. That shape separates by
     RULE, and this product separates by FIGURE AND GROUND — the distinction
     @/components/ui/tabs.tsx spells out where it retired the same underline
     from the Leaderboard's own strip. An underlined row is also the idiom of
     code-hosting tools and admin consoles, which is what it read as here: a
     developer surface bolted to a consumer one. The geometry below is
     SECTION_TABS_LIST / SECTION_TAB_BASE transcribed — 2px track, 32px
     segments, 16px of side padding, fully round.

     THE SELECTED STATE IS NOT RESTATED HERE, deliberately. The phone rule's
     periwinkle carries straight through, so the two widths are one control at
     two sizes rather than two ideas: the note beside it explains why that is
     the tint and not the primitive's near-black, and nothing about a wider
     window changes that argument.

     The track is `--dc-sheet-raise` and carries no frost. Frost is for the
     phone's bar, which floats over what scrolls beneath it; this one sits in
     the flow with nothing passing behind, so it wants the opaque raised
     surface the cards already use — the same reason tabs.tsx's track is white
     rather than the recessed grey a control gets on a card. */

  /* #3583: WHERE THE BAND PINS, which is the header's foot, and how far that
     is from the top of whatever scrolls the page.

     On a computer, and in the installed app and the native WebView, that is
     #dev-forum-scroll, and the header's foot overlaps its top edge by 7px
     (the header's `-mb-2`, 8px, less `.dc-lift`'s 1px hairline). The strip
     pinned at 0 rose into the header by that much, and at z-index 30 over
     the header's 10 its band painted there: a white slab biting the
     coloured header, which is half of what #3583's screenshot shows.

     Where the DOCUMENT scrolls instead (a tablet in its browser, a window
     under 768px: lib/browser-scroll.ts) the scrollport is the whole window
     and the header is sticky over it, so 0 was the top of the SCREEN: the
     strip pinned there drew straight over the header and hid it. There it
     is the header's own height, as everything else that sticks under the
     header in that mode is measured. */
  #dev-workshop { --ws-pin-top: var(--dev-ws-head-foot, 7px); }
  html[data-browser-scroller="dev-forum-scroll"] #dev-workshop {
    --ws-pin-top: calc(var(--browser-banner-h) + var(--platform-header-h) + var(--platform-safe-top));
  }
  /* Under 768px the strip is still the coloured band, tucked 18px up under
     the header's foot, so it rests 15px above the foot (that tuck, less
     #dev-body's 10px, plus the 7px the foot overlaps the page), and it pins
     exactly there, the way a phone's does (#3522): it never moves, and its
     tabs never drop. */
  @media (max-width: 767.98px) {
    .dev-ws-tabs.dev-ws-band { top: calc(var(--ws-pin-top, 0px) - 15px); }
  }

  /* EVERYTHING PINS UP HERE, as one band: the project's tabs and, on All
     items, the head under them, with the grouping, the search and the
     filters. The controls belong WITH the list you are
     narrowing, so they stay reachable however far down it you are.

     ALL ITEMS HAS NO BACK BAR OF ITS OWN (#4486). It was a second
     `.dev-ws-tabs` box (#3651), which the strip's rule below made sticky at
     the tabs' own offset, so two bars pinned in one place; then it scrolled
     away under the tabs. The way back and the page's name are the first
     things in the head's one row now (workshop.tsx `.dev-ws-allbar`), which
     pins here with the rest of the head. The tabs are the bar the head and
     its band are measured against on every page (workshop.tsx, `setBar`).

     THE HEAD KEEPS THE BASE RULE'S `position: sticky` and only changes where
     it comes to rest: under the pinned strip, at the strip's measured height
     plus the column gap, counted from where the strip pins (`--ws-pin-top`,
     #3583). `top: 0` would slide it under the strip.

     ABOVE THE STRIP IN PAINT ORDER at rest. The grouping tabs used to hang
     from the head into the strip's band as an "ear" (gone with #852), which
     is where the 31 came from; it is kept so the head and the strip keep the
     one order the "+" menu's rule below is written against.

     Scoped by `#dev-workshop`: the base rule is `.dev-ws-pane-head` six
     hundred lines BELOW this block, and on equal specificity the later one
     wins — a bare-class override here would apply to nothing. */
  #dev-workshop .dev-ws-pane-head {
    top: calc(var(--ws-pin-top, 0px) + var(--dev-ws-head-top, 0px));
    z-index: 31;
  }
  /* In the tablet window between 700px and the wide layout, as on a phone
     (#4703): the band is its 18px tuck, the row it held gone into the
     header, so the head rests on the band's foot: where the band pins, plus
     its 18px. */
  @media (max-width: 767.98px) {
    #dev-workshop .dev-ws-pane-head { top: calc(var(--ws-pin-top, 0px) - 15px + 18px); }
  }
  .dev-ws-tabs {
    order: 0;
    /* RELATIVE, NOT STATIC. There is nothing to stick to at the head of a
       column — that part is unchanged — but the bar has to remain the
       CONTAINING BLOCK for the selection marker, and the element `offsetLeft`
       and `offsetTop` resolve against when workshop.tsx measures a tab.
       `static` would send both the marker and the measurement to whatever
       ancestor happened to be positioned. */
    /* STICKY, NOT MERELY RELATIVE. Relative kept the containing block the
       selection marker and `offsetLeft` need, which is all this rule used to
       want; pinning needs the same thing and keeps it, since a sticky element
       is positioned too. The offset itself is set BELOW `inset: auto`, which
       would otherwise reset it — see the note on it. */
    position: sticky;
    /* THE PHONE BAR'S OFFSETS ARE NOT THIS BAR'S, and leaving them in place
       is what made the strip sit crooked in both axes.

       `left: 10px; right: 10px; bottom: var(--ws-lift)` size and place a
       FIXED pill against the viewport. `position: relative` does not ignore
       them — it SHIFTS the element by them — so the strip was displaced 10px
       right of the reading column it is supposed to line up with, and lifted
       `--ws-lift` (8px) off its own place in the flow. Measured at 1280px
       wide: 2px of air above the strip and 18px below, against the 10 and 10
       the two rules below actually declare. Every fix aimed at that air had
       been aimed at the wrong pair of numbers.

       `max-width` and `margin-inline` leak the same way and cost the
       alignment below: 740px with auto side margins is a shrink-to-fit box
       centred in the column, and a row cannot be left-aligned inside a box
       that has already centred itself. The board pane re-states both at
       higher specificity (`#dev-workshop.dev-ws-has-board > .dev-ws > …`),
       which is the one place they are wanted up here. */
    inset: auto;
    /* AFTER `inset: auto`, and that ordering is the whole of it. Written
       above, `top: 0` was reset to `auto` by the shorthand three lines later:
       the strip stayed `sticky`, pinned to nothing, and scrolled away while
       the head it is supposed to travel with stayed. Measured — the strip's
       top went to -890 on a 900px scroll. It was `top: 0`, the scroller's
       own top, on the reasoning that there was no chrome inside it to clear;
       there is, the header's foot (#3583, `--ws-pin-top` above). */
    top: var(--ws-pin-top, 0px);
    /* QA 2026-09-24 Q7: ABOVE THE CARDS, BELOW THE HEAD. Pinned with no
       z-index, the strip sat at the floor of the stacking order, and the
       pane and its cards come later in the tree, so everything that scrolled up past it painted over
       the tabs and took their clicks: the three tabs and the "+" went under
       the list. 30 puts it over the list and under the pane head's 31. The
       open "+" menu still lifts the strip to 32 (above). */
    z-index: 30;
    max-width: none;
    /* LEFT-ALIGNED, not centred. The pill is `.dev-ws-tabtrack` inside this
       nav and it is content-width, so whatever positions the pill is what
       decides where the strip appears — and the nav now spans the same
       reading column the pane below it does, so `flex-start` puts the strip's
       left edge on the pane's left edge. Centring put it on the WINDOW's
       centre line, which belongs to nothing on the screen: the strip drifted
       right as the column widened and lined up with no edge at any width.
       `flex` rather than `text-align: center`, because an inline-level box
       positioned by an INHERITED property is one stray `text-align` on any
       ancestor away from moving on its own.

       IT ALSO SETTLES THE SELECTION MARKER. The marker is placed from
       `offsetLeft` against this nav (see workshop.tsx), and under
       `justify-content: center` that number is `(nav - pill) / 2` plus the
       tab's own offset — so it MOVED whenever the nav's width did, while the
       tab stayed exactly where it was on screen. Switching By category →
       By stage widens the nav from the pill's width to the full 760 and the
       marker's coordinate jumped 158px for a tab that had not moved a pixel,
       which the transition then animated. Against `flex-start` the pill sits
       at offset 0 and the number is the tab's own, whatever the nav's width.
       (workshop.tsx no longer animates a re-measure either; this is the half
       that stops the coordinate changing in the first place.) */
    display: flex;
    justify-content: flex-start;
    gap: 0; padding: 0;
    border: 0; border-radius: 0;
    background: none; backdrop-filter: none; -webkit-backdrop-filter: none;
    /* NO MARGIN OF ITS OWN. `.dev-ws` is a flex column with `gap: 10px`, so a
       margin here stacks on top of it: 14px below the strip against the 8px
       of `#dev-body` padding above it, which is the unbalanced air. The gap
       alone sets both sides, once the padding below matches it. `margin: 0`
       rather than `margin-bottom: 0` because the side halves are the phone
       rule's `margin-inline: auto`, retired with the rest of its box above. */
    margin: 0;
  }
  /* The other half of that balance: 10px above, to equal the column gap
     below. The 8px here is the phone's, where the strip is `position: fixed`
     at the foot and this padding is just the top of the page.
     Both numbers are finally what lands: with the leaked `bottom` gone the
     strip no longer floats 8px up out of the air it was given, which is the
     "too little above, too much below" this pair always claimed to prevent. */
  #dev-body:has(> #dev-workshop) { padding-top: 10px; }
  /* QA 2026-09-24 Q7: THE BAND BEHIND THE PINNED STRIP. With the strip on top
     of the list, the pill itself is opaque, but the air around it was not:
     the column gap down to the pane head and, on By stage, the board columns either side of the reading column all showed
     the cards scrolling underneath, between the controls. So once the strip
     is pinned (`data-ws-pinned`, set by workshop.tsx's usePinnedStrip) a
     band runs behind it, from the scroller's top down to where the head pins
     (`--dev-ws-head-top`) and across the PANE's width (`--dev-ws-band-*`,
     measured by useStripInsets), and the strip and the head read as one
     pinned header.

     SOLID, NOT FROSTED. The frost cannot blur anything here: this whole
     column sits inside the dev frame's `.dc-lift`, which has a
     backdrop-filter of its own, and Chromium does not blur content through
     a backdrop-filter nested inside another one. What was left was 50%
     white, which is exactly the "cards showing through" this fixes (and
     why the search row looked washed rather than frosted over the list).
     So while pinned the band takes the pane's own opaque colour, the one
     its head and body already wear (`--dc-sheet-solid`, the fallback below
     the frost rules).

     THE PANE'S COLOUR, NOT `--dc-sheet` (#3651). The band and the pinned
     head used to switch to `--dc-sheet`, which is white where the pane is
     the warm `--dc-sheet-solid`: the head changed colour the moment it
     pinned, and a white slab sat over a cream pane, its edge reading as a
     gap down both sides and along the foot. The head keeps its colour now
     and the band matches it, so pinned and at rest are one material.

     ONLY WHILE PINNED. At rest the bar sits on the page, and a band there
     would draw a slab of sheet colour around it for nothing.

     Behind the nav's own content (`z-index: -1` inside the strip's stacking
     context), so the bar draws over it. The pinned head squares its top
     corners (`data-ws-head-pinned`, below the pane's base rule). */
  /* direction: physical — this band is MEASURED, not laid out. Its two
     offsets are `pane.left - bar.left` and `bar.right - pane.right`, read
     from the live rects by usePinnedStrip (workshop.tsx), so they are
     physical distances to the pane's own edges and mean the same thing in
     Arabic. Mirroring them would reach the wrong way. */
  .dev-ws-tabs::before {
    content: '';
    position: absolute;
    z-index: -1;
    top: 0;
    height: var(--dev-ws-head-top, calc(100% + 10px));
    left: var(--dev-ws-band-left, 0px);
    right: var(--dev-ws-band-right, 0px);
    background-color: var(--dc-sheet-solid);
    pointer-events: none;
    visibility: hidden;
  }
  /* direction: logical */
  .dev-ws[data-ws-pinned] > .dev-ws-tabs::before { visibility: visible; }
  /* THE TRACK HOLDS THE PILL AND THE "+", 6px apart, and draws neither
     (#2934): it hugs the two. The surface is the phone rule's two items at
     this width's metrics — a 2px ring in the raised sheet, no hairline — so
     the pill is 36px as the track was, and the "+" a 36px circle beside it. */
  .dev-ws-tabtrack {
    display: inline-flex; align-items: center; gap: 6px;
  }
  .dev-ws-tablist, .dev-ws-tabtrack > .dev-ws-plus {
    padding: 2px;
    border: 0;
    border-radius: 9999px;
    background-color: var(--dc-sheet-raise);
  }
  .dev-ws-tab {
    flex: 0 0 auto; flex-direction: row; gap: 7px;
    height: 32px; padding: 0 16px;
    border-radius: 9999px; font-size: 14px;
  }
  .dev-ws-tab-glyph { width: 16px; height: 16px; }
  /* #2915: the dot follows the label here, a little further off it than the
     tab's own gap, and centred on it. */
  .dev-ws-tab-dot { order: 0; margin-block: 0 0; margin-inline: 6px 0; transform: none; }
  /* The tab list hugs its three segments, and the "+" is the track's last
     item: a 32px round button, the tabs' own height, in its own circle after
     the pill — Current status · Needs you · All items   +. */
  .dev-ws-tablist { flex: 0 0 auto; }
  .dev-ws-plus-btn { width: 32px; height: 32px; }
  .dev-ws-plus-glyph { width: 18px; height: 18px; }

  /* ── THE FEED ON A WIDE WINDOW: THE STAGE ──
     Above 700px the lander is a ROW: the reel as a 440px card at the
     centre, the rail standing beside it on the page, its buttons at the
     card's foot, and the arrows to the rail's right doing what the wheel
     does. Comments and Ask are a PANEL to the right, with the card's caption
     repeated at its top while the card keeps only its by-line, so the
     picture stays in view while you use it; the vote is a popover on its own
     button. The Workshop column widens past its 760px reading measure for
     this tab alone — the same release the Board pane has. */
  #dev-workshop.dev-ws-on-needs { max-width: none; }
  /* The tab strip keeps the reading column while the stage takes the window
     (the same re-statement the board pane makes for itself below): a
     left-aligned strip inside a 1440px nav would sit at the window's edge,
     lined up with nothing, while the card it belongs to sits at the centre. */
  #dev-workshop.dev-ws-on-needs > .dev-ws[data-ws-tab="needs"] > :not(.dev-ws-tabbody) {
    width: 100%; max-width: 760px; margin-inline-start: auto; margin-inline-end: auto;
  }
  /* `place-content`, not `justify-content: center`, here and on the key
     legend below: on a single-line row the two are the same centring, and the
     wide block is held to never spelling the latter (the tab strip's test)
     because a centred STRIP moved the selection marker; a centred stage
     moves nothing. */
  .dev-ws-needs {
    flex-direction: row; place-content: center; align-items: stretch;
    gap: 18px; min-height: 480px;
    /* A line of its own under the stage for the key legend, so the legend
       never lies across the card's caption or the arrows beside the rail. */
    padding-bottom: 34px;
  }
  /* The stage takes the card's width, so the strip above it is as wide as
     the card and not as wide as the rail beside it. The scroller fills the
     stage (its base rule is already `flex: 1 1 auto; min-height: 0`). */
  .dev-ws-needs-stage { flex: 0 1 440px; max-width: 440px; }
  .dev-ws-needs-scroll { border-radius: 20px; }
  .dev-ws-needs-progress { margin: 0 4px 8px; }
  .dev-ws-item-top { margin: 26px 16px 0; }
  .dev-ws-item-caption { inset-inline-start: 18px; inset-inline-end: 18px; bottom: 20px; gap: 8px; }
  /* #5039: beside the card, the caption below a diagram needs no rail lane. */
  .dev-ws-item:not([data-ws-open]):has(> .dev-ws-diagram) > .dev-ws-item-caption { margin: 12px 18px 20px; }
  .dev-ws-item-avatar { width: 32px; height: 32px; font-size: 13px; }
  .dev-ws-item-by b { font-size: 15px; }
  .dev-ws-item-title { font-size: 21px; line-height: 1.2; }
  .dev-ws-item-summary-text { font-size: 15px; }
  .dev-ws-item[data-ws-picture="none"] > .dev-ws-item-caption { top: 64px; }
  .dev-ws-item[data-ws-picture="none"] .dev-ws-item-title { font-size: 26px; line-height: 1.18; }
  .dev-ws-item[data-ws-picture="none"] .dev-ws-item-summary-text { font-size: 17px; -webkit-line-clamp: 10; }
  /* The facts: the vote's words are the pill, the topic follows it. */
  .dev-ws-item-caption > .dev-ws-item-facts { padding: 0; border-radius: 0; background: none; font-size: 12.5px; line-height: 26px; color: var(--text-muted); }
  .dev-ws-item-caption .dev-ws-item-facts-vote { display: inline-block; padding: 0 10px; border-radius: 9999px; background: var(--state-neutral-bg); color: var(--text-primary); }
  .dev-ws-item-caption .dev-ws-item-facts-vote + .dev-ws-fact { margin-inline-start: 8px; }
  .dev-ws-item-caption .dev-ws-item-facts-vote + .dev-ws-fact::before { content: none; }
  .dev-ws-media-bar { margin: 0 16px 8px; }
  .dev-ws-item > .dev-ws-diagram { padding: 0 32px 16px; gap: 16px; }
  .dev-ws-item > .dev-ws-touches .dev-ws-diagram-what { font-size: 15px; font-weight: 650; }
  .dev-ws-item > .dev-ws-touches .dev-ws-diagram-bar { height: 10px; }
  /* With the panel up the card keeps its picture and its by-line: the rest
     of the caption is at the panel's top. */
  .dev-ws-needs:is([data-ws-sheet="comments"], [data-ws-sheet="ask"]) .dev-ws-item-caption > :not(.dev-ws-item-by) { display: none; }
  .dev-ws-needs:is([data-ws-sheet="comments"], [data-ws-sheet="ask"]) .dev-ws-item-scrim { height: 180px; }
  .dev-ws-needs:is([data-ws-sheet="comments"], [data-ws-sheet="ask"]) .dev-ws-item[data-ws-picture="none"] > .dev-ws-item-caption { top: auto; }
  .dev-ws-needs:is([data-ws-sheet="comments"], [data-ws-sheet="ask"]) .dev-ws-needs-stage { flex-basis: 400px; }
  .dev-ws-rail {
    position: relative; inset-inline-end: auto; bottom: auto; z-index: auto;
    flex: 0 0 64px; justify-content: flex-end; padding-bottom: 20px; gap: 16px;
  }
  .dev-ws-rail-btn { width: 64px; }
  .dev-ws-rail-ic { width: 48px; height: 48px; }
  .dev-ws-rail-lab { font-size: 12.5px; color: var(--text-secondary); text-shadow: none; }
  .dev-ws-rail-vote .dev-ws-rail-ic { width: 52px; height: 52px; box-shadow: 0 4px 12px rgba(10, 110, 224, .3); }
  .dev-ws-rail-vote .dev-ws-rail-lab { color: var(--accent); }
  .dev-ws-rail-vote.is-on .dev-ws-rail-lab { color: var(--state-ok); }
  .dev-ws-rail-vote.is-on[data-ws-voted="no"] .dev-ws-rail-lab { color: var(--state-blocked); }
  /* The arrows: a column of their own to the rail's right, at the stage's
     middle, out of the row's centring. Gone while the panel is up. */
  .dev-ws-move {
    position: absolute; inset-inline-start: calc(100% + 12px); top: 50%; transform: translateY(-50%);
    display: flex; flex-direction: column; align-items: center; gap: 10px;
  }
  .dev-ws-needs:is([data-ws-sheet="comments"], [data-ws-sheet="ask"]) .dev-ws-move { display: none; }
  .dev-ws-move-btn {
    width: 42px; height: 42px; border-radius: 9999px; cursor: pointer;
    border: 0; background: var(--state-neutral-bg); color: var(--text-primary);
    display: grid; place-items: center;
  }
  .dev-ws-move-btn:disabled { opacity: .35; cursor: default; }
  .dev-ws-move-icon { width: 18px; height: 18px; }
  .dev-ws-keys {
    display: flex; place-content: center; align-items: center; gap: 8px 12px;
    position: absolute; inset-inline-start: 0; inset-inline-end: 0; bottom: 0; height: 34px; margin: 0;
    white-space: nowrap;
    font-size: 13px; color: var(--text-muted); font-family: ui-monospace, Menlo, monospace;
  }
  .dev-ws-keys kbd {
    display: inline-grid; place-items: center; min-width: 20px; height: 22px; box-sizing: border-box; padding: 0 4px; margin: 0 2px; border-radius: 5px;
    border: 1px solid var(--border); background: var(--dc-sheet); color: var(--text-primary);
    font: inherit; font-size: 11px; font-weight: 600;
  }
  /* THE PANEL: Comments and Ask beside the rail, the stage's full height, in
     the plane colour with one hairline. It slides in from the right rather
     than rising from a floor it does not sit on (the names feed the base
     block's one animation rule). Its head is the card's caption again —
     who, the title, the description in full and the facts — and scrolls on
     its own if it runs long; under it the tabs, then the tab's body. */
  .dev-ws-sheet-talk {
    position: relative; inset: auto; flex: 0 1 380px; min-width: 300px; z-index: auto;
    display: flex; flex-direction: column;
    --ws-sheet-in: dev-ws-panel-in; --ws-sheet-out: dev-ws-panel-out;
  }
  .dev-ws-sheet-talk > .dev-ws-scrim { display: none; }
  .dev-ws-sheet-talk > .dev-ws-sheet-card {
    flex: 1 1 auto; height: auto; max-height: none; min-height: 0;
    padding: 0 0 12px;
    border-radius: 20px;
    background-color: var(--dc-sheet-solid);
    box-shadow: inset 0 0 0 1px var(--app-sheet-line), 0 8px 24px rgba(0, 0, 0, .06);
  }
  .dev-ws-talk-head {
    display: flex; flex-direction: column; gap: 8px; flex: 0 1 auto; max-height: 45%; overflow-y: auto;
    padding-block: 16px 14px; padding-inline: 18px 52px; border-bottom: 1px solid var(--border-light);
  }
  .dev-ws-talk-head .dev-ws-item-avatar { width: 28px; height: 28px; font-size: 12px; }
  .dev-ws-talk-head .dev-ws-item-by b { font-size: 14px; font-weight: 650; }
  .dev-ws-talk-title { margin: 0; font-size: 17px; font-weight: 750; line-height: 1.25; color: var(--text-primary); }
  .dev-ws-talk-words { margin: 0; font-size: 14px; line-height: 1.45; color: var(--text-secondary); white-space: pre-line; overflow-wrap: anywhere; }
  .dev-ws-talk-words > * { margin: 0 0 8px; }
  .dev-ws-talk-words > :last-child { margin-bottom: 0; }
  .dev-ws-talk-head .dev-ws-item-facts { background: var(--state-neutral-bg); color: var(--text-secondary); }
  .dev-ws-talk-tabs { position: static; justify-content: flex-start; padding: 0 18px; }
  .dev-ws-talk-tablist { gap: 22px; }
  .dev-ws-talk-tab { height: 42px; font-size: 14.5px; }
  .dev-ws-talk-tabs > .dev-ws-sheet-x { inset-inline-end: 12px; top: 12px; }
  .dev-ws-talk > .dev-ws-sheet-body { padding: 4px 18px 0; }
  .dev-ws-talk > .dev-ws-sheet-body > .dev-feed-thread > form { background-color: var(--dc-sheet-solid); }
  .dev-ws-talk > .dev-ws-ask { padding: 0 18px; }
  .dev-ws-sheet-handle { display: none; }
  /* The vote: a popover on its button, arrow towards it. The button's top in
     the rail is measured (`--ws-vote-top`, workshop.tsx), because the rail's
     buttons sit at its foot. */
  .dev-ws-sheet-vote { position: absolute; inset: auto calc(100% + 12px) auto auto; top: calc(var(--ws-vote-top, 0px) - 8px); width: 340px; z-index: 6; display: block; }
  .dev-ws-sheet-vote { --ws-sheet-in: dev-ws-pop-in; --ws-sheet-out: dev-ws-pop-out; }
  .dev-ws-sheet-vote > .dev-ws-scrim { position: fixed; background: transparent; }
  .dev-ws-sheet-vote > .dev-ws-sheet-card {
    max-height: none; overflow: visible; padding: 18px 18px 16px;
    border-radius: 18px; border: 1px solid var(--app-sheet-line);
    box-shadow: 0 18px 50px rgba(24, 39, 75, .22);
  }
  .dev-ws-sheet-vote > .dev-ws-sheet-card::after {
    content: ""; position: absolute; inset-inline-end: -8px; top: 24px; width: 16px; height: 16px;
    background: var(--dc-sheet); border-inline-end: 1px solid var(--app-sheet-line); border-top: 1px solid var(--app-sheet-line);
    transform: rotate(45deg);
  }
  .dev-ws-ask-q { font-size: 18px; }
  .dev-ws-vote-sub { font-size: 13px; }
  .dev-ws-answer-btn { height: 46px; font-size: 15px; border-radius: 12px; }
  .dev-ws-keys-hint { display: block; align-self: center; margin: 4px 0 0; font-size: 11px; color: var(--text-faint); font-family: ui-monospace, Menlo, monospace; }
  .dev-ws-ask-msg { font-size: 14px; }
  .dev-ws-ask-log { max-height: none; }
  /* #5820: from the wide layout up the All items chips say their words beside
     their glyphs — the same job the tooltip and the aria-label still do on a
     phone. Two classes so this beats Tailwind's `.sr-only`, which loads after
     this file; below 700px the word stays visually hidden but present, so the
     declared checks that read innerText pass at every width. */
  .sr-only.dev-chip-word {
    position: static; width: auto; height: auto; margin: 0; padding: 0;
    overflow: visible; clip: auto; white-space: nowrap;
  }
  /* The count is part of the word up here ("Filters (2)"), so the separate
     number beside the glyph would say it twice. */
  .dev-chip-count { display: none; }
}

/* Between the breakpoint and a wide desktop the panel would push the card
   off the stage, so it OVERLAYS the stage's right side instead. */
@media (min-width: 700px) and (max-width: 1179.98px) {
  .dev-ws-sheet-talk {
    position: absolute; inset-inline-end: 0; top: 0; bottom: 34px; width: min(380px, 60%); z-index: 8;
  }
}
.dev-ws-reveal[aria-expanded="true"] .dev-ws-reveal-chev { transform: rotate(180deg); }
/* A note under a list: the since list's "nothing has changed" and its
   floor, and the hub's quiet lines. Held off what it follows by its own
   margin. */
.dev-ws-week-note {
  margin: 11px 0 0; font-size: 12px; color: var(--text-muted); text-align: center;
}
/* ── One offer at a time, paged sideways ───────────────────────
   The track is the scroller and each item is exactly its width, so a swipe
   lands on a card rather than between two. `scroll-snap-type: x mandatory`
   and not `proximity`: a half-scrolled pair is the state this layout exists
   to prevent.

   `align-items: flex-start` matters more than it looks: a row UNFOLDS into
   the full card in place, so one item in the track can be several times the
   height of its neighbours, and stretched items would make every card as
   tall as the tallest. */
.dev-ws-pager { display: flex; flex-direction: column; gap: 6px; }
.dev-ws-pager-track {
  display: flex;
  align-items: flex-start;
  overflow-x: auto;
  overscroll-behavior-x: contain;
  /* BOTH AXES. The Discover rail carried the post-mortem (#1762): a rail
     that declares `touch-action: pan-x` DENIES vertical panning for every
     touch that starts on it, so on a phone it becomes a band you cannot
     scroll the page from. Failing to page the deck costs one retry; failing
     to scroll the lander costs the screen. */
  touch-action: pan-x pan-y;
  -webkit-overflow-scrolling: touch;
  /* `mandatory`, where the discover rail uses `proximity` — a deliberate
     deviation. That rail is a strip of small tiles where resting between two
     is a fine place to be; this one shows exactly one card at a time, and a
     deck resting half-way between two cards is the state it exists to
     prevent. */
  scroll-snap-type: x mandatory;
  /* The cards carry a real shadow; a track clipped to the content box would
     shave it off both sides on every page. */
  padding: 3px;
  margin: -3px;
  scrollbar-width: none;
}
.dev-ws-pager-track::-webkit-scrollbar { display: none; }
.dev-ws-pager-item {
  flex: 0 0 100%;
  min-width: 0;
  scroll-snap-align: start;
  /* The gutter between cards has to come from INSIDE the item: a `gap` on
     the track would offset every snap point by one gap and the last card
     would never reach its own. */
  padding-inline-end: 8px;
  box-sizing: border-box;
}
/* ON THE HEADING ROW, at its right end. Under the deck it was a row of
   three small things floating between a card and the next heading, reading
   as a caption for neither; beside the lane's own title it is unambiguously
   that lane's control, and the deck sits directly under the heading it
   belongs to. Smaller than it was, because the heading row is 12px type and
   a 28px control beside it dominated the words. */
.dev-ws-lane-head {
  display: flex; align-items: center; justify-content: space-between; gap: 8px;
}
/* The title keeps its own bottom margin; the row must not inherit it twice. */
.dev-ws-lane-head > .dev-ws-lane-title { margin-bottom: 0; }
.dev-ws-pager-ctl {
  display: flex; align-items: center; gap: 4px; flex: none;
  margin-bottom: 4px;
}
.dev-ws-pager-btn {
  display: inline-flex; align-items: center; justify-content: center;
  width: 22px; height: 22px; border-radius: 999px;
  border: 1px solid var(--app-sheet-line);
  background-color: var(--dc-sheet);
  color: var(--text-primary);
  line-height: 1;
  cursor: pointer;
}
.dev-ws-pager-btn:disabled { opacity: 0.35; cursor: default; }
.dev-ws-pager-chev { width: 13px; height: 13px; }
.dev-ws-pager-n {
  font-size: 11px; color: var(--text-muted); font-variant-numeric: tabular-nums;
  /* The heading above it is uppercase tracked-out small type; the counter is
     a number and stays a number. */
  text-transform: none; letter-spacing: 0; white-space: nowrap;
  padding: 0 2px;
}
/* The since lane needs no rule of its own: it is the same heading, note and
   `.dev-ws-lane-btn` the two lanes above it use.
   It briefly had one — `.dev-ws-since-btn`, a full-width bordered row that
   carried the whole sentence as its label — written because that sentence
   cannot live inside `.gc-vote-btn`, a 24px fixed-height pill that made it
   set a min-content width wider than a phone. Splitting the sentence out
   into the lane's note removes the problem rather than styling around it:
   the label is "Show 8" now, which is exactly what that pill is for. */
/* ── The Workshop's orientation pane ─────────────────────────
   "Since your last visit" was a line inside "Where the app is" (`.dev-ws-
   since-line`, retired): the description led and the personal line sat under
   it as a footnote. It is a BUTTON in "What needs you" now — see
   `.dev-ws-since-btn` above — because a list of things that moved for this
   reader belongs with the other things addressed to them, not under the
   app's own numbers. */
/* A control at the end of a lane — "N more waiting on you". `.dev-ws-link`
   set `font: inherit` with no size of its own, so it took whatever its parent
   had: 16px in the two strip heads, larger than every other control on the
   Dev screen and in a weight nothing else there wears. `.gc-vote-btn` is the
   platform's small action pill and is already what this screen uses. */
.dev-ws-lane-btn { margin-block: 2px 0; margin-inline: 4px 0; }
/* The offer under a lane's heading, where the heading states the fact. */
.dev-ws-lane-note { margin-block: -2px 6px; margin-inline: 16px 0; font-size: 12px; color: var(--text-muted); }
.dev-ws-pill {
  display: inline-flex; align-items: center; height: 22px; padding: 0 9px; border-radius: 999px;
  font-size: 12px; font-weight: 600; white-space: nowrap;
}
.dev-ws-pill-warn { background: var(--state-attention-bg); color: var(--state-attention); }
.dev-ws-pill-good { background: var(--state-ok-bg); color: var(--state-ok); }
.dev-ws-link {
  background: none; border: 0; padding: 0; font: inherit; font-size: inherit;
  color: var(--accent); cursor: pointer; text-decoration: none;
}
.dev-ws-link:hover { text-decoration: underline; }

/* The dashboard's four numbers.
   They were a sentence, and four integers read out as prose is the slowest
   form they can take: the reader parses a clause to learn something a glance
   should give. So they are tiles, on their own ground inside the pane, and
   the paragraph under them is freed to say the things a number cannot. */
.dev-ws-dash {
  /* ONE RULED ROW, NOT FOUR CARDS. Each figure used to carry the pane's own
     surface, a hairline and the two-layer lift the week cards had — four
     objects inside an object, above a fifth holding the summary line. The
     figures are the pane's content, so they sit on the pane: hairlines
     between them and nothing else.
     FOUR ACROSS AT EVERY WIDTH (5 Oct 2026). Under 420px they were two up,
     a 2x2 grid, and the owner asked for one row on an iPhone 13 mini. A
     phone keeps the row by drawing the figures closer and a size smaller
     (below), never by cutting a label short: a label wraps instead. At
     375px the pane's content box is 339px (375, less #dev-body's 4px a
     side, less the strip's 14px a side), so each column is 84.75px, and
     the narrowest text column, the third figure's beside its dot, is
     84.75 - 1 - 8 - 8 - 6 - 5 = 56.75px. In the system font at 11.5px
     its longest word, "waiting", is about 39px, and every label takes two
     lines at most; at the wider 14px spacing "waiting on votes" would
     take three. */
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin-top: 4px;
}
.dev-ws-dash-cell {
  min-width: 0;
  padding: 2px 8px;
  border-inline-start: 1px solid var(--app-sheet-line);
  font-size: 11.5px;
  color: var(--text-muted);
  line-height: 1.3;
}
@media (min-width: 420px) {
  .dev-ws-dash-cell { padding-inline-start: 14px; padding-inline-end: 14px; }
}
.dev-ws-dash-cell:first-child { border-inline-start: 0; padding-inline-start: 2px; }
.dev-ws-dash-cell:last-child { padding-inline-end: 2px; }
.dev-ws-dash-cell b {
  display: block;
  /* THE TEXT TOKEN, always. Tone used to be painted on the integer itself —
     a green 6, an amber 3 — which is state carried by hue alone and unread
     by anyone who cannot separate the two, and it put a status colour on
     text where the rest of the product keeps text in text ink. The mark
     moved to the label; the number is a number.
     20px on a phone, where four share the row; 24px from 420px. */
  font-size: 20px; font-weight: 650; line-height: 1.1;
  letter-spacing: -.02em; color: var(--text-primary);
}
@media (min-width: 420px) {
  .dev-ws-dash-cell b { font-size: 24px; }
}
/* A GRID, not an inline run. The label wraps at phone widths, and under
   `align-items: center` the dot floated to the middle of a two-line label
   while its second line ran back underneath it. Two columns keep the mark
   on the first line and the wrapped text in its own column. */
.dev-ws-dash-label {
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: start;
  gap: 0 5px;
  margin-top: 2px;
}
.dev-ws-dash-label:not(:has(> .dev-ws-dash-dot)) { grid-template-columns: 1fr; }
/* Only the two figures that are a CALL wear one. A zero is not a warning
   (the component leaves the class off), and "nobody on them" is a fact
   about the backlog rather than an alarm — it had no tone before and gains
   none here. */
.dev-ws-dash-dot { width: 6px; height: 6px; border-radius: 999px; margin-top: 5px; }
.dev-ws-dash-dot-good { background: var(--state-ok); }
.dev-ws-dash-dot-warn { background: var(--state-attention); }
/* AND THE FIGURE TAKES THE TONE BACK. The objection that moved it to the
   label was to state carried by hue ALONE — unreadable to anyone who cannot
   separate the two, and a status colour sitting on text. The dot answers
   that: the mark is the non-colour channel, so the colour on the number is
   now redundant rather than load-bearing, which is what makes it free. The
   tone still appears only where the component put a dot, so a zero — not a
   call — stays in text ink. */
.dev-ws-dash-cell-good b { color: var(--state-ok); }
.dev-ws-dash-cell-warn b { color: var(--state-attention); }
/* #4745: AND WHEN SOMETHING WAITS, THE VOTES FIGURE IS A BUTTON. The reset
   takes the browser's button chrome off without taking the cell's own look
   with it: the left border is the hairline between figures and stays
   (:first-child still removes it), and font-size, line-height and colour all
   keep coming from .dev-ws-dash-cell above — which is why the font reset is
   the family and weight longhands, not the `font:` shorthand, whose
   font-size would override the cell's. */
button.dev-ws-dash-cell {
  appearance: none;
  background: none;
  border-top: 0;
  border-inline-end: 0;
  border-bottom: 0;
  font-family: inherit;
  font-weight: inherit;
  text-align: start;
  cursor: pointer;
  /* Square, as the spans beside it are (polish board #24): a radius bent
     this cell's hairline into a faint rounded outline where the other
     figures have straight dividers. */
  border-radius: 0;
  box-shadow: none;
}
button.dev-ws-dash-cell:hover .dev-ws-dash-label { color: var(--accent); }
button.dev-ws-dash-cell:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
/* #5369, revised in the change's discussion: the three stage figures are
   NOT buttons. They stay the spans they always were, as unstyled clickable
   wrappers — the pointer cursor and a keyboard focus ring are the whole
   affordance, and nothing repaints on hover, so nothing on the strip looks
   like a button or a link. Votes keeps the button #4745 made it, above. */
span.dev-ws-dash-cell[data-ws-dash-open] { cursor: pointer; }
span.dev-ws-dash-cell[data-ws-dash-open]:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

/* ── The working pane ──────────────────────────────────────────────────
   The controls, the switch and the thing they act on, as one card — the same
   sheet the "Where the app is" and "What needs you" strips above it wear, so
   the page reads as a stack of panes rather than a pane, two loose control
   rows and a list.

   `overflow: visible` is load-bearing: the vote sheet is absolutely
   positioned inside this subtree and the sticky head below depends on no
   ancestor clipping. A `overflow: hidden` here to clip the radius would do
   both kinds of damage at once. (The "+" menu used to be the other thing
   escaping; it hangs off the tab strip now.) */
.dev-ws-pane {
  display: flex; flex-direction: column;
  border-radius: 22px;
  box-shadow: 0 0 0 1px var(--app-sheet-line) inset;
  overflow: visible;
}
/* ── One face, painted by the two PARTS and not by the pane ───────────
   The pane used to carry the fill and the sticky head carried a second one
   on top of it. 50% over 50% is ~75%: a lighter band across the controls,
   measurably (251,251,252 against the body's 250,250,252) and visibly. And
   because a backdrop-filter makes an element a backdrop root, the head's
   frost was a SECOND frost applied over the pane's — so the two could not be
   made equal by tuning the fill either.

   So the pane paints nothing. Head and body carry the SAME fill over the SAME
   backdrop — the page — which makes them the same colour by construction
   rather than by a value chosen to look close. They abut (the pane is a flex
   column with no gap), so the join does not show.

   The head's frost still does its job: the body is its SIBLING, so the rows
   scrolling inside the body pass through the head's backdrop and smear.

   `overflow: visible` on the pane is load-bearing: the vote sheet is
   absolutely positioned in this subtree, and sticky does not work under a
   clipping ancestor. */
.dev-ws-pane-head, .dev-ws-pane-body {
  background-color: var(--dc-sheet-fill);
  backdrop-filter: var(--dc-frost);
  -webkit-backdrop-filter: var(--dc-frost);
}
/* The head pins to the top of #dev-forum-scroll while the pane is in view and
   releases with it. `top: 0` and not an offset: the scroller's own top IS the
   top of the reading area — the platform header is outside it. */
.dev-ws-pane-head {
  position: sticky; top: 0; z-index: 20;
  display: flex; flex-direction: column; gap: 8px;
  padding: 8px 10px;
  border-start-start-radius: 22px; border-start-end-radius: 22px; border-end-end-radius: 0; border-end-start-radius: 0;
}
/* PINNED, THE HEAD IS SQUARE ON TOP, at every width (#3651). Its rounded
   corners are the pane's at rest; pinned, it meets the flat foot of the tabs
   above it, and each curve left a notch between the two that the cards
   scrolling by showed through. Only the top-left was squared, and only from
   700px; the top-right kept its notch, and a phone kept both.
   `data-ws-head-pinned` is workshop.tsx's usePinnedStrip: set once the head
   has left the top of its pane, which is the moment it sticks, so the pane
   keeps its rounded top all the while it is still scrolling up. */
.dev-ws[data-ws-head-pinned] .dev-ws-pane-head { border-start-start-radius: 0; border-start-end-radius: 0; }
.dev-ws-pane-body {
  display: flex; flex-direction: column; gap: 8px;
  padding: 8px 10px 12px;
  border-start-start-radius: 0; border-start-end-radius: 0; border-end-end-radius: 22px; border-end-start-radius: 22px;
}
/* Where there is no backdrop-filter the fill is all there is, and 50% white
   with rows sliding CRISPLY under the pinned head is the rendering fault the
   frost prevents — not a slightly flatter bar. Both halves go opaque together,
   because they must stay the same colour as each other above all. */
/* SOLID, BOTH TOGETHER, on every platform. The body scrolls under the
   sticky head, so with no blur the head has to be opaque; and the head and
   the body read as one pane, so staying the same colour as each other
   matters more than the body's translucency. */
.dev-ws-pane-head, .dev-ws-pane-body { background-color: var(--dc-sheet-solid); }
/* Inside the pane the toolbar is a plain row: the frame's own `px-3 pt-2`
   placed it against the scroller's edge, and here the pane supplies both. */
.dev-ws-pane .dev-ws-pane-head #dev-actions { padding: 0; }

/* ── The stage pane runs edge to edge ──────────────────────────────────
   `#dev-workshop` is a 760px reading column (below), which is right for a
   list of one-line rows and wrong for four side-by-side columns: bounded to
   760px the board is a horizontal scroller before it is a board, and the
   whole point of reading by stage is seeing the stages AT ONCE.

   So when the stage pane is up the column bound comes OFF the workshop and
   goes back on to every child except the board. The alternative — a
   `100vw` full-bleed with negative margins — was rejected on purpose:
   `100vw` counts the scrollbar that `#dev-forum-scroll` always has, so it
   overflows by its width and adds a horizontal scrollbar to the page.
   Re-parenting the bound has no such edge. */
#dev-workshop.dev-ws-has-board { max-width: none; }
/* THE TAB BODY IS A LEVEL THIS RULE HAS TO REACH THROUGH. It used to bound
   every direct child of `.dev-ws` except the pane; the tabs put the pane one
   level deeper, inside `.dev-ws-tabbody`, so the bound landed on the WRAPPER
   and the board was cramped to the reading column from outside. Bound the tab
   body's children instead, and leave the body itself unbounded — the rail is
   still a direct child of `.dev-ws`, so it keeps the column width, which is
   what it wants: a pill spanning 1440px is not a tab bar. */
#dev-workshop.dev-ws-has-board > .dev-ws > :not(.dev-ws-tabbody),
#dev-workshop.dev-ws-has-board > .dev-ws > .dev-ws-tabbody > :not(.dev-ws-pane) {
  width: 100%; max-width: 760px; margin-inline-start: auto; margin-inline-end: auto;
}
/* THE PLACE'S TITLE WIDENS WITH THE BOARD (overnight audit D12, 1 Nov 2026).
   Since #4417 the band is the page's title row ("Workshop" over its
   hairline), not the pill strip the rule above kept at reading width, and
   held to 760px it left the board starting left of the title and running on
   past the end of its rule. From 768px, where it is that title row, it spans
   the pane like the board's own head, and its name steps in by the head's
   10px so the title, the head's first control and the columns share one
   edge. A phone's band is the coloured strip and is left alone. */
@media (min-width: 768px) {
  #dev-workshop.dev-ws-has-board > .dev-ws > .dev-ws-placebar { max-width: none; }
  #dev-workshop.dev-ws-has-board > .dev-ws > .dev-ws-placebar > .dev-ws-tabtrack { padding-inline-start: 10px; padding-inline-end: 10px; }
}
/* On By stage the pane WIDENS AND STAYS A PANE. An earlier cut stripped its
   sheet, radius and padding here, on the argument that a card face is a frame
   drawn around the whole window. What that actually produced was the pane
   vanishing and the head's own fill left behind as a bare rectangle sitting
   over the controls alone — the board below it belonging to no pane at all.
   The pane is the unit; widening it must not dissolve it. So nothing is
   stripped: the same sheet, the same 22px, the same gutter, around a wider
   box, with the board filling it.

   The BOARD is what wanted the window, not the controls above it: a search
   field and a two-tab strip stretched across 1200px are a worse control than
   the same pair at reading width — the strip in particular reads as pulled
   apart rather than as a segmented pair. So the head still spans the pane, as
   a pinned edge must, while what sits IN it keeps the reading column. */
#dev-workshop.dev-ws-has-board .dev-ws-pane-head > :not(.dev-ws-allbar, .dev-kanban-stages) {
  /* 760px is the reading column; the 20px is the head's own left+right
     padding. Bounding to the column's OUTER width instead made the controls
     20px wider on By stage than on By category — a toolbar that grew slightly
     when you switched panes, which is the kind of drift nobody can name but
     everybody notices. Measured: 740 against 760.

     #4486: NOT the one-row head or the pipeline. The row is the page's own
     bar and runs the width of the board it heads, and the steps sit over
     their columns, so both take the board's width. */
  width: 100%; max-width: calc(760px - 20px);
  margin-inline-start: auto; margin-inline-end: auto;
}
/* The board brings its own horizontal scroller (#dev-kanban), so this
   wrapper only has to stop the columns sitting flush against what is
   around them. The 8px sides are not arbitrary: `#dev-body` drops to 4px
   of side padding when it holds the Workshop (below), which is right for a
   760px column centred in far more room than that and reads as a clipped
   edge once the board spans the window — 4 + 8 restores the 12px the
   standalone board gets from `#dev-body`'s own `px-3`, so the two surfaces
   sit on the same gutter. */
.dev-ws-board { padding: 2px 8px 0; }

/* The pane's title, above the tabs. Indented to the same 4px the sort row
   and the tab strip sit at, so the head reads as one column. */
/* `space-between` with the eyebrow gone leaves the chips alone at the START
   of the row, which is where they belong: on a healthy board there is no
   grouping state to report and the row is just the sort control. */
.dev-ws-sort { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 2px 4px 0; }
.dev-ws-sort-opts { display: flex; gap: 4px; flex: none; }
/* The eyebrow's grouping note comes and goes ("· drafting categories…"),
   and a longer eyebrow used to push the chips onto a second line and the
   whole list down with them. It gives way instead: on one line it shortens
   with an ellipsis, and where the row cannot hold both (a phone) it always
   has its own line, so the chips never move. */
.dev-ws-sort > .dev-ws-eyebrow { flex: 1 1 auto; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
@media (max-width: 639px) {
  .dev-ws-sort { flex-wrap: wrap; row-gap: 6px; }
  .dev-ws-sort > .dev-ws-eyebrow { flex-basis: 100%; }
}
.dev-ws-chip {
  height: 26px; padding: 0 10px; border-radius: 999px; border: 1px solid var(--app-sheet-line);
  background: var(--dc-sheet); color: var(--text-muted); font: inherit; font-size: 12px; cursor: pointer;
}
.dev-ws-chip[aria-pressed="true"] { background: var(--text-primary); color: var(--dc-sheet); border-color: var(--text-primary); }

.dev-ws-themes { display: flex; flex-direction: column; gap: 8px; }
.dev-ws-theme {
  /* Raised, not frosted: see `--dc-sheet-raise`. The frost was doing nothing
     here anyway — it blurs what is BEHIND, and what is behind is a pane of
     the same colour, so it cost a compositing layer per card to blur a flat
     field. */
  background-color: var(--dc-sheet-raise);
  border-radius: 22px;
  box-shadow: 0 0 0 1px var(--app-sheet-line) inset;
  overflow: hidden;
}
.dev-ws-theme-head {
  cursor: pointer; padding: 14px 14px 12px;
  display: grid; grid-template-columns: 1fr auto; gap: 4px 12px; align-items: start;
}
.dev-ws-theme-head:hover { background: var(--state-neutral-bg); }
.dev-ws-theme-head:focus-visible { outline: 2px solid var(--accent); outline-offset: -2px; }
.dev-ws-theme-name { font-size: 17px; font-weight: 600; letter-spacing: -.01em; color: var(--text-primary); text-wrap: balance; }
/* The theme's glyph, inline with its name so a long name still wraps under
   itself rather than around a floated square. Sized to the cap height of the
   name beside it. */
.dev-ws-theme-icon {
  display: inline-flex; align-items: center; justify-content: center;
  width: 24px; height: 24px; margin-inline-end: 7px; border-radius: 7px;
  font-size: 15px; line-height: 1; vertical-align: -5px;
  background: var(--state-neutral-bg);
}
/* The no-icon fallback: the initial on the name's own swatch — the same
   colour `Faces` gives that name — so it reads as chosen, not as missing. */
.dev-ws-theme-icon-letter { color: #fff; font-size: 12px; font-weight: 700; }
/* Two stats side by side — people, then how many items are still open in
   here — divided by a hairline rather than a glyph, so the pair reads as one
   block and the numbers stay the loudest thing in it. */
.dev-ws-theme-people { text-align: end; color: var(--text-muted); font-size: 12px; line-height: 1.2; display: flex; gap: 10px; }
.dev-ws-stat + .dev-ws-stat { padding-inline-start: 10px; border-inline-start: 1px solid var(--app-sheet-line); }
.dev-ws-theme-people b { display: block; font-size: 20px; font-weight: 600; color: var(--text-primary); letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
.dev-ws-theme-say { grid-column: 1 / -1; margin: 2px 0 0; font-size: 14px; color: var(--text-primary); }
/* A shut theme's summary is re-drafted as the board changes, and its length
   moved every theme below it. Shut, it holds to three lines; open, it reads
   in full. */
.dev-ws-theme:not(.dev-ws-theme-open) .dev-ws-theme-say {
  display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 3; overflow: hidden;
}
.dev-ws-theme-counts { grid-column: 1 / -1; display: flex; flex-wrap: wrap; gap: 6px; margin-top: 8px; }
.dev-ws-cnt {
  display: inline-flex; align-items: center; gap: 5px; height: 24px; padding: 0 8px; border-radius: 8px;
  background: var(--state-neutral-bg); font-size: 12px; color: var(--text-muted);
}
.dev-ws-cnt b { color: var(--text-primary); font-weight: 600; font-variant-numeric: tabular-nums; }
/* The chip's label in dark (QA 2026-09-24 Q20). --state-neutral-bg over a
   category card lands at #3e3f43, and the muted ink that reads fine on the
   card itself is 3.66:1 on the chip. One step brighter clears 4.76, and the
   bold count beside it is still the loudest thing in the chip. Light passes
   as it is (4.72), so this is dark-only. */
.dark .dev-ws-cnt { color: #aeaeb2; }
.dev-ws-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--state-neutral); flex-shrink: 0; }
.dev-ws-cnt-underway .dev-ws-dot, .dev-ws-lane-underway .dev-ws-dot { background: var(--accent); }
.dev-ws-cnt-review .dev-ws-dot, .dev-ws-lane-review .dev-ws-dot { background: var(--state-attention); }
.dev-ws-cnt-shipped .dev-ws-dot, .dev-ws-lane-shipped .dev-ws-dot { background: var(--state-ok); }
.dev-ws-cnt-fresh { background: var(--accent-tint); color: var(--accent); }
.dev-ws-cnt-fresh b { color: var(--accent); }
.dev-ws-theme-foot { grid-column: 1 / -1; display: flex; align-items: center; gap: 10px; margin-top: 10px; font-size: 13px; color: var(--text-muted); position: relative; }
.dev-ws-chev { width: 16px; height: 16px; color: var(--text-muted); flex-shrink: 0; transition: transform .18s ease; }
.dev-ws-theme-open > .dev-ws-theme-head .dev-ws-chev, .dev-ws-row-open > .dev-ws-chev { transform: rotate(90deg); }
@media (prefers-reduced-motion: reduce) { .dev-ws-chev { transition: none; } }
/* Reduce motion setting (#6510): the same, when Settings asks for it. */
:where(html[data-motion="reduce"]) .dev-ws-chev { transition: none; }

.dev-ws-faces-wrap { position: relative; display: inline-flex; }
.dev-ws-faces { display: flex; border: 0; background: transparent; padding: 2px; margin: -2px; border-radius: 999px; cursor: pointer; }
.dev-ws-faces:hover, .dev-ws-faces[aria-expanded="true"] { background: var(--state-neutral-bg); }
.dev-ws-faces:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
.dev-ws-face {
  width: 22px; height: 22px; border-radius: 50%; border: 2px solid var(--dc-sheet);
  display: grid; place-items: center; font-size: 10px; font-weight: 700; color: #fff; margin-inline-start: -6px;
}
.dev-ws-face:first-child { margin-inline-start: 0; }
.dev-ws-face-more { background: var(--bg-tertiary); color: var(--text-muted); font-size: 9px; }
.dev-ws-roster {
  position: absolute; inset-inline-start: 0; top: 30px; z-index: 6; min-width: 160px;
  background: var(--dc-sheet); border: 1px solid var(--app-sheet-line); border-radius: 12px;
  box-shadow: 0 6px 20px rgba(0,0,0,.12); padding: 6px 10px; display: flex; flex-direction: column; gap: 2px;
}
.dev-ws-roster-row { font-size: 13px; color: var(--text-primary); white-space: nowrap; }

.dev-ws-theme-body { border-top: 1px solid var(--app-sheet-line); padding: 10px 10px 12px; display: flex; flex-direction: column; gap: 10px; }
.dev-ws-lane-title {
  margin: 0 0 4px; padding: 0 4px; font-size: 12px; font-weight: 600; letter-spacing: .04em; text-transform: uppercase;
  color: var(--text-muted); display: flex; gap: 6px; align-items: center;
}
/* "Shipped this week" folds — it is the one lane nothing is waiting on. Its
   count rides in the heading so the fold never hides how much is in there. */
.dev-ws-lane-title[role="button"] { cursor: pointer; }
.dev-ws-lane-title[role="button"]:hover { color: var(--text-primary); }
.dev-ws-lane-title[role="button"]:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 6px; }
.dev-ws-lane-n { font-variant-numeric: tabular-nums; color: var(--text-primary); }
.dev-ws-lane-title[aria-expanded="true"] > .dev-ws-chev { transform: rotate(90deg); }
.dev-ws-lane-title > .dev-ws-chev { width: 14px; height: 14px; }
.dev-ws-rowwrap { margin-bottom: 4px; }
/* ── The row IS the card, folded ─────────────────────────────
   It used to be a grey strip on the sheet, which made an unfolded row read
   as two objects: the strip, and a whole card painted under it repeating the
   same title, number and author. Same sheet, border and radius as the entry
   below it now, so opening one GROWS the thing you clicked (#1787). */
.dev-ws-row {
  /* A COLUMN, as the card is: the head (glyph + title) on one line and the
     bar row under it spanning the whole card. It was a single row with the
     glyph in its own column, which put the bar 30px in. */
  width: 100%; text-align: start; display: flex; flex-direction: column; align-items: stretch;
  /* The card's own chrome, value for value (`div:is(.dev-card-dense,
     .dev-card-topic)` above): r22, 14px sides and top, 12px bottom, the 8px
     glyph gap, no border, the same soft drop shadow. The row had a hairline
     border, 9x10 padding, r12 and a 10px gap — four small differences that
     made the two sizes of one item read as two objects. */
  padding: 14px 14px 12px; border-radius: 22px; border: 0;
  background: var(--dc-sheet);
  color: var(--text-primary); font: inherit; cursor: pointer;
}
/* The hover FILL is the card's, applied as the card applies it: the same
   `hover:bg-zinc-50 dark:hover:bg-zinc-800` utilities, on the row itself
   (workshop.tsx). Two sizes of one object hovering to two different greys is
   the same mismatch as two icons or two chip styles, and hard-coding the
   colour here could not have fixed it — `zinc` is overridden in
   tailwind.config.js, so a hex copied from the stock palette would be a
   third grey rather than the card's. Only the border stays here. */
.dev-ws-row:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
/* -- The press ----------------------------------------------
   Both sizes toggle on a click, and neither said so while the button was
   down: the hover fill arrived on entry and nothing changed on press, so
   closing an open card gave no feedback until it had already closed.

   The exclusion list mirrors the two click guards in card/fold.tsx -- the
   row ignores a press that started on an anchor or a button, and the open
   card also ignores the thread, the comment list and the detail sections.
   :active matches every ancestor of the pressed element, so without the
   :not(:has(...)) a press on the Vote button would tint the whole card
   behind it, for a press that toggles nothing. */
/* The kit's scale-press, opted out of — like the list of opt-outs up at
   `.members-vis-pill:active`, for a different reason. The
   kit gives every button an instant scale on press; the row carries
   role="button" so a keyboard can reach it and the open card is a plain
   div, so the scale landed on ONE of the two sizes. That is the inset a
   pressed folded row showed and a pressed open card did not. The two sizes
   are one object: under press the fill changes and nothing else does, at
   both. The brightness dim stays, as it does for the pills. */
.dev-ws-row:active { transform: none; }
.dev-ws-row:active:not(:has(a:active, button:active, input:active, textarea:active, select:active)),
.dev-ws-rowwrap-open .gc-vote-item:active:not(:has(
  a:active, button:active, input:active, textarea:active, select:active,
  .dev-feed-thread:active, .dev-feed-comments:active
)) {
  background: var(--dev-press);
  /* Instant. The open card carries transition-colors, so the press colour
     eased in over ~150ms while the row snapped to it -- a quick click was
     released before the card had finished tinting, which is what made the
     press read as no feedback and the release read as a flash. The return
     to hover still eases, because that one is not feedback about a gesture. */
  transition: none;
}
/* -- The press, on touch: held back until the finger settles (#1928) ------
   On a phone a card list is mostly scrolled, not tapped, and every scroll
   starts as a touch on some card. Both press treatments above engage
   instantly -- the fill here, and the kit's scale + brightness dim on every
   role="button" card (the folded row, the session rows) -- so a flick down
   the board flashed a pressed state on whichever card the finger landed on,
   for a gesture that opened nothing. iOS lists wait a beat before
   highlighting, so a touch that becomes a scroll never lights up.

   Same here: the press still engages with no easing, but after 120ms. A
   scroll clears :active well inside that, so the pending change is
   cancelled and nothing is drawn; a real tap is held longer and tints as
   before. `transition` on the :active rule is the one read on the way IN;
   the way out keeps each element's own easing. Touch only -- a mouse press
   is never a scroll, so desktop keeps the instant feedback the rule above
   exists for. Real buttons inside the cards (Vote, Preview) are untouched:
   they are pressed on purpose. */
@media (hover: none) {
  .dev-ws-row:active:not(:has(a:active, button:active, input:active, textarea:active, select:active)),
  .dev-ws-rowwrap-open .gc-vote-item:active:not(:has(
    a:active, button:active, input:active, textarea:active, select:active,
    .dev-feed-thread:active, .dev-feed-comments:active
  )),
  #dev-forum-scroll [role="button"]:active {
    transition: background-color 0s linear 120ms, transform 0s linear 120ms, filter 0s linear 120ms;
  }
}
/* #1918: the challenge cards (the Challenges tab's grid and Home's
   Challenges block) are role="button" now, so the kit's scale + dim press
   reaches them. They sit in scrolled lists too, so on touch they take the
   same 120ms hold-back as the Dev board above. */
@media (hover: none) {
  .tc-se-card[role="button"]:active,
  .home-challenge-card[role="button"]:active {
    transition: transform 0s linear 120ms, filter 0s linear 120ms;
  }
}
/* Home's app tiles are role="button" too (features/home/app-grid.tsx), in the
   grid a phone scrolls most, so a flick down Home pressed whichever tile the
   finger started on. Same hold-back; the tile has no pressed fill of its own
   (its hover fill is `(hover: hover)` only, #2892), so it is the kit's scale
   and dim that wait. A held tile still presses before its long-press menu. */
@media (hover: none) {
  .app-card[role="button"]:active {
    transition: transform 0s linear 120ms, filter 0s linear 120ms;
  }
}
.tc-se-card[role="button"]:focus-visible,
.home-challenge-card[role="button"]:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
/* The row's icon is the CARD's icon, to the pixel: the same 22px box with no
   tile and no fill, and the same 18px glyph. It used to be a 28px tinted
   tile, which was the one part of the folded row that did not appear on the
   card at all — so the two sizes of one item opened on a different mark.
   The colour that tile was carrying is not lost: it moved to the left edge
   below, which is where the card carries it. */
/* The head: the card's `.dev-card-head`, at the row's gap. */
.dev-ws-row-head { display: flex; align-items: center; gap: 8px; }
.dev-ws-row-head > .dev-card-icon {
  /* No margin: the card's glyph sits flush on the padding edge, and a 1px
     nudge here made the two sizes of one item start on different pixels. */
  flex-shrink: 0; align-self: flex-start;
  width: 22px; height: 22px; background: transparent; border-radius: 0;
}
.dev-ws-row-head > .dev-card-icon > svg { width: 18px; height: 18px; }

/* ── The row's left edge ──
   The card's own spine (`div:is(.dev-card-dense, .dev-card-topic)[data-edge]`
   above), on the row, from the same model field and the same tokens: blue
   while a vote is open, violet while merging, amber behind main, red on a
   conflict, green once merged. A folded row and its card now agree on their
   colour, which is what makes the fold read as a fold. */
.dev-ws-row {
  --dev-edge-w: 4px;
  --dev-edge: transparent;
  padding-inline-start: calc(14px + var(--dev-edge-w));
  /* An inset shadow and a 33% mix, exactly as the card draws it: the same
     4px at the same strength, following the same corner arc, taking no
     layout, over the same drop shadow. A border here would have been a
     different mark at a different weight — which is the whole thing this
     row is trying to stop being. */
  box-shadow:
    inset var(--dev-edge-w) 0 0 color-mix(in srgb, var(--dev-edge) 33%, transparent),
    0 1px 2px rgba(0, 0, 0, 0.06);
}
.dev-ws-row[data-edge="vote"]      { --dev-edge: var(--accent); }
.dev-ws-row[data-edge="progress"]  { --dev-edge: var(--state-progress); }
.dev-ws-row[data-edge="attention"] { --dev-edge: var(--state-attention); }
.dev-ws-row[data-edge="blocked"]   { --dev-edge: var(--state-blocked); }
.dev-ws-row[data-edge="ok"]        { --dev-edge: var(--state-ok); }
.dev-ws-row[data-edge="neutral"]   { --dev-edge: var(--state-neutral); }
/* The title takes the head's remaining width, as `.dev-card-title` does
   on the card. It used to sit in a `.dev-ws-row-main` column with the meta
   line, which is what held the meta line 30px in: the card puts its meta
   line at the padding edge, under the glyph, not beside it. */
.dev-ws-row-head > .dev-ws-row-title { flex: 1; min-width: 0; }
/* 1.35, the dense card's leading (:is(.dev-card-dense, .dev-card-topic)
   .dev-card-title above). The row was 1.3, so a two-line title set slightly
   tighter folded than open — the same words on a different grid. */
.dev-ws-row-title { font-size: 14px; line-height: 1.35; }
/* The card's own meta line (dev-card.tsx metaLineNodes), at the card's
   sizes: 12.5px on 21px lines, wrapping, the number a link, the tags and
   the linked-issue chips in the card's chip geometry. Keep these in step
   with `:is(.dev-card-dense, .dev-card-topic) .dev-card-meta` above. */
/* The card's own tab, by the card's own rule: `:is(.dev-card-dense,
   .dev-card-topic) .dev-card-head:has(> .dev-card-icon) + .dev-card-meta`
   above sets the meta line 30px in so it starts under the title rather than
   under the glyph — and only when there IS a glyph. Same 30px, same
   condition, so a change to one keeps the other. The status row below takes
   no tab, at either size: it is the full-width line. */
.dev-ws-row-head:has(> .dev-card-icon) + .dev-ws-row-meta { padding-inline-start: 30px; }
.dev-ws-row-meta { display: block; font-size: 12.5px; line-height: 21px; color: var(--text-muted); min-width: 0; margin-top: 0; white-space: normal; }
.dev-ws-row-meta > .dev-badge { height: 19px; font-size: 11.5px; vertical-align: middle; margin-inline-start: 4px; }
.dev-ws-row-meta > .dev-badge.font-mono { font-size: 11px; }
.dev-ws-row-meta > .dev-badge .attr-avatar { width: 14px; height: 14px; }
/* ── The row's last line ─────────────────────────────────────
   The card's status row and facts row in one: a chip of the bar's state,
   the state chips, the message count, and the vote button at the right end
   — where the card's bar puts it — so the two sizes of one item keep one
   control in one corner. ONE line, clipped: a card with more state than
   fits loses the surplus whole rather than growing the row and breaking
   the column's rhythm; the state chip ellipsises first. */
.dev-ws-row-band {
  /* 8px, the card's own `.dev-card-status` margin. The row had 4px plus a
     1px column gap, so the gap above the one line that carries the state
     was 5px folded and 8px open. */
  display: flex; flex-wrap: nowrap; align-items: center; gap: 4px 6px;
  min-height: 18px; overflow: hidden; margin-top: 8px;
}
/* The bar fills the line, as the card's does. The card's pill is a flex
   item with basis 0 that grows into whatever the Vote button leaves; the
   row's chip was inline-block at its natural width, so on a 540px Workshop
   sheet it ended 221px short of the vote and the two sizes drew the same
   state at two lengths. */
.dev-ws-row-band > .dev-ws-row-state { flex: 1 1 0; }
.dev-ws-row-band > .dev-ws-row-trailing { margin-inline-start: auto; }
/* The card's facts-row geometry (:is(.dev-card-dense, .dev-card-topic)
   .dev-card-meta > .dev-badge), so "In review" and "@maya" are the same chip
   at both sizes. Without this they fell back to the base .dev-badge —
   10.5px on a 20px chip against the card's 11.5px on 19px. */
/* `0 1 auto`, not `none`: the band clips its one line, so a chip that does
   not fit used to be cut through at the row's edge (#5755). It shrinks now,
   and its words ellipsise inside a whole pill. */
.dev-ws-row-band > .dev-badge { flex: 0 1 auto; min-width: 0; overflow: hidden; height: 19px; font-size: 11.5px; }
.dev-ws-row-band > .dev-badge > :not(.dev-badge-label):not(.dev-badge-name) { flex-shrink: 0; }
/* The composite pill, wearing the tone it has always carried. Tones are
   `statusPillState`'s vocabulary (neutral / ok / attention / blocked /
   progress), not the merge badge's colour names — an unknown one falls
   through to the neutral base rather than rendering unstyled. */
/* At the card's bar's height and shape (30px, r14, 12.5px — the dense
   `.dev-status-pill-block` above) rather than a 10px chip: the row's last
   line is 30px tall whenever it carries the vote button, and a chip that
   grows into the bar when the card opens was the one thing on that line
   that still jumped. Content-width, ellipsising, where the card's bar
   flexes to fill. */
.dev-ws-row-state {
  display: inline-block; min-width: 0; overflow: hidden; text-overflow: ellipsis;
  height: 30px; line-height: 30px; box-sizing: border-box;
  font-size: 12.5px; font-weight: 500; white-space: nowrap;
  padding: 0 10px; border-radius: 14px;
  background: var(--state-neutral-bg); color: var(--state-neutral);
}
.dev-ws-row-state-blocked   { background: var(--state-blocked-bg);   color: var(--state-blocked); }
.dev-ws-row-state-ok        { background: var(--state-ok-bg);        color: var(--state-ok); }
.dev-ws-row-state-attention { background: var(--state-attention-bg); color: var(--state-attention); }
.dev-ws-row-state-progress  { background: var(--state-progress-bg);  color: var(--state-progress); }
/* ── The fold mark ───────────────────────────────────────────
   Which SIZE the item is at, at the top right of the row and of the card
   (card/fold.tsx FoldMark). The same two chevrons on both; on the open card
   they are pushed apart with a bar between them, so the mark stretches when
   the card does and nothing rotates: a chevron that turns promises a
   direction (the accordion's down → up, the tree's right → down) and the
   Vote button's ▾ on this same card already means a menu. Absolutely placed
   so it takes no width from the row's last line — the Vote button there
   reaches the right edge, as the card's bar row does — and only the title
   keeps clear of it. right: 14px puts its right edge over the hamburger's
   in the band below; top: 15px centres it on the title's first line. */
.dev-ws-row, .dev-ws-sheet > div:is(.dev-card-dense, .dev-card-topic) { position: relative; }
.dev-ws-row-title, .dev-ws-sheet .dev-card-title { padding-inline-end: 22px; }
.dev-fold-mark {
  position: absolute; top: 15px; inset-inline-end: 14px; width: 16px; height: 16px; display: block;
  padding: 0; margin: 0; border: 0; background: transparent; color: var(--text-faint); line-height: 0;
}
button.dev-fold-mark { cursor: pointer; color: var(--accent); border-radius: 4px; }
button.dev-fold-mark:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.dev-fold-mark > svg { width: 16px; height: 16px; display: block; }
/* The geometry is transforms on the three paths, in the SVG's own units (a
   CSS px is one user unit on an SVG element): open, the chevrons sit 2
   units further out and the bar between them is drawn; closed, the bar is
   scaled to nothing about its middle. Declared as end states, and ALSO as
   keyframes on the open card, so the stretch plays once when it mounts. */
.dev-fold-mark path { transform-box: view-box; transform-origin: 12px 12px; }
.dev-fold-mark .dev-fold-bar { transform: scaleY(0); }
.dev-fold-mark[data-open="1"] .dev-fold-top { transform: translateY(-2px); animation: dev-fold-top .15s ease both; }
.dev-fold-mark[data-open="1"] .dev-fold-bottom { transform: translateY(2px); animation: dev-fold-bottom .15s ease both; }
.dev-fold-mark[data-open="1"] .dev-fold-bar { transform: scaleY(1); animation: dev-fold-bar .15s ease both; }
@keyframes dev-fold-top { from { transform: translateY(0); } to { transform: translateY(-2px); } }
@keyframes dev-fold-bottom { from { transform: translateY(0); } to { transform: translateY(2px); } }
@keyframes dev-fold-bar { from { transform: scaleY(0); } to { transform: scaleY(1); } }
@media (prefers-reduced-motion: reduce) { .dev-fold-mark path { animation: none; } }
/* Reduce motion setting (#6510): the same, when Settings asks for it. */
:where(html[data-motion="reduce"]) .dev-fold-mark path { animation: none; }

.dev-ws-new {
  margin-inline-start: 6px; font-size: 10px; font-weight: 700; color: var(--accent); background: var(--accent-tint);
  padding: 1px 5px; border-radius: 6px; vertical-align: middle;
}
/* A card the server has themes for but has not placed yet: on its way, not unfit. */
.dev-ws-placing {
  margin-inline-start: 6px; font-size: 10px; font-weight: 600; color: var(--text-muted);
  border: 1px dashed currentColor; padding: 0 5px; border-radius: 6px; vertical-align: middle; opacity: .8;
}
/* ── Open: the card, at the size the Board draws it ─────────
   There is nothing to join here any more. The wrapper renders EITHER the
   compressed row or this entry, never both, so the entry keeps the ordinary
   `#dev-workshop .dev-feed-entry` sheet (above) and the dense card inside it
   keeps every bit of chrome the Board gives it: the 36px icon, the meta line,
   the full-width status bar, the facts line, the menu.

   #1799 did the opposite — it kept the row as a head and hid the card's head,
   meta and status band so they would not repeat it. That made the open state a
   third object belonging to neither size. Those four rules are gone rather
   than adjusted; the row IS the compressed representation of this card, and
   the way to show the card is to show the card. */
/* ── "Open card", and what it opens ────────────────────────
   The toggle sits in the card's action band, after its own pills and before
   the hamburger (card/dev-card.tsx's `actionEnd`), on the Workshop and the
   Board alike; on the Board it is a link to the item's page.

   On the Workshop it reveals the topic screen's own sections — the ledger,
   the About sheet with its before/after tiles, the transcript — drawn by the
   same components from the same view model, indented under the card so a
   reader can see where the item ends. Not the comment threads: the sheet
   already carries both, above and below this block. */
.dev-ws-open-btn { white-space: nowrap; text-decoration: none; }
.dev-ws-more { font-size: 13px; color: var(--text-muted); padding: 2px 10px; }
.dev-ws-theme-more { font-size: 13px; color: var(--text-muted); padding: 4px 10px 0; }
/* The row's vote button, at the right end of its last line (.dev-ws-row-band). */
.dev-ws-row-trailing { display: inline-flex; align-items: center; flex-shrink: 0; }
/* ── The Board's columns fold their cards too (#1787) ─────────
   The same row, the same sheet and the same fold (card/fold.tsx), inside a
   kanban column. The column's own `space-y-2` (4px, see #dev-kanban above)
   is the rhythm between rows, so the wrapper's 4px is not added to it. The
   open card is the column's tile as it always was; the sheet around it is
   transparent here — the Workshop's frosted plane is scoped to #dev-workshop
   on purpose — and it draws nothing else: the Board's "Open card" is itself
   the link to the item's page, so the sheet has no line under the card. */
#dev-kanban .dev-ws-rowwrap { margin-bottom: 0; }
#dev-kanban[data-cards-open] > .dev-kanban-col > .dev-kanban-lead { margin: 0 2px 8px; }
.dev-ws-foot-note { font-size: 12px; color: var(--text-muted); text-align: center; padding: 6px 0 2px; }

/* Illustration variants share one frame; only visibility changes with theme. */
.illustration-dark { display: none; }
.dark .illustration-light { display: none; }
.dark .illustration-dark { display: block; }
.home-discover-card[data-preview-theme="light"] .illustration-light { display: block; }
.home-discover-card[data-preview-theme="light"] .illustration-dark { display: none; }
.home-discover-card[data-preview-theme="dark"] .illustration-light { display: none; }
.home-discover-card[data-preview-theme="dark"] .illustration-dark { display: block; }
.home-discover-card[data-preview-theme="light"] .home-discover-name { color: #1c1c1e; }
.home-discover-card[data-preview-theme="light"] :is(.home-discover-blurb, .home-discover-meta, .home-discover-facts) { color: #48484a; }
.home-discover-card[data-preview-theme="dark"] .home-discover-name { color: #eaeaea; }
.home-discover-card[data-preview-theme="dark"] :is(.home-discover-blurb, .home-discover-meta, .home-discover-facts) { color: #8e8e93; }
.home-discover-card[data-preview-theme="light"] .card-add-btn:not([data-join="joined"]) { background: white; color: #0062cc; border-color: #e3e3e6; }
.home-discover-card[data-preview-theme="dark"] .card-add-btn:not([data-join="joined"]) { background: #2c2c2e; color: #5aa9ff; border-color: #48484a; box-shadow: none; }

/* ═══════════════════════════════════════════════════════════════════
   #platform-tabs — the shell's five sections, as a permanent bar
   ═══════════════════════════════════════════════════════════════════

   The markup is frontend/src/features/nav/tab-bar.tsx, and its header
   carries the product argument: every host this shell is modelled on keeps
   a flat per-mini-app menu AND a permanent bar of its own sections, and
   this shell had only the menu, so the platform's places were sitting in
   the app's list for want of anywhere else to put them.

   What lives HERE rather than in the component is everything that has to
   agree with a second rule somewhere else: the bar is out of flow, so
   nothing reserves its space automatically, and the space it covers is
   held open by the screens above it. Two rules, one number. */

/* THE BAND THE BAR COVERS, read by the screens above it.

   Declared on `body` in both branches, NOT on `:root`, and that is not a
   style choice. A custom property's `var()`s are substituted at
   computed-value time on the element the property is DECLARED on, and the
   result is what inherits — so a token declared on `:root` that reads
   `--platform-tabs-h` would bake in `:root`'s value and never see the
   override below. Both declarations sit on the same element so the cascade
   picks between them the ordinary way.

   `body:has(#platform-tabs:not(.hidden))` is the route test, and it is the
   same shape as the wallpaper's a few thousand lines up: the bar's own
   `hidden` class IS the fact, published once by the visibility store and
   applied by the island (features/nav/tab-bar.tsx), so no second flag has
   to be kept in step with it. A `:has()` that watches one id for one class
   is as cheap as that selector gets.

   IT INCLUDES THE INSET, unlike `--ws-bar` above, and for the opposite
   reason. The Workshop's pill floats clear of the bottom edge, so the strip
   beneath it is held open by the scroller and counting it twice was the
   #4149 bug. This bar is fused to the edge — it spends the inset itself, as
   its own lower padding — so the clearance a screen needs above it is the
   bar's FULL outer height. Every consumer therefore takes
   `max(--platform-tabs-h, --platform-safe-bottom)`: the bar's box when the
   bar is there (its padding already covers the strip), the bare strip when
   it is not. One expression, both states, no double count either way.

   `html:not(.un-kb)` because the keyboard takes the bar with it — see the
   display rule below. */
body {
  /* The BAR's own outer height, which the parked strip rests on. */
  --platform-bar-h: 0px;
  /* Everything at the foot of the screen, stacked — what a surface above has
     to clear. With no strip it is the bar; with one it is both. */
  --platform-tabs-h: 0px;
  /* HOW WIDE THE RAIL IS, which is not the same question as how much width
     it RESERVES — and keeping the two apart is what lets it float. A PEEKED
     rail (over an app, or over a screen whose rail is folded) is drawn at its
     full width while the content under it reserves nothing; a rail that had
     one number for both was 17px of padding and a border, because the
     reserved figure was 0. A constant, never overridden.
     #4417: 76px, THE STRIP. It was a 224px rail of rows and Recents. From
     768px the sidebar of rows sets it again (212px, its own block below),
     and what the strip's column beside it held is nested in the sidebar. */
  --platform-rail-full: 76px;
  /* WHAT IT RESERVES. 0 on a phone, where the five tabs are a bar at the foot
     and cost width nothing; 0 again on a desktop while the rail is folded or
     peeking, where the content takes the width back. */
  --platform-rail-w: 0px;
  --platform-gutter: 0px;
}
/* THE USABLE BOX: WHERE CONTENT CAN GO, DECIDED ONCE (iPhone Duo,
   1 November 2026). Widths summed from 100vw at each site did not know
   about the Duo's column of system chrome: Main's room counted the column
   twice, and a notice capped at `100vw - 24px` and centred on the window
   ran under the clock. Every width a surface takes from the window is
   taken from one of the two boxes below instead, and
   tests/usable-box.test.js fails on a `100vw` anywhere else in this file,
   and on one in a class string or an inline style under frontend/ or
   public/js/.

   WHAT IS TAKEN OFF, AND ON WHICH SIDE:
   - the RAIL'S RESERVED WIDTH, on the left: `--platform-rail-w` above, the
     sidebar's 212px from 768px, and 0 on a phone, folded or peeking;
   - the DUO'S COLUMN on the side it is on (THE SIDE STRIP:
     `data-side-strip`, `--platform-strip-w`), or the folded Duo's narrow
     corner (THE SIDE CORNER: `data-side-corner`, `--platform-corner-w`).
     These are the side safe-area insets as the shell honours them:
     frontend/src/lib/side-strip.ts reads env(safe-area-inset-left/right)
     once and publishes only what the body pads out. A phone's two-sided
     landscape notch and a narrow camera cutout are kept clear nowhere in
     the shell, so not here either, and the side panel's own document
     drops the column it does not touch.

   TWO BOXES, because a surface either belongs to the page or floats over
   it:
   - `--platform-usable-left`, `-right` and `-w`, THE PAGE'S BOX, beside
     the rail and the column. A width for content (`--ai-room`, Main's
     column) and a surface fixed to the window on the page's behalf (the
     language notice) take it.
   - `--platform-float-left`, `-right` and `-w`, A FLOATING SURFACE'S BOX:
     a menu, a popover, a lightbox, a dialog (what `--dc-float-fill`
     paints). It floats over the rail, so only the column is taken off.
   Off the Duo the float box is the window; on a phone the two are one.

   WHY 100vw HERE, AND NOWHERE ELSE. A custom property's `100%` would
   resolve against each reader's own containing block, so only a viewport
   unit names the window for every reader alike. `100vw` would count a
   classic scrollbar on the root, and the root never draws one: `html,
   body` are `overflow: hidden` (the bounded shell), and the one mode in
   which the document scrolls, `html[data-browser-scroller]`, is a touch
   browser's, whose scrollbars overlay the page and take no width. A box
   inside a scroller that does draw one sizes against that scroller (a
   percentage, or plain flow) instead, as the Workshop's stage pane does
   above ("The stage pane runs edge to edge").

   On body for the reason the band tokens are (the head of this section):
   these read `--platform-rail-w` as body sets it. The column's side is
   the attribute rules after this one, on body too. */
body {
  --platform-float-left: 0px;
  --platform-float-right: 0px;
  --platform-float-w: calc(100vw - var(--platform-float-left) - var(--platform-float-right));
  /* The rail comes off whichever side it stands on: the left, or in Arabic
     the right (--rtl-sign is -1 there, so one factor is 0 and the other 1). */
  --platform-usable-left: calc(var(--platform-float-left) + var(--platform-rail-w, 0px) * (1 + var(--rtl-sign)) / 2);
  --platform-usable-right: calc(var(--platform-float-right) + var(--platform-rail-w, 0px) * (1 - var(--rtl-sign)) / 2);
  --platform-usable-w: calc(var(--platform-float-w) - var(--platform-rail-w, 0px));
}
/* The column, on the side the body pads it out: at every width for the
   strip, and on a phone for the corner, exactly as THE SIDE STRIP and THE
   SIDE CORNER pad the body. The two are never set together (side-strip.ts). */
html[data-side-strip="left"] body { --platform-float-left: var(--platform-strip-w, 0px); }
html[data-side-strip="right"] body { --platform-float-right: var(--platform-strip-w, 0px); }
@media (max-width: 767px) {
  html[data-side-corner="left"] body { --platform-float-left: var(--platform-corner-w, 0px); }
  html[data-side-corner="right"] body { --platform-float-right: var(--platform-corner-w, 0px); }
}
/* `:not(.platform-tabs-peek)` because a PEEKING bar reserves nothing: the
   router still says the bar is hidden (see features/nav/tab-bar.tsx), the app
   under it is full width, and a rail that claimed 224px on the way in would
   reflow the app under the pointer that revealed it. */
html:not(.un-kb) body:has(#platform-tabs:not(.hidden):not(.platform-tabs-peek)) {
  --platform-bar-h: calc(56px + var(--platform-tabs-inset, 0px));
  --platform-tabs-h: calc(56px + var(--platform-tabs-inset, 0px));
}
/* THE PARKED STRIP ADDS ITS OWN BAND, and only while the bar is there to sit
   on: the strip is offered on the platform's screens and never inside a
   running app, which is the one route where resuming that app would be a
   shortcut to where you already are. Both terms are spelled out rather than
   summed from the token above, because a custom property's var()s resolve on
   the element the property is DECLARED on — see the note at the head of this
   section — so `calc(52px + var(--platform-bar-h))` here would read the 0px
   from the plain `body` rule rather than the value the selector above sets. */
html:not(.un-kb) body:has(#platform-tabs:not(.hidden):not(.platform-tabs-peek)):has(#platform-parked:not(.hidden)) {
  --platform-tabs-h: calc(52px + 56px + var(--platform-tabs-inset, 0px));
}

/* KEYBOARD UP, BAR GONE. The same reasoning `html.un-kb .platform-safe-scroll`
   states for the home-indicator strip: a bar pinned to the bottom of the
   viewport with a keyboard over it is either behind the keyboard or riding
   on top of it, and neither is navigation. `display: none` rather than the
   `hidden` class because the class has an owner (the island) and this is a
   presentation rule, not a route fact — the bar comes back with no state to
   restore the moment the keyboard drops. The reservation above is already
   off, because its selector excludes this state.

   ON A PHONE ONLY (iPhone Duo, 1 November 2026). From 768px the bar is the
   sidebar down the left of the window, beside the page and not at its foot:
   the keys cover its lower end and nothing rides on them. Hidden there, the
   page took the sidebar's width back the moment a field was focused, slid
   212px left under the reader, and slid back when the keyboard dropped. */
@media (max-width: 767px) {
  html.un-kb #platform-tabs {
    display: none;
  }
}

/* KEYBOARD UP IN THE HOMEROOM APP, BAR AND STRIP GONE THERE TOO (first-session
   run, 4 October 2026). `un-kb` is the kit's answer to "do the keys COVER the
   page", and in the phone app they never do: its Flutter shell resizes the
   web view to end at the keyboard, so the page just gets shorter, the kit
   measures nothing covered, and `un-kb` stays off. The bar and the Resume
   strip, fixed to the foot of a page that now ends at the keys, were drawn on
   the keyboard and over the composer, half covering Send, while every screen
   still reserved their band. `platform-kb-open` is the page's own answer
   (frontend/src/lib/keyboard-open.ts: a text field focused and the visible
   page shorter than at rest by a keyboard's height), written on a phone
   layout only, and it takes the same two bars away so the composer sits
   directly on the keys. `!important` on the band for the reason the side
   panel's document gives below: the rules that reserve it key off the bars'
   own classes, not this one. The home-indicator strip is behind the keys as
   well, so the safe-area clearances drop exactly as they do under `un-kb`.
   Everything returns the moment the field lets go. */
@media (max-width: 767px) {
  html.platform-kb-open body {
    --platform-bar-h: 0px !important;
    --platform-tabs-h: 0px !important;
  }
  html.platform-kb-open #platform-tabs,
  html.platform-kb-open #platform-parked {
    display: none;
  }
  html.platform-kb-open .platform-safe-scroll {
    padding-bottom: 0 !important;
  }
  html.platform-kb-open .platform-safe-bar {
    padding-bottom: 0.5rem !important;
  }
}

/* A FULL-SCREEN SURFACE KEEPS ITS FIELD AND ITS BUTTON ABOVE THE KEYS
   (iPhone 17 simulator, iOS 26 Safari, 5 October 2026). The sign-in sheet's
   Sign in button sat behind the keyboard with the password field half under
   the keyboard's floating bar, and the make screen's "Make it" sat under the
   same bar. Both are `fixed inset-0`, which Safari leaves at the page's full
   height with the keys, the address pill and the form bar over its foot, and
   which iOS pans up to reveal a tapped field. The band of the page that is
   actually visible while the keyboard is open is the pan above it
   (`--platform-vv-top`, lib/visual-viewport.ts) and `--platform-kb-cover`
   below it (lib/keyboard-open.ts; the visual viewport ends above the pill
   and the bar, so whatever iOS draws over the keys is in the cover, and
   nothing here assumes a height for it).

   - `.platform-kb-surface`, a full-screen column (the make screen): padded
     into the band, so its bar stays at the top of what is seen and its
     scroller ends where the keys begin. The ground still paints the whole
     box, so the pill and the bar float over the screen's own wallpaper.
   - `.platform-kb-sheet`, a bottom sheet inside a full-screen root (the
     sign-in sheet): its foot on the band's foot and its height capped to the
     band, so it rides on the keys and scrolls inside.

   In the Homeroom app the web view itself ends at the keys, so both are 0
   and nothing moves. Phone only, like the rest of this block. */
@media (max-width: 767px) {
  html.platform-kb-open .platform-kb-surface {
    padding-top: var(--platform-vv-top, 0px);
    padding-bottom: var(--platform-kb-cover, 0px);
  }
  html.platform-kb-open .platform-kb-sheet {
    bottom: var(--platform-kb-cover, 0px);
    max-height: calc(100% - var(--platform-vv-top, 0px) - var(--platform-kb-cover, 0px) - 12px);
    /* The home indicator is behind the keys. */
    padding-bottom: 1.25rem;
  }
}

/* THE SHEET'S BUTTON CLEARS SAFARI'S TOOLBAR WITH THE KEYS DOWN (#4593).
   Mobile Safari, the release mail's "Create my account": the sign-in sheet
   opened over the story with its Continue below the fold. The sheet's root
   is `fixed inset-0`, and Safari 26 runs that box on under its floating
   toolbar whenever the toolbar is tucked away or drawn over the page, so the
   panel's foot (`bottom-0`), where the step's button is, sat behind it. The
   story reserves the same toolbar under its own foot (`100lvh - 100svh`,
   above). Here the panel stands on the small viewport's foot instead: its
   `bottom` is however far the root runs past `100svh` (the root's height
   less the viewport with every toolbar showing, 0 when the root already
   ends above the toolbar), and its height is capped to 92% of that same
   small viewport. Where no toolbar comes and goes (the Homeroom app, an
   installed app, Android with its bar at the top) `100svh` is the root's
   height and nothing moves. With the keys up, the rule above (more
   specific) still puts the foot on the keys. Phone only: the desktop card
   is centred. */
@media (max-width: 767px) {
  @supports (height: 100svh) {
    html .platform-kb-sheet {
      bottom: max(0px, calc(100% - 100svh));
      max-height: 92svh;
    }
  }
}
/* THE SIGN-IN SHEET RUNS TO THE FOOT OF THE SCREEN (Evan, 10 Oct 2026,
   iPhone Safari). Stood on the small viewport's foot (above), the panel ended
   over a band of the dim, and under that the page showed undimmed beneath
   Safari's toolbar: a card floating over the screen's foot rather than a
   sheet rising from it. Its own fill now carries on below it to past the
   foot of the screen, as a shadow (the panel scrolls, and a scroller clips
   anything drawn inside it, but not its own shadow): offset 20px down so
   the rounded corners stay round, and spread wide enough to clear the screen
   below and at both sides. Nothing in the panel moves. The hairline is drawn
   along the top only, where the sheet meets the dim. Phone only, as above. */
@media (max-width: 767px) {
  [data-sign-in-sheet] > .platform-kb-sheet {
    box-shadow: inset 0 1px 0 var(--app-sheet-line), 0 calc(50vh + 20px) 0 50vh var(--dc-sheet-solid);
  }
}

/* A FULL-SCREEN SURFACE THAT LEAVES THE PLATFORM HEADER SHOWING (#4195).
   The make and made screens opened from Create are `fixed` from the header's
   foot down rather than `inset-0` over it, so the header's back, bell and
   menus stay where they always are (first-session/make.tsx MAKE_ROOT). The
   tab bar stays covered. With the keyboard up, the band the
   `.platform-kb-surface` rule above pads into starts at the pan
   (`--platform-vv-top`) from the page's top, and this box starts the
   header's height further down, so only the part of the pan past that is
   padding here. */
.platform-under-header {
  top: calc(var(--browser-banner-h, 0px) + var(--platform-header-h) + var(--platform-safe-top));
}
@media (max-width: 767px) {
  html.platform-kb-open .platform-kb-surface.platform-under-header {
    padding-top: max(0px, calc(var(--platform-vv-top, 0px) - var(--browser-banner-h, 0px) - var(--platform-header-h) - var(--platform-safe-top)));
  }
}
/* THE MAKE AND MADE SCREENS RUN ON UNDER SAFARI'S TOOLBAR (Evan, 10 Oct
   2026, iPhone Safari). Both are `fixed` boxes with their own scroller, and
   with Safari's toolbar showing such a box ends above it: what scrolled was
   cut off there, Make it in half, with the page's plain ground below. Now
   the box runs on 200px past its foot, under the toolbar and off the foot of
   the screen, so what scrolls carries on under the toolbar as a page does,
   and the scroller keeps those 200px after its last line, so the end still
   scrolls up to where it stopped before. A fixed length, not the viewport
   units: on an iPhone 13 mini in Safari 26 `100lvh` came out shorter than
   the box itself, so `100% - 100lvh` extended nothing (#4691's first try).
   200px is more than the toolbar and the home indicator together. In a
   phone browser on iOS, with the keys down: the keyboard surface measures
   its padding against the box as it was.

   THOSE 200PX ARE A SPACER, NOT PADDING (onboarding run two, 12 Oct 2026,
   iPhone 17 simulator, Safari 26, measured on a copy of the screen): Safari
   paints a fixed box only down to the foot of its layout viewport (714px
   tall there, ending above the toolbar), whatever runs on past it, so what
   lies in the last 200px is never seen. And WebKit leaves a flex
   scroller's end padding out of what it scrolls: the scroller was 862px
   with 862px to scroll, so Make it, once a starting idea had grown the
   form, sat under the toolbar with nothing to scroll it up. The page lock
   (#4909) also keeps Safari from collapsing its toolbar, which a drag on
   the page used to. An empty last item is counted: with it the same
   screen scrolled 962px, and Make it came up clear of the toolbar. */
@media (max-width: 767px) {
  html.un-ios.web-browser-chrome:not(.platform-kb-open) :is([data-first-session-make], [data-first-session-made]) {
    bottom: -200px;
  }
  html.un-ios.web-browser-chrome:not(.platform-kb-open) :is([data-first-session-make-scroll], [data-first-session-made])::after {
    content: '';
    flex: 0 0 200px;
  }
}
/* AND OVER THEIR TOP, UNDER THE STATUS BAR (onboarding run, 12 Oct 2026,
   iPhone 17 Safari, #4893). Safari draws the page behind the status bar,
   above these boxes as it does under its toolbar below them, and what showed
   there, behind the clock, was Home's cards once it had scrolled. The page
   holds still under them now (`platform-page-locked`, above), and their
   ground also runs on 200px above them, as the box's own shadow in the
   ground's colour: a scroller (the made screen is one) clips what it holds
   but not its own shadow, as the sign-in sheet's foot has it, and nothing in
   the box moves, so the wallpaper's star and washes stay where they are.
   Where a box already starts at the top of the glass the shadow is off the
   screen. Not from Create, whose screens begin under the platform header. */
@media (max-width: 767px) {
  html.un-ios.web-browser-chrome :is([data-first-session-make], [data-first-session-made], [data-first-session-welcome]):not(.platform-under-header) {
    box-shadow: 0 -200px 0 0 var(--home-ground, #f4f2e4);
  }
}

.platform-tabs {
  /* FIXED TO THE REAL VIEWPORT. `.dev-ws-tabs` above documents the three
     rounds this saves: `sticky` puts a bar's resting place at the mercy of
     whatever container it sits in, and every one of those inputs behaves
     differently in a real iOS PWA than in a headless Chromium. This one has
     a second reason on top — on `html[data-browser-scroller]` routes the
     DOCUMENT is the scroller and `body` is `height: auto`, so a flex child
     at the end of the column scrolls away with the page.

     No portal, unlike the Workshop's bar: this is a direct child of <body>
     and nothing between here and the viewport carries a `backdrop-filter`,
     a `transform` or a `filter`, so `fixed` already means the screen. */
  position: fixed;
  inset-inline-start: 0;
  inset-inline-end: 0;
  bottom: 0;
  /* UNDER the panels, sheets and dialogs (which sit at 40 and above) and
     OVER the screens. A tab bar that a sheet does not cover reads as part
     of the sheet; one the screens paint over is not a bar at all. */
  z-index: 30;

  display: grid;
  grid-template-columns: repeat(5, 1fr);
  align-items: stretch;
  padding: 0 4px;
  /* THE INSET, SPENT EXACTLY ONCE, here. `--platform-tabs-h` above counts on
     this and the screens count on that. `--platform-tabs-inset` is the inset
     itself everywhere but iOS, where the bar sits lower — see below. */
  padding-bottom: var(--platform-tabs-inset);
  /* A DRAG THAT STARTS ON THE BAR MOVES NOTHING (#2771). Every tab is a tap;
     nothing here scrolls. In an installed iOS app a vertical drag that begins
     on a surface with no scroller under it rubber-bands the whole document,
     and the bar — fixed to that document's viewport — rides up with it,
     showing the page's foot beneath it. Taps still land: `none` only
     withholds panning and zooming. */
  touch-action: none;

  /* EDGE TO EDGE AND FROSTED, not the Workshop's floating pill. The two bars
     are different kinds of thing and the shapes should say so: the Workshop's
     switches between three views OF one screen, so it floats over that
     screen's content; this one switches between screens, so it is a wall at
     the bottom of the app with the content ending against it. Fusing it to
     the edge is also what lets it spend the home-indicator inset itself,
     which is what keeps the arithmetic above to one number. */
  border-top: 1px solid var(--app-sheet-line);
  background-color: var(--dc-sheet-fill);
  backdrop-filter: var(--dc-frost);
  -webkit-backdrop-filter: var(--dc-frost);
}
/* FAKED GLASS: THE TAB BAR (and the header, "…AND THE HEADER" above). The
   two places the glass carries the look, so they keep it, without a filter.
   The wallpaper is fixed, so what the glass showed over it never changed:
   the tint over the washes behind the bar (a 24px blur erases the grain and
   the star, and the washes are soft already). So the bar paints exactly
   that, once: a viewport-sized fixed layer of the same `--home-washes` the
   wallpaper draws, so it lines up with the body's pixel for pixel, under the
   glass tint, and clipped to the bar by `clip-path`, which, unlike
   `overflow`, also clips a fixed descendant (the usual stand-in for
   `background-attachment: fixed`, which iOS ignores). Nothing is sampled per
   frame, so scrolling costs nothing. The one thing it gives up is page
   content showing through as it passes under: that is the part that cost a
   filter pass on every frame. Nothing between the bar and the viewport has a
   transform or a filter (see `.platform-tabs` above), so `fixed` is the
   screen. */
.platform-tabs {
  background-color: transparent;
  clip-path: inset(0);
}
/* THE ONE FAKED LAYER, for every surface that fakes its glass: the tab bar,
   the parked strip, the header and the signed-out landing header. Each sets
   the transparent background and the clip on itself; `--fake-glass-tint` is
   its glass fill (the pane fill unless it says otherwise). Resolved here, on
   the surface, so it reads the route's --home-washes (set on <body>); a
   route with no wallpaper gets the solid plane colour. */
.platform-tabs::before,
.platform-parked::before,
body:has(:is(#home-screen, #leaderboard-screen, #profile-screen,
             #settings-screen, #messages-screen, #workshop-screen, #weekly-digest-screen, #communities-screen, #ai-screen,
             #profile-proposals-screen):not(.hidden)) #platform-header::before,
body:has(#app-view:not(.hidden)[data-app-surface="platform"]) #platform-header::before,
html[data-browser-scroller] #landing-header::before {
  content: '';
  position: fixed;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background:
    linear-gradient(var(--fake-glass-tint, var(--dc-sheet-fill)), var(--fake-glass-tint, var(--dc-sheet-fill))),
    var(--home-washes, var(--dc-sheet-solid));
}
/* THE HAIRLINE GOES BACK ON TOP. The layer paints over its surface's own
   border (a stacking context's negative layer comes after its background and
   border), so a bar whose edge is a border redraws it above the layer. */
@media (max-width: 767px) {
  .platform-tabs::after,
  .platform-parked::after {
    content: '';
    position: absolute;
    top: -1px;
    inset-inline-start: 0;
    inset-inline-end: 0;
    height: 1px;
    background: var(--app-sheet-line);
    pointer-events: none;
  }
}
/* THE DOCKED DESKTOP RAIL NEEDS NO FAKE. The page is laid out beside it, not
   under it, so only the fixed wallpaper is ever behind it and its own
   translucent fill is exactly the glass without the blur; its edge borders
   draw as they always did. (The peeked rail floats over the page, so it is
   solid; see `.platform-tabs.platform-tabs-peek`.) The parked row sits in
   the rail here and is transparent there, so it drops its layer too. */
@media (min-width: 768px) {
  .platform-tabs {
    background-color: var(--dc-sheet-fill);
    clip-path: none;
  }
  .platform-tabs::before,
  .platform-parked::before { content: none; }
  .platform-parked { clip-path: none; }
}

/* THE BAR SITS LOWER ON iOS (#2766). The inset under it there is the
   home-indicator strip, 34px on a Face ID iPhone, and the indicator is a 5px
   line drawn in the bottom 13px of it: nothing is under the upper part but
   more of the page. Spending all 34 as padding floated the five tabs a full
   strip above the edge, well above where the system's own tab bars put
   theirs. This spends all but 14px of it, which keeps the glyph and label
   15px clear of the indicator and drops the bar by that much. `max()` so a
   thin or absent inset (Safari with its toolbar up, a landscape phone) is
   never driven negative.

   iOS ONLY, and not by accident. On Android the same token measures the
   system navigation bar — three real buttons, or a gesture handle the
   system keeps clear of content — so borrowing from it would put the tabs
   under the system's own controls, which is the #2755 report in reverse.

   Declared on <html> (the kit's `un-ios` class is on it by the first paint)
   so it resolves beside `:root`'s inset; the bar's padding and both band
   tokens above read it, so the screens clear exactly the bar that is drawn. */
html.un-ios {
  --platform-tabs-inset: max(0px, calc(var(--platform-safe-bottom, 0px) - 14px));
}

/* THE WHOLE BAR ON AN INSTALLED ANDROID APP (#2755). An installed Android
   web app can be drawn edge to edge, under the system navigation bar, where
   Chrome's `safe-area-inset-bottom` can read 0 or arrive late while its
   `safe-area-max-inset-bottom` (Chrome 135+) carries the bar's full height. With
   an inset of 0 the bar's padding is 0 and the navigation bar paints over its
   lower half: the truncated bar in the report. Taking the larger of the two
   is exact where the inset is right (they agree, there is no browser chin in
   an installed app) and whole where it is not. A browser without the second
   variable falls back to 0px, which leaves the first untouched.

   STANDALONE ONLY. In a browser tab the max variable is the height the inset
   grows to when Chrome's bottom chin collapses, and reserving it while the
   chin is still up would stack the bar on top of a strip the browser already
   keeps clear. Both declarations restate the kit form so `?shot=safe-bottom`
   still drives them; the second is the platform surface's own restatement
   (see `#app-view[data-app-surface="platform"]`), which would otherwise win
   inside it. */
@media (display-mode: standalone), (display-mode: fullscreen) {
  html.un-android,
  html.un-android #app-view[data-app-surface="platform"] {
    --platform-safe-bottom: max(var(--un-safe-inset-bottom, env(safe-area-inset-bottom, 0px)), env(safe-area-max-inset-bottom, 0px));
  }
}

/* THE STATUS BAR ON AN INSTALLED ANDROID APP (#5970), the top twin of the
   rule above. The same edge-to-edge app can report `safe-area-inset-top` as
   0 while `safe-area-max-inset-top` (Chrome 135+) carries the status bar's
   height. With an inset of 0 the header's padding is its ordinary 8px and
   the title and the bell are drawn under the clock, the signal and the
   battery icons — the overlap in the report. Taking the larger of the two is
   exact where the inset is right (they agree in an installed app) and whole
   where it is not. A browser without the second variable falls back to 0px,
   which leaves the first untouched.

   THE TOKEN, NOT A NEW ONE: every top-inset rule reads
   `--un-safe-inset-top` (the #2305 header padding, `--platform-safe-top` on
   :root, the kit's `.un-safe-top*` classes), so one declaration on <html>
   reaches them all with no rule restated. The value is `env()` only, never
   `var(--un-safe-inset-top)`, so it cannot reference itself. The review
   state (`?safe-bottom=1`) writes the same property as an inline style on
   <html>, which wins over this rule.

   STANDALONE AND NATIVE WEBVIEW, NEVER A BROWSER TAB (#2509): the same
   reasoning as the bottom rule, and `html.web-browser-chrome` keeps its
   `--platform-safe-top: 0px` and 0.5rem clamp below. iOS is untouched —
   `un-android` is the kit's device class and never lands there. */
@media (display-mode: standalone), (display-mode: fullscreen) {
  html.un-android {
    --un-safe-inset-top: max(env(safe-area-inset-top, 0px), env(safe-area-max-inset-top, 0px));
  }
}
html.un-android.in-native-webview:not(.web-browser-chrome) {
  --un-safe-inset-top: max(env(safe-area-inset-top, 0px), env(safe-area-max-inset-top, 0px));
}

/* A GLYPH OVER ITS LABEL, 56px tall: 8 of padding, 24 of glyph, 3 of gap, a
   13px line, 8 again. Above the 44px minimum the shell holds every phone
   target to, which this has to clear by a margin — it is the platform's
   primary navigation and it is the control nearest the bottom edge, where a
   thumb is least precise.

   THE LABEL STAYS. A five-icon bar with no words asks the viewer to learn
   five glyphs, and two of these five (Workshop, Discover) name things that
   have no conventional icon at all. The same argument `.dev-ws-tab` makes
   one screen down: at 11px under a glyph the glyph carries the scanning and
   the word settles what the glyph cannot. */
.platform-tab {
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  min-width: 0;
  height: 56px;
  padding: 0 2px;
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: .01em;
  line-height: 13px;
  text-decoration: none;
  white-space: nowrap;
  overflow: hidden;
  -webkit-tap-highlight-color: transparent;
}

/* THE ACCENT, the `--lit-*` tokens: where you are, among the places you
   could be. It was the header's periwinkle; the accent is the product's one
   blue, and the lit tab is the one place on the bar that says "here".
   `aria-current` is the only marker the component renders, so it is the only
   one this reads. */
.platform-tab[aria-current="page"] {
  color: var(--lit-ink);
}

/* THE LIT TAB'S MARKER (#2824) — the Workshop's sliding pill, on the phone's
   bar. The colour above was the only thing that said which tab you were on,
   and at 11px under a glyph that is easy to miss; the Workshop's strip one
   screen down already answers the same question with a blue fill that slides
   between tabs, so this is that answer with the same tokens and the same
   curve (`.dev-ws-tab-marker`).

   Its geometry is measured off the lit tab's GLYPH AND LABEL (useTabMarker
   and markerBoxFor in frontend/src/features/nav/tab-bar.tsx), so this rule
   carries none: the transform is the only thing that moves. It hugs them,
   5px over the glyph, 8px either side of the wider of the two and 3px under
   the label, and the tab under it stays the full cell, so the pill is sized
   by what it holds and the tap target by the bar. `.platform-tabs` is `position:
   fixed`, which makes it the containing block the offsets are measured in.

   Each tab is raised one step so the marker, rendered before them, paints
   behind the glyph and label rather than over them. */
.platform-tab {
  position: relative;
  z-index: 1;
}
.platform-tabs-marker {
  position: absolute;
  top: 0;
  inset-inline-start: 0;
  z-index: 0;
  border-radius: 16px;
  background: var(--lit-tint);
  box-shadow: inset 0 0 0 1px var(--lit-line);
  pointer-events: none;
  /* The slide scales from the corner the transform places (tab-bar.tsx,
     slideKeyframes). */
  transform-origin: 0 0;
  /* Hidden until measured, and while nothing is lit. */
  opacity: 0;
}
.platform-tabs-marker[data-marker-at] { opacity: 1; }
/* ONLY A SELECTION CHANGE SLIDES, as on the Workshop's strip: the first
   placement and a re-measure of the same tab land where they are.

   THE SLIDE IS NOT A TRANSITION HERE (#3259). It is an animation useTabMarker
   plays over the resting style (MARKER_SLIDE in tab-bar.tsx): the Workshop
   strip's duration and curve, but transform only. A transition of width
   and height ran on the main thread, and a press now starts the slide
   before the screen swap, whose long frames froze them mid-slide. Reduced
   motion is read there too, and gets no slide.

   IT SLIDES THROUGH A VIEW TRANSITION TOO. A tab change is a screen swap,
   and the swap runs as a view transition in which #platform-tabs is its own
   group whose OLD image is dropped and whose NEW image is shown at once
   (see the `platform-tabs` group near the top of this file). The new image
   is a live rendering of the element, not a still, so an animation started
   by the press plays inside it; this is the one part of the bar that moves
   on a tab change, and the label colour still pops, as it should. */

/* The badge's anchor. `position: relative` on the glyph's wrapper rather
   than on the whole tab, so the count sits on the ICON's corner and not on
   the tab's — the tab is 56px tall and a badge pinned to its top-right
   would float in the air above the glyph, away from the thing it is about.
   That is the PHONE's bar; the desktop rail dissolves this wrapper and draws
   the count at the row's end instead (#2912, in the desktop block below). */
.platform-tab-mark {
  position: relative;
  display: inline-flex;
  flex: none;
}
/* THE RAIL'S SETTINGS COG (#3120) is desktop-only: the phone's bar is five
   equal cells and Settings stays a row of the Profile screen there. The
   desktop block below is the only place that gives it a box. */
.platform-rail-settings {
  display: none;
}
.platform-tab-glyph {
  width: 22px;
  height: 22px;
  flex: none;
  /* 1.8, not the icon set's 2: at 22px a 2px stroke reads heavier than the
     11px label under it, and the glyph is the half of the tab that scans. */
  stroke-width: 1.8;
}
.platform-tab-label {
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  /* A LINE BOX THAT TRACKS THE FONT. `.platform-tab` sets `line-height: 13px`
     as an absolute, which is right for the 11px caption under a phone glyph
     and two pixels too short for the rail's 15px row — so with `overflow:
     hidden` on this element the tail of a `g` or a `p` was sliced off flat.
     Measured at 1280: an 18px ink box in a 13px line box, 2px over the edge.
     A unitless multiplier is the one value that is correct at both sizes. */
  line-height: 1.35;
}

/* "COMMUNITIES" AND "HOMEROOM BOT" ARE THE BAR'S LONG LABELS. Eleven
   letters at 11px is about a phone's fifth of the screen — a hair over it in
   some fonts — so at 390px Communities was clipped to "Communi…", and the
   bot's name (Evan, 29 Oct 2026) is 79px against a fifth's 67-70. These two
   labels tighten their tracking and are let out of their cells rather than
   cut: they are centred, and their seats are wider than the others.
   Narrower than 375px they drop half a point as well. Measured in the bar's
   own font: the bot's name has 4px to spare at 360 and 375, 8 at 390. The
   rail has room and is left alone.

   AND THE ROOM BESIDE IT GOES TO MESSAGES (overnight audit M01, 2 Nov 2026).
   With Messages lit its pill reaches 8px past its label, and on an iPhone 13
   mini that pill ran into "Homeroom bot" (2px apart in the bar's font, none
   in the phone's). Home's and You's words are short and their seats had 30px
   to spare, so they give some: Messages' seat is a little wider and the
   bot's a little more, and the pill now clears the bot's name by about 9px
   at 375 and 12 at 360. */
@media (max-width: 767.98px) {
  /* FIVE SEATS: Home · Communities · Homeroom bot · Messages · You (the
     Communities tab is back, 18 Nov 2026; One Home, #6361, had drawn four).
     Communities' seat, the second, and Homeroom bot's, the third, are a
     little wider than the others: they hold the longest words, and the
     bar's other labels (Home, Messages, and You) have room to spare. */
  #platform-tabs { grid-template-columns: 1fr 1.25fr 1.4fr 1.15fr 1fr; }
  :is(#platform-tab-workshop, #platform-tab-ai) { overflow: visible; }
  :is(#platform-tab-workshop, #platform-tab-ai) .platform-tab-label {
    letter-spacing: -.02em;
    overflow: visible;
    text-overflow: clip;
  }
}
@media (max-width: 374.98px) {
  /* The smallest phones: every label drops half a point and tightens, the
     cells lose their 2px sides, and the two wide seats widen a little less. */
  #platform-tabs { grid-template-columns: 1fr 1.2fr 1.35fr 1.15fr 1fr; }
  .platform-tab { padding: 0; }
  .platform-tab .platform-tab-label { font-size: 10.5px; letter-spacing: -.02em; }
}

/* TWO ORDERS, ONE MARKUP (Evan, 29 Oct 2026). The tabs' markup is the
   desktop sidebar's order, Home, AI, Messages, Communities, then you, so a
   keyboard on a desktop moves through them in the order it sees
   (features/nav/tab-bar.tsx TABS). The phone's bar is five cells, Home ·
   Communities · AI · Messages · You, which `order` lays out: Communities,
   fourth in the markup, is second on the bar, next to Home. The orders are
   below zero so the side strip's own (`order: 1` for the app you left, `2`
   for you, further down) still come after the four. You keeps the default,
   last in the markup.

   THE COMMUNITIES TAB IS DRAWN AGAIN (18 Nov 2026), on both bars. One Home
   (#6361) had hidden it here and kept your communities on Home; they are
   its page's now (`#communities`, features/communities/). */
@media (max-width: 767.98px) {
  #platform-tab-home { order: -5; }
  #platform-tab-workshop { order: -4; }
  #platform-tab-ai { order: -3; }
  #platform-tab-messages { order: -2; }
}

/* A QUIET GREY DISC, NOT THE BELL'S RED (#2912). This used to be the same
   red disc as #notifications-badge, on the argument that two counts on one
   screen should look alike. But an unread message was ALSO counted in the
   bell, so the same news arrived twice in the loudest colour on the screen,
   and the second red drew the eye away from the one that is the alarm. The
   bell keeps the red; this only says "there is something here".

   ONE MEANING PER BADGE since the 19 Oct 2026 polish board (#18): grey is
   NEW TO READ wherever it is (this, the channels' count beside it, a chat's
   row), the accent is WAITING ON YOU (votes), and red is the bell alone,
   which no longer counts plain messages at all: this count is theirs.

   Same size and place on the phone's bar, on the glyph's corner, with white
   ink. The fill is `--text-faint`, the neutral ramp's lightest step, which
   is #8e8e93 in BOTH themes: a mid grey that reads as a mark on the light
   bar and on the dark one without competing with either. The desktop rail
   moves the count off the glyph altogether (the desktop block below). */
.platform-tab-badge {
  position: absolute;
  top: -3px;
  inset-inline-start: calc(100% - 7px);
  min-width: 1.1rem;
  height: 1.1rem;
  padding: 0 4px;
  box-sizing: border-box;
  border-radius: 999px;
  background: var(--text-faint, #8e8e93);
  color: #fff;
  font-size: 0.65rem;
  font-weight: 700;
  line-height: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

/* THE COMMUNITIES TAB'S COUNT: every vote waiting on you, in the accent,
   because it asks for you. The quiet unread-channels count gives way to it
   on the same glyph. The tab's face is the people glyph, as every tab's is
   its own: the ring that named the community it was on went when the tab
   became a plain door to its page (18 Nov 2026). */
.platform-tab-votes {
  position: absolute; top: -4px; inset-inline-start: calc(100% - 8px);
  min-width: 1.1rem; height: 1.1rem; padding: 0 4px; box-sizing: border-box;
  border-radius: 999px; background: var(--accent); color: #fff;
  font-size: 0.65rem; font-weight: 700; line-height: 1;
  display: inline-flex; align-items: center; justify-content: center;
}
.platform-tab-mark:has(.platform-tab-votes) > #platform-tabs-badge-communities { display: none; }
/* V02 (audit, 2 Nov 2026): ON THE PHONE'S BAR THE TAB'S ONE NUMBER IS THE
   VOTES. The unread channels were a grey number in the same seat, so voting
   on the only change waiting turned a blue 1 into a grey 2, which read as
   the count growing. They are a grey dot there now: "something new to read"
   with no figure to mistake for the votes. The span keeps its text and its
   accessible name; the desktop rail, which gives the count its own pill at
   the row's end, keeps the number. */
@media (max-width: 767px) {
  #platform-tabs-badge-communities {
    top: -1px;
    inset-inline-start: calc(100% - 5px);
    min-width: 0;
    width: 9px;
    height: 9px;
    padding: 0;
    font-size: 0;
    color: transparent;
  }
}

/* THE MARK'S TILE (#2718). The artwork is a near-black squircle, which is a
   shade the dark bar behind it is also wearing — `bg-zinc-900` on
   #platform-header — so at 26px the tile's own edge disappears and the figure
   floats. The inset hairline is what draws it back, and it is the same
   hairline `.app-icon-tile` puts under an app's artwork one screen down, for
   exactly this reason. Light mode does not need it and gets it anyway: at 6%
   white over a near-black tile it is invisible on a light ground, so one rule
   is correct in both rather than two rules being correct in one each. */
.platform-mark-tile {
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.06);
  /* The file is 261px square drawn at 26: tell the decoder so, rather than
     letting it pick. */
  object-fit: cover;
}

/* direction: physical — from here to the `direction: logical` marker below,
   the rules stay physical on purpose and tests/rtl-logical-css.test.js skips
   them. A device's strip, corner and top band are sides of the HARDWARE, not
   of the prose: the native insets that set `data-side-strip` and
   `data-side-corner` are the inset of the SCREEN's left or right edge, so a
   strip on the right stays on the right when the language is Arabic and the
   content is padded off the right. Mirroring these would put the content
   under the camera. Everything outside this block is reading direction. */
/* ── THE NOTCH: insets on the sides that are not the Duo's column ─────────
   (iPhone held sideways in Safari, 1 November 2026.) A phone on its side
   reports the camera island's inset on BOTH sides (59px on an iPhone),
   which side-strip.ts deliberately does not call a column. Nothing kept
   clear of it: the layout audit (scripts/layout-audit) found the sidebar's
   icons and labels under the island, and with the phone turned the other
   way the page's right edge goes under it instead. From 768px, where the
   wide layout runs, the page keeps clear of both sides the way it keeps
   clear of the Duo's column (THE CONTENT STOPS AT THE STRIP, above): the
   body pads, the header spans the screen and pads its controls, and the
   fixed pieces (the sidebar, the bot tab's columns) clear it one by one.
   Only where no column or corner is set, so the Duo's own inset is never
   counted twice; 0 on every device without side insets. */
body {
  --platform-notch-left: 0px;
  --platform-notch-right: 0px;
}
@media (min-width: 768px) {
  html:not([data-side-strip]):not([data-side-corner]) body {
    --platform-notch-left: var(--un-safe-inset-left, env(safe-area-inset-left, 0px));
    --platform-notch-right: var(--un-safe-inset-right, env(safe-area-inset-right, 0px));
    /* THE USABLE BOX's sides, so a menu or a popover clears it too, and the
       bot tab's room (`--ai-room`) leaves it out. */
    --platform-float-left: var(--platform-notch-left);
    --platform-float-right: var(--platform-notch-right);
    padding-left: var(--platform-notch-left);
    padding-right: var(--platform-notch-right);
  }
  html:not([data-side-strip]):not([data-side-corner]) #platform-header {
    margin-left: calc(-1 * var(--platform-notch-left));
    margin-right: calc(-1 * var(--platform-notch-right));
    padding-left: calc(1rem + var(--platform-notch-left));
    padding-right: calc(1rem + var(--platform-notch-right));
  }
  /* The sidebar is fixed to the screen's left edge: its ground runs under
     the island and its rows start after it. The screens beside it already
     start after the notch (the body's padding), so what they reserve for
     it, `--platform-rail-w`, stays its own width. */
  html:not([data-side-strip]):not([data-side-corner]) .platform-tabs {
    width: calc(var(--platform-rail-full) + var(--platform-notch-left));
    padding-left: calc(6px + var(--platform-notch-left));
  }
  /* In Arabic the sidebar stands on the screen's right, so that is the side
     whose island its ground runs under. */
  html[dir="rtl"]:not([data-side-strip]):not([data-side-corner]) .platform-tabs {
    width: calc(var(--platform-rail-full) + var(--platform-notch-right));
    padding-left: 6px;
    padding-right: calc(6px + var(--platform-notch-right));
  }
}

/* ═══════════════════════════════════════════════════════════════════
   THE SIDE STRIP — iPhone Duo's column of system chrome (24 Oct 2026)
   ═══════════════════════════════════════════════════════════════════

   frontend/src/lib/side-strip.ts carries the argument and sets the two
   facts read here: `data-side-strip` on <html> (the side the column is on)
   and `--platform-strip-w` (its width, 84px on the Duo). Folded, the Duo's
   cover is 466x678 with the clock, the camera and the Wi-Fi ring stacked at
   the top of an 84pt column down its right edge; the inner display has the
   same column in landscape. The system's own apps keep their content to
   its left, stand their tab bar at its foot and hang their back button
   under the clock. This is the same arrangement for the shell.

   Nothing here applies without the attribute, and only a one-sided inset
   of 64px or more sets it, so every other phone, tablet and desktop is
   untouched.

   THE CONTENT STOPS AT THE STRIP, at every width. The body is the column
   every screen root, the header and the landing shell sit in, so padding it
   moves all of them at once, and the wallpaper (the body's own background)
   still runs under the clock the way a native app's ground does. Fixed
   surfaces are not in the body's content box and are placed one by one
   below. */
html[data-side-strip="right"] body {
  padding-right: var(--platform-strip-w, 0px);
}
html[data-side-strip="left"] body {
  padding-left: var(--platform-strip-w, 0px);
}
/* The signed-out shell is a fixed full-screen root of its own, so it pads
   itself: its ground still fills the screen, its content does not. */
html[data-side-strip="right"] #auth-landing-screen {
  padding-right: var(--platform-strip-w, 0px);
}
html[data-side-strip="left"] #auth-landing-screen {
  padding-left: var(--platform-strip-w, 0px);
}

/* THE HEADER RUNS ACROSS THE TOP, the strip included (Evan, 24 Oct 2026).
   It reaches into the body's padding and pads itself by the same width,
   so its ground and its rounded foot span the screen the way a phone's do
   while every control in it stays where it was, beside the strip. The
   camera and the clock sit over it there, as a status bar sits over a
   phone's header. */
html[data-side-strip="right"] #platform-header {
  margin-right: calc(-1 * var(--platform-strip-w, 0px));
  padding-right: calc(1rem + var(--platform-strip-w, 0px));
}
html[data-side-strip="left"] #platform-header {
  margin-left: calc(-1 * var(--platform-strip-w, 0px));
  padding-left: calc(1rem + var(--platform-strip-w, 0px));
}

/* THE NOTIFICATION SHEET IS FIXED TOO, so it is not in the body's content
   box: like the header, its ground spans the screen while its content
   stops beside the column. Every control moves together — the close disc,
   Mark all read, the search field, the tabs and the rows' ends — and on
   the Duo's wider inner screen, where the sheet docks as a side panel,
   the panel keeps its 26rem width and its content gets the padding
   instead. */
html[data-side-strip="right"] #notifications-sheet {
  padding-right: var(--platform-strip-w, 0px);
}
html[data-side-strip="left"] #notifications-sheet {
  padding-left: var(--platform-strip-w, 0px);
}

/* The strip's own pieces (features/nav/strip-back.tsx, side-apps.tsx)
   exist only here. */
.platform-side-strip-top,
.platform-side-strip-ground,
.platform-side-strip-frost,
.platform-side-apps {
  display: none;
}

@media (max-width: 767px) {
  /* NO BAND AT THE FOOT. The five tabs stand in the strip, so a screen has
     only the home-indicator strip to clear below it. Both selectors repeat
     the phone rules' own (the bar alone, and the bar with the parked strip
     on it) with the attribute added, so each outranks the one it replaces.
     The parked strip stands in the strip too (below), so it adds nothing. */
  html[data-side-strip]:not(.un-kb) body:has(#platform-tabs:not(.hidden):not(.platform-tabs-peek)),
  html[data-side-strip]:not(.un-kb) body:has(#platform-tabs:not(.hidden):not(.platform-tabs-peek)):has(#platform-parked:not(.hidden)) {
    --platform-bar-h: 0px;
    --platform-tabs-h: var(--platform-safe-bottom);
  }
  /* WHERE THE STRIP'S CONTROLS START: under the camera, the clock and the
     Wi-Fi ring, 174px down on the Duo's cover, where Settings hangs its own
     back button (measured on the simulator). The page cannot measure that
     stack (the top inset is 0 in this pose and `statusBarFrame` is a 2pt
     stub), so it is this one number. The back button is a 48px disc there,
     and the slot is kept free on every screen, with a way back or without,
     so the back button appears in it and nothing moves (Evan, 24 Oct 2026).

     THE AXIS (Evan, 18 Nov 2026). Everything in the column stands on the
     system's own centre line, not on the middle of our 84px strip: on the
     cover the clock is centred at x 419, the Wi-Fi ring at 418, and Safari's
     and a stock SwiftUI app's buttons at 417.8, i.e. 48px in from the
     screen's edge, where the strip's middle is 42px in. Measured on the
     simulator (iOS 27.1, cover 466x678), like the top. */
  html[data-side-strip] {
    --platform-strip-top: 174px;
    --platform-strip-back: 48px;
    --platform-strip-axis: 48px;
    --platform-strip-foot: 24px;
  }

  /* THE TABS, ONE CAPSULE AT THE FOOT (Evan, 18 Nov 2026), the way iOS draws
     a tab bar in the Duo's column: a stock SwiftUI TabView there is a 48px
     capsule from y 443 to 653 on the cover, icons only, the selected tab a
     pill inside it, while toolbar buttons and the back button stand as
     separate 48px discs under the Wi-Fi ring. Ours is the same: Home,
     Homeroom bot, Messages and You in one capsule on the axis, its foot
     24px off the screen's edge (inside the home-indicator strip, as the
     system's is), the labels kept for screen readers but not drawn. The
     capsule is the page's own plane with its hairline, so light, dark and
     the brand look all read; the lit place is filled from the bar's
     `--lit-*` tokens, so the sliding marker is not drawn here (below).
     It replaces the column of separate bubbles of #6788. */
  html[data-side-strip] #platform-tabs {
    left: auto;
    right: calc(var(--platform-strip-axis) - 24px);
    top: auto;
    bottom: var(--platform-strip-foot);
    width: 48px;
    flex-direction: column;
    align-items: stretch;
    gap: 0;
    padding: 2px;
    border-top: 0;
    border-radius: 999px;
    background: var(--dc-sheet-solid);
    box-shadow: inset 0 0 0 1px var(--app-sheet-line), 0 6px 18px rgba(0, 0, 0, .08);
    clip-path: none;
    /* The app you are in stands above the capsule, outside its box. */
    overflow: visible;
  }
  /* No fake glass behind it: that layer is the phone bar's blue, and an id
     outranks the brand look's own background on it. */
  html[data-side-strip] #platform-tabs::before {
    content: none;
  }
  html[data-side-strip="left"] #platform-tabs {
    left: calc(var(--platform-strip-axis) - 24px);
    right: auto;
  }
  /* A column of cells, only where the bar would be drawn at all: this
     selector outranks the bar's `hidden` (a running app, the signed-out
     shell) and the keyboard's `display: none`, so it names both. */
  html[data-side-strip]:not(.un-kb):not(.platform-kb-open) #platform-tabs:not(.hidden) {
    display: flex;
  }
  /* …AND IN A RUNNING APP TOO (Evan, 24 Oct 2026). A phone hides the bar
     there and leaves the header's ✕ as the way out; on the Duo the strip
     is the system's, the app has the width beside it either way, and the
     places are a tap away as they are on a desktop with the rail beside
     an app. The route still says the bar is hidden (it is the phone's
     answer, and the parked strip and the screens' bands key off it), so
     this draws it from the route-hidden class: only over a running app,
     only with the platform header up (not chromeless, not signed out). The
     ✕ goes (below): leaving is one of the places. */
  html[data-side-strip]:not(.un-kb):not(.platform-kb-open) body:has(#app-view:not(.hidden)[data-app-surface="app"]):not(:has(#platform-header.hidden)) #platform-tabs.platform-tabs-route-hidden {
    display: flex;
  }
  html[data-side-strip] #platform-tabs::after {
    content: none;
  }
  /* THE LIT STATE IS DRAWN ONCE, as the desktop rail already does: the
     marker is still measured (tab-bar.tsx), it is just not painted here. */
  html[data-side-strip] .platform-tabs-marker {
    display: none;
  }
  /* A TAB IS ITS GLYPH. Each place is a 52px cell the capsule's width less
     its padding, the glyph a size up from the phone bar's (24px, about the
     system's own), drawn in the page's ink with no tile of its own. The
     count's badge anchors to the glyph's box, so it sits on its corner. */
  html[data-side-strip] .platform-tab {
    flex: none;
    height: 52px;
    padding: 0;
    gap: 0;
    border-radius: 999px;
    color: var(--text-primary);
  }
  html[data-side-strip] .platform-tab .platform-tab-mark {
    align-items: center;
    justify-content: center;
    color: var(--text-primary);
  }
  html[data-side-strip] .platform-tab .platform-tab-glyph {
    width: 24px;
    height: 24px;
  }
  /* The place you are on is the pill inside the capsule, filled from the
     bar's own lit tokens with their hairline, exactly as the phone's marker
     and the rail's lit row are. A community's page lights Communities, which
     is on the bar again (18 Nov 2026). */
  html[data-side-strip] .platform-tab[aria-current="page"] {
    background: var(--lit-tint);
    box-shadow: inset 0 0 0 1px var(--lit-line);
  }
  html[data-side-strip] .platform-tab[aria-current="page"] .platform-tab-mark {
    color: var(--lit-ink);
  }
  /* The words are not drawn (the system's own side tabs have none), but the
     tab is still named by them: clipped to nothing rather than removed, so a
     screen reader reads "Home" and the declared checks still find it. */
  html[data-side-strip] :is(.platform-tab, .platform-side-app) .platform-tab-label {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  /* THE APPS, ABOVE THE CAPSULE (Evan, 24 Oct 2026; 18 Nov 2026): the app
     on screen, lit by the ring on its tile, and the app you left, with its
     ✕ (features/nav/side-apps.tsx), each a 48px disc of the capsule's own
     plane standing 12px above it, as Safari stands its own buttons apart
     from its tabs. The section is the bar's first child (the declared
     checks pin the tabs' sibling chain), so it is lifted out of the flow
     rather than reordered: the capsule holds the four places alone, you at
     its foot. The phone's Resume strip offers the app you left over the
     bar; here the section does, so the strip stands aside. */
  html[data-side-strip] .platform-side-apps:not(.hidden) {
    position: absolute;
    left: 0;
    bottom: calc(100% + 12px);
    display: flex;
    flex-direction: column;
    gap: 12px;
    width: 48px;
  }
  html[data-side-strip] .platform-side-apps-head {
    display: none;
  }
  html[data-side-strip] .platform-side-app {
    position: relative;
    z-index: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 48px;
    height: 48px;
    border-radius: 999px;
    background: var(--dc-sheet-solid);
    box-shadow: inset 0 0 0 1px var(--app-sheet-line), 0 6px 18px rgba(0, 0, 0, .08);
    color: var(--text-muted);
    text-decoration: none;
    -webkit-tap-highlight-color: transparent;
  }
  /* A thin highlight ring on the app's own tile is what says it is the one
     on screen. */
  html[data-side-strip] .platform-side-app[aria-current="page"] .platform-side-app-tile {
    box-shadow: 0 0 0 2px var(--lit-tint), 0 0 0 3px var(--lit-ink);
  }
  html[data-side-strip] .platform-side-app-tile {
    width: 28px;
    height: 28px;
    flex: none;
    border-radius: 8px;
    overflow: hidden;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 14px;
    font-weight: 700;
  }
  html[data-side-strip] .platform-side-app-row {
    position: relative;
  }
  html[data-side-strip] .platform-side-app-x {
    position: absolute;
    z-index: 2;
    top: -6px;
    right: -8px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 20px;
    height: 20px;
    border: 0;
    border-radius: 999px;
    background: transparent;
    color: var(--text-muted);
    cursor: pointer;
    -webkit-tap-highlight-color: transparent;
  }
  /* A FINGER'S TARGET, NOT A POINTER'S (overnight audit U02). The ✕ that
     forgets an app was its 20px glyph box, perched on the tile's corner: it
     is pressed as 32px now, out over the disc's corner, and drawn as
     before. Above the app's own target (z-index 2), so a press near the
     corner forgets rather than opens. */
  html[data-side-strip] .platform-side-app-x::after {
    content: "";
    position: absolute;
    inset: -6px;
  }
  html[data-side-strip] #platform-parked {
    display: none;
  }

  /* THE BACK BUTTON, UNDER THE CLOCK. The header's back controls give way,
     `#back-btn` and the phone drawer's arrow alike, and their copies stand
     at the top of the strip (`--platform-strip-top`, above) as 48px discs,
     where the system's own back button sits, on the system's axis (above).
     The header's own back disc's colours, a size up. Not while the header
     is away (chromeless): the slot is the header's. */
  html[data-side-strip] #platform-header :is(#back-btn, .nav-drawer-back) {
    display: none;
  }
  html[data-side-strip] body:not(:has(#platform-header.hidden)) .platform-side-strip-top {
    position: fixed;
    z-index: 30;
    top: var(--platform-strip-top);
    right: calc(var(--platform-strip-axis) - var(--platform-strip-back) / 2);
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 10px;
    width: 48px;
    /* The box is not a target: the drawer's arrow is still in it on a
       screen with no way back, faded out (it sets its own pointer-events
       none until it is live), and only a live control takes the press. */
    pointer-events: none;
  }
  html[data-side-strip] .platform-side-strip-top > * {
    pointer-events: auto;
  }
  html[data-side-strip="left"] body:not(:has(#platform-header.hidden)) .platform-side-strip-top {
    left: calc(var(--platform-strip-axis) - var(--platform-strip-back) / 2);
    right: auto;
  }
  html[data-side-strip] .platform-side-strip-top :is(.platform-side-strip-back, .nav-drawer-back) {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 48px;
    height: 48px;
    border-radius: 999px;
    border: 1px solid var(--brand-line);
    background: var(--brand-tint);
    color: var(--brand-ink);
    -webkit-tap-highlight-color: transparent;
  }
  html[data-side-strip] .platform-side-strip-top .platform-side-strip-back:is(.hidden, [data-back="close"]) {
    display: none;
  }
  html[data-side-strip] .platform-side-strip-top svg {
    width: 22px;
    height: 22px;
  }
  /* The header's left group held only the back: with it gone the group is
     empty, and an empty flex item still spends the header's gap. The places
     button stays where it is: it opens the project's places, it is not a
     way back. */
  html[data-side-strip] #platform-header .platform-header-left:not(:has(> .header-places-btn)) {
    display: none;
  }

  /* THE STRIP'S GROUND UNDER A SHEET (Evan, 24 Oct 2026). On Home, Discover
     and You the screen is the bare wallpaper, which is the body's own
     ground and runs under the strip already. Messages and Settings stand
     on a sheet over it instead, the `.dc-lift-strip`
     plane, and the plane stops at the strip with the body behind it, so the
     strip read as a band of a different colour. (A project's pages and
     Messages' drawer run their sheet under the strip themselves; see the
     drawers, below.)

     So on those screens the strip is given the plane's look: its fill over
     the wallpaper (the faked layer every glass surface uses, so it lines up
     with the body pixel for pixel), from the plane's own top (8px up under
     the header's foot) to the floor, with the plane's hairline and radius at
     its top. The plane squares the corner it meets the strip at, so the two
     read as one sheet.

     The ground is OPAQUE, and that is the second half of it. The phone's
     drawer pans the page sideways (back from a community's page, a
     conversation opening), and the page slid through the strip under the
     tabs and the back button. Over the ground it slides under the strip
     instead, as off a phone's edge. Under the header (z-index 10), over
     the screens. */
  html[data-side-strip] body:has(:is(#messages-screen, #settings-screen):not(.hidden) .dc-lift-strip:not(.messages-drawer)) .platform-side-strip-ground {
    position: fixed;
    z-index: 9;
    top: calc(var(--browser-banner-h, 0px) + var(--platform-header-h) + var(--platform-safe-top, 0px) - 0.5rem);
    bottom: 0;
    right: 0;
    width: var(--platform-strip-w, 0px);
    display: block;
    border-top-right-radius: 1.75rem;
    clip-path: inset(0 round 0 1.75rem 0 0);
    pointer-events: none;
  }
  html[data-side-strip="left"] body:has(:is(#messages-screen, #settings-screen):not(.hidden) .dc-lift-strip:not(.messages-drawer)) .platform-side-strip-ground {
    left: 0;
    right: auto;
    border-top-right-radius: 0;
    border-top-left-radius: 1.75rem;
    clip-path: inset(0 round 1.75rem 0 0 0);
  }
  html[data-side-strip] .platform-side-strip-ground::before {
    content: '';
    position: fixed;
    inset: 0;
    z-index: -1;
    pointer-events: none;
    background:
      linear-gradient(var(--dc-strip-fill), var(--dc-strip-fill)),
      var(--home-wallpaper, var(--dc-strip-solid));
  }
  /* The plane's hairline, drawn over the layer (which paints over a
     border, as the tab bar's does). */
  html[data-side-strip] .platform-side-strip-ground::after {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 1px;
    background: var(--app-sheet-line);
  }
  html[data-side-strip="right"] .dc-lift-strip:not(#app-content > .dc-lift-strip):not(.messages-drawer) {
    border-top-right-radius: 0;
  }
  html[data-side-strip="left"] .dc-lift-strip {
    border-top-left-radius: 0;
  }

  /* THE VEIL OVER THE DRAWER UNDER THE STRIP (Evan, 24 Oct 2026). The phone
     drawers' levels go on under the strip (below: a community's places and
     page, Messages' peeking conversation), and their rows read through it,
     cut by the pill. So while a level is out the strip wears a veil, from
     the header's foot to the floor, under the pill, the back button and the
     apps (z-index 30) and over the drawer (20): the rows go faint under it
     and the pill stands on the screen's ground again.

     THE VEIL IS WHAT IS BEHIND THE STRIP AT REST: a screen's sheet (the
     plane's `--dc-strip-fill`) over the wallpaper, drawn as the faked glass
     is (a viewport-sized fixed layer, so its washes line up with the body's
     pixel for pixel, clipped to the veil), at 86% so the rows read faintly
     through. A flat `--home-ground` read as a yellower cream beside the
     pink wash the strip rests on (measured 240,238,226 against
     244,234,229). It is out while a level is (features/nav/
     strip-back.tsx StripFrost sets `data-out` from the drawer's level) and
     fades over the slide's own 300ms (drawer-math SLIDE_MS): in on the
     slide's curve (SLIDE_EASE), out on its mirror, an ease-in, so it lifts
     off as the page settles. Out on the slide's own ease-out it was half
     gone in 60ms, under a page arriving at the same moment, and read as a
     snap. A transition, not a script: the slide runs on the compositor,
     and so does this.

     It is whole from the strip's own edge, the pill's gap to the screen's
     edge mirrored on its other side, and comes in over the 16px before it,
     the margin a screen's content keeps from its edge, so it covers what
     runs to the edge (the drawer's levels) and never a card. The ramp is
     eased (slow, then quicker): at 86% a straight 6px ramp read as a line.

     NO BLUR. It was a 14px backdrop blur, and the slides stuttered on the
     Duo: the page sliding under it had the blur re-run on every frame,
     which is what the platform turned its blur off everywhere for
     (`--dc-frost`). Off, they were smooth. A fill is what every surface
     content passes behind wears since then (the `-solid` plane colours),
     and a fill that never changes costs nothing to composite over a page
     that moves. */
  html[data-side-strip] .platform-side-strip-frost {
    position: fixed;
    z-index: 25;
    top: calc(var(--browser-banner-h, 0px) + var(--platform-header-h) + var(--platform-safe-top, 0px));
    bottom: 0;
    right: 0;
    width: calc(var(--platform-strip-w, 0px) + 16px);
    display: block;
    pointer-events: none;
    background: transparent;
    clip-path: inset(0);
    -webkit-mask-image: linear-gradient(to right, transparent, rgba(0, 0, 0, .2) 5px, rgba(0, 0, 0, .55) 10px, rgba(0, 0, 0, .85) 14px, #000 16px);
    mask-image: linear-gradient(to right, transparent, rgba(0, 0, 0, .2) 5px, rgba(0, 0, 0, .55) 10px, rgba(0, 0, 0, .85) 14px, #000 16px);
    visibility: hidden;
    opacity: 0;
    transition: opacity 300ms cubic-bezier(0.32, 0, 0.67, 0), visibility 0s linear 300ms;
  }
  html[data-side-strip] .platform-side-strip-frost[data-out] {
    visibility: visible;
    opacity: 1;
    transition: opacity 300ms cubic-bezier(0.33, 1, 0.68, 1), visibility 0s;
  }
  html[data-side-strip] .platform-side-strip-frost::before {
    content: '';
    position: fixed;
    inset: 0;
    z-index: -1;
    pointer-events: none;
    opacity: .86;
    background:
      linear-gradient(var(--dc-strip-fill), var(--dc-strip-fill)),
      var(--home-wallpaper, var(--dc-strip-solid));
  }
  /* Messages' list alone has nothing peeking beside it to veil. */
  html[data-side-strip] body:has(#messages-screen:not(.hidden) .messages-drawer-alone) .platform-side-strip-frost {
    visibility: hidden;
    opacity: 0;
  }
  @media (prefers-reduced-motion: reduce) {
    html[data-side-strip] .platform-side-strip-frost,
    html[data-side-strip] .platform-side-strip-frost[data-out] {
      transition: none;
    }
  }
  /* Reduce motion setting (#6510): the same, when Settings asks for it. */
  html[data-side-strip]:where([data-motion="reduce"]) .platform-side-strip-frost,
  html[data-side-strip]:where([data-motion="reduce"]) .platform-side-strip-frost[data-out] { transition: none; }
  /* Not while the header is away (chromeless): its top is the header's foot. */
  html[data-side-strip] body:has(#platform-header.hidden) .platform-side-strip-frost {
    display: none;
  }
  html[data-side-strip="left"] .platform-side-strip-frost {
    left: 0;
    right: auto;
    -webkit-mask-image: linear-gradient(to left, transparent, rgba(0, 0, 0, .2) 5px, rgba(0, 0, 0, .55) 10px, rgba(0, 0, 0, .85) 14px, #000 16px);
    mask-image: linear-gradient(to left, transparent, rgba(0, 0, 0, .2) 5px, rgba(0, 0, 0, .55) 10px, rgba(0, 0, 0, .85) 14px, #000 16px);
  }

  /* A PROJECT'S PAGES, AND THE DRAWER OVER THEM, RUN UNDER THE STRIP (Evan,
     24 Oct 2026). The phone's drawer lays a community's levels beside its
     page and pans between them; with the strip's own ground between them
     and the screen's edge, a level only half on screen (the places peeking
     at the side of your communities, the page at the side of the places)
     stopped at a band of a different colour. So the levels and the page go
     on under the strip, as off a phone's edge, and the pill floats over
     whatever is there.

     The page (#app-view on a platform surface) reaches into the body's
     padding and pads itself by the same width, and so do its content host
     and its sheet, the chain the clip runs through; everything inside stays
     beside the strip. Only on the platform's surface: a running app keeps
     the width beside the strip and no more. */
  html[data-side-strip="right"] :is(#app-view[data-app-surface="platform"], #app-view[data-app-surface="platform"] > #app-content, #app-view[data-app-surface="platform"] > #app-content > .dc-lift-strip) {
    margin-right: calc(-1 * var(--platform-strip-w, 0px));
    padding-right: var(--platform-strip-w, 0px);
  }
  /* …AND MESSAGES' DRAWER DOES THE SAME (Evan, 24 Oct 2026): the list, the
     conversation peeking beside it and the conversation open run on under
     the strip, frosted while one peeks (StripFrost). The screen reaches
     into the body's padding and its sheet (a fixed-width flex child, which
     a margin would not widen) pads itself by the strip; the list keeps its
     85% of the width beside the strip that features/messages/
     phone-drawer.tsx pans by (stripWidth), and the conversation's sheet
     runs to the screen's edge with its contents padded back beside it. */
  html[data-side-strip="right"] #messages-screen:has(> .messages-layout.messages-drawer) {
    margin-right: calc(-1 * var(--platform-strip-w, 0px));
  }
  html[data-side-strip="right"] #messages-screen > .messages-layout.messages-drawer {
    padding-right: var(--platform-strip-w, 0px);
  }
  html[data-side-strip="right"] .messages-layout.messages-drawer > .messages-list-pane {
    width: calc((100% - var(--platform-strip-w, 0px)) * 0.85);
  }
  html[data-side-strip="right"] .messages-layout.messages-drawer.messages-drawer-alone > .messages-list-pane {
    width: calc(100% - var(--platform-strip-w, 0px));
  }
  html[data-side-strip="right"] .messages-layout.messages-drawer > .messages-thread-pane {
    padding-right: var(--platform-strip-w, 0px);
  }
  /* The conversation's discs (⋯ and the rest) float at its top-right
     corner, positioned off the sheet's edge, which padding does not move:
     they went under the strip's camera. In by the strip's width too. */
  html[data-side-strip="right"] .messages-layout.messages-drawer > .messages-thread-pane > .messages-thread-header {
    right: calc(12px + var(--platform-strip-w, 0px));
  }

}

/* ═══════════════════════════════════════════════════════════════════
   THE TOP BAND — iPhone Duo unfolded, held upright (31 Oct 2026)
   ═══════════════════════════════════════════════════════════════════

   Unfolded and upright the Duo is 669px wide, and iOS moves the clock, the
   camera and the Wi-Fi ring into a band across the top instead of the column
   down its edge. The page is handed that band as `env(safe-area-inset-top)`
   — 80px on the simulator (iOS 27.1) — and #2305 spends it as the header's
   own padding-top, so the bar read as 80px of empty ground with its 52px
   row underneath.

   frontend/src/lib/side-strip.ts turns a top inset of 64px or more, with NO
   side column, on a screen at least 600px wide (#6161: an ordinary iPhone's
   inset reaches 64px in the app too, and its clock runs across the top-left,
   so the width is what tells the Duo's band from a plain phone's status
   bar), into one fact on <html>:

     data-top-band        the band is there
     --platform-band-h    its height, in px (84 in `?side-strip=up`)

   and this is the layout. The header's row moves UP into the band beside
   the system controls, as the header already runs into the folded Duo's
   column above: the inset leaves its padding-top, the row sits on the
   clock's line, its foot falls on the band's foot, and its right group
   keeps clear of the clock and camera's corner.
   `--platform-header-h` loses what the band now covers, so the bar plus the
   safe inset is still max(52px, band) under the bar and under every screen
   and sheet below it.

   Nothing here applies without the attribute, and only on a phone: ordinary
   phones reserve 47 to 62px, landscape reports 0, and a browser tab never
   sets it (#2509, applyTopBand). */
@media (max-width: 767px) {
  @supports (padding: env(safe-area-inset-top)) {
    html[data-top-band] {
      --platform-header-h: max(0px, calc(3.25rem - var(--platform-band-h)));
    }
    /* THE BARS: one rule, both of them, so parity survives the band (the
       #2305 rule above is `!important`, hence the `!important` here). The
       second selector repeats the community tint's app-view rule with
       `html[data-top-band]` added, so it outranks that rule too. The bar
       drops the inset and puts its 28px row on the clock's line: the
       clock's digits are centred 34px above the band's foot (measured on the
       Duo simulator, iOS 27.1: digits from y 42 to 54 of an 82px band), so
       the row keeps a 20px foot under it and the band's rest over it, and
       the bar's foot still meets the band's foot with the -mb-2 notch
       unchanged. Pinned to the top of the band the row sat about 25px above
       the clock's line, and centred in the band about 7px above it
       (1 Nov 2026). The 8px floor over the row is the ordinary bar's, for a
       band under 56px. The right padding keeps the bell and the account
       button clear of the corner the clock and Wi-Fi ring use, with an 8px
       gap. That corner is a pill about 130px wide across the band's top right
       (measured on the Duo simulator, iOS 27.1: from x 540 to the edge of the
       669px screen), not the folded Duo's 84px column: at 84px the account
       button's chevron sat under the clock. */
    html[data-top-band] :is(#platform-header, #landing-header).un-safe-top-extend,
    html[data-top-band][data-community-tint] body:has(#app-view:not(.hidden)) #platform-header.un-safe-top-extend {
      padding-top: max(0.5rem, calc(var(--platform-band-h) - 3rem)) !important;
      padding-bottom: 1.25rem;
      padding-right: calc(0.5rem + 130px);
    }
  }
}

/* ═══════════════════════════════════════════════════════════════════
   THE SIDE CORNER — iPhone Duo folded, its island in one corner
   ═══════════════════════════════════════════════════════════════════

   In the 466x678 folded pose the report shows, iOS keeps the clock, the
   camera and the signal in a narrow pill at the top-right corner rather
   than the full column above: about 52px, so under STRIP_MIN_PX and not a
   strip. Nothing read that space, and the header's bell and app chip, the
   page's own buttons and the last tile in a row sat under the system's
   pill.

   frontend/src/lib/side-strip.ts turns a one-sided inset wider than
   nothing and narrower than a strip, with no column and no top band, on a
   phone held upright, into one fact on <html>:

     data-side-corner     the side the system's corner is on
     --platform-corner-w  its width, in px (52 in `?side-strip=corner`)

   This is the layout. The header still runs edge to edge — its ground
   under the clock, as it runs into the folded Duo's column above — while
   its controls move clear of the corner; the content stops at the corner;
   and the five-cell bar keeps its ground across the screen with its cells
   beside the corner. The strip's column layout above is never keyed on
   this attribute: the two facts are never set together, and an ordinary
   phone or a browser tab renders exactly as it did.

   The header's controls keep 84px clear of that corner, the width of the
   folded Duo's column. (The unfolded top band clears a wider pill, 130px:
   THE TOP BAND above.) */
@media (max-width: 767px) {
  html[data-side-corner="right"] body,
  html[data-side-corner="right"] #auth-landing-screen {
    padding-right: var(--platform-corner-w, 0px);
  }
  html[data-side-corner="left"] body,
  html[data-side-corner="left"] #auth-landing-screen {
    padding-left: var(--platform-corner-w, 0px);
  }
  /* The header's ground spans the screen, its controls clear the corner. */
  html[data-side-corner="right"] #platform-header {
    margin-right: calc(-1 * var(--platform-corner-w, 0px));
    padding-right: calc(1rem + 84px);
  }
  html[data-side-corner="left"] #platform-header {
    margin-left: calc(-1 * var(--platform-corner-w, 0px));
    padding-left: calc(1rem + 84px);
  }
  /* The bell's sheet, fixed like the header, keeps its ground and moves its
     content by the corner's own width rather than the header's 84px: the
     sheet's 16px row padding plus that width already clears the pill, and
     84px on a 466px screen would squeeze every row. */
  html[data-side-corner="right"] #notifications-sheet {
    padding-right: var(--platform-corner-w, 0px);
  }
  html[data-side-corner="left"] #notifications-sheet {
    padding-left: var(--platform-corner-w, 0px);
  }
  /* The five cells stay left of the corner; the bar's ground does not. */
  html[data-side-corner="right"] #platform-tabs {
    padding-right: var(--platform-corner-w, 0px);
  }
  html[data-side-corner="left"] #platform-tabs {
    padding-left: var(--platform-corner-w, 0px);
  }
}

/* direction: logical — the hardware blocks above end here; everything below
   follows the reading direction again. */


/* ── #platform-parked — the app you left ─────────────────────────────
   frontend/src/features/nav/parked-store.js carries the argument. What lives
   here is the geometry: a 52px strip resting ON the tab bar, out of flow like
   it, with its band reserved by the same token the bar's is. */
.platform-parked {
  position: fixed;
  inset-inline-start: 0;
  inset-inline-end: 0;
  /* ON the bar, not above the screen's edge: the bar already spends the
     home-indicator inset, so the strip's floor is the bar's ceiling and
     neither reserves the strip twice. */
  bottom: var(--platform-bar-h, 0px);
  /* UNDER the bar's z-index by one. They never overlap, so this only decides
     what a shadow falls across — and a temporary offer casting over permanent
     furniture is the wrong way round. */
  z-index: 29;

  display: flex;
  align-items: center;
  gap: 4px;
  height: 52px;
  padding-block: 0 0; padding-inline: 4px 8px;
  border-top: 1px solid var(--app-sheet-line);
  background-color: var(--dc-sheet-fill);
  backdrop-filter: var(--dc-frost);
  -webkit-backdrop-filter: var(--dc-frost);
}
/* Pages scroll under the strip, which sits on the tab bar: faked glass, the
   same layer as the bar (see "THE ONE FAKED LAYER"), so the two read as one
   material on every platform. */
.platform-parked {
  background-color: transparent;
  clip-path: inset(0);
}

/* THE WHOLE STRIP IS THE TARGET. A shortcut whose tappable area is a 60px
   pill inside a full-width bar is a shortcut you miss; the pill is a LABEL
   inside this anchor rather than a button beside it, which is also the only
   valid markup (a button inside an anchor is not). */
.platform-parked-open {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 10px;
  height: 44px;
  padding-block: 0 0; padding-inline: 8px 4px;
  border-radius: 12px;
  color: var(--text-primary);
  text-decoration: none;
  -webkit-tap-highlight-color: transparent;
}
.platform-parked-tile {
  width: 32px;
  height: 32px;
  flex: none;
  border-radius: 9px;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 15px;
  font-weight: 700;
}
/* THE APP'S NAME IN FULL, not a description of it. It read "A chat is
   working" for a round, which is a sentence about a session rather than the
   thing you are going back to — and the answer to "what is this" here is the
   app's own name, which is what you were looking at a moment ago. */
.platform-parked-name {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 15px;
  font-weight: 600;
}
/* RESUME IS AN ACTION, so it is drawn in the accent, filled (#3618). It was
   the header's periwinkle, which is the header's own ink and nothing else's,
   at a tint light enough that the strip's one action read as a tag. */
.platform-parked-pill {
  flex: none;
  display: inline-flex;
  align-items: center;
  height: 28px;
  padding: 0 12px;
  border-radius: 999px;
  border: 0;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 13px;
  font-weight: 600;
}
/* FORGET, not hide. A strip that comes back on the next screen swap is a
   strip you cannot get rid of, and the handle's promise is that it is there
   until you are done with it. */
.platform-parked-x {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
/* KEYBOARD UP, STRIP GONE (#2762), for the reason `html.un-kb #platform-tabs`
   gives for the bar under it: with the bar gone the strip's floor
   (`--platform-bar-h`) drops to 0 and it would ride on top of the keyboard,
   over the very field being typed into. It comes back with the bar. Not the
   `hidden` class, which the island owns — this is presentation. */
html.un-kb #platform-parked {
  display: none;
}

/* IN AND OUT BY THE BAR (#3376), on the phone. Parked, the strip rises out
   from behind the tab bar (it sits one z-index under it); forgotten, it sinks
   back in, a little quicker, and ends clipped until `hidden` lands. The ROOT
   animates its clip and never a transform: a transform would make it the
   containing block for its fixed `::before` glass layer, which would draw at
   strip size and snap back at the end. The children carry the slide. The
   band the strip reserves does not ease — it feeds every screen's padding —
   so content already ends above where the strip is arriving. */
@media (max-width: 767px) {
  .platform-parked-enter {
    animation: platform-parked-reveal 220ms cubic-bezier(0.2, 0.8, 0.2, 1);
  }
  .platform-parked-enter > * {
    animation: platform-parked-rise 220ms cubic-bezier(0.2, 0.8, 0.2, 1);
  }
  .platform-parked-leave {
    pointer-events: none;
    animation: platform-parked-conceal 160ms cubic-bezier(0.4, 0, 1, 1) forwards;
  }
  .platform-parked-leave > * {
    animation: platform-parked-sink 160ms cubic-bezier(0.4, 0, 1, 1) forwards;
  }
}
@keyframes platform-parked-reveal {
  from { clip-path: inset(100% 0 0 0); }
  to   { clip-path: inset(0); }
}
@keyframes platform-parked-conceal {
  from { clip-path: inset(0); }
  to   { clip-path: inset(100% 0 0 0); }
}
@keyframes platform-parked-rise {
  from { transform: translateY(52px); opacity: 0; }
  to   { transform: translateY(0); opacity: 1; }
}
@keyframes platform-parked-sink {
  from { transform: translateY(0); opacity: 1; }
  to   { transform: translateY(52px); opacity: 0; }
}
@media (prefers-reduced-motion: reduce) {
  .platform-parked-enter, .platform-parked-leave,
  .platform-parked-enter > *, .platform-parked-leave > * { animation: none; }
}
/* Reduce motion setting (#6510): the same, when Settings asks for it. */
:where(html[data-motion="reduce"]) .platform-parked-enter,
:where(html[data-motion="reduce"]) .platform-parked-leave,
:where(html[data-motion="reduce"]) .platform-parked-enter > *,
:where(html[data-motion="reduce"]) .platform-parked-leave > * { animation: none; }

/* ── THE APP YOU CLOSED, ON ITS WAY INTO RESUME (#3618) ──────────────
   frontend/src/features/nav/resume-motion.ts carries the argument: a
   stand-in for the app (its page colour, its icon) pinned where the app was,
   shrinking into the Resume control in the rail or the strip. Above the page
   and the bars, at the kit's zoom layer and under every kit overlay; never a
   target; gone when the motion ends. The script never runs it with reduced
   motion; the rule below is the belt to that. */
.resume-ghost {
  position: fixed;
  z-index: 9960;
  pointer-events: none;
  transform-origin: 0 0;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  /* The app's own page colour when its frame reported one (set inline);
     the page ground otherwise — a card lifted off whatever is behind it,
     never the wallpaper it would vanish into. */
  background: var(--bg-primary);
  box-shadow: inset 0 0 0 1px var(--app-sheet-line), 0 12px 40px rgba(0, 0, 0, .18);
  will-change: transform, opacity;
}
.resume-ghost-tile {
  width: 72px;
  height: 72px;
  border-radius: 18px;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 36px;
  font-weight: 700;
}
.resume-ghost-tile > img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
@media (prefers-reduced-motion: reduce) {
  .resume-ghost { display: none; }
}
/* Reduce motion setting (#6510): the same, when Settings asks for it. */
:where(html[data-motion="reduce"]) .resume-ghost { display: none; }


/* ═══════════════════════════════════════════════════════════════════
   THE SAME FIVE TABS, STANDING UP — desktop from 768px (#2718)
   ═══════════════════════════════════════════════════════════════════

   A bottom bar is a PHONE shape, and it does not survive the trip: at
   1280px the five tabs sit 250px apart along the foot of the screen, which
   is a row of unrelated buttons rather than a set of places, and it spends
   the one dimension a desktop has plenty of to save the one it does not.

   Every host in the study does the same thing here, and it is not a
   compromise — it is what their desktop apps have always been. Slack,
   Discord, Teams and Telegram Desktop all turn their phone tab bar into a
   LEFT RAIL: the sections stand up, get their labels beside their glyphs
   instead of under them, and the content takes the width back.

   UNDER THE HEADER, not beside it. That is this shell's own arrangement
   rather than a borrowed one, and it is the half of the design the product
   owner chose: the bar names where you are and carries the platform's own
   controls, so it spans the window and the rail hangs below it. It also
   means the header is the SAME OBJECT on both sides of every navigation,
   so nothing about it animates when a screen swaps.

   768px because that is `md`, which is where every other two-level layout in
   this file switches (the Settings sidebar, the Admin console's nav, the
   Messages list-and-thread split). One breakpoint, not a fourth opinion. */

/* ── THE RAIL'S OWN SWITCH (#2718 review) ───────────────────────────
   #sidebar-toggle, in the header's left group. The component carries the
   argument; what lives here is the one fact React must not decide, because
   it does not know the viewport and asking would put a measurement in the
   render path: the control exists only where there is a rail to fold.

   A phone's bar is at the FOOT of the screen and is the only navigation
   there is. Folding it would leave a reader with nothing and no hover to
   bring it back, so below the breakpoint the button is not there — and
   because it is not there, `railOpen` can never leave `true` on a phone. */
.platform-sidebar-toggle {
  display: none;
}

/* ANDROID'S BACK IS A PLAIN ARROW (overnight audit G01, 2 Nov 2026). The
   header's back was iOS's chevron in a periwinkle disc on every device,
   which on Android reads as an iPhone port: Material's back is a bare
   arrow. The kit marks the device on <html> (`un-android`, native.js
   detectPlatform), so there the disc goes and the arrow
   (platform-header.tsx `.back-icon-android`) stands in for the chevron,
   shown exactly when the chevron would be. The house and the ✕ keep their
   glyphs; only the disc goes from under them. Elsewhere the arrow never
   shows. */
.back-icon-android { display: none; }
html.un-android #back-btn {
  border-color: transparent;
  background: transparent;
}
html.un-android #back-btn > #back-icon-arrow { display: none; }
html.un-android #back-btn > #back-icon-arrow:not(.hidden) + .back-icon-android { display: block; }

/* ── WHAT REACT STOPPED DECIDING (#2718 review) ──────────────────────
   The toggle's markup is constant and so is its group's class string. Both
   used to be computed from `useVisibility('platform-tabs')` during render,
   and that store is published by public/js/app.js — a classic script, which
   runs BEFORE the deferred island bundle hydrates. The prerender used the
   default and the first client render used the router's real answer, so the
   two disagreed and React threw #418 on every route. A console error on any
   route fails every declared check; 291 of them, which is all of them.

   All three questions are CSS's now, and none of them is part of hydration:

     does the rail exist   → `#platform-tabs.hidden`, which the island
                             publishes through useHiddenClass — and not
                             `.platform-tabs-route-hidden`, which says the
                             ROUTE has none and only the peek is showing it
     is there room for it  → the media query
     has the group anything→ `:has(> #back-btn.hidden)` plus the two above

   #4703 adds a fourth thing the group can hold: the merged header's places
   button, on a phone, on a project page — where the back slot is empty and
   the group used to be gone with it. A group holding it is not empty, so
   the `:not(:has(...))` asks. The phone's drawer's back arrow
   (features/nav-drawer/header-drawer.tsx) takes that button's seat, and is
   asked about the same way.

   THE GROUP GOES WHEN IT IS EMPTY, and that is not cosmetic: an
   empty-but-present flex item still reserves the header's own `gap-4`, which
   put the wordmark 16px in from the edge of every root screen the first time
   this was tried. Scoped through `#platform-header` for specificity, not for
   reach — the group carries Tailwind's `flex`, app.css loads BEFORE
   tailwind.css, and the utilities win every equal-specificity conflict in
   this file (#938). */
#platform-header .platform-header-left:has(> #back-btn.hidden):not(:has(> .header-places-btn)):not(:has(> .nav-drawer-back)) {
  display: none;
}
@media (min-width: 768px) {
  /* …unless the toggle is in it, which needs both a rail and the width. */
  body:has(#platform-tabs:not(.hidden):not(.platform-tabs-route-hidden)) #platform-header
    .platform-header-left:has(> #back-btn.hidden) {
    display: flex;
  }
}

@media (min-width: 768px) {
  /* NO DISC AT REST, EITHER WAY (#2798). The button used to wear the bar's
     periwinkle disc for as long as the rail was up, which read as a control
     permanently highlighted. The disc is a HOVER state now (the component's
     `hover:` classes); what still tells the two states apart is the ink —
     periwinkle while the rail is up, muted while it is folded. Colour only:
     the button does not move, because it is the fixed thing the layout
     pivots around when the whole content column slides.

     `body:has(...)` is what replaces the `return null` this component used
     to do for itself: a route with no rail has no fold to offer, and a dead
     control is worse than none.

     A PEEK IS NOT A RAIL THE ROUTE HAS. Over a running app the peek takes
     `hidden` off the bar, and this rule used to answer that alone: pointing
     at the window's left edge inside an app put the toggle into the app's
     own strip, pushed ✕, the tile and the name 34px right, and pressing it
     folded the docked rail behind the app. `.platform-tabs-route-hidden` is
     the route's answer published beside the peek's (features/nav/
     tab-bar.tsx), so the toggle stays out of the app layer and the peek
     still works. A rail the viewer FOLDED is still the route's, so its
     toggle stays — it is how the fold comes undone. */
  body:has(#platform-tabs:not(.hidden):not(.platform-tabs-route-hidden)) .platform-sidebar-toggle {
    display: inline-flex;
    transition: background-color 140ms ease, color 140ms ease,
                border-color 140ms ease;
  }
  .platform-sidebar-toggle[aria-pressed='false'] {
    background: transparent;
    color: var(--text-muted);
    border-color: transparent;
  }
  .platform-sidebar-toggle[aria-pressed='false']:hover {
    background: var(--brand-tint);
    color: var(--brand-ink);
    border-color: var(--brand-line);
  }
}

@media (prefers-reduced-motion: reduce) {
  .platform-sidebar-toggle { transition: none; }
}
/* Reduce motion setting (#6510): the same, when Settings asks for it. */
:where(html[data-motion="reduce"]) .platform-sidebar-toggle { transition: none; }

@media (min-width: 768px) {
  /* THE BAND AT THE FOOT GOES AWAY ENTIRELY. What a screen has to clear
     below it is the home-indicator inset and nothing else — on a desktop
     that is 0, and the expression keeps it correct on a tablet that has one.
     The rail's width takes its place, as padding rather than as a band.

     WITH THE KEYBOARD UP AS WELL (1 November 2026). The rail stays while a
     field has the keys (the bar's own display rule says why), so the rules
     in this block that give it its column, and move the page over, no
     longer stand aside under `un-kb`. The two band-token rules below keep
     `html:not(.un-kb)`: the home-indicator strip they reserve is behind the
     keys, and they must match the phone rule's selector exactly. */
  body:has(#platform-tabs:not(.hidden)) {
    --platform-rail-w: var(--platform-rail-full);
    /* The air between the rail and the content, spent again on the right —
       see the padding rule below. 1.5rem is the shell's own outer gutter
       (`px-4` is 1rem and every pane steps out to 1.5rem at `sm`), so this
       is the page's existing rhythm rather than a number for this one edge. */
    --platform-gutter: 1.5rem;
  }

  /* THE BAND TOKENS NEED THE OTHER RULE'S SELECTOR, EXACTLY (#2718 review).
     `--platform-bar-h` and `--platform-tabs-h` were declared in the block
     above and never once applied. `:has()` takes the specificity of its most
     specific argument, so the phone rule near the head of this section —
     `body:has(#platform-tabs:not(.hidden):not(.platform-tabs-peek))`, whose
     argument carries one class more — outranks it and kept winning at every
     width. Measured at 1280: `--platform-bar-h` read `calc(56px + 0px)` and
     `--platform-tabs-h` read `calc(52px + 56px + 0px)`.

     Two things were wrong because of it. The parked strip is placed at
     `bottom: var(--platform-bar-h)`, so the app you left floated 56px above
     the bottom-left corner instead of resting in it. And every desktop
     screen reserved 108px of band at its foot for a bar that is a rail down
     the side.

     Matching the selector character for character is the fix, and it is the
     right selector on its own terms: a PEEKING rail reserves nothing, which
     is what that `:not()` has always meant. Source order decides between two
     rules of equal specificity, and this one is thousands of lines later. */
  html:not(.un-kb) body:has(#platform-tabs:not(.hidden):not(.platform-tabs-peek)) {
    --platform-bar-h: 0px;
    --platform-tabs-h: var(--platform-safe-bottom);
  }
  html:not(.un-kb) body:has(#platform-tabs:not(.hidden):not(.platform-tabs-peek)):has(#platform-parked:not(.hidden)) {
    --platform-tabs-h: var(--platform-safe-bottom);
  }

  /* A FOLDED RAIL SPENDS NO WIDTH (#2718 review, #sidebar-toggle).
     Same specificity as the rule above and immediately after it, so source
     order decides — which is the whole of the arrangement: the rail's other
     tokens (`--platform-bar-h: 0px`, the tabs band) stay exactly as they are,
     because folding changes where the navigation IS and not whether this is
     the desktop layout. The gutter deliberately survives: content that ran to
     the window's edge the moment the rail went away would make folding it a
     bigger change than the reader asked for.

     INSIDE THE MEDIA QUERY AND NOWHERE ELSE. Below 768px the bar is the
     phone's bottom bar and the only navigation there is; the class is still
     on the element after a resize, and this is what keeps it inert there. */
  body:has(#platform-tabs.platform-tabs-folded) {
    --platform-rail-w: 0px;
  }

  /* ── WHERE THE BAR MEETS THE RAIL (#2718 review) ──────────────────
     The header is `rounded-b-2xl`, which is right while it floats over the
     page with nothing under its corners. The rail arrives directly beneath
     its left one, so that 1rem curve cut a bite out of the top of the rail
     and the two surfaces — the same material since this review — read as one
     pane with a chip out of it. Square on the left only: the right corner
     still has page under it and keeps its curve.

     AND A HAIRLINE ACROSS THE SEAM, which is the same line the rail already
     draws down its right edge, so the rail is outlined on the two sides that
     touch something rather than on one. It is on the RAIL rather than the
     header because the rail is what it bounds: a border under the header
     would run the whole width of the window and divide the bar from the page
     as well, which is a different statement and not the one asked for.

     Both are keyed off the rail actually occupying its column. A FOLDED rail
     is not there, so the corner keeps its curve; a folded rail PEEKING is an
     overlay with the page still underneath, and the curve is right there for
     the same reason it is right over an app. */
  body:has(#platform-tabs:not(.hidden):not(.platform-tabs-folded)) #platform-header {
    border-end-start-radius: 0;
  }
  .platform-tabs:not(.platform-tabs-folded) {
    border-top: 1px solid var(--app-sheet-line);
  }

  /* THE SCREENS MOVE OVER, and they move over by PADDING rather than by a
     layout change: every root is a `flex-1` child of the body column and
     stays one, so nothing about the flex chain, the scroll containers or the
     view transitions is touched. A root's own centred column then centres in
     what is left, which is what it should do.

     #app-view is deliberately absent: an app covers the rail, which is what
     "the app is the whole window" means, and the rail is hidden there anyway
     so the token would be 0 even if it were listed.

     #profile-proposals-screen is listed (#3498): Your requests and Your votes
     centred in the whole window, so from a laptop width down their cards
     began under the rail. */
  :is(#home-screen, #workshop-screen, #weekly-digest-screen, #communities-screen, #ai-screen, #leaderboard-screen,
      #profile-screen, #admin-screen, #settings-screen, #messages-screen,
      #profile-proposals-screen) {
    /* A GUTTER AFTER THE RAIL, MIRRORED ON THE FAR EDGE (#2718 review).
       The rail's hairline was the content's left margin, so a card began
       where the rail ended and the page had air on the right and none on the
       left. Spending the same figure on both sides is what makes a centred
       column inside actually centre in the window rather than sit a gutter's
       width to the left of centre. */
    padding-inline-start: calc(var(--platform-rail-w, 0px) + var(--platform-gutter));
    padding-inline-end: var(--platform-gutter);
  }

  /* …AND #app-view JOINS THEM WHILE ITS RAIL IS UP (#2718 review). It is
     absent from the list above because that list is keyed on the screen id
     and this screen is TWO screens behind one id: the running app on the
     `app` tab, which takes the whole window, and on `dev` the platform's own
     Workshop for it, which is a platform screen like the others.

     Keyed off the RAIL rather than off the tab, because the rail is already
     the answer to that question — App._syncPlatformTabs publishes it — and a
     second flag saying the same thing is a second flag to keep in step. The
     peeking and folded cases are excluded for the reason they always are: a
     rail that claimed 224px on the way in would reflow the page under the
     pointer that revealed it. */
  body:has(#platform-tabs:not(.hidden):not(.platform-tabs-peek):not(.platform-tabs-folded)) #app-view {
    padding-inline-start: calc(var(--platform-rail-w, 0px) + var(--platform-gutter));
    padding-inline-end: var(--platform-gutter);
  }

  /* …AND A RUNNING APP, WHOSE RAIL STAYS BESIDE IT (#3319). On by default
     now, and Settings → Theme → "Keep sidebar open in apps" switches it off
     (App._syncPlatformTabs publishes it and puts `rail-pinned` on the body;
     the header's corner is then the sidebar toggle, not a ✕). Folded, the
     rule above stands aside and the app has the whole window.
     The frame steps out of the rail's column and nothing more: the gutters
     are a platform page's rhythm, and somebody's program still runs edge to
     edge in what is left. One class more than the rule above, so it wins.
     Inside this block only — a phone never gets the class, and a window
     narrowed past 768px with it set keeps the full-screen app. */
  body.rail-pinned:has(#platform-tabs:not(.hidden):not(.platform-tabs-peek):not(.platform-tabs-folded)) #app-view {
    padding-inline-start: var(--platform-rail-w, 0px);
    padding-inline-end: 0;
  }

  /* THE RAIL STAYS OVER AN APP THAT IS ZOOMING. Opening an app out of its
     tile (and shrinking it back into one) pins #app-view as a fixed card at
     z-index 9960 over its whole box, wallpaper and all, and that box runs
     under the rail: the rail's room is the padding above. So with the rail
     beside the app it vanished for the length of the zoom and snapped back
     when the card was lifted. While the card is pinned (PlatformUI.markZoom
     puts `data-zooming` on it for exactly that long) the docked rail and its
     foot sit over the card instead; the part of the card under them is only
     the padding. Still under the kit's
     sheets (9990 and up). A route whose rail is hidden is untouched. */
  body:has(#app-view[data-zooming]) :is(#platform-tabs, #platform-parked):not(.hidden) {
    z-index: 9961;
  }

  .platform-tabs {
    /* FROM UNDER THE HEADER TO THE FLOOR. The header is `position: relative`
       in normal flow, so its height is a token rather than something to
       measure — `--platform-header-h`, which the bar's own py-3 arithmetic
       keeps true, plus whatever strips are above it. */
    top: calc(var(--browser-banner-h, 0px) + var(--platform-header-h)
      + var(--platform-safe-top, 0px));
    inset-inline-end: auto;
    bottom: 0;
    /* THE FULL WIDTH, not the reserved one: this is the element being drawn,
       and while it peeks the reserved figure is deliberately 0. */
    width: var(--platform-rail-full);

    /* A COLUMN THAT DOES NOT STRETCH. `grid-template-rows: repeat(5, 1fr)`
       would spread five rows over 800px of rail, which is the bottom bar's
       mistake turned on its side.

       FLEX RATHER THAN GRID since #2718's review, for one reason: Me sits at
       the FOOT of this rail now, and `margin-top: auto` is how an item claims
       the leftover space in a flex column. In a grid with `align-content:
       start` the rows are packed at the top and an item's auto margin only
       moves it inside its own `max-content` row, which is no movement at all.
       Everything else is the same arrangement said the other way: a column of
       rows at their natural height, packed from the top. */
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 2px;
    /* #4417: 4px at the sides in a 76px strip, so a label has 68px. */
    padding: 8px 4px;
    /* WHAT THE PARKED STRIP RESTS ON. That strip is `position: fixed` to the
       foot of this column and overlays it, so the rail owes it a floor's
       worth of room or the last row reads through it. `--platform-bar-h` is
       0 here (the band at the foot of a phone is a rail at the side of a
       desktop), which is why this is spelled out rather than borrowed. */
    padding-bottom: calc(8px + var(--platform-safe-bottom, 0px));

    border-top: 0;
    border-inline-end: 1px solid var(--app-sheet-line);

    /* IT SCROLLS WHEN IT IS TALLER THAN THE SCREEN (layout audit, 1 November
       2026). On an iPhone held sideways (393px) its last communities and
       You ran off the bottom with no way to reach them, and on the iPhone
       Duo held sideways a project's places pushed You into the home
       indicator's strip. Me's auto margin still pins it to the foot when
       there is room; when there is not, it follows the rest and scrolls,
       and the padding above keeps it clear of the home indicator at the
       end. Sideways it never scrolls: nothing in it is wider than it. */
    overflow-x: hidden;
    overflow-y: auto;
    overscroll-behavior: contain;
    scrollbar-width: thin;
  }

  /* ── ME SITS AT THE FOOT (#2718 review) ──────────────────────────────
     "Move Me to the bottom left of the sidebar, like on the prototype." It
     is the one tab that is not a place in the product — it is the reader —
     and every rail in the study puts the account at the bottom for exactly
     that reason: Slack, Discord, Linear, Notion, VS Code. The other four are
     a list of sections; this is who is looking at them.

     An auto top margin and nothing else: no reordering in the markup, no
     second element, no id moved. The margin is on the rule drawn above Me
     now (below), which pins the pair to the foot. The DOM order is this
     rail's own reading order (the phone's bar lays its five out with
     `order`: "TWO ORDERS, ONE MARKUP" above), and this
     rule lives inside the desktop media query because on a phone the five
     are a row across the foot and an auto margin there would drop Me out of
     line with its four neighbours.

     THE PARKED STRIP SITS ABOVE IT, which is the prototype's order: the
     sections, then the app you left, then you. */
  /* A THIN RULE ABOVE ME (#2800, #2878): the sections and the history above
     it, you below it. It is the rail's own `::after` rather than an element
     in the markup, drawn before Me with `order` — so the DOM, the reading
     order and the shell's id inventory are untouched, and the phone's bar
     (where none of this media query applies) never sees it. Me used to carry
     the `margin-top: auto`; the rule carries it now, and Me follows it. */
  .platform-tabs::after {
    content: "";
    order: 1;
    flex: none;
    height: 1px;
    margin: auto 4px 6px;
    background: var(--app-sheet-line);
  }
  /* SETTINGS, THEN YOU, AT THE FOOT (#3120, #4417): after the rule, your
     settings next to you, and you last. The markup does not move (the cog
     follows Me there); `order` places them after the rule's spacer. The
     sidebar of rows puts the cog at the end of your row (its block below). */
  .platform-rail-settings {
    order: 2;
  }
  #platform-tab-me {
    order: 3;
  }
  /* The cog: the ink, radius, lit fill and hover are a tab's, so it reads as
     one more place in the rail rather than a toolbar button.
     ONE STEP ABOVE THE TABS (#4 of the 19 Oct polish board). A flex item
     paints in `order`, not in markup order, so Me (`order: 3`) painted over
     the cog (`order: 2`) at the same z-index 1. In the sidebar of rows Me's
     row runs under the cog, and its padding left room to see the cog but
     not to press it: every click on the cog opened Profile, and Me's lit
     fill covered it on Profile, Settings and the leaderboard. */
  .platform-rail-settings {
    position: relative;
    z-index: 2;
    align-self: center;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 40px;
    margin-bottom: 2px;
    border-radius: 12px;
    color: var(--text-muted);
    text-decoration: none;
    -webkit-tap-highlight-color: transparent;
    transition: background-color 120ms ease, color 120ms ease;
  }
  .platform-rail-settings[aria-current="page"] {
    background: var(--lit-tint);
    color: var(--lit-ink);
  }
  .platform-rail-settings-glyph {
    width: 22px;
    height: 22px;
    flex: none;
  }
  @media (hover: hover) {
    .platform-rail-settings:not([aria-current="page"]):hover {
      background: color-mix(in srgb, var(--lit-tint) 55%, transparent);
      color: var(--lit-ink);
    }
  }
  /* The rail keeps its own fill on the lit row; the phone's sliding marker
     is not drawn here (#2824). */
  .platform-tabs-marker {
    display: none;
  }
  /* A TAB ANSWERS THE POINTER (#2798). The rail's rows had no hover at all,
     so nothing said a row was a target until it was pressed. The hover is the
     same periwinkle as the lit tab, stronger now (#6194: at half strength the
     inactive rows were hard to tell apart), with the same thin outline that
     lit chips elsewhere wear. The tab you are on keeps its full fill and its
     weight 600, so it still reads as the strongest thing in the rail and the
     one under the pointer reads as "this one, if you press". Only where there
     IS a pointer: a touch screen's sticky hover would leave a tapped tab half
     lit. */
  .platform-tab {
    transition: background-color 120ms ease, color 120ms ease, box-shadow 120ms ease;
  }
  @media (hover: hover) {
    .platform-tab:not([aria-current="page"]):hover {
      background: color-mix(in srgb, var(--lit-tint) 85%, transparent);
      box-shadow: inset 0 0 0 1px var(--lit-line);
      color: var(--lit-ink);
    }
  }

  /* THE RESUME STRIP GIVES WAY TO THE SIDEBAR ON THE DESKTOP (#2802,
     #4417). A running app keeps its App row, with its dot, under its
     community there (features/nav/rail-communities.tsx), the same offer for
     every app still open, so a second copy at its foot would say it twice.
     The phone has no sidebar and keeps it. By id so no later
     `.platform-parked` rule can bring it back. */
  #platform-parked {
    display: none;
  }
}

/* ── D: THE SIDEBAR OF ROWS, ON EVERY DESKTOP WINDOW (18 Oct 2026) ───────
   features/nav/sidebar-rows.ts carries the argument. From 768px the rail
   is one 212px sidebar for the whole platform: Home, Homeroom bot, Messages
   and Communities as rows, then RECENTS (features/nav/rail-pinned.tsx, the
   communities you pinned to it, and ./rail-communities.tsx, the five you
   opened last),
   and you at the foot with Settings beside you, a community's places and
   the inbox's latest conversations nested under their rows (v3). It began
   at 1024px with the 76px strip and its 264px column below that, 340px
   where this is 212px; from 768px it is the one desktop rail, and the
   phone's bar never sees any of this. The block comes after the rail's own
   768px block, so at the same width it wins, and what that block still
   says about the strip is what this one does not override.

   The parts only the sidebar draws are in the markup at every width and
   drawn only here. */
.platform-rail-communities,
.platform-rail-pinned {
  display: none;
}

/* All communities' search and audience chips went with its list, which is
   Home's since One Home (#6361). */

@media (min-width: 768px) {
  /* THE ONE NUMBER THE REST FOLLOWS. Everything the strip's width placed
     (the screens' padding among it) reads this token, so the sidebar
     moves them all at once. */
  body {
    --platform-rail-full: 212px;
  }
  .platform-tabs {
    gap: 1px;
    padding: 10px 6px calc(10px + var(--platform-safe-bottom, 0px));
  }

  /* A ROW: the glyph, then the words, then the count at the far end. The
     glyph's wrapper dissolves so its counts can sit at the row's end, as the
     places column's counts do. */
  .platform-tab {
    flex: none;
    flex-direction: row;
    justify-content: flex-start;
    gap: 9px;
    height: 36px;
    padding: 0 8px;
    border-radius: 10px;
    color: var(--text-primary);
    font-size: 14px;
    font-weight: 500;
    letter-spacing: 0;
    line-height: 18px;
  }
  .platform-tab[aria-current="page"] {
    background: var(--lit-tint);
    color: var(--lit-ink);
    font-weight: 600;
  }
  .platform-tab-mark {
    display: contents;
  }
  .platform-tab-glyph {
    width: 20px;
    height: 20px;
    color: var(--text-muted);
  }
  .platform-tab[aria-current="page"] .platform-tab-glyph {
    color: inherit;
  }
  .platform-tab-label {
    flex: 1 1 auto;
    text-align: start;
    overflow: hidden;
    text-overflow: ellipsis;
  }
  .platform-tab-badge,
  .platform-tab-votes {
    position: static;
    order: 2;
    flex: none;
    min-width: 18px;
    height: 18px;
    padding: 0 5px;
    font-size: 11px;
  }

  /* THE COMMUNITIES TAB IS A ROW LIKE THE OTHERS (18 Nov 2026): its glyph,
     its word and, at the row's end, every vote waiting on you
     (`.platform-tab-votes`, the row's one number: the grey count of unread
     channels gives way to it, by the rule beside the badge's own). It was
     the Recents section's "All 13 communities" row, under the list, while
     its own page was Home's. */
  /* ON A COMMUNITY'S PAGE ITS OWN ROW IS LIT, NOT COMMUNITIES. The tab keeps
     `aria-current` (the router lights Communities there, and the declared
     checks read it); only its fill gives way to the row that says which. */
  .platform-tabs:has(.platform-rail-community[aria-current="page"]) #platform-tab-workshop[aria-current="page"] {
    background: transparent;
    color: var(--text-primary);
    font-weight: 500;
  }
  .platform-tabs:has(.platform-rail-community[aria-current="page"]) #platform-tab-workshop[aria-current="page"] .platform-tab-glyph {
    color: var(--text-muted);
  }

  /* ── THE HEADINGS: the places column's small capitals ── */
  .platform-rail-head {
    position: relative;
    flex: none;
    display: flex;
    align-items: center;
    height: 28px;
    margin-top: 12px;
    padding: 0 8px;
    color: var(--text-muted);
    font-size: 12px;
    font-weight: 700;
    line-height: 16px;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    white-space: nowrap;
  }
  .platform-rail-head-label {
    flex: 1 1 auto;
    min-width: 0;
    padding-inline-end: 28px;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  /* THE SEARCH BESIDE "COMMUNITIES", while the pointer is over the section
     (its heading, its rows or All under them) or the search has focus. A
     touch screen has no hover to find it with, so there it stays. */
  .platform-rail-search {
    position: absolute;
    top: 50%;
    inset-inline-end: 2px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 26px;
    height: 26px;
    border-radius: 8px;
    color: var(--text-muted);
    opacity: 0;
    transform: translateY(-50%);
    text-decoration: none;
    transition: opacity 120ms ease, background-color 120ms ease, color 120ms ease;
    -webkit-tap-highlight-color: transparent;
  }
  .platform-rail-search-glyph {
    width: 16px;
    height: 16px;
    stroke-width: 2;
  }
  .platform-rail-communities:hover .platform-rail-search,
  .platform-rail-search:focus-visible {
    opacity: 1;
  }
  .platform-rail-search:hover,
  .platform-rail-search:focus-visible {
    background: color-mix(in srgb, var(--lit-tint) 70%, transparent);
    color: var(--lit-ink);
  }
  .platform-rail-search:focus-visible {
    outline: 2px solid var(--lit-ink);
    outline-offset: 1px;
  }
  @media (hover: none) {
    .platform-rail-search { opacity: 1; }
  }

  /* ── YOUR COMMUNITIES (features/nav/rail-communities.tsx) ── */
  .platform-rail-communities {
    display: flex;
    flex: none;
    flex-direction: column;
    gap: 1px;
  }
  /* Until its rows are drawn (the heading is all it holds: the prerender,
     and a cold load until the list is read), it keeps the height this device
     last drew it at, so "All 31 communities" under it does not drop 185px as
     they arrive (#10; `first-paint-reserved`, as Home's areas). */
  html.first-paint-reserved .platform-rail-communities:has(> .platform-rail-head:last-child) {
    min-height: var(--reserve-rail-communities);
  }
  .platform-rail-community {
    position: relative;
    z-index: 1;
    display: flex;
    align-items: center;
    gap: 9px;
    height: 36px;
    padding: 0 8px;
    border-radius: 10px;
    color: var(--text-primary);
    font-size: 14px;
    font-weight: 500;
    line-height: 18px;
    text-decoration: none;
    white-space: nowrap;
    -webkit-tap-highlight-color: transparent;
    transition: background-color 120ms ease, color 120ms ease;
  }
  .platform-rail-community[aria-current="page"] {
    background: var(--lit-tint);
    color: var(--lit-ink);
    font-weight: 600;
  }
  /* The row being dragged onto My apps (#6025): the kit's clone, on a solid
     surface so it reads over the grid. Without it the clone takes the row's
     hover tint, or the rail's group background, which can be clear. */
  .platform-rail-community.un-reorder-ghost {
    background: var(--bg-primary);
    border-radius: 10px;
  }
  .platform-rail-tile {
    flex: none;
    width: 22px;
    height: 22px;
    border-radius: 6px;
    overflow: hidden;
    display: grid;
    place-items: center;
    font-size: 12px;
    font-weight: 700;
    line-height: 1;
  }
  .platform-rail-tile > span { font-size: 13px; }
  .platform-rail-name {
    flex: 1 1 auto;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
  }
  .platform-rail-votes {
    flex: none;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    min-width: 18px;
    height: 18px;
    padding: 0 5px;
    border-radius: 999px;
    background: var(--accent);
    color: #fff;
    font-size: 11px;
    font-weight: 700;
    line-height: 1;
  }
  @media (hover: hover) {
    .platform-rail-community:not([aria-current="page"]):hover,
    .platform-tabs:has(.platform-rail-community[aria-current="page"]) #platform-tab-workshop:hover {
      background: color-mix(in srgb, var(--lit-tint) 55%, transparent);
      color: var(--lit-ink);
    }
  }

  /* ── THE COMMUNITIES YOU PINNED (features/nav/rail-pinned.tsx) ──
     Above your communities, under their own heading, drawn as they are. */
  .platform-rail-pinned:not(.hidden) {
    display: flex;
    flex: none;
    flex-direction: column;
    gap: 1px;
  }
  .platform-rail-pinned > .platform-rail-nest {
    margin-top: -1px;
  }
  /* THE "PIN HERE" SLOT (#5323): the one row the section draws while a My
     apps tile is in the air, after the pins. A dashed tile in the lit colour
     says "here"; a drop that would be refused says so in words instead (the
     muted states). */
  .platform-rail-pin-drop {
    display: flex;
    flex: none;
    align-items: center;
    gap: 9px;
    height: 36px;
    padding: 0 8px;
    border-radius: 10px;
    color: var(--text-muted);
    font-size: 14px;
    font-weight: 600;
  }
  .platform-rail-pin-drop[data-drop-state='ok'] {
    background: color-mix(in srgb, var(--lit-tint) 70%, transparent);
    color: var(--lit-ink);
  }
  .platform-rail-pin-drop-tile {
    flex: none;
    width: 22px;
    height: 22px;
    border-radius: 6px;
    border: 1.5px dashed currentColor;
    box-sizing: border-box;
  }
  .platform-rail-pin-drop-label {
    flex: 1 1 auto;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  /* THE DRAGGED PINNED ROW'S TILE (#5323): the ghost that follows the pointer
     while a pinned community is dragged back out of the sidebar. Portaled to
     the body (the sidebar clips), pointer-events:none so it never becomes the
     hit-test, and it carries the "Unpin" caption only while it is outside the
     sidebar: the state whose release takes the pin off. */
  .platform-rail-pin-ghost {
    position: fixed;
    inset-inline-start: 0;
    top: 0;
    z-index: 80;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 3px;
    pointer-events: none;
    transform: translate(-50%, -50%) scale(1.05);
  }
  .platform-rail-pin-ghost .platform-rail-tile {
    box-shadow: 0 10px 24px rgba(0, 0, 0, 0.18);
  }
  .platform-rail-pin-ghost-caption {
    padding: 2px 8px;
    border-radius: 8px;
    background: var(--lit-ink);
    color: var(--bg-primary);
    font-size: 10px;
    font-weight: 600;
    white-space: nowrap;
  }
  @media (prefers-reduced-motion: reduce) {
    .platform-rail-pin-ghost { transform: translate(-50%, -50%); }
  }
  /* Reduce motion setting (#6510): the same, when Settings asks for it. */
  :where(html[data-motion="reduce"]) .platform-rail-pin-ghost { transform: translate(-50%, -50%); }

  /* ── YOU AT THE FOOT, SETTINGS AT THE END OF YOUR ROW ── */
  .platform-tabs::after {
    margin: auto 6px 6px;
  }
  #platform-tab-me {
    padding-inline-end: 46px;
  }
  /* IN THE FLOW, AT THE END OF YOUR ROW (1 November 2026). It was pinned to
     the sidebar's bottom edge; once the sidebar scrolls when it is taller
     than the screen, that edge is the bottom of what shows, and the cog
     stayed there over other rows while You scrolled away. It takes no
     height of its own: its line (36px, and the 1px gap) comes back as a
     negative margin, so You, next in `order`, sits on the same line, under
     it, and both scroll together. */
  .platform-rail-settings {
    position: relative;
    align-self: flex-end;
    /* Never squeezed: in a sidebar that holds more than fits, a flex child
       of no fixed basis shrank to its 20px glyph. */
    flex: none;
    width: 36px;
    height: 36px;
    margin: 0 0 -37px;
    border-radius: 10px;
  }
  .platform-rail-settings-glyph {
    width: 20px;
    height: 20px;
  }

  /* ── v3: WHAT THE SECOND COLUMN HELD, NESTED UNDER ITS ROW ────────────
     features/nav/rail-nest.tsx. The community whose page is up opens its
     places under its row (features/nav/rail-communities.tsx: the section
     column's own list, ../dev-board/workshop/project-places.tsx). So there
     is no second column from here: the page has the 264px it took. Messages
     nested its five latest conversations here too until 7 Nov 2026; the
     inbox draws its own list beside a conversation now.

     ONE INDENT A LEVEL, ONE LINE. A nested row's glyph starts 30px in; a
     group under a sub-header (Channels, Topics) is tabbed in a step
     further, its sub-header where the rows above it start. One hairline runs
     unbroken from under the parent's tile to the last row, past the
     sub-headers. The sub-headers are sentence case: the section headings'
     small capitals are a level up.

     THE PARENT ROW GIVES ITS FILL TO THE ROW LIT UNDER IT. It keeps
     `aria-current` (the declared checks and a screen reader read it), and is
     named in the ink and a heavier weight instead, so one row is lit. */
  /* The part's one grid row is what features/nav/rail-nest.tsx animates
     (`0fr` to `1fr`, which is the rows' own height on every frame). */
  /* ITS ONE COLUMN IS THE RAIL'S WIDTH (N19). With no column size the
     implicit track grew to the widest row, which never wraps (350px inside
     199px), so a long name ran past the edge and was clipped by the
     overflow with no ellipsis. Sized to the rail, each label ends in "…". */
  .platform-rail-nest {
    flex: none;
    display: grid;
    grid-template-rows: minmax(0, 1fr);
    grid-template-columns: minmax(0, 1fr);
    overflow: hidden;
  }
  .platform-rail-nest[data-nest="closing"] {
    pointer-events: none;
  }
  /* Under a community's row the part is a child of the section, whose 1px
     gap would arrive with it and go with it: a step in the rows below on
     both ends of the move. */
  .platform-rail-communities > .platform-rail-nest {
    margin-top: -1px;
  }
  .platform-rail-nest-in {
    position: relative;
    display: flex;
    flex-direction: column;
    min-height: 0;
    padding: 1px 0 4px;
  }
  .platform-rail-nest-in::before {
    content: "";
    position: absolute;
    top: 2px;
    bottom: 6px;
    inset-inline-start: 18px;
    width: 1px;
    background: color-mix(in srgb, var(--text-muted) 38%, transparent);
    pointer-events: none;
  }
  .platform-rail-nest .dev-ws-places {
    min-height: 0;
  }
  .platform-rail-nest :is(.dev-ws-places-nav, .dev-ws-places-group, .platform-rail-group) {
    display: flex;
    flex-direction: column;
    gap: 1px;
  }
  .platform-rail-nest .dev-ws-places-line {
    display: none;
  }
  .platform-rail-nest :is(.dev-ws-place, .platform-rail-sub) {
    position: relative;
    display: flex;
    align-items: center;
    gap: 8px;
    box-sizing: border-box;
    width: auto;
    height: 30px;
    margin-inline-start: 24px;
    padding-block: 0 0; padding-inline: 6px 8px;
    border-radius: 8px;
    color: var(--text-primary);
    font-size: 13.5px;
    font-weight: 500;
    line-height: 18px;
    text-decoration: none;
    white-space: nowrap;
    -webkit-tap-highlight-color: transparent;
  }
  .platform-rail-nest :is(.dev-ws-places-group .dev-ws-place, .platform-rail-group[data-rail-headed] .platform-rail-sub) {
    margin-inline-start: 36px;
  }
  .platform-rail-nest :is(.dev-ws-place, .platform-rail-sub)[aria-current="page"] {
    background: var(--lit-tint);
    color: var(--lit-ink);
    font-weight: 600;
  }
  @media (hover: hover) {
    .platform-rail-nest :is(.dev-ws-place, .platform-rail-sub):not([aria-current="page"]):hover {
      background: color-mix(in srgb, var(--lit-tint) 55%, transparent);
      color: var(--lit-ink);
    }
  }
  .platform-rail-nest :is(.dev-ws-place-glyph, .platform-rail-sub-glyph) {
    flex: 0 0 16px;
    width: 16px;
    height: 16px;
    margin: 0;
    color: var(--text-muted);
  }
  .platform-rail-nest [aria-current="page"] :is(.dev-ws-place-glyph, .platform-rail-sub-glyph) {
    color: inherit;
  }
  .platform-rail-nest :is(.dev-ws-place-label, .platform-rail-sub-name) {
    flex: 1 1 auto;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
  }
  .platform-rail-nest :is(.dev-ws-place-count, .platform-rail-sub-count) {
    flex: none;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    min-width: 16px;
    height: 16px;
    padding: 0 4px;
    border-radius: 999px;
    background: var(--accent);
    color: #fff;
    font-size: 10px;
    font-weight: 700;
    line-height: 1;
  }
  /* A conversation's and a channel's count is new to read (#18): grey, as
     the Messages tab's is. Needs you's votes keep the accent. */
  .platform-rail-nest :is(.platform-rail-sub-count, :is([data-place="discussion"], [data-place^="c:"]) > .dev-ws-place-count) {
    background: var(--text-faint, #8e8e93);
  }
  .platform-rail-nest :is(.dev-ws-places-head, .platform-rail-subhead),
  .platform-rail-nest .dev-ws-places-group + .dev-ws-places-group .dev-ws-places-head {
    flex: none;
    padding-block: 8px 3px; padding-inline: 30px 8px;
    color: var(--text-muted);
    font-size: 12px;
    font-weight: 600;
    line-height: 16px;
    letter-spacing: 0;
    text-transform: none;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }
  .platform-rail-nest-in > :first-child > .platform-rail-subhead {
    padding-top: 3px;
  }
  .platform-rail-nest .platform-rail-group:not([data-rail-headed]) {
    padding-top: 4px;
  }
  /* A COMMUNITY'S APP, ITS FIRST ROW (features/nav/rail-communities.tsx),
     with the green "still open" dot at its end while the app runs: the dot
     the launcher's tile wears, without the ring a tile needs. Its places sit
     in a part inside the one that holds it, so leaving a community whose app
     is still running folds them away and keeps App. The outer part draws the
     one line and the padding round both. */
  .platform-rail-nest .platform-rail-live {
    width: 8px;
    height: 8px;
    margin-inline-end: 3px;
    box-shadow: none;
  }
  /* The dot's close control (#5525): an X in a small round disc, sitting
     exactly over the dot (the anchor's 8px right padding, the dot 3px in
     from that, its centre 15px from the row's edge) and shown only on the
     disc's hover or keyboard focus. The dot is hidden while the X shows, so
     the two are never drawn together. */
  .platform-rail-nest .platform-rail-app-row {
    position: relative;
  }
  .platform-rail-nest .platform-rail-live-stop {
    position: absolute;
    top: 50%;
    inset-inline-end: 6px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    width: 18px;
    height: 18px;
    padding: 0;
    border: 0;
    border-radius: 999px;
    background: color-mix(in srgb, var(--lit-tint) 55%, transparent);
    color: var(--text-primary);
    opacity: 0;
    cursor: pointer;
    transform: translateY(-50%);
  }
  .platform-rail-nest .platform-rail-live-stop:hover,
  .platform-rail-nest .platform-rail-live-stop:focus-visible {
    opacity: 1;
  }
  .platform-rail-nest .platform-rail-live-stop-glyph {
    width: 11px;
    height: 11px;
  }
  .platform-rail-nest .platform-rail-app-row:has(.platform-rail-live-stop:is(:hover, :focus-visible)) .platform-rail-live {
    visibility: hidden;
  }
  .platform-rail-nest .platform-rail-places > .platform-rail-nest-in {
    padding: 0;
  }
  .platform-rail-nest .platform-rail-app-row + .platform-rail-places > .platform-rail-nest-in {
    padding-top: 1px;
  }
  .platform-rail-nest .platform-rail-places > .platform-rail-nest-in::before {
    display: none;
  }
  /* The parent: lit by its page, filled by none, its count said under it. */
  .platform-rail-community[data-rail-open][aria-current="page"] {
    background: transparent;
    color: var(--text-primary);
    font-weight: 650;
  }

  /* ── MESSAGES ON A DESKTOP: THE LIST AS THE PAGE ─────────────────────
     features/messages/index.tsx. With nothing open the whole list is the
     page (`messages-list-page`, All messages): its search, its headings, its
     rows with their previews and times, in a readable column. An open
     conversation has the list beside it (from v3 until 7 Nov 2026 the list
     sat in the sidebar instead, and the conversation had the page alone). */
  /* AUDIT C04 (2 Nov 2026): a conversation with nothing beside it keeps a
     reading width, as All messages keeps its column, rather than running
     about 1500px wide at 1920, its bubbles a screen apart. Since the list
     came back beside it, that is a conversation set to Full width. */
  .messages-layout.messages-list-collapsed > .messages-thread-pane:last-child {
    max-width: 960px;
    margin-inline: auto;
  }
  .messages-layout.messages-list-page > .messages-thread-pane {
    display: none;
  }
  .messages-layout.messages-list-page > .messages-list-pane {
    flex: 1 1 auto;
    width: auto;
    max-width: 720px;
    margin: 0 auto;
    padding-inline-end: 0;
  }
}

/* ── Messages is one inbox, and says which kind each row is (#2718) ──
   frontend/src/features/messages/inbox.ts carries the argument: people, the
   Homeroom bot and changes in flight in one list, ordered on one clock, told apart
   by a mark rather than by three sidebars — which is what Slack and Teams do
   with a channel, a DM and a bot thread. What lives here is the filter row
   and the two shapes the list grew. */

/* THE FILTER ROW, with the control that starts something at its far end.
   The plus moved here from beside the title: a title row is where a screen
   says what it IS, a filter row is where it says what it is SHOWING, and the
   thing that adds to what is shown belongs on the line with the thing that
   narrows it. The Workshop's tab strip now wears the same arrangement, which
   is what makes the two screens read as one product. */
/* ── THE INBOX'S OWN CHROME (#2718 review) ────────────────────────────
   A search, a segmented strip, and what starts something — in that order,
   which is the order the questions come in: what am I looking for, which
   kinds am I looking through, and what if it is not here yet. */

/* THE SEARCH, at the head of the pane where the screen's own <h2> used to
   sit. The bar above already says Messages; a list that runs to hundreds of
   rows and holds three kinds of thing needed the space for this instead. */
.messages-search {
  position: relative;
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  /* 20px AT THE TOP, NOT 12: the header is `rounded-b-2xl -mb-2`, so this
     pane starts 8px under its bottom edge and 12 of those were spent getting
     back to level — 4px of air under the bar, which reads as none. The 8 the
     notch owes plus 12 of air, matching the step the Workshop's chip takes
     for the same reason. */
  margin: 20px 16px 10px;
}
.messages-search-glyph {
  position: absolute;
  inset-inline-start: 12px;
  color: var(--text-muted);
  pointer-events: none;
}
.messages-search-input {
  width: 100%;
  height: 40px;
  padding-block: 0 0; padding-inline: 40px 12px;
  border: 1px solid var(--app-sheet-line);
  border-radius: 999px;
  background: var(--dc-sheet-raise);
  color: var(--text-primary);
  font: inherit;
  font-size: 15px;
}
.messages-search-input::placeholder { color: var(--text-muted); }
.messages-search-input:focus {
  outline: none;
  border-color: var(--brand-line);
  box-shadow: 0 0 0 3px var(--brand-tint);
}
/* The UA's own clear affordance, which draws a second glyph of its own in a
   size and colour this shell does not choose. */
.messages-search-input::-webkit-search-cancel-button { -webkit-appearance: none; }

/* THE SEARCH AND THE "+" ON ONE LINE (16 Oct 2026). The filter strip the
   "+" ended (#2778) went: the list's sections are headed (Homeroom bot,
   Agents, People), so the headings say which is which. */
.messages-toolbar {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 8px;
  margin: 20px 16px 10px;
}
.messages-toolbar .messages-search {
  flex: 1 1 auto;
  min-width: 0;
  margin: 0;
}
.messages-new-btn {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border: 1px solid var(--brand-line);
  border-radius: 9999px;
  background: var(--brand-tint);
  color: var(--brand-ink);
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.messages-new-btn svg { width: 18px; height: 18px; stroke-width: 2; }
.messages-new-btn[aria-expanded="true"] { background: var(--brand-ink); color: var(--bg-primary); }
/* The popover: the vote picker's frame (.dev-vote-pop) — body-mounted,
   fixed, placed from the button's rect by lib/anchor-popover.ts. */
.messages-new-pop {
  position: fixed;
  z-index: 2000;
  width: 240px;
  box-sizing: border-box;
  padding: 6px;
  border-radius: 16px;
  background: var(--bg-primary);
  border: 1px solid var(--border);
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.28);
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.messages-new-option {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 8px 10px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: var(--text-primary);
  font: inherit;
  text-align: start;
  cursor: pointer;
}
.messages-new-option:hover, .messages-new-option:focus-visible { background: var(--bg-tertiary); outline: none; }
.messages-new-option svg { flex: 0 0 auto; width: 20px; height: 20px; color: var(--brand-ink); }
.messages-new-option-label { display: block; font-size: 14px; font-weight: 600; }
.messages-new-option-hint { display: block; font-size: 12px; color: var(--text-muted); }

/* THE SECTION HEAD (#2783): People over the conversations, small and muted
   so it heads the list without competing with its rows. */
.messages-section-head {
  display: flex;
  align-items: center;
  margin: 0;
  padding: 16px 16px 8px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: var(--text-muted);
}
/* 16 Oct 2026: how many messages from people are unread ("3 unread") sits
   at the heading's trailing edge in the row's own case, grey: new to read,
   not waiting on you (#18). */
.messages-section-name { min-width: 0; }
.messages-section-aside {
  margin-inline-start: auto;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0;
  text-transform: none;
  white-space: nowrap;
}
/* A SECTION'S ROWS ARE A CARD: the grouped list's shape (@/components/ui/
   grouped-list.tsx), spelled here because these rows are app.css's. The same
   plane colour, the same 20px radius and the same inset hairline in the
   sheets' edge colour, so Messages, Workshop and Discover read as one
   material. `overflow: hidden` clips a row's hover and selected fill to the
   card's corners. */
.messages-section-card {
  margin: 0 16px 8px;
  overflow: hidden;
  border-radius: 20px;
  background: var(--dc-sheet-solid);
  box-shadow: inset 0 0 0 1px var(--app-sheet-line);
}
/* A channel's tile is the `#` it is named with. */
.messages-channel-tile {
  background: var(--bg-tertiary);
  color: var(--text-muted);
  font-size: 22px;
  font-weight: 700;
}
.messages-thread-channel-tile { width: 36px; height: 36px; font-size: 18px; }
/* An app channel's handle, muted after its name. */
.messages-channel-handle {
  margin-inline-start: 6px;
  color: var(--text-muted);
  font-size: 13px;
  font-weight: 500;
}

/* The two new rows' leading tiles, at the `lg` square UserAvatar's 44px box
   so all three kinds line up down the left edge. `.app-icon-tile` draws the
   app face; this call site adds only the geometry, which is the rule app.css
   states for every tile call site. */
.messages-inbox-tile {
  flex: 0 0 auto;
  width: 44px;
  height: 44px;
  border-radius: 12px;
  overflow: hidden;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  font-weight: 700;
}


/* ── The rail, peeked back over a folded rail (#2718, #2764) ─────────
   frontend/src/features/nav/tab-bar.tsx carries the argument: a rail the
   viewer folded comes back on hover and stops spending width while they
   work — an auto-hiding dock and Slack's own collapsed rail are this move.
   NOT over a running app (#3138): an app's own controls put the pointer at
   the left edge all the time, so the hot zone is not rendered there. A rail
   folded beside an app comes back from #sidebar-toggle, in the header. */

/* THE HOT ZONE, and the only thing that can start a peek. Narrow enough that
   it never intercepts a pointer heading for the app's own left edge, wide
   enough to be findable without aiming. */
.platform-rail-peek {
  position: fixed;
  inset-inline-start: 0;
  top: calc(var(--browser-banner-h, 0px) + var(--platform-header-h)
    + var(--platform-safe-top, 0px));
  bottom: 0;
  width: 18px;
  /* UNDER the peeked rail and OVER the app, so the pointer can cross from one
     to the other without passing through the app's own hover targets. */
  z-index: 39;
}
/* A PHONE HAS NO POINTER TO HOVER WITH, and an invisible strip down the left
   edge of a touch screen eats the swipe that goes back. Below the desktop
   breakpoint the zone is not there at all — which is also why the peek can
   only ever happen on the layout that has a rail to peek. */
@media (max-width: 767px) {
  .platform-rail-peek { display: none; }
}

@media (min-width: 768px) {
  /* FOLDED BY HAND: gone, but coming back on hover. Not `hidden` — that is
     the ROUTER's answer about whether this route has a rail, and the two have
     to stay tellable apart (frontend/src/features/nav/tab-bar.tsx). A peeking
     bar keeps both classes and this rule stands aside for it, which is what
     makes the hot zone at the window's edge the way back. It stands aside
     too while the rail slides away (`platform-tabs-leaving`, N21:
     frontend/src/features/nav/rail-slide.ts). */
  .platform-tabs.platform-tabs-folded:not(.platform-tabs-peek):not(.platform-tabs-leaving) {
    display: none;
  }
  /* …AND ITS FOOTER GOES WITH IT (#2762). The parked strip is fixed to the
     rail's corner rather than drawn inside the rail, so a folded rail would
     otherwise leave it floating alone over the foot of the page. */
  body:has(#platform-tabs.platform-tabs-folded:not(.platform-tabs-peek)) .platform-parked {
    display: none;
  }

  /* THE PEEKED RAIL: the same element, over the app instead of beside it.
     Everything about its inside — the rows, the labels, the lit tab — is the
     rail's own, because it IS the rail; what changes is that it floats. */
  .platform-tabs.platform-tabs-peek {
    z-index: 40;
    /* THE SAME FROSTED SURFACE AS THE DOCKED RAIL (#2795). This was the solid
       `--dc-sheet`, so the rail came back over the page as a white panel
       rather than as the rail. `.platform-tabs` already carries the frost;
       restating the fill is what stops the solid one winning, and the
       peeked rail floats over the page, so with no blur it is solid in the
       plane colour, and unclipped, so its shadow still falls. */
    background-color: var(--dc-sheet-solid);
    backdrop-filter: var(--dc-frost);
    -webkit-backdrop-filter: var(--dc-frost);
    border-inline-end: 1px solid var(--app-sheet-line);
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.18);
    /* A FADE, NOT A SLIDE. A rail that slides in from the edge races the
       pointer that summoned it and arrives under it; one that fades is
       already where it is going to be. It was tried both ways in the design
       study and this is the one that stopped feeling like a mistake. */
    animation: platform-rail-peek-in 140ms ease-out;
    /* On the peek itself, so the way back in from a half-finished fade is
       the same curve as the way out. */
    transition: opacity 200ms ease-in;
  }
  /* …AND IT FADES OUT THE SAME WAY (#2795). It used to snap: the grace
     period ran out and the rail went straight to `display: none`. The peek
     now stays up for 200ms with this class on (frontend/src/features/nav/
     rail-peek.ts, PEEK_FADE_MS), and pointing back at it during the fade
     takes the class off, so the rail comes back from wherever it had got to. */
  .platform-tabs.platform-tabs-peek.platform-tabs-peek-out {
    opacity: 0;
  }
  /* The peeked rail's footer: the parked strip rides ON the rail rather than
     under it (a peeking rail is 40, above the strip's 31 beside a docked one)
     and fades in with it. Only a platform screen's folded rail can carry one — over a
     running app the strip is hidden with the bar (features/nav/parked-strip.tsx). */
  body:has(#platform-tabs.platform-tabs-peek) .platform-parked {
    z-index: 41;
    animation: platform-rail-peek-in 140ms ease-out;
  }

}

@keyframes platform-rail-peek-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}

@media (prefers-reduced-motion: reduce) {
  .platform-tabs.platform-tabs-peek,
  body:has(#platform-tabs.platform-tabs-peek) .platform-parked { animation: none; }
  .platform-tabs.platform-tabs-peek { transition: none; }
}
/* Reduce motion setting (#6510): the same, when Settings asks for it. */
:where(html[data-motion="reduce"]) .platform-tabs.platform-tabs-peek,
:where(html[data-motion="reduce"]) body:has(#platform-tabs.platform-tabs-peek) .platform-parked { animation: none; }
:where(html[data-motion="reduce"]) .platform-tabs.platform-tabs-peek { transition: none; }

/* ── #platform-side-panel — THE PANEL BESIDE A RUNNING APP ───────────────
   On a desktop-width window, while an app runs on its App tab, the pages
   about it (its Workshop, its discussion, a proposal, an issue, a change, a
   conversation) open in a panel beside it rather than replacing it —
   frontend/src/features/side-panel/, whose controller carries the why.

   THE APP IS NEVER RE-PARENTED, HIDDEN OR RE-SOURCED: its frame lives in
   #app-view, and the only thing that changes about #app-view is its SIZE — a
   right margin the width of the panel, keyed off `<html data-side-panel>`,
   which the panel's mount writes while the panel is on screen. <html> is not
   React-owned (main.tsx hydrates <body>), and a margin on a flex item is a
   resize, which an iframe survives with its document intact.

   THE BREAKPOINT IS 1024px, not the rail's 768. The panel is
   clamp(360px, 36vw, 560px) wide and the app keeps about 480px beside it; at
   768px the app would be left 408, and 1024 (`lg`, used above already) is the
   first breakpoint where both fit — 655px of app at the narrowest. Below it
   the panel is not drawn and the app takes the width back, so a window that
   shrinks while the panel is open simply hides it, navigating nothing; every
   link below the breakpoint navigates as it always has (the controller's
   DESKTOP_QUERY is the same figure). */
:root {
  --side-panel-w: clamp(360px, 36vw, 560px);
}

.side-panel {
  /* From the top of the app's sheet to the floor, down the right edge. The
     same arithmetic the rail uses for "under the header", less the half rem
     the header's rounded lower edge overlaps the screen below it — which is
     where #app-view, and so the app's sheet, begins. */
  position: fixed;
  top: calc(var(--browser-banner-h, 0px) + var(--platform-header-h)
    + var(--platform-safe-top, 0px) - .5rem);
  inset-inline-end: 0;
  bottom: 0;
  width: var(--side-panel-w);
  /* Over the app view and the header's transparent lower edge, under every
     sheet, menu and rail (30 and up). */
  z-index: 20;
  display: flex;
  flex-direction: column;
  /* THE APP'S SHEET, CONTINUED. The running app arrives as a raised sheet with
     a rounded top and a hairline (see "THE APP SHEET" above); the panel is the
     rest of that sheet, split from it by one hairline, and it takes the
     sheet's outer corner — the app's own top-right corner goes square while
     the panel is up (below). */
  background: var(--home-ground);
  border-top: 1px solid var(--app-sheet-line);
  border-inline-start: 1px solid var(--app-sheet-line);
  border-start-end-radius: 1.75rem;
  overflow: hidden;
}

/* THE DIVIDER (#2886) — the panel's left edge, as a handle. It is the
   panel's child and is drawn on the line between the panel and what is beside
   it (below), and shows itself only under the pointer, on focus and while
   held: a brand-coloured bar on that line. The width it
   sets is `--side-panel-w` on <html> (features/side-panel/resize.ts), so the
   app beside it follows through the margin rule below. */
.side-panel-divider {
  /* ON THE LINE BETWEEN THE TWO HALVES (iPhone Duo, 1 November 2026), not
     just inside the panel. Fixed, so the panel's clipping (overflow: hidden,
     for its corner) does not reach it while it stays the panel's child, and
     hides and shows with it; centred on `--divider-at`, the line's distance
     from the window's right edge. Beside an app that is the panel's own edge,
     where the two sheets meet; beside the Homeroom bot's list it is the
     pane's own edge too, the hairline it drags (below), with half the handle
     in the gutter and half over the pane. Inside the panel the bar and the
     grip sat on the panel's side of the gap. Nothing between
     it and the window may take a transform or a filter, which would make
     that ancestor its frame instead. */
  --divider-w: 10px;
  position: fixed;
  top: calc(var(--browser-banner-h, 0px) + var(--platform-header-h)
    + var(--platform-safe-top, 0px) - .5rem);
  bottom: 0;
  inset-inline-end: calc(var(--divider-at, var(--side-panel-w)) - var(--divider-w) / 2);
  width: var(--divider-w);
  z-index: 21;
  cursor: col-resize;
  touch-action: none;
  outline: none;
}
/* Beside the bot's list: Main (and a page in Main's place) is
   `--ai-main-w` wide plus the Duo's column it runs under. #6397: the handle
   is centred on that pane's own edge, the hairline it drags, so it reads as
   the edge moving and not as a line floating in the list's 16px gutter.
   Main's own handle starts where Main does, which is not under the banner
   the side panel clears. */
body:has(#ai-screen:not(.hidden)) :is(#side-panel-divider, #ai-main-divider) {
  --divider-at: calc(var(--ai-main-w) + var(--ai-edge, 0px));
}
/* IN THE MIDDLE OF THE GAP (#6447). Below 1024px the two sheets are close,
   so the list's 16px gutter is the gap you see between them, and the handle
   on the pane's edge read as stuck to the column. Half of that gutter (8px)
   toward the list puts the line, its bar and the touch grip halfway across
   the empty space. A desktop keeps the pane's own edge above: its gap is
   wide and a line in it would float. Same specificity as that rule, so
   source order decides, and this block stays before the three and halves
   rules below so those still win. */
@media (max-width: 1023.98px) {
  body:has(#ai-screen:not(.hidden)) :is(#side-panel-divider, #ai-main-divider) {
    --divider-at: calc(var(--ai-main-w) + var(--ai-edge, 0px) + 8px);
  }
}
/* #6394: with a plan open beside the page the panel holds, the panel's edge
   is the thread's edge of three columns, on the line where the panel begins.
   In halves the list has stepped aside and the preview's own handle is the
   one that drags, so this edge is not drawn (as .ai-main-pane's is not). */
body:has(#ai-screen[data-ai-preview="three"]:not(.hidden)) #side-panel-divider {
  --divider-at: calc(var(--ai-col-w) + var(--ai-preview-w) + var(--ai-edge, 0px));
}
body:has(#ai-screen[data-ai-preview="halves"]:not(.hidden)) #side-panel-divider {
  display: none;
}
#ai-main-divider {
  top: calc(var(--browser-banner-h, 0px) + var(--platform-header-h) + var(--platform-safe-top, 0px) + .5rem);
}
.side-panel-divider::after {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  inset-inline-start: calc(50% - 1.5px);
  width: 3px;
  background: var(--brand-ink);
  opacity: 0;
  transition: opacity 120ms ease;
}
/* #6397: the bar starts where the pane's rounded top corner ends (28px), so it
   meets the straight part of the edge instead of standing beside the curve.
   Only the panes that have that corner: Main and the side panel beside the bot
   page. #ai-preview-divider has none, and neither does the side panel beside a
   running app (its top-left corner is square). */
body:has(#ai-screen:not(.hidden)) :is(#side-panel-divider, #ai-main-divider)::after {
  top: 1.75rem;
}
/* Under a pointer that hovers only: a finger's tap leaves iOS holding
   :hover on the handle, which kept the bar lit after the drag (iPhone Duo,
   1 November 2026). */
@media (hover: hover) {
  .side-panel-divider:hover::after { opacity: .45; }
}
.side-panel-divider:focus-visible::after,
html.side-panel-resizing .side-panel-divider::after {
  opacity: .45;
}
/* ON A TOUCH SCREEN, A HANDLE YOU CAN SEE AND HIT (iPhone Duo, 1 November
   2026). The bar above shows only under a pointer, which a finger never
   hovers over, and 10px is narrower than a fingertip, so the edge read as
   no handle at all. With a coarse pointer the handle is 24px across the
   line, reaching 12px into the pane (its rows and the reply box begin 12 to
   18px in), and a short grip on the line is drawn at rest.
   THE GRIP IS THE WHOLE MARK. The full-height bar is a pointer's hover
   cue; under a finger it ran the screen's height beside the grip, held or
   focused, and read as a second divider. The grip darkens while held. */
@media (pointer: coarse) {
  .side-panel-divider { --divider-w: 24px; }
  .side-panel-divider::after { display: none; }
  .side-panel-divider::before {
    content: "";
    position: absolute;
    top: 50%;
    inset-inline-start: calc(50% - 2px);
    width: 4px;
    height: 40px;
    margin-top: -20px;
    border-radius: 999px;
    background: var(--text-faint);
    opacity: .5;
  }
  html.side-panel-resizing .side-panel-divider::before { opacity: .85; }
}
/* WHILE HELD: the two frames would take the pointer the moment it crossed
   them and the drag would stall, so they stand aside; and nothing under the
   pointer selects or shows another cursor. */
html.side-panel-resizing iframe {
  pointer-events: none;
}
html.side-panel-resizing,
html.side-panel-resizing * {
  cursor: col-resize !important;
  user-select: none;
  -webkit-user-select: none;
}
@media (prefers-reduced-motion: reduce) {
  .side-panel-divider::after { transition: none; }
}
/* Reduce motion setting (#6510): the same, when Settings asks for it. */
:where(html[data-motion="reduce"]) .side-panel-divider::after { transition: none; }

.side-panel-head {
  /* Back · title · Expand · Close, in the header's own disc controls. */
  height: 3rem;
  padding-block: 0 0; padding-inline: 0.75rem 0.875rem;
  border-bottom: 1px solid var(--app-sheet-line);
}
/* Beside the AI tab's page (its section above has the why): Main's header
   row, its padding, its hairline, its fill and its height, so the page below
   starts where Main's chat does. */
body:has(#ai-screen:not(.hidden)) .side-panel-head {
  height: auto;
  min-height: 63px;
  gap: 10px;
  padding-block: 12px; padding-inline: 18px calc(18px + var(--ai-edge, 0px));
  background-color: var(--dc-sheet-fill);
}
/* AND ITS FOOT CLEARS THE KEYBOARD (1 Nov 2026). In the Homeroom app beside
   this page (side-panel controller canTake), a reply typed in the panel's
   own document had the keyboard over its box: the page's composers lift
   themselves, the frame does not know the keyboard is there. The kit
   measures it from the screen whichever document has the focus
   (`un-kb`, `--un-kb-inset`), so the panel ends above it. */
html.un-kb body:has(#ai-screen:not(.hidden)) .side-panel { bottom: var(--un-kb-inset, 0px); }
/* The column's × that closes the page, centred in the row rather than at its
   top (6 Nov 2026, #6425: it took the "‹ Main Chat" chip's place). */
.side-panel-head > .side-panel-ai-close { margin: 0; align-self: center; }
/* The ⋯ beside the column's heading (3 Nov 2026), at the row's end: Copy
   link, the item's own page address. It is a sibling of the heading, so it
   stays put when the heading's words are long.
   #6431: and it is a LAYER ABOVE THE PAGE, solidly (Evan, 6 Nov 2026: the
   menu "is overlapping weirdly? Maybe because it is fully transparent?").
   Its surface tokens come from .side-panel-head, which is in the lists that
   declare Messages' (above), and the wrapper stacks above the panel's body
   so no page content paints over it. */
.side-panel-more {
  position: relative;
  z-index: 2;
  margin-inline-start: auto;
  align-self: center;
}
/* The menu's own hairline, on top of the lift its base rule already draws, so
   it reads as a sheet lying over the page rather than a hole in it. */
.side-panel-more .messages-thread-menu {
  box-shadow: 0 12px 30px rgba(0, 0, 0, .18), inset 0 0 0 1px var(--messages-hair);
}
/* The column's heading, as Main's header reads (30 Oct 2026): the project's
   tile, then what is open over where it is, the rows' 15 over 13. The
   project's name is the door to it, underlined under the pointer. */
.side-panel-place {
  flex: 1 1 auto;
  align-items: center;
  gap: 10px;
  min-width: 0;
}
.side-panel-place-title {
  font-size: 15px;
  font-weight: 650;
  line-height: 20px;
  color: var(--text-primary);
}
.side-panel-place-where {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  font-size: 13px;
  line-height: 18px;
  color: var(--text-faint);
}
/* The project and the number truncate; the pill after them never does
   (#6431 — it is the page's own, at the size the page's bar drew it). */
.side-panel-place-where-text { min-width: 0; }
.side-panel-place-status { flex: none; display: inline-flex; }
/* The thin divider between the column's own two rows and the page's (#6431):
   Copy link and Open in workshop, then everything the page's ⋯ holds. */
.side-panel-menu-sep {
  height: 1px;
  margin: 4px 6px;
  background: var(--app-sheet-line);
}
.side-panel-place-link { color: inherit; text-decoration: none; border-radius: 4px; }
.side-panel-place-link:hover { color: var(--text-primary); text-decoration: underline; text-underline-offset: 2px; }
.side-panel-place-link:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.side-panel-body {
  position: relative;
  flex: 1;
  min-height: 0;
}

/* The panel's own document. Transparent until it has routed its first page —
   a shell booting in a frame paints its boot screen first — with the spinner
   behind it; then it fades in once and stays. */
.side-panel-frame {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  border: 0;
  background: transparent;
  opacity: 0;
  transition: opacity 160ms ease;
}
.side-panel-frame-ready {
  opacity: 1;
}
.side-panel-loading {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}
.side-panel-spinner {
  width: 20px;
  height: 20px;
}

@media (prefers-reduced-motion: reduce) {
  .side-panel-frame { transition: none; }
}
/* Reduce motion setting (#6510): the same, when Settings asks for it. */
:where(html[data-motion="reduce"]) .side-panel-frame { transition: none; }

@media (max-width: 1023.98px) {
  /* Below the breakpoint the panel is not drawn at all, and the rules below
     do not apply, so the app has the whole window back. 1 Nov 2026: beside
     the Homeroom bot tab's page it is the column Main Chat docks in, drawn
     from 768px (the controller's BESIDE_AI_QUERY). */
  body:not(:has(#ai-screen:not(.hidden))) #platform-side-panel {
    display: none;
  }
}
@media (max-width: 767.98px) {
  #platform-side-panel {
    display: none;
  }
}

/* ── THE SIDE PANEL'S OWN DOCUMENT (`?panel=1`) ──────────────────────────
   The platform, framed beside the Homeroom bot tab's list, showing one
   page: no header,
   no tab bar or rail, no parked strip, no banners — the top window has all
   of those — and none of the space they reserve. `in-side-panel` is put on
   <html> by head.html before the first paint, and only when the document is
   framed by a same-origin top window (a `?panel=1` address opened on its own
   is the ordinary platform). The frame is narrow, so every screen takes its
   phone layout, which is the point: the panel is a phone-width column. */
html.in-side-panel :is(#platform-header, #platform-tabs, #platform-rail-peek,
    #platform-parked, #chromeless-pill, #connection-status, #mobile-install-banner,
    #view-as-non-admin-banner, #language-notice, #platform-side-panel) {
  display: none !important;
}
html.in-side-panel {
  /* Nothing sits above a screen here, so nothing measured from the header's
     foot (the Workshop's fitted area, a sheet's cap) reserves its 52px. */
  --platform-header-h: 0px;
}
html.in-side-panel body {
  /* The bar's band, its parked-strip addition and the rail's width, all nil —
     !important because the rules that reserve them key off the bar's own
     visibility, which the router publishes only once it has routed. */
  --platform-tabs-h: 0px !important;
  --platform-bar-h: 0px !important;
  --platform-rail-w: 0px !important;
}

/* ── The Workshop tab, cleaned up (#4457) ─────────────────────────────
   One list per section, a hairline between rows (workshop/work-row.tsx).
   A row is a neutral tile, the title (15px, two lines at most), one line
   in words (13px, muted), then small tags for what is happening on it and,
   on a change up for a vote, its votes. The title is a link stretched over
   the row; the Vote button sits above it. */
.dev-ws-wlist { display: flex; flex-direction: column; margin-top: 4px; }
/* A row is square at rest and rounded only while it is lit (hovered, open
   beside the board, focused): the hairline between rows is the row's top
   border, and a 12px corner bent each end of that line down, so every row
   read as the top of a card of its own. Lit, the row's own line goes
   clear too, as the next row's does, since its fill says where it is. */
.dev-ws-wrow {
  position: relative; display: flex; align-items: flex-start; gap: 12px;
  padding: 12px 2px; min-width: 0; border-radius: 0;
}
.dev-ws-wrow + .dev-ws-wrow,
.dev-ws-week + .dev-ws-week { border-top: 1px solid var(--app-sheet-line); }
.dev-ws-wrow:hover { background: var(--state-neutral-bg); }
.dev-ws-wrow[data-on] { background: var(--lit-tint); }
.dev-ws-wrow[data-on] + .dev-ws-wrow,
.dev-ws-wrow:hover + .dev-ws-wrow { border-top-color: transparent; }
.dev-ws-wrow:hover, .dev-ws-wrow[data-on] { margin: 0 -8px; padding-inline-start: 10px; padding-inline-end: 10px; }
.dev-ws-wrow:is(:hover, [data-on], :has(> .dev-ws-wrow-main > .dev-ws-wrow-link:focus-visible)) { border-radius: 12px; border-top-color: transparent; }
.dev-ws-wrow-tile {
  flex: none; width: 34px; height: 34px; margin-top: 1px; border-radius: 10px;
  display: inline-flex; align-items: center; justify-content: center;
  background: var(--state-neutral-bg); color: var(--text-secondary);
}
.dev-ws-wrow-tile svg { width: 18px; height: 18px; }
.dev-ws-wrow-main { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.dev-ws-wrow-link {
  font-size: 15px; font-weight: 650; line-height: 1.3; color: var(--text-primary); text-decoration: none;
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
}
.dev-ws-wrow-link::after { content: ''; position: absolute; inset: 0; border-radius: inherit; }
.dev-ws-wrow-link:focus-visible { outline: none; }
.dev-ws-wrow:has(> .dev-ws-wrow-main > .dev-ws-wrow-link:focus-visible) { outline: 2px solid var(--accent); outline-offset: 2px; }
.dev-ws-wrow-sub {
  font-size: 13px; line-height: 1.35; color: var(--text-muted);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.dev-ws-wrow-status { margin-top: 6px; display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
.dev-ws-wrow-chev { flex: none; width: 16px; height: 16px; margin-top: 2px; color: var(--text-muted); opacity: .7; }
.dev-ws-tag {
  display: inline-flex; align-items: center; gap: 5px; height: 22px; padding: 0 8px; border-radius: 999px;
  font-size: 12px; font-weight: 600; white-space: nowrap;
  background: var(--state-neutral-bg); color: var(--text-secondary);
}
.dev-ws-tag svg { width: 12px; height: 12px; }
.dev-ws-tag .dc-status-spinner-arc { width: 11px; height: 11px; }
.dev-ws-tag[data-tone="run"] { color: var(--lit-ink); background: var(--lit-tint); }
.dev-ws-tag[data-tone="ok"] { color: var(--state-ok); background: var(--state-ok-bg); }
.dev-ws-tag[data-tone="warn"] { color: var(--state-attention); background: var(--state-attention-bg); }
.dev-ws-tag[data-tone="bad"] { color: var(--state-blocked); background: var(--state-blocked-bg); }
/* #4499: how far a check run is, as a thin bar inside the checks chip
   (the cards' status band, the Workshop's rows, All items). It is drawn in
   the chip's own ink, so it wears whichever tone the chip does; the exact
   count is the chip's tooltip and the bar's accessible name. */
.checks-chip-bar {
  position: relative; flex: none; display: inline-block; overflow: hidden;
  width: 36px; height: 4px; margin-inline-start: 4px; border-radius: 999px; vertical-align: middle;
  background: color-mix(in srgb, currentColor 22%, transparent);
}
.checks-chip-bar-fill {
  position: absolute; inset-block: 0 0; inset-inline: 0 auto; border-radius: inherit;
  background: currentColor; transition: width .3s ease;
}
@media (prefers-reduced-motion: reduce) { .checks-chip-bar-fill { transition: none; } }
/* Reduce motion setting (#6510): the same, when Settings asks for it. */
:where(html[data-motion="reduce"]) .checks-chip-bar-fill { transition: none; }
/* #4628: the run's early phase — the preview build and the checks'
   preparation, before the run knows how many checks it will run — shows
   the same bar pulsing, with nothing to fill it yet. The pulse is the
   Testing card's ledger bar's own (dev-ledger-progress-pulse). */
.checks-chip-bar-busy {
  background: color-mix(in srgb, currentColor 45%, transparent);
  animation: dev-ledger-progress-pulse 1.4s ease-in-out infinite;
}
@media (prefers-reduced-motion: reduce) {
  .checks-chip-bar-busy { animation: none; }
}
/* Reduce motion setting (#6510): the same, when Settings asks for it. */
:where(html[data-motion="reduce"]) .checks-chip-bar-busy { animation: none; }
/* A change's vote (#4486): the card's own status bar with its own words
   ("0 of 1 approval"), as long as its words plus the 56px the thin bar it
   replaced took, then the card's Vote button. #4718: the pair takes a line
   of its own under the row's tags, at that line's far end
   (`margin-left: auto`), on every width, a phone's too — never on the tags
   line, so rows beside each other keep their pills lined up. Only Vote
   takes a click: a tap on the bar is a tap on the row. */
.dev-ws-wrow-votes { margin-top: 6px; display: flex; align-items: center; }
.dev-ws-wvote {
  position: relative; z-index: 1; margin-inline-start: auto; display: inline-flex; align-items: center; gap: 8px;
  pointer-events: none;
}
.dev-ws-wvote > .dev-ws-wvote-btn { pointer-events: auto; }
.dev-ws-wvote-state { flex: none; padding: 0 calc(10px + 56px) 0 10px; }
.dev-ws-none { margin: 6px 0 2px; font-size: 14px; color: var(--text-muted); }

/* Week by week: one row a week, which opens the week's own page. */
.dev-ws-week {
  appearance: none; border: 0; background: transparent; font: inherit; text-align: start; cursor: pointer;
  display: flex; align-items: center; gap: 12px; width: 100%; padding: 12px 2px; border-radius: 12px; color: inherit;
}
.dev-ws-week:hover { background: var(--state-neutral-bg); }
.dev-ws-week:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.dev-ws-week-main { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.dev-ws-week-head { display: flex; align-items: baseline; flex-wrap: wrap; gap: 4px 8px; font-size: 13px; color: var(--text-muted); }
.dev-ws-week-head b { font-size: 15px; font-weight: 650; color: var(--text-primary); }
.dev-ws-week-fresh {
  align-self: center; display: inline-flex; align-items: center; height: 20px; padding: 0 8px; border-radius: 999px;
  font-size: 12px; font-weight: 600; background: var(--accent-tint); color: var(--accent-wash-ink);
}
.dev-ws-week-n { flex: none; font-size: 13px; color: var(--text-muted); white-space: nowrap; }
.dev-ws-week-n b, .dev-ws-week-live { font-size: 15px; font-weight: 650; color: var(--state-ok); font-variant-numeric: tabular-nums; }
.dev-ws-week .dev-ws-wrow-chev { margin-top: 0; }
.dev-ws-weekpage { display: flex; flex-direction: column; gap: 10px; }
.dev-ws-week-meta { margin: 0; font-size: 13px; color: var(--text-muted); }
.dev-ws-week-lead { margin: 8px 0 0; font-size: 15px; line-height: 1.5; color: var(--text-primary); }

/* ── The Workshop tab in three titled parts (After-Workshop-B) ──────────
   OVERVIEW, WHAT'S HAPPENING and WHAT HAPPENED, each the shell's small-caps
   SectionHeader over its card or cards. What happened's label carries Mark
   all seen at its far end, outside the card. */
.dev-ws-parthead { display: flex; align-items: baseline; gap: 8px; }
.dev-ws-parthead > .dev-ws-since-clear { margin-inline-end: 2px; }

/* The Overview card: the four figures, where most of the open work is, and
   the approval rule in one line. The card is its own container, so the rule
   says itself shorter where the CARD is narrow ("Goes live when …"), on a
   phone or beside the side panel, not only where the window is. */
.dev-ws-strip[data-ws-dashboard] { container-type: inline-size; }
.dev-ws-dash-sub {
  display: flex; align-items: center; gap: 3px; margin-top: 1px;
  font-size: 11.5px; line-height: 1.3; color: var(--text-muted);
}
@media (min-width: 420px) {
  .dev-ws-dash-sub { font-size: 12px; }
}
/* "4 on you" asks something of the viewer, so it is the accent; "from 382"
   is green going up, muted otherwise, its glyph turned over going down. */
.dev-ws-dash-sub[data-ws-dash-sub="owed"] { color: var(--accent-wash-ink); }
.dev-ws-dash-sub[data-dir="up"] { color: var(--state-ok); }
.dev-ws-dash-trend { flex: none; width: 10px; height: 10px; }
.dev-ws-dash-sub[data-dir="down"] .dev-ws-dash-trend { transform: rotate(180deg); }
.dev-ws-ov-rule {
  margin: 0; padding-top: 10px; border-top: 1px solid var(--app-sheet-line);
  display: flex; align-items: flex-start; gap: 8px;
  font-size: 13px; line-height: 1.4; color: var(--text-secondary);
}
.dev-ws-ov-rule-icon { flex: none; width: 16px; height: 16px; margin-top: 1px; color: var(--text-muted); }
.dev-ws-ov-rule-text { flex: 1 1 auto; min-width: 0; }
.dev-ws-ov-rule-text b { font-weight: 650; color: var(--text-primary); }
.dev-ws-ov-rule-wait { margin-inline-start: 4px; color: var(--text-muted); }
.dev-ws-ov-rule-edit { flex: none; margin-inline-start: 4px; }
.dev-ws-ov-faces { display: inline-flex; margin-inline-end: 4px; vertical-align: -3px; }
.dev-ws-ov-face {
  width: 16px; height: 16px; border-radius: 999px;
  display: inline-flex; align-items: center; justify-content: center;
  color: #fff; font-size: 9px; font-weight: 700;
  box-shadow: 0 0 0 1.5px var(--dc-sheet-solid, var(--bg-primary));
}
.dev-ws-ov-face + .dev-ws-ov-face { margin-inline-start: -4px; }
.dev-ws-ov-narrow { display: none; }
@container (max-width: 520px) {
  .dev-ws-ov-wide { display: none; }
  .dev-ws-ov-narrow { display: inline; }
}

/* Your work and New for you (workshop/work-row.tsx ActRow): the title and
   one line in words, then the row's one next step at its end, above the
   stretched link; under the words on a phone. A vote that waits on the
   viewer wears the attention tint on its tile. */
.dev-ws-arow { align-items: center; }
.dev-ws-arow-act { position: relative; z-index: 1; flex: none; display: inline-flex; align-items: center; }
.dev-ws-wrow-tile[data-tone="ask"] { background: var(--state-attention-bg); color: var(--state-attention); }
@media (max-width: 640px) {
  .dev-ws-arow { flex-wrap: wrap; align-items: flex-start; }
  .dev-ws-arow > .dev-ws-wrow-main { flex: 1 1 0; }
  .dev-ws-arow-act { flex-basis: 100%; padding-inline-start: 40px; }
}

/* What happened (workshop/week-pages.tsx): this week's head and its rows,
   one line each, then a row for every week before it. A row's title is a
   link stretched over it; on a narrow card the title wraps and the rest
   goes under it. */
.dev-ws-strip[data-ws-happened] { container-type: inline-size; gap: 4px; }
.dev-ws-hweek { display: flex; flex-direction: column; }
.dev-ws-hweek-head { display: flex; align-items: center; gap: 12px; padding: 4px 2px 8px; }
.dev-ws-hweek-head > .dev-ws-week-head { flex: 1 1 auto; min-width: 0; }
.dev-ws-hlist { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; }
.dev-ws-hrow {
  position: relative; display: flex; align-items: center; gap: 10px; min-width: 0;
  padding: 8px 2px; border-top: 1px solid var(--app-sheet-line); border-radius: 10px;
}
.dev-ws-hrow:hover { background: var(--state-neutral-bg); }
.dev-ws-hrow[data-on] { background: var(--lit-tint); }
.dev-ws-hrow-dot { flex: none; width: 7px; height: 7px; border-radius: 999px; }
.dev-ws-hrow[data-new] .dev-ws-hrow-dot { background: var(--accent); }
.dev-ws-hrow-glyph { flex: none; display: inline-flex; align-items: center; justify-content: center; width: 16px; height: 16px; color: var(--text-muted); }
.dev-ws-hrow-glyph svg { width: 16px; height: 16px; }
.dev-ws-hrow-glyph[data-kind="live"] { color: var(--state-ok); }
.dev-ws-hrow-glyph .dc-status-spinner-arc { width: 13px; height: 13px; color: var(--lit-ink); }
.dev-ws-hrow-main { flex: 1 1 auto; min-width: 0; display: flex; align-items: center; gap: 10px; }
.dev-ws-hrow-link {
  flex: 1 1 auto; min-width: 0; font-size: 15px; line-height: 1.35; color: var(--text-primary); text-decoration: none;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.dev-ws-hrow-link::after { content: ''; position: absolute; inset: 0; border-radius: inherit; }
.dev-ws-hrow-link:focus-visible { outline: none; }
.dev-ws-hrow:has(.dev-ws-hrow-link:focus-visible) { outline: 2px solid var(--accent); outline-offset: 2px; }
.dev-ws-hrow-meta {
  flex: none; display: inline-flex; align-items: center; gap: 8px;
  font-size: 13px; color: var(--text-muted); white-space: nowrap;
  /* Never wider than the row (polish board #24): a long step, "Waiting for
     a slot, 1 request ahead of it", ran past the card's edge and was cut
     with no ellipsis. The words tags give way with an ellipsis instead; the
     pill, the glyph tags and the time keep their size. */
  max-width: 100%; min-width: 0;
}
.dev-ws-hrow-meta > * { flex: none; }
.dev-ws-hrow-meta > .dev-ws-hrow-tag:not(:has(> svg)) {
  flex: 0 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis;
}
.dev-ws-hrow-you {
  display: inline-flex; align-items: center; height: 18px; padding: 0 6px; border-radius: 999px;
  background: var(--accent-tint); color: var(--accent-wash-ink); font-size: 11px; font-weight: 700;
}
.dev-ws-hrow-tag[data-tone="run"] { color: var(--lit-ink); }
.dev-ws-hrow-tag[data-tone="bad"] { color: var(--state-blocked); }
/* What's happening's own-work rows end with where the work stands
   (week-pages.tsx MetaTag): the tag's words in its tone, no pill, with its
   glyph ("Only you", Homeroom bot) where it has one. */
.dev-ws-hrow-tag[data-tone="warn"] { color: var(--state-attention); }
.dev-ws-hrow-tag[data-tone="ok"] { color: var(--state-ok); }
.dev-ws-hrow-tag:has(> svg) { display: inline-flex; align-items: center; gap: 4px; }
.dev-ws-hrow-tag > svg { flex: none; width: 12px; height: 12px; }
.dev-ws-hrow-ago { font-variant-numeric: tabular-nums; }
.dev-ws-hweek > .dev-ws-reveal { margin-top: 2px; }
.dev-ws-hweek + .dev-ws-wlist { margin-top: 4px; border-top: 1px solid var(--app-sheet-line); }
@container (max-width: 520px) {
  .dev-ws-hrow { align-items: flex-start; }
  .dev-ws-hrow-dot { margin-top: 7px; }
  .dev-ws-hrow-glyph { margin-top: 2px; }
  .dev-ws-hrow-main { flex-direction: column; align-items: flex-start; gap: 2px; }
  .dev-ws-hrow-link { white-space: normal; }
}

/* Your work (#4716, workshop/work-row.tsx variant `line`): This week's
   one-line row with a second line. The first line is the small glyph, the
   title on one line in This week's weight, and at its end the card's status
   pill and Vote (#4486's pair, unchanged), then ☰; the line is as tall as
   Vote, so the glyph and ☰ centre on it whether or not the row has one. The
   second line is the item's number (and the requests it is for), its tags
   most important first, then Homeroom bot's tag on a change it built for
   you (#4716; your own work names nobody), on one line that scrolls
   sideways and fades at its end, so nothing wraps; it sits above the row's
   stretched link to take the swipe, and a click on it opens the item
   (work-row.tsx). On a narrow card the title wraps (two lines at most)
   and the pill and Vote end the row, at its
   far end, as they do on a phone today (#4718): the first line lets go of
   its box (`display: contents`) so the title and the pair are the column's
   own items, and the pair is ordered after the tags. */
/* WHAT'S HAPPENING IS ONE CARD (After-Workshop-C, Oct 2026), drawn as What
   happened's is: its own container (so a narrow card wraps its rows, not
   only a narrow window), each part headed with This week's head
   (`.dev-ws-hweek-head`: the name at 15px/650, its count beside it, 4px
   above and 8px below), a hairline over every row, and a hairline between
   parts, as between This week and the weeks under it. Waiting on you, Your
   work and Going live are This week's one-line row (`.dev-ws-hrow`, the
   `standing` HappenedRow); Yours, up for a vote keeps the two-line row
   below (`.dev-ws-lrow`), whose glyph starts where the one-line rows'
   does, after their 7px dot and 10px gap. A row lights in place on hover,
   as This week's does, rather than bleeding past the card's edge. */
.dev-ws-strip[data-ws-happening] { container-type: inline-size; gap: 4px; }
.dev-ws-hpart { display: flex; flex-direction: column; min-width: 0; }
.dev-ws-hpart + .dev-ws-hpart { margin-top: 4px; border-top: 1px solid var(--app-sheet-line); }
.dev-ws-hpart + .dev-ws-hpart > .dev-ws-hweek-head { padding-top: 14px; }
.dev-ws-hpart .dev-ws-wlist { margin-top: 0; }
.dev-ws-hpart > .dev-ws-wlist > .dev-ws-wrow:first-child { border-top: 1px solid var(--app-sheet-line); }
.dev-ws-hpart .dev-ws-reveal { margin-top: 2px; }
.dev-ws-hpart [data-ws-mine-empty] { margin: 0; padding: 8px 2px; border-top: 1px solid var(--app-sheet-line); }
.dev-ws-lrow { gap: 10px; padding-block: 8px 8px; padding-inline: 19px 2px; border-top: 1px solid var(--app-sheet-line); border-radius: 10px; }
.dev-ws-lrow:hover, .dev-ws-lrow[data-on] { margin: 0; padding-inline-start: 19px; padding-inline-end: 2px; }
.dev-ws-lrow:hover + .dev-ws-lrow, .dev-ws-lrow[data-on] + .dev-ws-lrow { border-top-color: var(--app-sheet-line); }
.dev-ws-lrow > .dev-ws-hrow-glyph { height: 30px; margin-top: 0; }
.dev-ws-lrow > .dev-ws-wrow-main { gap: 2px; }
.dev-ws-lrow-line { display: flex; align-items: center; gap: 10px; min-width: 0; min-height: 30px; }
.dev-ws-lrow .dev-ws-wrow-link {
  flex: 1 1 auto; min-width: 0; display: block; font-weight: 400; line-height: 1.35;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.dev-ws-lrow:has(.dev-ws-wrow-link:focus-visible) { outline: 2px solid var(--accent); outline-offset: 2px; }
.dev-ws-lrow-line > .dev-ws-wvote { flex: none; margin-inline-start: 0; }
.dev-ws-lrow .dev-ws-wrow-status {
  position: relative; z-index: 1; margin-top: 0; column-gap: 8px; flex-wrap: nowrap; min-width: 0;
  overflow-x: auto; overscroll-behavior-x: contain; scrollbar-width: none; cursor: pointer;
  -webkit-mask-image: linear-gradient(to var(--fade-to-inline-end, right), #000 calc(100% - 20px), transparent);
  mask-image: linear-gradient(to var(--fade-to-inline-end, right), #000 calc(100% - 20px), transparent);
}
.dev-ws-lrow .dev-ws-wrow-status::-webkit-scrollbar { display: none; }
.dev-ws-lrow .dev-ws-wrow-status > * { flex: none; }
/* The category chip is the one thing on this line that gives way (#5755):
   it took the line's last room, so it was faded by the mask and cut at the
   edge. It shrinks into what is left and its label ends in "…". */
.dev-ws-lrow .dev-ws-wrow-status > .attr-chip { flex: 0 1 auto; min-width: 0; overflow: hidden; }
/* The line ends 20px before its mask does, so a chip that FITS is never
   faded by the mask. */
.dev-ws-lrow .dev-ws-wrow-status { padding-inline-end: 20px; }
.dev-ws-lrow .dev-ws-wrow-sub { overflow: visible; }
.dev-ws-lrow > .dev-ws-wrow-menu { margin-top: 1px; }
@container (max-width: 520px) {
  .dev-ws-lrow > .dev-ws-hrow-glyph { height: 20px; }
  .dev-ws-lrow-line { display: contents; }
  .dev-ws-lrow .dev-ws-wrow-link {
    white-space: normal; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical;
  }
  .dev-ws-lrow-line > :not(.dev-ws-wrow-link) { order: 1; align-self: flex-end; margin-top: 4px; }
  .dev-ws-lrow .dev-ws-wrow-status { margin-top: 2px; }
  .dev-ws-lrow > .dev-ws-wrow-menu { margin-top: -4px; }
}

/* The item's page beside the list, on a wide window (workshop/side-panel.tsx).
   The list keeps its reading width at the 24px inset and the panel takes the
   room it leaves (#6208) — the rule #6206 asks for on Main Chat, here as one
   width both of them read. `--dev-ws-side-list-w` is the list's width: its
   760px, or the container less the 616px the panel needs (its 560px floor,
   the 24px inset and the 32px gap). `--dev-ws-side-start` is the usable box's
   edge on the rail's side, mirrored in Arabic as `--platform-usable-left` and
   `-right` are. Both live on body because the panel is portalled into it: a
   property set on #dev-workshop would never reach the panel. `--platform-
   usable-w - 2 × gutter` is the Workshop's own container box — the `100%`
   these rules used to spend — so the value means the same under the rail as
   inside the page. */
body {
  --dev-ws-side-list-w: min(760px, calc(var(--platform-usable-w) - 2 * var(--platform-gutter, 0px) - 616px));
  --dev-ws-side-start: calc(var(--platform-usable-left) * (1 + var(--rtl-sign)) / 2 + var(--platform-usable-right) * (1 - var(--rtl-sign)) / 2);
}
#dev-workshop:has(> .dev-ws[data-ws-side-open]) {
  margin-inline-start: 24px; margin-inline-end: 0;
  max-width: var(--dev-ws-side-list-w);
}
.dev-ws-side {
  position: fixed; z-index: 40;
  inset-inline-start: calc(var(--dev-ws-side-start) + var(--platform-gutter, 0px) + 24px + var(--dev-ws-side-list-w) + 32px);
  inset-inline-end: 24px;
  top: calc(var(--browser-banner-h, 0px) + var(--platform-header-h, 3.25rem) + var(--platform-safe-top, 0px) + 8px);
  bottom: 12px;
  display: flex; flex-direction: column; overflow: hidden; border-radius: 20px;
  background: var(--dc-sheet-solid, var(--bg-primary));
  box-shadow: 0 16px 48px rgba(0, 0, 0, .28), inset 0 0 0 1px var(--app-sheet-line);
}
.dev-ws-side-bar {
  flex: none; display: flex; align-items: center; gap: 8px; padding: 8px 10px;
  border-bottom: 1px solid var(--app-sheet-line);
}
.dev-ws-side-btn {
  appearance: none; border: 0; cursor: pointer; font: inherit; font-size: 13px; font-weight: 600;
  color: var(--text-secondary); background: var(--state-neutral-bg);
  height: 30px; padding: 0 12px; border-radius: 999px; display: inline-flex; align-items: center; gap: 4px;
}
.dev-ws-side-btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.dev-ws-side-btn svg { width: 15px; height: 15px; }
.dev-ws-side-close { width: 30px; padding: 0; justify-content: center; }
.dev-ws-side-full { margin-inline-start: auto; }
.dev-ws-side-page { flex: 1 1 auto; min-height: 0; overflow: auto; }
/* #4875, #6230: the page and, beside it, the detail column. The page and
   the plan share the panel in halves (app.css's detail-column section at the
   foot of this file); below 1180px there is no panel, so a row opens the
   request's own page instead. */
.dev-ws-side-body { position: relative; flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; }

/* ── The row's card parts, on every row (#4486) ──────────────────────
   The Workshop's row carries the card's own pieces now: on live work the
   bar's "✓ Live" at its words' width first on the tags line, then the
   coloured category chip and the 💬 count (dev-card.tsx, unchanged), and ☰,
   the card's own menu trigger, at the row's top right in place of the
   chevron. The chips and ☰ sit above the row's stretched link, so each does
   its own job; the 💬 count and the bar are words, and a tap on them is a
   tap on the row. */
.dev-ws-wrow-status > .dev-badge { height: 22px; font-size: 12px; margin: 0; }
.dev-ws-wrow-status > button.dev-badge { position: relative; z-index: 1; }
.dev-ws-wrow-status > .dev-ws-wrow-live { flex: none; }
/* #6075: the final counted vote beside a live row's "✓ Live", in the muted
   13px of the row's own subtitle line. Read-only history, so it is text,
   never a second pill. */
.dev-ws-wrow-tally {
  flex: none; font-size: 13px; line-height: 1.35; color: var(--text-muted);
  font-variant-numeric: tabular-nums; white-space: nowrap;
}
.dev-ws-wrow-menu { position: relative; z-index: 1; flex: none; display: inline-flex; margin-block: -3px 0; margin-inline: -2px -6px; }
.dev-ws-wrow-menu > .gc-vote-btn.dev-card-menu-btn {
  width: 28px; height: 28px; padding: 0; border-color: transparent;
  background: transparent; box-shadow: none; color: var(--text-muted);
}
.dev-ws-wrow-menu > .gc-vote-btn.dev-card-menu-btn:hover,
.dev-ws-wrow-menu > .gc-vote-btn.dev-card-menu-btn[aria-expanded="true"] {
  background: var(--state-neutral-bg); border-color: transparent; color: var(--text-primary);
}
.dev-ws-wrow-menu > .dev-card-menu-btn svg { width: 17px; height: 17px; }

/* ── The board's row (#4486, work-row.tsx variant `board`) ────────────
   All items' columns and By category's lanes: no tile (the column or the
   stage label says what it is), the title up to three lines, the line in
   words free to wrap in a narrow column, and the card's status bar with
   Vote under it all, the row's full width (fold.tsx RowBand, without the
   chips its tags say). The bar is words: a tap on it opens the row; only
   Vote takes its own click. */
.dev-ws-brow { flex-wrap: wrap; column-gap: 8px; row-gap: 0; }
.dev-ws-brow > .dev-ws-wrow-main { flex: 1 1 0; gap: 1px; }
.dev-ws-brow .dev-ws-wrow-link { -webkit-line-clamp: 3; text-wrap: pretty; }
/* `pretty`: a wrapped line in words ends on more than "ago" or "now"
   (a browser without it wraps as it did). */
.dev-ws-brow .dev-ws-wrow-sub { white-space: normal; overflow: visible; text-wrap: pretty; }
.dev-ws-brow .dev-ws-wrow-status { margin-top: 6px; gap: 5px; }
.dev-ws-brow > .dev-ws-row-band {
  position: relative; z-index: 1; flex: 1 0 100%; min-width: 0; margin-top: 8px; pointer-events: none;
}
.dev-ws-brow > .dev-ws-row-band > .dev-ws-row-trailing { pointer-events: auto; }

/* ── All items' one-row head (#4486) ─────────────────────────────────
   The way back and the page's name, the search, then the filters, in one
   row that wraps on a narrow window and on a phone. The search and the
   filter chips are the strip's own (kanban-filters.tsx), laid out here as
   the row's items; the chips wrap as one group. (The By category / By stage
   switch sat between them until request 6708.) */
.dev-ws-allbar { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 10px; min-width: 0; }
.dev-ws-allbar > .dev-ws-pagehead { order: 0; flex: none; margin-inline-end: 6px; }
.dev-ws-allbar .dev-ws-pagehead-title { font-size: 22px; line-height: 28px; }
.dev-ws-allbar :is(#dev-actions, #dev-kanban-filterbar, #dev-filter-row) { display: contents; }
.dev-ws-allbar #dev-kanban-search {
  order: 1; flex: 1 1 320px; min-width: 200px; max-width: 440px; height: 36px; padding: 0 14px;
  border-color: transparent; border-radius: 999px; font-size: 14px;
  background: var(--state-neutral-bg); color: var(--text-primary);
}
.dev-ws-allbar #dev-filter-chips { order: 3; display: inline-flex; flex-wrap: wrap; align-items: center; gap: 6px; min-width: 0; }
.dev-ws-allbar #dev-filter-chips button { height: 28px; padding: 0 11px; font-size: 12.5px; }


/* ── The pipeline (#4486, card/dev-kanban.tsx StageStrip) ────────────
   The column heads as the steps an idea goes through, joined by arrows,
   each with its icon and its count, and Done's the one green step. On the
   board's own grid (`#dev-kanban`), 8px in from the head's padding to meet
   the board's; it scrolls sideways only with the board. */
.dev-kanban-stages {
  display: grid; grid-template-columns: repeat(4, minmax(220px, 1fr)); column-gap: 20px;
  margin-top: 4px; padding: 0 8px; overflow: hidden;
}
.dev-kanban-step {
  position: relative; display: flex; align-items: center; gap: 9px; min-width: 0;
  padding: 4px 2px; border: 0; background: transparent; font: inherit; color: inherit;
  text-align: start; cursor: default; -webkit-tap-highlight-color: transparent;
}
.dev-kanban-step:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 10px; }
.dev-kanban-step-tile {
  flex: none; width: 30px; height: 30px; border-radius: 9px;
  display: inline-flex; align-items: center; justify-content: center;
  background: var(--state-neutral-bg); color: var(--text-secondary);
}
.dev-kanban-step-tile svg { width: 16px; height: 16px; }
.dev-kanban-step-tile[data-kind="done"] { background: var(--state-ok-bg); color: var(--state-ok); }
.dev-kanban-step-name {
  min-width: 0; font-size: 15px; font-weight: 650; color: var(--text-primary);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.dev-kanban-step-n { flex: none; font-size: 15px; font-weight: 600; color: var(--text-muted); font-variant-numeric: tabular-nums; }
.dev-kanban-step-arrow {
  position: absolute; inset-inline-end: -19px; top: 50%; width: 18px; height: 18px; margin-top: -9px;
  color: var(--text-muted); opacity: .6;
}

/* ── A column is one card of rows (#4486) ────────────────────────────
   Drawn like the shell's other lists: the plane colour, 20px corners, one
   hairline. Waiting for approval leads with its order (Newest or Vote
   priority), Done with what is live; "Show 2,748 more" closes Done. */
.dev-kanban-card {
  border-radius: 20px; padding: 2px 14px 8px;
  background: var(--dc-sheet-solid, var(--bg-primary));
  box-shadow: inset 0 0 0 1px var(--app-sheet-line);
}
.dev-kanban-card > .dev-ws-wlist { margin-top: 0; }
.dev-kanban-lead { margin: 10px 2px 2px; font-size: 12.5px; line-height: 1.4; }
.dev-kanban-sort { display: inline-flex; align-items: center; gap: 5px; }
.dev-kanban-sort-icon { width: 13px; height: 13px; transform: rotate(180deg); }
.dev-kanban-empty { padding: 12px 2px; font-size: 13px; color: var(--text-muted); }
.dev-kanban-foot { margin: 2px 0 2px; }
.dev-kanban-foot > .dev-kanban-more { justify-content: flex-start; padding: 8px 2px; font-size: 13px; }
.dev-kanban-card > .dev-col-divider { margin: 10px 2px 2px; }

/* ── By stage, the board sits on the page ────────────────────────────
   The columns are the cards, so the pane around them draws no sheet of its
   own, and its head is on the page until it pins: then the row and the
   steps take the sheet's colour, square on top under the tabs and rounded
   below, with a hairline at their foot (`data-ws-head-pinned`). */
#dev-workshop.dev-ws-has-board .dev-ws-pane { box-shadow: none; }
#dev-workshop.dev-ws-has-board .dev-ws-pane-head,
#dev-workshop.dev-ws-has-board .dev-ws-pane-body { background-color: transparent; backdrop-filter: none; -webkit-backdrop-filter: none; }
#dev-workshop.dev-ws-has-board .dev-ws-pane-head { gap: 12px; padding: 8px 10px 10px; }
#dev-workshop.dev-ws-has-board .dev-ws[data-ws-head-pinned] .dev-ws-pane-head {
  background-color: var(--dc-sheet-solid);
  border-start-start-radius: 0; border-start-end-radius: 0; border-end-end-radius: 18px; border-end-start-radius: 18px;
  box-shadow: inset 0 -1px 0 var(--app-sheet-line);
}

/* ── The board beside the panel (#4486) ──────────────────────────────
   A row opens its page in the Workshop's panel; the board keeps its place
   to its left, its columns 316px, and scrolls sideways (the Workshop brings
   the tapped column beside the panel). */
#dev-workshop.dev-ws-has-board:has(> .dev-ws[data-ws-side-open]) { margin-inline-start: 24px; max-width: var(--dev-ws-side-list-w); }
.dev-ws[data-ws-side-open] :is(#dev-kanban, .dev-kanban-stages) { grid-template-columns: repeat(4, 316px); }

@media (max-width: 639px) {
  /* #4486: on a phone the steps are the tabs, one column at a time, and
     they scroll sideways on their own. */
  .dev-kanban-stages {
    display: flex; gap: 6px; padding: 0 0 2px; margin-top: 2px;
    overflow-x: auto; scrollbar-width: none;
  }
  .dev-kanban-stages::-webkit-scrollbar { display: none; }
  .dev-kanban-step {
    flex: none; min-height: 40px; padding-block: 6px 6px; padding-inline: 7px 13px; gap: 7px; cursor: pointer;
    border-radius: 999px; background: var(--state-neutral-bg);
  }
  .dev-kanban-step[aria-selected="true"] { background: var(--lit-tint); box-shadow: inset 0 0 0 1px var(--lit-line); }
  .dev-kanban-step[aria-selected="true"] :is(.dev-kanban-step-name, .dev-kanban-step-tile) { color: var(--lit-ink); }
  .dev-kanban-step-tile, .dev-kanban-step-tile[data-kind="done"] { width: 22px; height: 22px; border-radius: 999px; background: transparent; }
  .dev-kanban-step-name, .dev-kanban-step-n { font-size: 14px; }
  .dev-kanban-step-arrow { display: none; }
  .dev-kanban-card { padding: 2px 12px 6px; }
  /* The head: the way back and the name, then the search on its own line,
     and the switch and the filters sharing the line under it (#5029). */
  .dev-ws-allbar #dev-kanban-search { flex-basis: 100%; max-width: none; min-width: 0; }
  /* #5820: the grouping stays at the left and the filters at the right edge,
     so the line reads as two groups. It still scrolls when it overflows. */
  .dev-ws-allbar #dev-filter-chips { flex: 0 1 auto; margin-inline-start: auto; min-width: 0; flex-wrap: nowrap; overflow-x: auto; scrollbar-width: none; }
  .dev-ws-allbar .dev-ws-pagehead-title { font-size: 20px; line-height: 26px; }
}
@media (max-width: 640px) {
  .dev-ws-wrow { gap: 10px; }
  .dev-ws-wrow-tile { width: 30px; height: 30px; border-radius: 9px; }
}

/* ═══════════════════════════════════════════════════════════════════
   The Needs you review flow (.rf-*)
   ═══════════════════════════════════════════════════════════════════

   frontend/src/features/review-flow/. One run through the changes
   waiting on you: each change's page with its sheet of screens, a screen
   opened in place as a before/after slider, the strip of screens under it
   and the vote sheet. Drawn for the phone first; a wide window shows the
   same column centred. Colours are the shell's own tokens, light and dark. */
.rf-run, .rf-page-wrap {
  --rf-page: var(--home-ground);
  --rf-sheet: var(--dc-sheet-solid);
  --rf-fill: var(--bg-tertiary);
  --rf-ink: var(--text-primary);
  --rf-muted: var(--text-muted);
  --rf-line: var(--app-sheet-line);
  --rf-black: var(--text-primary);
  --rf-cream: var(--bg-primary);
}

/* The pane under the run: empty while the page is up, the end once it is
   done. One column, never wider than the change page (520px, gutters
   included), centred in the pane. */
.rf-run, .rf-feed-note { box-sizing: border-box; width: 100%; max-width: 520px; margin-inline-start: auto; margin-inline-end: auto; }
.rf-run { padding: 4px 16px 32px; }
.rf-loading { min-height: 50vh; }
.rf-end { display: flex; flex-direction: column; align-items: center; padding: 28px 8px 8px; text-align: center; }
.rf-end-mark { width: 48px; height: 48px; border-radius: 999px; background: var(--lit-tint); color: var(--lit-ink); display: grid; place-items: center; }
.rf-end-line { margin: 14px 0 20px; font-size: 15px; line-height: 21px; color: var(--rf-muted); }
.rf-end-btn { align-self: stretch; height: 48px; border: 0; border-radius: 999px; background: var(--rf-fill); color: var(--rf-ink); font: inherit; font-size: 15px; font-weight: 600; cursor: pointer; }
.rf-capped { margin: -12px 0 0; font-size: 12px; color: var(--rf-muted); text-align: center; }
/* Everything had your vote: the end alone, centred where the list was. */
.rf-end-alone { min-height: 56vh; justify-content: center; padding: 0 24px 48px; }
/* The end when some changes were skipped: not done, so no check. The
   skipped changes wait as a small fanned stack (each on its own ground),
   with one way to look at them again and a quiet way back. */
.rf-end-stack { position: relative; width: 168px; height: 124px; margin-bottom: 22px; }
.rf-end-tile { position: absolute; left: 50%; top: 8px; width: 88px; height: 104px; margin-inline-start: -44px; border-radius: 18px; box-shadow: 0 0 0 2px var(--rf-page), 0 6px 16px rgba(0,0,0,.12); display: grid; place-items: center; }
.rf-end-tile i { width: 48px; height: 76px; border-radius: 9px; background: rgba(255,255,255,.9); }
.rf-end-tile[data-n="-1"] { transform: translateX(calc(-38px * var(--rtl-sign))) rotate(-8deg); }
.rf-end-tile[data-n="-0.5"] { transform: translateX(calc(-20px * var(--rtl-sign))) rotate(-5deg); }
.rf-end-tile[data-n="0.5"] { z-index: 1; transform: translateX(calc(20px * var(--rtl-sign))) rotate(5deg); }
.rf-end-tile[data-n="0"] { z-index: 1; }
.rf-end-tile[data-n="1"] { transform: translateX(calc(38px * var(--rtl-sign))) rotate(8deg); }
.rf-end-title { margin: 0; font-size: 20px; font-weight: 650; line-height: 26px; color: var(--rf-ink); }
.rf-end-line-tight { margin: 8px 0 24px; }
.rf-end-btn-go { background: var(--accent); color: #fff; }
.rf-end-back { height: 44px; margin-top: 6px; padding: 0 12px; border: 0; background: none; color: var(--rf-muted); font: inherit; font-size: 15px; font-weight: 500; cursor: pointer; }

/* The change page. A change is a detail view drawn inside the tab: below the
   shell's header, above its tab bar on a phone, in the pane's column on a
   desktop. Its own bar is the way back, and the vote bar clears the home
   indicator itself (.rf-sheet-inner). Nothing is drawn over the rest of the
   screen: no wash, no floating panel. */
.rf-page-wrap { position: relative; }
.rf-page { position: relative; width: min(100%, 520px); margin-inline: auto; height: calc(100dvh - var(--browser-banner-h, 0px) - var(--platform-header-h) - var(--platform-safe-top, 0px) - var(--platform-tabs-h, 0px)); display: flex; flex-direction: column; overflow: hidden; background: var(--rf-page); color: var(--rf-ink); -webkit-font-smoothing: antialiased; }
/* On the Communities tab the page's own bar names the change, so the pane's
   "Needs you" head steps aside while a change is open. */
[data-workshop-pane="needs"]:has([data-rf-page]) [data-workshop-needs-head] { display: none; }
.rf-stage { position: relative; flex: 1; min-height: 0; overflow-y: auto; overflow-x: hidden; overscroll-behavior: contain; }
.rf-stage-layer { background: var(--rf-page); }
.rf-stage-leaving { position: absolute; inset-inline-start: 0; inset-inline-end: 0; top: 0; z-index: 0; }
.rf-stage-arriving { position: relative; z-index: 1; }
.rf-page-body { padding-bottom: 0; }
/* The picture: the change's sheet on its ground, and a screen opened in
   place over it. One hairline, the one the strip's tiles wear. */
.rf-picture { position: relative; margin: 0 12px; border-radius: 32px; overflow: hidden; isolation: isolate; }
.rf-picture::after { content: ''; position: absolute; inset: 0; z-index: 4; border-radius: inherit; box-shadow: inset 0 0 0 1px var(--rf-line); pointer-events: none; }
.rf-plates { position: absolute; inset: 0; z-index: 1; }
.rf-plate-btn { position: absolute; padding: 0; border: 0; overflow: hidden; background: #fff; cursor: pointer; box-shadow: 0 1px 2px rgba(40,20,10,.10), 0 10px 24px -10px rgba(40,20,10,.30); -webkit-tap-highlight-color: transparent; transition: scale .16s ease-out; }
.rf-plate-btn::after { content: ''; position: absolute; inset: 0; border-radius: inherit; box-shadow: inset 0 0 0 1px rgba(0,0,0,.08); pointer-events: none; }
.rf-plate-btn:active { scale: .96; }
.rf-plate-btn:focus-visible { outline: 2px solid var(--rf-black); outline-offset: 3px; }
.rf-plate-btn img { position: absolute; display: block; max-width: none; pointer-events: none; }
@keyframes rf-deal { from { opacity: 0; transform: translateY(10px) scale(.985); } }
.rf-open { position: absolute; inset: 0; }
/* The landing dim: one hard-edged hole round the change, the rest of the
   screen veiled. It sits on each side's own picture (compare.tsx), so it
   rides every move; it comes on at once and fades out. */
.rf-veil-box { position: absolute; inset-inline-start: 0; top: 0; overflow: hidden; pointer-events: none; transition: opacity .5s cubic-bezier(0.22,1,0.36,1); }
.rf-veil { position: absolute; box-shadow: 0 0 0 4000px rgba(6,6,8,.5); }
/* The strip: its own row under the picture, on its left edge. Radii step in
   by 12 as the elements do: picture 32, tile 20. The first tile is the
   sheet's glyph in the page's ink; each screen's tile unfolds from its bar
   in the glyph when a change arrives. */
.rf-strip { position: relative; flex: none; height: 44px; margin: 12px 12px 0; }
/* Each tile sits on a grey ground, so it reads as something to press; where
   you are is the lit tint and ink. */
.rf-strip-all, .rf-tile { position: absolute; padding: 0; border: 0; background: var(--rf-fill); color: var(--rf-muted); cursor: pointer; -webkit-tap-highlight-color: transparent; }
.rf-strip-all[aria-current], .rf-tile[aria-current] { background: var(--lit-tint); color: var(--lit-ink); }
.rf-strip-all { z-index: 1; inset-inline-start: 0; top: 0; width: 44px; height: 44px; border-radius: 14px; transition: scale .15s ease-out, color .2s, background-color .2s; }
.rf-strip-all:active, .rf-tile:active { scale: .92; }
.rf-strip-all:focus-visible, .rf-tile:focus-visible { outline: 2px solid var(--rf-ink); outline-offset: 2px; }
.rf-gbox { position: absolute; inset-inline-start: 9px; top: 9px; width: 26px; height: 26px; box-sizing: border-box; border: 1.5px solid currentColor; border-radius: 8px; pointer-events: none; }
.rf-gbar { position: absolute; border-radius: 1.5px; background: currentColor; }
.rf-tile { z-index: 2; transition: left .38s cubic-bezier(0.22,1,0.36,1), top .38s cubic-bezier(0.22,1,0.36,1), width .38s cubic-bezier(0.22,1,0.36,1), height .38s cubic-bezier(0.22,1,0.36,1), border-radius .38s cubic-bezier(0.22,1,0.36,1), background-color .16s cubic-bezier(0.22,1,0.36,1), color .2s, scale .15s ease-out; }
.rf-tile[data-folded] { background: var(--rf-ink); }
/* A screen's pictogram: its outline at a phone's proportions, one bar where
   the change sits (review-flow.tsx PICTO, model.ts pictoMark). */
.rf-picto { position: absolute; left: 50%; top: 50%; width: 20px; height: 30px; margin-block: -15px 0; margin-inline: -10px 0; box-sizing: border-box; border: 1.5px solid currentColor; border-radius: 5px; pointer-events: none; transition: opacity .2s cubic-bezier(0.22,1,0.36,1) 40ms; }
.rf-picto-mark { position: absolute; margin-block: -1.5px 0; margin-inline: -1.5px 0; border-radius: 1px; background: currentColor; }
.rf-tile[data-folded] .rf-picto { opacity: 0; }
/* The page leads with what the change does, or what the open screen shows:
   two lines at most, on the header's 16pt edge. The gap under it is a
   margin, not padding, so the clamp never lets a third line show. */
/* The bar: Back, the change's title on one line, and ⌄. On a phone it stands
   in for the shell's header, which the page covers; the pictures under it
   are the heavy thing on the page, so it has no fill and one line of type.
   Open (⌄, the title, or the line under the bar), the title wraps in full
   and a card under the bar holds what the change does (.rf-desc). */
.rf-bar { position: relative; z-index: 9; flex: none; display: flex; flex-wrap: wrap; align-items: flex-start; gap: 2px; padding: var(--platform-safe-top, env(safe-area-inset-top, 0px)) 16px 0 4px; min-height: 44px; background: var(--rf-page); }
/* #6199: the vote-type chips sit under the bar's title row, so the folded
   bar's measurement includes them. */
.rf-bar .needs-vote-chips { flex-basis: 100%; }
.rf-back { flex: none; display: grid; place-items: center; width: 40px; height: 44px; border: 0; background: none; color: inherit; cursor: pointer; -webkit-tap-highlight-color: transparent; }
.rf-bar-title { flex: 1; min-width: 0; margin: 0; padding: 11px 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 17px; font-weight: 650; line-height: 22px; letter-spacing: -0.015em; }
.rf-bar-title-btn { display: block; width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: inherit; padding: 0; border: 0; background: none; color: inherit; font: inherit; letter-spacing: inherit; text-align: start; cursor: pointer; -webkit-tap-highlight-color: transparent; }
.rf-bar[data-open] .rf-bar-title { white-space: normal; text-wrap: pretty; padding-bottom: 4px; }
.rf-bar-toggle { flex: none; display: grid; place-items: center; width: 32px; height: 32px; margin-block: 6px 0; margin-inline: 6px 0; border: 0; border-radius: 999px; background: var(--rf-fill); color: var(--rf-ink); cursor: pointer; -webkit-tap-highlight-color: transparent; }
.rf-bar-toggle svg { transition: transform .26s cubic-bezier(0.22,1,0.36,1); }
.rf-bar-toggle[aria-expanded="true"] svg { transform: rotate(180deg); }
/* The line under the bar: a tap anywhere on it opens the change in full. */
.rf-claim-row { position: relative; flex: none; display: flex; align-items: flex-end; gap: 8px; width: 100%; margin: 0 0 14px; padding: 6px 16px 0; border: 0; background: none; color: inherit; font: inherit; text-align: start; -webkit-tap-highlight-color: transparent; }
button.rf-claim-row { cursor: pointer; }
button.rf-claim-row:active .rf-claim { color: var(--rf-ink); }
.rf-claim-row .rf-claim { flex: 1; min-width: 0; margin: 0; padding: 0; }
/* The card: from under the bar, over the page; the rest dims, and a tap there
   folds it. It slides out of the bar rather than fading in, so it reads as
   the bar's own. */
.rf-desc-wrap { position: absolute; inset-inline-start: 0; inset-inline-end: 0; bottom: 0; z-index: 8; overflow: hidden; pointer-events: none; }
.rf-desc-wrap[data-open] { pointer-events: auto; }
.rf-desc-dim { position: absolute; inset: 0; background: rgba(0,0,0,.32); opacity: 0; transition: opacity .26s ease; }
.rf-desc-wrap[data-open] .rf-desc-dim { opacity: 1; }
.dark .rf-desc-dim { background: rgba(0,0,0,.56); }
.rf-desc { position: absolute; inset-inline-start: 0; inset-inline-end: 0; top: 0; max-height: calc(100% - 48px); overflow-y: auto; padding-block: 6px 16px; padding-inline: 46px 16px; background: var(--rf-page); border-start-start-radius: 0; border-start-end-radius: 0; border-end-end-radius: 24px; border-end-start-radius: 24px; transform: translateY(-104%); transition: transform .32s cubic-bezier(0.22,1,0.36,1), box-shadow .32s; }
.rf-desc-wrap[data-open] .rf-desc { transform: none; box-shadow: 0 16px 40px rgba(0,0,0,.18); }
.rf-desc-text { margin: 0; font-size: 15px; line-height: 21px; color: var(--rf-muted); white-space: pre-line; overflow-wrap: anywhere; }
/* Across all projects the card opens on the project's name: the same type as
   the title, before the description's lighter grey. */
.rf-desc-app { margin: 0 0 4px; font-size: 15px; line-height: 21px; font-weight: 650; color: var(--rf-ink); overflow-wrap: anywhere; }
.rf-desc-foot { display: flex; margin-top: 16px; margin-inline-start: -30px; }
.rf-desc-go { flex: 1; display: flex; align-items: center; justify-content: center; height: 44px; border-radius: 999px; background: var(--rf-fill); color: var(--rf-ink); font-size: 15px; font-weight: 600; text-decoration: none; }
.rf-desc-by { margin: 8px 0 0; font-size: 13px; line-height: 18px; color: var(--rf-muted); }
/* Help, at the card's foot: each row opens its sheet over the page. */
.rf-desc-help { margin-block: 16px 0; margin-inline: -30px 0; border-radius: 16px; background: var(--rf-sheet); overflow: hidden; }
.rf-help-row { position: relative; width: 100%; display: flex; align-items: center; gap: 12px; min-height: 48px; padding: 0 14px; border: 0; background: none; color: var(--rf-ink); font: inherit; font-size: 15px; font-weight: 600; text-align: start; cursor: pointer; -webkit-tap-highlight-color: transparent; }
.rf-help-row > span { flex: 1; min-width: 0; }
.rf-help-row > svg { flex: none; color: var(--rf-muted); }
.rf-help-row + .rf-help-row::before { content: ''; position: absolute; inset-inline-start: 46px; inset-inline-end: 0; top: 0; height: 1px; background: var(--rf-line); }
.rf-help-row:focus-visible { outline: 2px solid var(--accent); outline-offset: -2px; }
.rf-claim { flex: none; margin: 0 0 14px; padding: 6px 16px 0; min-height: 42px; font-size: 15px; font-weight: 400; line-height: 21px; color: var(--rf-muted); text-wrap: pretty; animation: rf-claim-in .36s cubic-bezier(0.22,1,0.36,1); }
/* The project's name leads the line across all projects, in the same bold ink
   as the title; inline, so the line keeps its two-line height. */
.rf-claim-app { font-weight: 650; color: var(--rf-ink); }
@keyframes rf-claim-in { from { opacity: 0; transform: translateY(4px); } }
.rf-hero-quiet { width: 100%; }
.rf-scrim { position: absolute; inset: 0; z-index: 5; background: rgba(0,0,0,.62); opacity: 0; pointer-events: none; transition: opacity .22s cubic-bezier(0.22,1,0.36,1); }
.rf-scrim-on { opacity: 1; pointer-events: auto; }

/* The slider. The switch sits at the foot of the picture, where a thumb
   pressing it covers the least of the shot. */
/* direction: ltr, in Arabic too. A screenshot does not mirror, and everything
   in here is laid out in its coordinates: the framed layers' translate and
   scale from their left edge, the close-ups' and the veil's boxes, the seam's
   translate and the clip behind it. compare.tsx's seam runs Before on the left,
   After on the right; the captions and the switch say the same. */
.rf-compare { direction: ltr; position: relative; overflow: hidden; touch-action: pan-y; user-select: none; -webkit-user-select: none; -webkit-touch-callout: none; outline: none; }
.rf-compare:focus-visible { box-shadow: inset 0 0 0 2px var(--accent); }
.rf-layer, .rf-layer-clip { position: absolute; inset-inline-start: 0; top: 0; }
.rf-layer-clip { inset: 0; }
.rf-shot-img { display: block; max-width: none; }
.rf-shot-whole { width: 100%; height: auto; }
.rf-closeup { position: absolute; display: block; max-width: none; pointer-events: none; }
.rf-seam { position: absolute; top: 0; bottom: 0; inset-inline-start: 0; width: 2px; margin-inline-start: -1px; background: var(--rf-black); z-index: 3; pointer-events: none; transition: opacity .18s cubic-bezier(0.22,1,0.36,1), width .15s ease-out; }
.rf-dragging .rf-seam { width: 1px; opacity: .5 !important; }
/* Each side's caption is printed on its own picture, under a short shade
   that keeps it legible on any shot, and the seam wipes it with the picture. */
.rf-cap { position: absolute; inset-inline-start: 0; inset-inline-end: 0; top: 0; height: 84px; background: linear-gradient(rgba(12,12,14,.62) 0%, rgba(12,12,14,.55) 18%, rgba(12,12,14,.45) 33%, rgba(12,12,14,.35) 46%, rgba(12,12,14,.26) 57%, rgba(12,12,14,.18) 67%, rgba(12,12,14,.11) 76%, rgba(12,12,14,.06) 84%, rgba(12,12,14,.025) 91%, rgba(12,12,14,0) 100%); pointer-events: none; transition: opacity .3s cubic-bezier(0.22,1,0.36,1); }
.rf-cap-line { position: absolute; top: 18px; display: flex; align-items: center; gap: 6px; font: 600 11px/1 'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, monospace; letter-spacing: .14em; text-transform: uppercase; color: #fffeea; text-shadow: 0 1px 2px rgba(12,12,14,.35); white-space: nowrap; }
.rf-cap-after .rf-cap-line { inset-inline-end: 22px; }
.rf-cap-before .rf-cap-line { inset-inline-start: 22px; }
.rf-cap-dim { opacity: .72; }
/* The switch: Before on its left, After on its right, its knob on the side
   most of the window shows, carrying that side's mark. Flat and inked, like
   the captions it names. */
.rf-switch { position: absolute; inset-inline-start: 50%; bottom: 12px; z-index: 5; width: 72px; height: 40px; margin-inline-start: -36px; padding: 0; box-sizing: border-box; border: 1.5px solid var(--rf-black); border-radius: 999px; background: var(--rf-cream); color: var(--rf-black); cursor: pointer; touch-action: manipulation; -webkit-touch-callout: none; -webkit-tap-highlight-color: transparent; transition: opacity .3s cubic-bezier(0.22,1,0.36,1), background .2s, color .2s; }
.rf-switch::before { content: ''; position: absolute; left: 50%; top: 50%; width: 88px; height: 48px; transform: translate(-50%, -50%); }
.rf-switch:focus-visible { outline: 2px solid var(--accent); outline-offset: 3px; }
.rf-switch[data-view="before"] { background: var(--rf-black); color: var(--rf-cream); }
.rf-switch-mark { position: absolute; top: 11.5px; display: flex; opacity: .45; }
.rf-switch-mark-before { inset-inline-start: 11.5px; }
.rf-switch-mark-after { inset-inline-start: 43.5px; }
.rf-knob { position: absolute; top: 2.5px; inset-inline-start: 34.5px; width: 32px; height: 32px; border-radius: 16px; background: var(--rf-black); color: var(--rf-cream); transition: inset-inline-start .35s cubic-bezier(.34,1.3,.64,1), width .18s cubic-bezier(0.22,1,0.36,1), background .2s, color .2s; }
.rf-switch[data-view="before"] .rf-knob { inset-inline-start: 2.5px; background: var(--rf-cream); color: var(--rf-black); }
.rf-switch-pressed .rf-knob { inset-inline-start: 24.5px; width: 42px; }
.rf-switch-pressed[data-view="before"] .rf-knob { inset-inline-start: 2.5px; }
.rf-knob-icon { position: absolute; inset: 0; display: grid; place-items: center; transition: opacity .25s, transform .4s cubic-bezier(.34,1.56,.64,1); }
.rf-knob-before { opacity: 0; transform: rotate(-120deg) scale(.6); }
.rf-switch[data-view="before"] .rf-knob-before { opacity: 1; transform: none; }
.rf-switch[data-view="before"] .rf-knob-after { opacity: 0; transform: rotate(120deg) scale(.6); }

/* Held still, the shot opens a round magnifier: the switch's cream and
   near-black ring, the plates' own soft shadow. */
.rf-lens { position: absolute; inset-inline-start: 0; top: 0; z-index: 6; width: 132px; height: 132px; border-radius: 999px; overflow: hidden; pointer-events: none; box-shadow: 0 0 0 2px var(--rf-cream), 0 0 0 3px var(--rf-black), 0 8px 24px rgba(0,0,0,.18); animation: rf-lens-in .12s cubic-bezier(0.22,1,0.36,1); }
@keyframes rf-lens-in { from { opacity: 0; scale: .85; } }

/* The vote at the page's foot: part of the page at rest, a sheet over it
   while its help or the header's menu is open. */
.rf-sheet { position: relative; z-index: 6; flex: none; overflow: hidden; border-start-start-radius: 20px; border-start-end-radius: 20px; border-end-end-radius: 0; border-end-start-radius: 0; background: var(--rf-sheet); box-shadow: 0 -8px 32px rgba(0,0,0,.18), inset 0 1px 0 rgba(255,255,255,.06); transition: height .26s cubic-bezier(0.22,1,0.36,1), background .22s, box-shadow .22s; }
.rf-sheet-rest { background: var(--rf-page); box-shadow: none; }
/* How tall the home indicator's inset is, for the page's height budget. */
.rf-safe-probe { position: absolute; inset-inline-start: 0; top: 0; width: 0; height: var(--platform-safe-bottom, 0px); visibility: hidden; pointer-events: none; }
.rf-sheet-rest .rf-sheet-inner { padding-top: 4px; padding-bottom: calc(12px + var(--platform-safe-bottom, 0px)); }
.rf-sheet-inner { display: flex; flex-direction: column; max-height: inherit; padding: 0 16px calc(10px + var(--platform-safe-bottom, 0px)); }
.rf-sheet button, .rf-sheet input, .rf-sheet textarea { font-family: inherit; }
.rf-grab { flex: none; display: block; width: 100%; height: 27px; margin: 0; padding: 0; border: 0; background: none; cursor: pointer; }
.rf-grab span { display: block; width: 36px; height: 5px; margin: 8px auto 14px; border-radius: 999px; background: var(--rf-line); }
/* The row never moves: the room above it is kept for a No's reason, the
   pair shows your choice in place, and the round ⋯ grows into Next change. */
.rf-vote { flex: none; display: flex; flex-direction: column; }
.rf-why { flex: none; height: 44px; margin-bottom: 8px; display: flex; align-items: center; justify-content: center; transition: opacity .25s, transform .3s cubic-bezier(0.22,1,0.36,1); }
.rf-why-off { opacity: 0; transform: translateY(6px); pointer-events: none; }
.rf-why-add { min-height: 44px; padding: 0 6px; border: 0; background: none; color: var(--rf-muted); font-size: 15px; font-weight: 500; text-decoration: underline; text-underline-offset: 3px; cursor: pointer; }
.rf-why-said { max-width: 100%; font-size: 15px; line-height: 20px; color: var(--rf-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.rf-why-head { margin: 6px 0 10px; font-size: 17px; font-weight: 600; line-height: 22px; color: var(--rf-ink); }
.rf-vrow { flex: none; display: flex; gap: 12px; }
.rf-pair { position: relative; flex: 1; min-width: 0; display: flex; padding: 4px; border-radius: 999px; background: var(--rf-fill); }
.rf-sheet:not(.rf-sheet-rest) .rf-pair { flex: none; }
.rf-pair-thumb { position: absolute; top: 4px; bottom: 4px; inset-inline-start: 4px; width: calc(50% - 4px); border-radius: 999px; background: var(--rf-ink); opacity: 0; transform: scale(.92); pointer-events: none; transition: left .32s cubic-bezier(.34,1.25,.64,1), opacity .18s, transform .32s cubic-bezier(.34,1.4,.64,1); }
.rf-pair[data-rf-voted] .rf-pair-thumb { opacity: 1; transform: none; }
.rf-pair[data-rf-voted="no"] .rf-pair-thumb { left: 50%; }
.rf-pair-btn { position: relative; flex: 1; min-width: 0; height: 44px; border: 0; border-radius: 999px; background: none; color: var(--rf-ink); display: flex; align-items: center; justify-content: center; font-size: 17px; font-weight: 600; cursor: pointer; transition: color .2s; }
.rf-pair-btn[aria-checked="true"] { color: var(--rf-page); }
.rf-pair-btn:disabled { opacity: .6; }
/* #6098: the pair is shown busy, not switched off, so it keeps keyboard
   focus while the vote is sent (`.rf-go`, the reason sheet's Send, stays off). */
.rf-pair-btn[aria-disabled="true"] { opacity: .6; }
.rf-pair-btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.rf-pair-mark { display: flex; width: 0; overflow: hidden; opacity: 0; transition: width .26s cubic-bezier(0.22,1,0.36,1), margin .26s cubic-bezier(0.22,1,0.36,1), opacity .2s; }
.rf-pair-btn[aria-checked="true"] .rf-pair-mark { width: 18px; margin-inline-end: 6px; opacity: 1; }
.rf-pair-div { position: relative; flex: none; align-self: center; width: 1px; height: 22px; background: var(--rf-muted); opacity: .4; transition: opacity .15s; }
.rf-pair[data-rf-voted] .rf-pair-div { opacity: 0; }
.rf-morph { position: relative; flex: none; width: 128px; height: 52px; padding: 0; border: 0; border-radius: 26px; overflow: hidden; background: var(--rf-fill); color: var(--rf-ink); cursor: pointer; transition: width .38s cubic-bezier(.34,1.2,.64,1), background .25s, color .25s; }
.rf-morph[data-rf-morph="next"] { width: 128px; background: var(--accent); color: #fff; }
/* Next's number: the same size and baseline as the word, so "Next 2" reads
   as one phrase; a lighter weight, so the word leads (full white: on the
   blue anything dimmer falls under 4.5:1); fixed-width figures, so the pair
   holds still as it counts down. */
.rf-count { font-weight: 400; font-variant-numeric: tabular-nums; letter-spacing: -0.01em; }
.rf-morph:active { scale: .97; }
.rf-morph:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.rf-morph-in { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; gap: 6px; white-space: nowrap; font-size: 17px; font-weight: 600; transition: opacity .2s, transform .3s cubic-bezier(0.22,1,0.36,1); }
.rf-morph-next { opacity: 0; transform: translateX(calc(10px * var(--rtl-sign))); }
.rf-morph[data-rf-morph="next"] .rf-morph-skip { opacity: 0; transform: scale(.5); }
.rf-morph[data-rf-morph="next"] .rf-morph-next { opacity: 1; transform: none; }
.rf-line { margin: 12px 4px 6px; font-size: 13px; line-height: 18px; color: var(--rf-muted); }
.rf-line-tight { margin: 6px 4px 0; }
.rf-sub { flex: none; display: flex; align-items: center; gap: 2px; margin-block: 10px 2px; margin-inline: -12px 0; }
.rf-sub button { width: 44px; height: 44px; flex: none; display: grid; place-items: center; border: 0; background: none; color: var(--rf-ink); cursor: pointer; }
.rf-sub h2 { margin: 0; font-size: 17px; font-weight: 600; line-height: 22px; }
.rf-body { flex: 1 1 auto; min-height: 0; overflow-y: auto; display: flex; flex-direction: column; gap: 12px; padding: 2px 0 12px; }
.rf-note { margin: 0; font-size: 13px; line-height: 18px; color: var(--rf-muted); }
.rf-para { margin: 0; font-size: 15px; line-height: 21px; }
.rf-sect { margin: 6px 0 -4px; font-size: 12px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--rf-muted); }
.rf-facts { border-radius: 16px; background: var(--rf-fill); padding: 4px 14px; }
.rf-facts > div { display: flex; flex-direction: column; justify-content: center; min-height: 52px; border-bottom: 1px solid var(--rf-line); }
.rf-facts > div:last-child { border-bottom: 0; }
.rf-facts b { font-size: 15px; font-weight: 600; line-height: 20px; }
.rf-facts small { font-size: 13px; color: var(--rf-muted); }
.rf-link { align-self: flex-start; min-height: 44px; display: inline-flex; align-items: center; color: var(--accent); font-size: 15px; font-weight: 500; text-decoration: none; }
.rf-me { align-self: flex-end; max-width: 80%; padding: 10px 14px; border-start-start-radius: 18px; border-start-end-radius: 18px; border-end-end-radius: 4px; border-end-start-radius: 18px; background: var(--accent); color: #fff; font-size: 15px; line-height: 20px; white-space: pre-wrap; }
.rf-ai { align-self: flex-start; max-width: 88%; display: flex; flex-direction: column; gap: 6px; }
.rf-ai small { display: flex; align-items: center; gap: 6px; font-size: 12px; line-height: 16px; color: var(--rf-muted); }
.rf-ai small svg { width: 14px; height: 14px; }
.rf-ai p { margin: 0; padding: 10px 14px; border-start-start-radius: 18px; border-start-end-radius: 18px; border-end-end-radius: 18px; border-end-start-radius: 4px; background: var(--rf-fill); font-size: 15px; line-height: 20px; white-space: pre-wrap; }
.rf-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.rf-chip { height: 44px; padding: 0 13px; border: 0; border-radius: 999px; background: var(--rf-fill); color: var(--rf-ink); font-size: 15px; font-weight: 500; white-space: nowrap; cursor: pointer; }
.rf-chip[aria-checked="true"] { background: var(--rf-ink); color: var(--rf-page); }
.rf-ask-form { flex: none; display: flex; align-items: center; gap: 8px; margin: 0; padding: 4px 0 8px; }
.rf-ask-form input { flex: 1; min-width: 0; box-sizing: border-box; border: 0; background: var(--rf-fill); box-shadow: inset 0 0 0 1px var(--rf-line); color: var(--rf-ink); font-size: 16px; line-height: 22px; outline: 0; }
.rf-ask-form input { height: 44px; padding: 0 16px; border-radius: 999px; }
.rf-go { flex: none; height: 44px; padding: 0 20px; border: 0; border-radius: 999px; background: var(--accent); color: #fff; font-size: 15px; font-weight: 600; cursor: pointer; }
.rf-go:disabled { opacity: .5; cursor: default; }
.rf-go-wide { align-self: stretch; height: 48px; }
.rf-thread { min-height: 200px; }
@media (prefers-reduced-motion: reduce) {
  .rf-sheet, .rf-scrim, .rf-seam, .rf-cap, .rf-switch, .rf-knob, .rf-knob-icon, .rf-pair-thumb, .rf-pair-mark, .rf-morph, .rf-morph-in, .rf-why, .rf-tile, .rf-picto, .rf-gbar, .rf-veil-box, .rf-bar-toggle svg, .rf-desc, .rf-desc-dim { transition: none; }
  .rf-lens { animation: none; }
  .rf-claim { animation: none; }
}
/* Reduce motion setting (#6510): the same, when Settings asks for it. */
:where(html[data-motion="reduce"]) .rf-sheet,
:where(html[data-motion="reduce"]) .rf-scrim,
:where(html[data-motion="reduce"]) .rf-seam,
:where(html[data-motion="reduce"]) .rf-cap,
:where(html[data-motion="reduce"]) .rf-switch,
:where(html[data-motion="reduce"]) .rf-knob,
:where(html[data-motion="reduce"]) .rf-knob-icon,
:where(html[data-motion="reduce"]) .rf-pair-thumb,
:where(html[data-motion="reduce"]) .rf-pair-mark,
:where(html[data-motion="reduce"]) .rf-morph,
:where(html[data-motion="reduce"]) .rf-morph-in,
:where(html[data-motion="reduce"]) .rf-why,
:where(html[data-motion="reduce"]) .rf-tile,
:where(html[data-motion="reduce"]) .rf-picto,
:where(html[data-motion="reduce"]) .rf-gbar,
:where(html[data-motion="reduce"]) .rf-veil-box,
:where(html[data-motion="reduce"]) .rf-bar-toggle svg,
:where(html[data-motion="reduce"]) .rf-desc,
:where(html[data-motion="reduce"]) .rf-desc-dim { transition: none; }
:where(html[data-motion="reduce"]) .rf-lens { animation: none; }
:where(html[data-motion="reduce"]) .rf-claim { animation: none; }

/* From 768px the change page is a panel inside the pane. It is as tall as
   what it holds, up to its room, and past it the stage scrolls inside it.
   The vote sheet is its foot, right under the claim. Nothing behind it is
   dimmed: it sits in the page. review-flow.tsx opens the card onto these
   corners (restRadius). A phone keeps the page above exactly as it was. */
@media (min-width: 768px) {
  .rf-page-wrap {
    --rf-room: calc(100dvh - var(--browser-banner-h, 0px) - var(--platform-header-h) - var(--platform-safe-top, 0px) - var(--platform-tabs-h, 0px) - 32px);
  }
  .rf-bar { padding-top: 0; }
  .rf-page { height: auto; max-height: var(--rf-room); border-radius: 20px; box-shadow: 0 0 0 1px var(--rf-line); }
  .rf-stage { flex: 0 1 auto; }
  .rf-sheet { max-height: calc(var(--rf-room) - 52px); border-radius: 0; box-shadow: inset 0 1px 0 var(--rf-line); }
}

/* New Needs you (an experiment), pictures for every card: a drawn picture
   fills its card or hero; the shots run's own crop sits on a plate. */
.rf-hero-drawn { display: block; position: relative; overflow: hidden; }
.rf-plate-fill { position: static !important; display: block; width: 100%; height: 100%; object-fit: cover; object-position: center; transform: none !important; }
.rf-plate-strip { object-fit: contain; }
/* A long URL or word wraps inside the two lines and ends in the clamp's
   ellipsis instead of running off the side. */
.rf-claim { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; overflow-wrap: anywhere; }

/* ── Review flow: drawn pictures (features/review-flow/illustrations.tsx) ──
   One outlined object per benefit or group decision, on the ground the caller
   paints. Sizes are set inline from the box; these rules are the fixed parts.
   The hero replays the sage part once (rf-ill-play), never with reduced motion. */
.rf-ill { position: relative; display: block; overflow: hidden; }
.rf-ill-stage { position: absolute; display: block; overflow: visible; }
.rf-ill-label { position: absolute; display: block; margin: 0; line-height: 1.25; font-family: 'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, monospace; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; color: rgba(27,27,29,.86); }
.rf-ill-area { color: rgba(27,27,29,.62); }
.rf-ill-token { position: absolute; left: 50%; transform: translateX(-50%); display: flex; align-items: stretch; border-radius: 999px; overflow: hidden; white-space: nowrap; line-height: 1; font-variant-numeric: tabular-nums; letter-spacing: -.005em; }
.rf-ill-token > span { display: flex; align-items: center; }
.rf-ill-before { background: #1b1b1d; color: #FFFEEA; font-weight: 500; }
.rf-ill-after { background: #A9CF97; color: #1b1b1d; font-weight: 700; }
@keyframes rf-ill-fill { 0%, 30% { fill: #FFFEEA; } 100% { fill: #A9CF97; } }
@keyframes rf-ill-pop { 0%, 30% { transform: scale(.92); } 70% { transform: scale(1.05); } 100% { transform: none; } }
.rf-ill-play .rf-ill-sage { animation: rf-ill-fill .84s cubic-bezier(0.22,1,0.36,1) both; }
.rf-ill-play .rf-ill-gain { transform-box: fill-box; transform-origin: center; animation: rf-ill-pop .84s cubic-bezier(0.22,1,0.36,1) both; }
@media (prefers-reduced-motion: reduce) {
  .rf-ill-play .rf-ill-sage, .rf-ill-play .rf-ill-gain { animation: none; }
}
/* Reduce motion setting (#6510): the same, when Settings asks for it. */
:where(html[data-motion="reduce"]) .rf-ill-play .rf-ill-sage,
:where(html[data-motion="reduce"]) .rf-ill-play .rf-ill-gain { animation: none; }

/* New Needs you (an experiment), the title shot's plates: real pixels of the
   changed area and 16px of its surroundings, flat (no shadow, no card of
   their own), the house radius; a deck's back plates are plain tones. */
.rf-tplate { position: absolute; overflow: hidden; display: block; }
.rf-tplate img { position: absolute; display: block; max-width: none; }
.rf-tplate-pair img { position: static; width: 100%; height: 100%; object-fit: cover; object-position: center; }

/* ── Versions: switches and picks in the version dialogs ────────────────
   docs/plans/versions.md. "Get Tier list's updates" in the Make your own
   dialog (fork-app.tsx) and the Updates sheet's two switches
   (features/versions/updates-sheet.tsx): a row of words with the switch at
   its end, as the board filters dialog draws one, inside the hairline of
   the dialog's info box so it reads as one more thing about the version.
   The whole row is the switch's label. */
.fork-follow {
  display: flex; align-items: center; gap: 12px; padding: 10px 12px;
  border-radius: 8px; border: 1px solid var(--app-sheet-line); cursor: pointer;
}
.fork-follow-title { display: block; font-size: 14px; font-weight: 600; line-height: 19px; color: var(--text-primary); overflow-wrap: anywhere; }
.fork-follow-sub { display: block; margin-top: 2px; font-size: 12px; line-height: 16px; color: var(--text-muted); }
/* Suggest to <original>'s list of the version's own changes
   (dev-board/suggest-back-dialog.tsx): one tick box a change, the row its
   label, a hairline between rows, the box in the accent. */
.suggest-pick { padding: 4px 0; }
.suggest-pick ul { margin: 0; padding: 0; list-style: none; }
.suggest-pick li + li .suggest-pick-row { border-top: 1px solid var(--app-sheet-line); }
.suggest-pick-row { display: flex; align-items: flex-start; gap: 10px; padding: 8px 12px; cursor: pointer; }
.suggest-pick-box { width: 18px; height: 18px; margin-top: 1px; flex: none; accent-color: var(--accent); }
.suggest-pick-title { min-width: 0; font-size: 14px; font-weight: 600; line-height: 19px; color: var(--text-primary); overflow-wrap: anywhere; }

/* ── The detail column, one per thread (#6230, 3 Nov 2026) ─────────────
   A design's preview, a plan and a change's before and after are one
   column now (features/detail/), and the column has the same three
   layouts on every surface: three side by side where they fit, halves
   where they do not, the whole screen on a phone. The slot's own
   `data-detail` says which, and `:has()` lets a frame that has always
   been one flex row split by it. */

/* The shots viewer is still a popover, even here; in the column only its
   CLOSED state is flattened into the column's contents, scrolling under
   the reader's header. Open, it must keep `.shots-viewer:popover-open`: it
   goes to the top layer and is drawn as the window-sized card over a dim.
   Flattening that too left a dim with nothing readable in it (#6382). */
.gc-detail-shots {
  flex: 1 1 auto;
  min-height: 0;
  height: auto;
  overflow: auto;
  padding: 0 4px 12px;
}
.gc-detail-shots :is(.shots-viewer, [popover]):not(:popover-open) {
  display: block !important;
  position: static !important;
  inset: auto !important;
  width: auto;
  max-width: none;
  margin: 0;
  border: 0;
  padding: 0;
}
/* #6381: the before and after's own toolbar has no way out of the column,
   so this small head above it carries the close the design preview has in
   its header — an × at the right, or the back arrow at the left where the
   column is the whole screen. */
.gc-detail-shots-head {
  display: flex;
  align-items: center;
  flex-shrink: 0;
  padding: 4px 8px 2px;
}
.gc-detail-shots-close {
  margin-inline-start: auto;
  width: 32px; height: 32px; padding: 0; flex-shrink: 0;
  display: inline-flex; align-items: center; justify-content: center;
  border: none; border-radius: 999px; cursor: pointer;
  background: transparent; color: var(--text-primary, #18181b);
}
.gc-detail-shots-close:hover { background: var(--state-neutral-bg, rgba(24,24,27,.06)); }
.gc-detail-shots-close:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.gc-detail-shots-close svg { width: 18px; height: 18px; }
.gc-detail-back {
  width: 32px; height: 32px; padding: 0; flex-shrink: 0;
  display: inline-flex; align-items: center; justify-content: center;
  border: none; border-radius: 999px; cursor: pointer;
  background: transparent; color: var(--text-primary, #18181b);
}
.gc-detail-back:hover { background: var(--state-neutral-bg, rgba(24,24,27,.06)); }
.gc-detail-back:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.gc-detail-back svg { width: 18px; height: 18px; }

/* A request's own page, and the general chat: between a phone and the
   1024px dock the page and the detail share the room in halves instead
   of the detail covering the page. Only while the detail is open (18 Nov
   2026): the slot carries its layout closed too, so the page in the
   column beside Homeroom bot's list (876px wide in its own document) wore
   the halves' edge down its side with nothing beside it. */
@media (max-width: 1023px) and (min-width: 768px) {
  .gc-tab-body:has(> #gc-spec-side-panel.gc-spec-side-panel-open[data-detail="halves"]) > #dev-topic-thread,
  .gc-tab-body:has(> #gc-spec-side-panel.gc-spec-side-panel-open[data-detail="halves"]) > #gc-chat-pane,
  .gc-tab-body:has(> #gc-spec-side-panel[data-detail="halves"]) > #gc-spec-side-panel.gc-spec-side-panel-open {
    position: static;
    inset: auto;
    flex: 1 1 50%;
    width: auto !important;
    min-width: 0;
    max-width: none;
    border-inline-start: 1px solid var(--border, rgba(255,255,255,0.12));
  }
  .gc-tab-body:has(> #gc-spec-side-panel[data-detail="halves"]) > #gc-spec-side-panel.gc-spec-side-panel-open {
    border-inline-start: 1px solid var(--border, rgba(255,255,255,0.12));
  }
}

/* The Workshop's request panel: Read opens the plan in the panel's right
   half, the request's page in its left. From 1760px the list stays beside
   them; below that the panel widens over the list. */
.dev-ws-side-body:has(> #gc-spec-side-panel[data-detail="halves"]),
.dev-ws-side-body:has(> #gc-spec-side-panel[data-detail="three"]) {
  flex-direction: row;
}
.dev-ws-side-body:has(> #gc-spec-side-panel[data-detail="halves"]) > #dev-topic-thread,
.dev-ws-side-body:has(> #gc-spec-side-panel[data-detail="three"]) > #dev-topic-thread {
  flex: 1 1 50%;
  min-width: 0;
}
.dev-ws-side-body:has(> #gc-spec-side-panel[data-detail="halves"]) > #gc-spec-side-panel.gc-spec-side-panel-open,
.dev-ws-side-body:has(> #gc-spec-side-panel[data-detail="three"]) > #gc-spec-side-panel.gc-spec-side-panel-open {
  position: static;
  inset: auto;
  flex: 1 1 50%;
  width: auto !important;
  min-width: 0;
  max-width: none;
  border-inline-start: 1px solid var(--app-sheet-line);
  z-index: auto;
}
/* Only while the plan is open in the panel's half (18 Nov 2026): this block
   used to apply whenever the window was under 1760px, so the panel covered
   the list on most laptops with no plan open at all. */
@media (max-width: 1759px) {
  body:has(.dev-ws-side-body > #gc-spec-side-panel.gc-spec-side-panel-open) #dev-workshop:has(> .dev-ws[data-ws-side-open]) { margin-inline-start: 0; max-width: none; }
  body:has(.dev-ws-side-body > #gc-spec-side-panel.gc-spec-side-panel-open) .dev-ws-side {
    inset-inline-start: calc(var(--dev-ws-side-start) + var(--platform-gutter, 0px) + 24px);
    background: var(--bl-page, var(--home-ground));
  }
}

/* ── ONE HOME (#6361): THE SIDEBAR'S RECENTS ────────────────────────────
   One list under one heading: the communities pinned to its top
   (#platform-rail-pinned, community_pins, four at most), then the ones you
   opened lately, each where it first arrived (#platform-rail-communities).
   The pinned group carries the heading when it is drawn, and the list under
   it then draws none of its own. The search beside the heading went with
   the Communities page: Home lists and searches every community. */
@media (min-width: 768px) {
  #platform-rail-pinned:not(.hidden) + #platform-rail-communities > .platform-rail-head { display: none; }
  #platform-rail-search { display: none; }

  /* A row: the link fills it, and the pin and the count sit over its end in
     their own columns, the pin first, so the count keeps the row's end and
     does not move when the pin shows. */
  .platform-rail-row {
    position: relative;
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto auto;
    align-items: center;
  }
  .platform-rail-row > .platform-rail-community { grid-column: 1 / -1; grid-row: 1; padding-inline-end: 38px; }
  .platform-rail-row[data-votes] > .platform-rail-community { padding-inline-end: 62px; }
  .platform-rail-pin {
    grid-column: 2; grid-row: 1; position: relative; z-index: 2;
    width: 26px; height: 26px; margin-inline-end: 6px; border-radius: 8px;
    display: grid; place-items: center;
    color: var(--text-muted);
    opacity: 0;
    transition: opacity 120ms ease, background-color 120ms ease;
  }
  .platform-rail-row[data-votes] > .platform-rail-pin { margin-inline-end: 2px; }
  .platform-rail-row > .platform-rail-votes {
    grid-column: 3; grid-row: 1; position: relative; z-index: 2;
    margin-inline-end: 8px; pointer-events: none;
  }
  .platform-rail-pin-glyph { width: 16px; height: 16px; }
  .platform-rail-row:hover > .platform-rail-pin,
  .platform-rail-row:focus-within > .platform-rail-pin { opacity: 1; }
  .platform-rail-pin:hover { background: var(--lit-tint); color: var(--lit-ink); }
  .platform-rail-pin[aria-pressed="true"] { opacity: 1; color: var(--lit-ink); }
  .platform-rail-pin[aria-pressed="true"] .platform-rail-pin-glyph { fill: currentColor; }
  .platform-rail-pin:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; opacity: 1; }
}
@media (min-width: 768px) and (hover: none) {
  .platform-rail-pin { opacity: .55; }
}

/* ── THE FRAME IN THE SHELL ──────────────────────────────────────────────
   Hand-written, unlike the kit and the looks below it: how the frame sits
   in the shell while a look is on (data-skin on <html>).

   A PAGE DRAWN IN THE KIT replaces its screen's standard body. The screen
   renders the kit page as its own first child and sets data-frame-page;
   the standard body stays mounted, so the legacy module that writes into
   it still finds its nodes, and is hidden here. */
html[data-skin] [data-frame-page] > :not(.fr) { display: none !important; }
/* THE KIT'S ELEMENTS ARE REAL ONES HERE. The tour's mock drew every row,
   tab and button as a <div> or a <span>; in the product a row that opens
   something is a link or a button, and its name and line are spans so
   they may sit inside either. These give them the box the kit's rules
   assume, at a weight under any kit rule that says otherwise (Mosaic
   clamps a tile's name to two lines with display: -webkit-box). */
html[data-skin] .fr-tx > .fr-t,
html[data-skin] .fr-tx > .fr-s { display: block; }
html[data-skin] button.fr-row,
html[data-skin] button.fr-at { width: 100%; text-align: start; }
/* The field's value is an <input> here, where the mock had a span: it takes
   the field's width and brings no box of its own; the field shows the
   focus the kit draws for it. */
html[data-skin] .fr-inp > input.fr-v { flex: 1; min-width: 0; border: 0; outline: 0; background: none; font: inherit; color: var(--fr-ink); }
html[data-skin] .fr-inp > input.fr-v::placeholder { color: var(--fr-faint); opacity: 1; }
html[data-skin] .fr-inp:focus-within { box-shadow: inset 0 0 0 2px var(--fr-acc); color: var(--fr-ink); }

/* A kit page brings its own margins (.fr-inner), so its screen gives up the
   gutter it adds after the sidebar and keeps only the sidebar's width. */
html[data-skin] [data-frame-page] { padding-inline-start: var(--platform-rail-w, 0px) !important; padding-inline-end: 0 !important; }

/* THE CHROME (features/frame/frame-app.tsx): the kit's sidebar, bar and
   phone tab bar, as one fixed layer at the tab bar's own level (30: over
   the screens, under the panels, sheets and dialogs at 40 and above). It
   takes presses only on what it draws; the page area between is empty and
   lets the screen under it through. Three classes on each selector, so
   these hold whatever the kit says of .fr-app. */
html[data-skin] .fr.fr-app.fr-shell { position: fixed; inset: 0; z-index: 30; height: auto; min-height: 0; pointer-events: none; }
html[data-skin] .fr.fr-shell > .fr-side,
html[data-skin] .fr.fr-shell .fr-bar,
html[data-skin] .fr.fr-shell .fr-banner,
html[data-skin] .fr.fr-shell .fr-tabbar { pointer-events: auto; }
html[data-skin] .fr.fr-shell .fr-pagearea { overflow: visible; }
/* THE BAR HAS A GROUND HERE. In the tour's mock the page scrolls inside
   the page area, under the bar's edge; in the shell it scrolls in the
   document and passes behind the bar, which the looks draw with no ground
   of its own (the mock never needed one). The shell's bar wears the look's
   ground as a 90% tint, no blur (NO LARGE BLUR CAME BACK, tests/no-glass-
   one-scheme.test.js: a live blur stuttered the phone's slides; the
   standard header's own tint is 92%): a flat ground stays one colour, a
   wallpaper shows faintly, and what scrolls under is put away either way.
   The inert copy behind the screens keeps none of this. A look that gives
   its bar a ground of its own keeps it: the shell's classes weigh nothing
   here. */
html[data-skin] :where(.fr.fr-shell:not(.fr-shell-under)) .fr-bar { background: color-mix(in srgb, var(--fr-ground) 90%, transparent); }
/* The line under the bar's first row on a phone (a title's second line
   that did not fit, frame-app.tsx lineUnder) is more bar: the same ground. */
/* What a look gives the page column itself (Paper's white sheet) is
   painted by an inert copy BEHIND the screens, so a page reads on it; the
   copy over the screens paints nothing there. */
html[data-skin] .fr.fr-app.fr-shell.fr-shell-under { z-index: -1; }
/* …which needs <body> to be the stacking context it is behind: else a
   negative layer sinks under the body's own background, the wallpaper. */
html[data-frame-chrome] body { isolation: isolate; }
html[data-skin] .fr.fr-shell.fr-shell-under > .fr-side { visibility: hidden; }
html[data-skin] .fr.fr-shell:not(.fr-shell-under) > .fr-colm { background: none; box-shadow: none; }

/* PAPER'S SHEET HAS AN EDGE. The look's page column is a white sheet with
   10px of ground after it and under it and 22px corners (paper.css
   .colm), painted by the copy behind the screens. A screen scrolls over
   it to the window's own edge, so a long list ran past the sheet's foot
   and round its corners. From 768px each screen drawn in the frame is cut
   to the sheet: 10px off its end and its foot, the sheet's corners at the
   foot, starting where the sidebar ends. */
@media (min-width: 768px) {
  html[data-skin="paper"][data-frame-chrome] :is([data-frame-page], #ai-screen[data-frame-list]) { clip-path: inset(0 10px 10px var(--platform-rail-w, 0px) round 0 0 22px 22px); }
}

/* THE PHONE'S SAFE AREA. A look's bar sits at y=0 and its tab bar at the
   window's foot, so on a phone with a notch the bar was under the status
   bar and the tab bar under the home strip. Each now grows around the
   inset and its own ground fills the strip: margin, not padding, so each
   look keeps its border-box height. The page area the chrome measures
   (--fr-shell-top, -bottom) then starts below the bar and ends above the
   tab bar, and the screens follow. A tablet's sidebar takes the insets as
   transparent borders, which its own ground paints under. Covered by
   tests/frame-app.test.js. */
html[data-skin] .fr.fr-shell .fr-bar {
  position: relative;
  margin-top: var(--platform-safe-top, 0px);
}
html[data-skin] .fr.fr-shell .fr-bar::before {
  content: '';
  position: absolute;
  inset-inline: 0;
  bottom: 100%;
  height: var(--platform-safe-top, 0px);
  background: inherit;
}
html[data-skin] .fr.fr-shell > .fr-side {
  border-top: var(--platform-safe-top, 0px) solid transparent;
  border-bottom: var(--platform-safe-bottom, 0px) solid transparent;
}
/* WITH THE KEYS UP ON A PHONE THE FRAME'S TAB BAR GOES, on every page, as
   the standard look's does (`html.un-kb #platform-tabs`,
   `html.platform-kb-open #platform-tabs`): it rode on the keyboard under a
   reply box, a chat's field or a filter. The frame measures its page area,
   so the room comes back to the page by itself. */
@media (max-width: 767.98px) {
  html[data-skin]:is(.un-kb, .platform-kb-open) .fr.fr-shell .fr-tabbar { display: none; }
}
@media (max-width: 767.98px) {
  html[data-skin] .fr.fr-shell .fr-tabbar {
    position: relative;
    margin-bottom: var(--platform-safe-bottom, 0px);
  }
  html[data-skin] .fr.fr-shell .fr-tabbar::after {
    content: '';
    position: absolute;
    inset-inline: 0;
    top: 100%;
    height: var(--platform-safe-bottom, 0px);
    background: inherit;
  }
}
/* HOME UNDER A LOOK, IN A NARROW WINDOW (features/home/frame/home-frame.tsx).
   The kit's two columns are the tour's 1440px page; the kit's files have no
   widths of their own between that and a phone. Beside the sidebar in a
   1024px window the work column was 350px, and six tiles across it cut
   every name mid-letter. The page's own width decides: under 912px (six
   tiles of 90px and the side column no longer fit) it is one column in the
   phone's order, the challenges before the directory, which has no end;
   under 560px the tiles are four across, as on a phone. */
html[data-skin] [data-home-frame] > .fr-inner { container: fr-home / inline-size; }
@container fr-home (max-width: 911.98px) {
  html[data-skin] [data-home-frame] .fr-cols { grid-template-columns: minmax(0, 1fr); gap: 24px; }
  html[data-skin] [data-home-frame] .fr-cols.fr-mix > .fr-stack { display: contents; }
  html[data-skin] [data-home-frame] .fr-cols.fr-mix > .fr-stack > .fr-tail { order: 1; }
}
@container fr-home (max-width: 559.98px) {
  html[data-skin] [data-home-frame] .fr-tiles { grid-template-columns: repeat(4, minmax(0, 1fr)); }
  html[data-skin] [data-home-frame] .fr-grid.fr-c4 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

/* HOME UNDER A LOOK: THE PRODUCT'S OWN PIECES (features/home/frame/
   home-frame.tsx, class fr-own). The standard grid while Pinned apps is
   arranged, the iOS widget strip, the waitlist card and the verify card
   are the standard components, handed in whole; the kit's reset stops at
   them, so their own utilities lay them out. What is set here is only
   what the kit page already gives: the section's gutter (the column is
   the gutter) and the card (the look's own surface and corner, where the
   standard one is the plane colour). */
html[data-skin] [data-home-frame] :is(#home-waitlist-card, #home-verify-card, #home-widget-strip-section) { padding: 0; }
html[data-skin] [data-home-frame] #app-list { color: var(--fr-ink); }
html[data-skin] [data-home-frame] #widget-strip { border-color: var(--fr-line); background: var(--fr-surface); }

/* THE BOT'S CARDS IN A CONVERSATION, UNDER A LOOK (the tour's s10). The
   cards under a message wear the kit's rows in one card (looks.json wear);
   the product's own fills, corners and gaps step aside here so the look's
   are the ones drawn. A card on its own (a file) keeps its padding. */
html[data-skin] .messages-message .messages-object-list { gap: 0; }
html[data-skin] .messages-message .messages-object-list > :is(.messages-object-card, .messages-pending-object) { border-radius: 0; background: none; box-shadow: none; }
html[data-skin] .messages-message .messages-object-list > .messages-object-card:hover { background: var(--fr-line2); }
html[data-skin] .messages-message :is(.messages-object-icon, .messages-file-icon) { background: var(--fr-sunk); color: var(--fr-ink); }
html[data-skin] .messages-message .messages-object-card :is(.text-base, .text-sm, .text-xs) { color: var(--fr-ink); }
html[data-skin] .messages-message .messages-object-card :is(.text-sm, .text-xs, span:last-child) { color: var(--fr-mut); }
html[data-skin] .messages-message .messages-attachment { background: var(--fr-surface); }

/* A LIST BESIDE ITS OPEN ITEM (the kit's split: Homeroom bot's page). The
   screen stays the scroller and keeps its own column for the open item;
   under a look the list is the kit's pane, 520px as the tour draws it, and
   the column takes what is left: its width token is set here instead of
   by the handle, which steps aside. The column gives up its own ground,
   corner and top line for the kit's one line between two panes. */
html[data-skin] .fr.fr-pane,
html[data-skin] .fr.fr-pane > .fr-scroll { overflow: visible; }
/* Version 2: the phone's Ask Homeroom bot bar stays over the tab bar, as
   on the standard page, wearing the kit's composer (looks.json wear); its
   words start a little in, as the mockup's do. The room it keeps after the
   list's last row is the bar's own sticky margin. */
html[data-skin] #ai-screen[data-frame-list] .ai-askbar { padding: 0 12px 8px; }
html[data-skin] #ai-screen[data-frame-list] .ai-askbar-card { flex-direction: row; align-items: center; margin: 0; padding-inline-start: 20px; }
/* The bar floats over the list's rows: a see-through look's composer let a
   row's words read inside the field beside its own. It takes the look's
   opaque surface where it has one (--fr-solid), as a menu does. */
html[data-skin] #ai-screen[data-frame-list] .ai-askbar-card { background: var(--fr-solid, var(--fr-surface)); backdrop-filter: none; -webkit-backdrop-filter: none; }
html[data-skin] #ai-screen[data-frame-list] .ai-askbar-text { font-size: 15px; padding: 0; color: var(--fr-faint); }
html[data-skin] #ai-screen[data-frame-list] .ai-askbar-gap { display: none; }
/* A private thread's ⋯ in its row (the product's ThreadDoneMenu): its menu
   reads the Messages surface tokens, which are declared where a chat is
   drawn, so they are given here from the kit's. */
html[data-skin] #ai-screen[data-frame-list] .fr-rowx { --messages-surface: var(--fr-ground); --messages-surface-2: var(--fr-sunk); --messages-hair: var(--fr-line); }
html[data-skin] #ai-screen[data-frame-list] .fr-rowx .messages-thread-menu { padding: 6px; box-shadow: 0 0 0 1px var(--fr-line), var(--fr-sh); }
html[data-skin] #ai-screen[data-frame-list] .fr-rowx .messages-thread-menu button { padding: 10px 12px; color: var(--fr-ink); }
/* IN A NARROW WINDOW the open item keeps 360px and the list has what is
   left, less than the tour's 520px (432px in a 1024px window): its head is
   then the phone's (the 24px title, the tighter gutter) and a row gives up
   its number, as it does on a phone, so the title has the line. The pane's
   own width decides. */
html[data-skin] #ai-screen[data-frame-list] > .fr-pane { container: fr-botlist / inline-size; }
@container fr-botlist (max-width: 479.98px) {
  html[data-skin] #ai-screen[data-frame-list] .fr-botpage .fr-title { font-size: 24px; }
  html[data-skin] #ai-screen[data-frame-list] > .fr-pane > .fr-scroll { padding-inline: 16px; }
  html[data-skin] #ai-screen[data-frame-list] .fr-list .fr-row > .fr-num { display: none; }
}
/* A private thread or New thread on a phone is the whole screen: its lines
   keep the kit's 16px gutter (from 768px the column's rules below give
   32px; without either the bot's picture touched the screen's edge). */
@media (max-width: 767.98px) {
  html[data-skin]:where(:not([data-skin="brand"])) #ai-screen[data-frame-list] .messages-reply-pane > .messages-thread-scroll { padding-inline: 16px; }
}
/* With nothing open beside it (#6425: the column opens from a row) the list is
   a page of one column: the kit's narrow page (784px), not the whole width. */
@media (min-width: 768px) {
  html[data-skin] #ai-screen[data-frame-list]:not([data-ai-open]) > .fr-pane > .fr-scroll { max-width: 784px; margin-inline: auto; }
  html[data-skin] #ai-screen[data-frame-list] { --ai-main-w: max(360px, calc(var(--platform-usable-w) - 520px)); }
  html[data-skin] #ai-screen[data-frame-list] .ai-main-pane { top: var(--fr-shell-top); background: none; border-top: 0; border-inline-start: 1px solid var(--fr-line); border-radius: 0; }
  html[data-skin] #ai-screen[data-frame-list] #ai-main-divider { display: none; }
  /* The chat in the column keeps the kit's 32px gutter (the Messages
     pane's, below). The column's own centring rule (`A WIDER COLUMN KEEPS A
     READABLE LINE`) names the screen's id and floors the gutter at 0, so a
     column under 784px ran its lines to the window's edge. */
  html[data-skin]:where(:not([data-skin="brand"])) #ai-screen[data-frame-list] .ai-main-pane .messages-layout[data-bot-threads] .chat-transcript { padding-inline: max(32px, calc((100% - 720px) / 2)); }
  /* A request or a decision opened from the list stands in the column
     through the shell's side panel, which is in <body> and reads the
     column's width there: the same width, so it ends where the list ends,
     and the same one line between the two panes. */
  html[data-skin] body:has(#ai-screen[data-frame-list]:not(.hidden)) { --ai-main-w: max(360px, calc(var(--platform-usable-w) - 520px)); }
  html[data-skin] body:has(#ai-screen[data-frame-list]:not(.hidden)) .side-panel { top: var(--fr-shell-top); border-radius: 0; background: none; box-shadow: none; border-inline-start: 1px solid var(--fr-line); }
  /* Version 2 (s11): the column's head is the kit's open-item head (.dhead): 68px, the 32px gutter, the project's
     tile at 40px, the name at 17px over one 13px line, then the ⋯ and the × as the kit's round buttons. */
  html[data-skin] body:has(#ai-screen[data-frame-list]:not(.hidden)) .side-panel-head { min-height: 68px; gap: 12px; padding-block: 8px; padding-inline: 32px; background: none; border-bottom: 1px solid var(--fr-line); }
  html[data-skin] body:has(#ai-screen[data-frame-list]:not(.hidden)) .side-panel-place { gap: 12px; }
  html[data-skin] body:has(#ai-screen[data-frame-list]:not(.hidden)) .side-panel-place > .app-icon-tile { width: 40px; height: 40px; border-radius: 12px; }
  html[data-skin] body:has(#ai-screen[data-frame-list]:not(.hidden)) .side-panel-place-title { font-size: 17px; line-height: 1.3; color: var(--fr-ink); }
  html[data-skin] body:has(#ai-screen[data-frame-list]:not(.hidden)) .side-panel-place-where { color: var(--fr-mut); }
  html[data-skin] body:has(#ai-screen[data-frame-list]:not(.hidden)) .side-panel-ai-close { width: 36px; height: 36px; border-radius: 50%; background: var(--fr-surface); color: var(--fr-ink); box-shadow: inset 0 0 0 1px var(--fr-line); }
}

/* The × and the ⋯ of a private thread's head and of New thread's are the
   same round buttons as Main Chat's and a request's (s12, s13): they were
   the look's disc with no edge, bare on a pane of the same surface. Three
   weights (the id), to outweigh each look's own disc. */
html[data-skin] #ai-main-pane .messages-thread-header .messages-thread-action { background: var(--fr-surface); box-shadow: inset 0 0 0 1px var(--fr-line); }

/* Version 2 (s13): New thread stays where the product opens it (the column;
   the whole screen on a phone) and wears the kit. Its five starts are
   single-line rows in one card (the card is worn, looks.json; the rows are
   the kit's .row with a 40px .lead for the glyph), its two chips the kit's
   small quiet buttons. The words, the chips' pickers and the box are the
   product's own (messages/new-thread.tsx). */
html[data-skin] #ai-screen[data-frame-list] [data-bot-new-thread-pane] .messages-starts { gap: 20px; padding: 16px 32px; font-family: var(--fr-f); }
html[data-skin] #ai-screen[data-frame-list] [data-bot-new-thread-pane] .messages-starts-hello { gap: 6px; }
html[data-skin] #ai-screen[data-frame-list] [data-bot-new-thread-pane] .messages-starts-hello > img { width: 44px; height: 44px; }
html[data-skin] #ai-screen[data-frame-list] [data-bot-new-thread-pane] .messages-starts-title { color: var(--fr-ink); font-size: 15px; font-weight: 650; line-height: 1.45; }
html[data-skin] #ai-screen[data-frame-list] [data-bot-new-thread-pane] .messages-starts-sub { color: var(--fr-mut); }
html[data-skin] #ai-screen[data-frame-list] [data-bot-new-thread-pane] .messages-starts-list { align-items: stretch; gap: 0; max-width: 432px; }
html[data-skin] #ai-screen[data-frame-list] [data-bot-new-thread-pane] .messages-start { display: flex; gap: 12px; min-height: 60px; padding: 8px 16px; border-radius: 0; background: none; box-shadow: none; color: var(--fr-ink); font-size: 15px; font-weight: 650; line-height: 1.45; }
html[data-skin] #ai-screen[data-frame-list] [data-bot-new-thread-pane] .messages-start + .messages-start { border-top: 1px solid var(--fr-line2); }
html[data-skin] #ai-screen[data-frame-list] [data-bot-new-thread-pane] .messages-start > svg { box-sizing: border-box; width: 40px; height: 40px; padding: 10px; border-radius: 12px; background: var(--fr-sunk); color: var(--fr-ink); }
