html[data-skin] [data-you-friends-search] [data-friend-search-result] + * { border-top: 1px solid var(--fr-line2); }
html[data-skin] [data-you-friends-search] [data-friend-search-result] > span { width: 40px; height: 40px; background: var(--fr-sunk); color: var(--fr-mut); font-size: 16px; }
