html[data-skin]:not([data-skin="brand"]) #profile-edit-sheet { color: var(--fr-ink); }
html[data-skin]:not([data-skin="brand"]) #profile-edit-sheet > div:first-child { font-size: 24px; padding: 8px 4px 16px; }
