html[data-skin]:where(:not([data-skin="brand"])) :is(#profile-app-slots-sheet, #profile-week-share-sheet, #profile-feedback-sheet):not(#x) > div > h2 { font-size: 24px; }
html[data-skin]:where(:not([data-skin="brand"])) :is(#profile-app-slots-close, #profile-week-share-close, #profile-feedback-close) {
  flex: none; width: 36px; height: 36px; padding: 0; border-radius: 50%;
