}
html[data-skin]:where(:not([data-skin="brand"])) :is(#profile-app-slots-sheet, #profile-week-share-sheet, #profile-feedback-sheet) :is(.text-zinc-500, .text-zinc-600, .text-zinc-400) { color: var(--fr-mut); }
html[data-skin]:where(:not([data-skin="brand"])) :is(#profile-app-slots-sheet, #profile-week-share-sheet, #profile-feedback-sheet) :is(.text-zinc-700, .text-zinc-800, .text-zinc-900) { color: var(--fr-ink); }
html[data-skin]:where(:not([data-skin="brand"])) :is(#profile-app-slots-sheet, #profile-week-share-sheet, #profile-feedback-sheet) :is(.text-red-700, .text-red-600) { color: var(--fr-bad); }
html[data-skin]:where(:not([data-skin="brand"])) :is(#profile-app-slots-sheet, #profile-week-share-sheet, #profile-feedback-sheet) .text-emerald-700 { color: var(--fr-ok); }
html[data-skin]:where(:not([data-skin="brand"])) :is(#profile-app-slots-sheet, #profile-week-share-sheet, #profile-feedback-sheet) :is(.text-violet-700, .text-violet-600) { color: var(--fr-acc); }
/* App slots: the allowance box is the kit's card. */
html[data-skin]:where(:not([data-skin="brand"])) #profile-app-slots-sheet #profile-app-quota {
  margin-bottom: 0; padding: 14px 16px; border: 0; border-radius: 16px;
