html[data-skin]:where(:not([data-skin="brand"])) #profile-week-share-sheet label > span { font-size: 15px; font-weight: 500; }
html[data-skin]:where(:not([data-skin="brand"])) #profile-week-share-sheet .rounded-2xl { padding: 12px 16px; border-radius: 16px; background: var(--fr-sunk); color: var(--fr-ink); font-size: 14px; line-height: 1.5; overflow-wrap: anywhere; }
html[data-skin]:where(:not([data-skin="brand"])) #profile-week-share-sheet :is(#profile-week-share-send, #profile-week-share-copy) { flex: 1 1 0; }
/* Your feedback: the list is the kit's card of rows; a report's state is
   the kit's small pill. */
html[data-skin]:where(:not([data-skin="brand"])) #profile-feedback-sheet #profile-feedback-summary { font-size: 15px; }
