html[data-skin]:where(:not([data-skin="brand"])) #profile-feedback-sheet #profile-feedback-list [data-feedback-report] svg { color: var(--fr-faint); }
html[data-skin]:where(:not([data-skin="brand"])) #profile-feedback-sheet [data-feedback-report] .rounded-full { height: 20px; padding: 0 8px; display: inline-flex; align-items: center; background: var(--fr-sunk); color: var(--fr-mut); font-size: 11px; font-weight: 700; }
