html[data-skin]:where(:not([data-skin="brand"])) :is(.msgx-thread-chip.msgx-thread-card, .msgx-thread-activity-card):focus-visible,
html[data-skin]:where(:not([data-skin="brand"])) .msgx-thread-chip.msgx-thread-card.msgx-thread-chip-active { box-shadow: inset 0 0 0 2px var(--fr-acc); }
