html[data-skin]:where(:not([data-skin="brand"])) [data-sign-in-sheet] .rounded-2xl.overflow-hidden > div { padding: 16px 16px 0; border: 0; }
html[data-skin]:where(:not([data-skin="brand"])) [data-sign-in-sheet] .rounded-2xl.overflow-hidden > div:last-child { padding-bottom: 16px; }
