  padding: 14px 12px 14px 16px;
  border-radius: 20px;
  background: var(--thread-card-solid, var(--dc-sheet-solid));
  box-shadow: var(--thread-card-edge, inset 0 0 0 1px var(--app-sheet-line));
}
.dev-thread-bar-tile { flex: none; width: 48px; height: 48px; border-radius: 14px; font-size: 22px; overflow: hidden; }
/* The small line, then the title: one grid, so the nodes keep their order
   (the project and topic after the title, which the checks select on) and
   the kicker and its status pill are cells of the line, not a row. */
html:is(:not([data-skin]), [data-skin="brand"]) :is(#dev-topic-thread, #ai-screen) .dev-request:has(.dev-thread-card) :is(#gc-thread-bar, .dev-request-bar) .dev-thread-bar-text {
