}
html:is(:not([data-skin]), [data-skin="brand"]) :is(#dev-topic-thread, #ai-screen) .dev-request:has(.dev-thread-card) :is(#gc-thread-bar, .dev-request-bar) .dev-thread-bar-text:has(> .messages-thread-sub) .messages-thread-kicker::before {
  content: "·";
  margin-inline: 6px;
}
/* The title. A request's is the node itself; a change's is the run inside
   its Details button, with the author's pencil beside it. */
html:is(:not([data-skin]), [data-skin="brand"]) :is(#dev-topic-thread, #ai-screen) .dev-request:has(.dev-thread-card) :is(#gc-thread-bar, .dev-request-bar) .dev-thread-bar-text > .messages-thread-name {
  min-width: 0;
  margin: 0;
  font-size: 20px;
  line-height: 26px;
